const sectionScrollPositions = new Map();
function rememberSectionScroll(section=currentSection){if(section)sectionScrollPositions.set(section,window.scrollY||0)}
function restoreSectionScroll(section){
  const top=sectionScrollPositions.get(section)||0;
  requestAnimationFrame(()=>window.scrollTo({top,behavior:'auto'}));
}
