function translateCommonLiteralText(root=document.body){
  if(!root)return;
  const target=WEB_COMMON_LITERALS[currentWebLanguage]||{};
  const reverse={};
  for(const [canon] of Object.entries(WEB_COMMON_LITERALS.ru||{}))reverse[canon]=canon;
  for(const map of Object.values(WEB_COMMON_LITERALS))for(const [canon,val] of Object.entries(map))reverse[val]=canon;
  reverse['BlockLogger']='BlockLogger'; reverse['Block Logging']='BlockLogger';
  const translatedValue=raw=>{
    const trimmed=String(raw??'').trim(); if(!trimmed)return null;
    const canonical=reverse[trimmed]||trimmed;
    return currentWebLanguage==='en'?(canonical==='BlockLogger'?'Block Logging':canonical):(target[canonical]||target[trimmed]||null);
  };
  const translateNode=node=>{
    if(!node||node.nodeType!==Node.TEXT_NODE)return;
    const parent=node.parentElement;if(!parent||['SCRIPT','STYLE','TEXTAREA'].includes(parent.tagName))return;
    const raw=node.nodeValue||''; const translated=translatedValue(raw); if(!translated)return;
    const leading=raw.match(/^\s*/)?.[0]||''; const trailing=raw.match(/\s*$/)?.[0]||'';
    const next=leading+translated+trailing;if(next!==raw)node.nodeValue=next;
  };
  const translateAttrs=el=>{
    if(!el||el.nodeType!==Node.ELEMENT_NODE)return;
    for(const attr of ['placeholder','title','aria-label','alt','data-tooltip']){
      if(!el.hasAttribute(attr))continue;
      const raw=el.getAttribute(attr)||''; const translated=translatedValue(raw);
      if(translated&&translated!==raw)el.setAttribute(attr,translated);
    }
  };
  if(root.nodeType===Node.TEXT_NODE){translateNode(root);return;}
  if(root.nodeType===Node.ELEMENT_NODE)translateAttrs(root);
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n;
  while((n=walker.nextNode())){if(n.nodeType===Node.TEXT_NODE)translateNode(n);else translateAttrs(n);}
}
let webLiteralObserver=null;
