function formatIngameDate(raw){
  const value=String(raw??'').trim();
  if(!value)return '';
  if(value.toLowerCase()==='unknown')return t('date.unknown');
  const m=value.match(/^Year\s+(-?\d+)\s*,\s*Month\s+(\d+)\s*,\s*Day\s+(\d+)\s*,\s*(-?\d+(?:\.\d+)?)h$/i);
  return m?`${t('date.year')} ${m[1]}, ${t('date.month')} ${m[2]}, ${t('date.day')} ${m[3]}, ${m[4]}h`:value;
}
