  [['#globalStatusBar .statusPill:nth-of-type(2)','status.health'],['#globalStatusBar .statusPill:nth-of-type(3)','status.cpu'],['#globalStatusBar .statusPill:nth-of-type(4)','status.delay'],['#globalStatusBar .statusPill:nth-of-type(5)','status.players'],['#globalStatusBar .statusPill:nth-of-type(6)','status.entities'],['#globalStatusBar .statusPill:nth-of-type(7)','status.alerts'],['#globalStatusBar .statusPill:nth-of-type(8)','status.queue'],['#globalStatusBar .statusPill:nth-of-type(9)','status.updated']].forEach(([sel,key])=>{const e=document.querySelector(sel);if(e&&e.firstChild)e.firstChild.nodeValue=t(key)+' ';});
  [['server','status.server'],['anticheat','status.anticheat'],['packetguard','status.packetguard'],['memory','status.memory'],['webmap','status.webmap'],['blocklogger','status.blocklogger'],['chatguard','nav.chatguard'],['discord','nav.discord'],['loginprotection','nav.loginProtection']].forEach(([id,key])=>{const e=document.querySelector(`[data-summary-status="${id}"] span:last-child`);if(e)e.textContent=t(key);});
  const ob=document.querySelector('#offlineBanner b');if(ob)ob.textContent=t('offline.title'); applyText('#offlineDetail','offline.detail'); applyText('#retryConnectionBtn','offline.retry');
  const ro=document.querySelector('#readOnlyNotice b');if(ro)ro.textContent=t('readonly.title'); const rs=document.querySelector('#readOnlyNotice span');if(rs)rs.textContent=t('readonly.text');
  Object.keys(SECTION_I18N_KEYS).forEach(section=>{const h=document.querySelector(`#${section} .pageTitle h2`);const key='page.'+section;if(h&&WEB_LANGS.en[key])h.textContent=t(key);});
  const crumb=$('breadcrumbCurrent');if(crumb)crumb.textContent=sectionLabels[currentSection]||t('nav.dashboard');
