const pageStatusState = new Map();
const summaryStatusState = new Map();
let globalOverallState = 'neutral';

function statusStateRank(state){return state==='bad'?3:state==='warn'?2:state==='good'?1:0;}
function updateCurrentPageStatus(){
  const box=$('globalPageContext'),name=$('globalPageName'),stateText=$('globalPageStateText');
  if(!box||!name||!stateText)return;
  const label=sectionLabels[currentSection]||'Dashboard';
  let entry=pageStatusState.get(currentSection);
  if(!entry&&currentSection==='dashboard')entry={state:globalOverallState,detail:globalOverallState==='good'?'Suite healthy':globalOverallState==='warn'?'Suite needs attention':globalOverallState==='bad'?'Suite has a problem':'Waiting for status data'};
  entry=entry||{state:'neutral',detail:'No page-specific status available'};
  const state=['good','warn','bad','neutral'].includes(entry.state)?entry.state:'neutral';
  box.className=`globalPageContext ${state}`;
  name.textContent=label;
  stateText.textContent=pageStatusLabel(state,entry.detail);
  box.title=entry.detail||`${label} status`;
}

function updateOverallStatus(){
  const button=$('globalOverallStatus'),text=$('globalOverallText'),count=$('globalOverallCount');
  if(!button||!text||!count)return;
  const entries=[...summaryStatusState.entries()].filter(([key])=>key!=='healthcore');
  const bad=entries.filter(([,x])=>x.state==='bad');
  const warn=entries.filter(([,x])=>x.state==='warn');
  const health=summaryStatusState.get('healthcore');
  const alerts=Math.max(0,Number(globalStatusData?.operations?.activeAlerts||globalAlerts?.length||0));
  let state='neutral',label='Waiting',attention=0;
  if(bad.length||health?.state==='bad'){state='bad';attention=bad.length+(health?.state==='bad'?1:0);label='Problem';}
  else if(warn.length||health?.state==='warn'||alerts>0){state='warn';attention=warn.length+(health?.state==='warn'?1:0)+(alerts>0?1:0);label='Attention';}
  else if(entries.some(([,x])=>x.state==='good')||health?.state==='good'){state='good';label='Healthy';}
  globalOverallState=state;
  button.className=`globalOverallStatus ${state}`;
  text.textContent=label;
  count.textContent=attention>0?(attention>99?'99+':String(attention)):'';
  count.className='globalStatusCount'+(attention>0?' visible':'');
  const details=[...bad,...warn].slice(0,5).map(([key,x])=>x.detail||key);
  if(health&&(health.state==='bad'||health.state==='warn'))details.unshift(health.detail);
  if(alerts>0)details.unshift(`${alerts} active Action Center alert${alerts===1?'':'s'}`);
  button.title=details.length?details.join(' · '):(state==='good'?'All monitored Suite modules are healthy':'Waiting for module status');
  updateCurrentPageStatus();
}

function initGlobalStatusStrip(){
  document.querySelectorAll('[data-summary-section]').forEach(btn=>{
    btn.onclick=()=>{const target=btn.dataset.summarySection;if(target)setSection(target,true);};
  });
  const overall=$('globalOverallStatus');
  if(overall)overall.onclick=()=>setSection(globalOverallState==='good'?'health':'actionCenter',true);
  updateCurrentPageStatus();
  updateOverallStatus();
}

