function setAntiCheatTab(tab){
  const valid=['overview','players','clientmods','oreshield','packet','history','policy','enforcement','integrity'];
  if(!valid.includes(tab))tab='overview';
  antiCheatActiveTab=tab;
  localStorage.setItem('nsu.antiCheatTab',tab);
  document.querySelectorAll('[data-ac-tab]').forEach(b=>b.classList.toggle('active',b.dataset.acTab===tab));
  document.querySelectorAll('[data-ac-panel]').forEach(p=>p.classList.toggle('active',p.dataset.acPanel===tab));
  if(currentSection==='anticheat'&&tab==='history'&&typeof loadAntiCheatHistory==='function') loadAntiCheatHistory(($('acHistoryPlayerFilter')?.value||'').trim());
}

function initAntiCheatTabs(){
  document.querySelectorAll('[data-ac-tab]').forEach(b=>b.onclick=()=>setAntiCheatTab(b.dataset.acTab));
  document.querySelectorAll('[data-ac-jump]').forEach(b=>b.onclick=()=>setAntiCheatTab(b.dataset.acJump));
  setAntiCheatTab(antiCheatActiveTab);
}

function setBreadcrumb(detail=''){
  const base=sectionLabels[currentSection]||'Dashboard';
  $('breadcrumbCurrent').textContent=detail?`${base} › ${detail}`:base;
}

function setGlobalLiveState(){
  const pulse=$('globalLivePulse');
  const text=$('globalLiveText');
  if(!pulse||!text)return;
  pulse.className='livePulse '+(liveUpdates?'on':'');
  if(liveUpdates){
    const left=Math.max(0,(nextLiveRefreshAt-Date.now())/1000);
    text.textContent=`LIVE ${left.toFixed(1)}s`;
  }else text.textContent='MANUAL';
}

function updateGlobalStatusFromDashboard(d){
  if(!d)return;
  globalStatusData=d;
  lastSuccessfulUpdate=Date.now();
  const p=d.profiler||{},pc=p.current||{},smart=p.smart||{},b=d.blockLogger||{},ops=d.operations||{};
  $('globalHealth').textContent=p.enabled&&smart.available?`${Number(smart.healthScore||0)}/100`:'—';
  $('globalCpu').textContent=p.enabled?`${Number(pc.cpuPercent||0).toFixed(0)}%`:'—';
  $('globalDelay').textContent=p.enabled?`${Number(pc.mainThreadDelayMs||0).toFixed(0)}ms`:'—';
  $('globalPlayers').textContent=Number(d.playersOnline||0).toLocaleString();
  $('globalEntities').textContent=p.enabled?Number(pc.loadedEntities||0).toLocaleString():'—';
  $('globalAlerts').textContent=Number(ops.activeAlerts||0).toLocaleString();
  $('globalQueue').textContent=Number(b.pending||0).toLocaleString();
  $('globalUpdated').textContent=new Date().toLocaleTimeString();
  $('notificationBadge').textContent=Number(ops.activeAlerts||0)>0?String(ops.activeAlerts):'';
  setActionCenterNavState(Number(ops.activeAlerts||0));
  setNavStatus('serverStatus','good','Server status data is responding');
  const blDropped=Number(b.dropped||0),blRejected=Number(b.overflowRejected||0),blPending=Number(b.pending||0),blWriter=Number(b.writerMs||0);
  const blState=(blDropped>0||blRejected>0)?'bad':(blPending>=1000||blWriter>=100?'warn':'good');
  setNavStatus('blocklogger',blState,blState==='bad'?`BlockLogger has ${blDropped} dropped / ${blRejected} rejected event(s)`:blState==='warn'?`BlockLogger pressure: queue ${blPending}, writer ${blWriter}ms`:'BlockLogger healthy');
  if(p.enabled&&smart.available){
    const score=Number(smart.healthScore||0);
    const state=score>=85?'good':score>=65?'warn':'bad';
    setNavStatus('health',state,`System health ${score}/100`);
    setNavStatus('performance',state,`Performance health ${score}/100`);
    setSummaryStatus('healthcore',state,`System health ${score}/100`);
  }else{
    setNavStatus('health','neutral','Performance diagnostics are not currently producing a health score');
    setNavStatus('performance','neutral','Performance diagnostics are not currently producing a health score');
    setSummaryStatus('healthcore','neutral','Performance diagnostics are not currently producing a health score');
  }
  setGlobalLiveState();
}

async function refreshGlobalStatus(force=false){
  const now=Date.now();
  if(!force && now-lastGlobalStatusFetch<15000)return;
  lastGlobalStatusFetch=now;
  try{
    const d=await api('/api/dashboard');
    updateGlobalStatusFromDashboard(d);
  }catch{}
}

function alertTarget(category){
  category=String(category||'').toLowerCase();
  if(category.includes('memory')||category.includes('gc'))return 'memory';
  if(category.includes('compat')||category.includes('command')||category.includes('harmony'))return 'compatibility';
  if(category.includes('entity')||category.includes('chunk'))return 'performance';
  if(category.includes('storage')||category.includes('blocklogger')||category.includes('worldsave'))return 'performance';
  return 'profiler';
}

function updateNotifications(d){
  const alerts=(d&&d.alerts)||[];
  globalAlerts=alerts.filter(x=>x.status==='Active'||x.status==='Investigating');
  $('notificationBadge').textContent=globalAlerts.length?String(globalAlerts.length):'';
  setActionCenterNavState(globalAlerts.length);
  $('notificationList').innerHTML=globalAlerts.length
    ? globalAlerts.slice(0,40).map(x=>`<div class="notificationItem" data-notify-id="${esc(x.id)}">
        <div><span class="badge ${String(x.severity||'').toLowerCase()==='critical'?'low':String(x.severity||'').toLowerCase()==='high'?'medium':'high'}">${esc(x.severity)}</span> <b>${esc(x.title)}</b></div>
        <div class="small" style="margin-top:4px">${esc(x.evidence||'')}</div>
        <div style="display:flex;gap:8px;align-items:center;margin-top:6px">
          <div class="small" style="flex:1">${esc(new Date(Number(x.lastSeenUnixMilliseconds||0)).toLocaleString())}</div>
          <button data-notify-remove="${esc(x.id)}" title="Remove this warning from retained history">Remove</button>
        </div>
      </div>`).join('')
    : '<div class="emptyAction"><b>No active alerts.</b><br>The bell will populate when the Action Center records something that needs attention.</div>';

  document.querySelectorAll('[data-notify-id]').forEach(el=>{
    el.onclick=()=>{
      const a=globalAlerts.find(x=>x.id===el.dataset.notifyId);
      $('notificationPanel').classList.remove('open');
      if(a)setSection(alertTarget(a.category),true);
    };
  });
  document.querySelectorAll('[data-notify-remove]').forEach(btn=>{
    btn.onclick=async e=>{
      e.stopPropagation();
      await removeAlert(btn.dataset.notifyRemove||'');
    };
  });
}

async function openNotifications(){
  $('notificationPanel').classList.toggle('open');
  if(!$('notificationPanel').classList.contains('open'))return;
  try{
    operationsData=await api('/api/operations/overview');
    updateNotifications(operationsData);
  }catch(e){
    $('notificationList').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
  }
}

function commandItems(){
  const base=Object.entries(sectionLabels).map(([section,title])=>({
    type:'Page',title,keywords:`${title} ${section}`,run:()=>setSection(section,true)
  }));
  base.push(
    {type:'Action',title:'Run Entity / Chunk Hotspot Scan',keywords:'entity chunk scan hotspot pressure',run:()=>{setSection('performance',true);setTimeout(()=>scanPerformanceEntities(),250)}},
    {type:'Action',title:'Download Diagnostic Bundle v2',keywords:'diagnostic support zip export bundle webops',run:()=>downloadPerformanceBundle()},
    {type:'Action',title:'Run Compatibility Deep Scan',keywords:'compatibility harmony command conflict mods',run:()=>{setSection('compatibility',true);setTimeout(()=>loadCompatibility(true),250)}},
    {type:'Action',title:'Open SQLite Health',keywords:'database sqlite wal integrity quick check',run:()=>setSection('health',true)},
    {type:'Action',title:'Copy Quick Troubleshooting Report',keywords:'report support clipboard diagnostics',run:()=>copyQuickReport()},
    {type:'Action',title:'Customize Dashboard',keywords:'dashboard hide cards layout widgets',run:()=>openDashboardCustomize()},
    {type:'Action',title:'Toggle Live Updates',keywords:'live refresh polling',run:()=>toggleLiveUpdates()}
  );
  globalAlerts.forEach(a=>base.push({
    type:'Alert',
    title:a.title,
    keywords:`${a.category} ${a.severity} ${a.evidence||''}`,
    hint:a.severity,
    run:()=>setSection(alertTarget(a.category),true)
  }));
  loadedMods.slice(0,200).forEach(m=>base.push({
    type:'Mod',
    title:`${m.modId} ${m.version||''}`.trim(),
    keywords:`${m.modId} ${m.name||''} ${m.fileName||''}`,
    run:()=>openModFilter(m.modId)
  }));
  watchItems.forEach(w=>base.push({
    type:'Pinned',
    title:w.label,
    keywords:`${w.type} ${w.label} ${w.key}`,
    run:()=>openWatchItem(w)
  }));
  return base;
}

function renderCommandResults(){
  const q=String($('commandInput').value||'').trim().toLowerCase();
  let rows=commandItems().filter(x=>!q||`${x.title} ${x.keywords||''}`.toLowerCase().includes(q)).slice(0,24);
  commandResultCache=rows;
  commandSelectedIndex=Math.min(commandSelectedIndex,Math.max(0,rows.length-1));
  $('commandResults').innerHTML=rows.length
    ? rows.map((x,i)=>`<div class="commandItem ${i===commandSelectedIndex?'selected':''}" data-command-index="${i}">
        <span class="commandType">${esc(x.type)}</span>
        <span class="commandTitle">${esc(x.title)}</span>
        <span class="commandHint">${esc(x.hint||'')}</span>
      </div>`).join('')
    : '<div class="emptyAction"><b>No match.</b><br>Try a page name, alert category, mod ID, or action.</div>';
  document.querySelectorAll('[data-command-index]').forEach(el=>{
    el.onmouseenter=()=>{
      commandSelectedIndex=Number(el.dataset.commandIndex||0);
      document.querySelectorAll('[data-command-index]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.commandIndex||0)===commandSelectedIndex));
    };
    el.onclick=()=>runCommandIndex(Number(el.dataset.commandIndex||0));
  });
}

function openCommandPalette(){
  $('notificationPanel').classList.remove('open');
  $('commandOverlay').classList.add('open');
  $('commandInput').value='';
  commandSelectedIndex=0;
  renderCommandResults();
  setTimeout(()=>$('commandInput').focus(),0);
}

function closeCommandPalette(){
  $('commandOverlay').classList.remove('open');
}

function runCommandIndex(index){
  const item=commandResultCache[index];
  if(!item)return;
  closeCommandPalette();
  item.run();
}

function persistWatchlist(){
  localStorage.setItem('nsu.watchItems',JSON.stringify(watchItems.slice(0,50)));
}

function addWatchItem(type,key,label,target,extra={}){
  const id=`${type}:${key}`;
  const existing=watchItems.find(x=>x.id===id);
  if(existing){
    toast('Already pinned.');
    return;
  }
  watchItems.unshift({id,type,key,label,target,...extra});
  watchItems=watchItems.slice(0,50);
  persistWatchlist();
  renderDashboardWatchlist();
  toast('Pinned to Dashboard watchlist.','success');
}

function removeWatchItem(id){
  watchItems=watchItems.filter(x=>x.id!==id);
  persistWatchlist();
  renderDashboardWatchlist();
}

function openWatchItem(item){
  if(!item)return;
  if(item.type==='chunk'){
    openChunkInBlockLogger(Number(item.chunkX||0),Number(item.chunkZ||0),Number(item.dimension||0));
    return;
  }
  if(item.type==='mod'){
    openModFilter(item.key);
    return;
  }
  setSection(item.target||'performance',true);
  if(item.type==='entity')toast(`Pinned entity: ${item.label}`);
}

function renderDashboardWatchlist(){
  const host=$('dashboardWatchlist');
  if(!host)return;
  $('watchCount').textContent=`${watchItems.length} pinned`;
  host.innerHTML=watchItems.length
    ? watchItems.map(w=>`<div class="watchItem">
        <span class="badge medium">${esc(w.type)}</span>
        <b>${esc(w.label)}</b>
        <div class="spacer"></div>
        <button class="iconBtn" data-watch-open="${esc(w.id)}">Open</button>
        <button class="iconBtn" data-watch-remove="${esc(w.id)}">Remove</button>
      </div>`).join('')
    : '<div class="emptyAction"><b>No pinned items yet.</b><br>Use Pin on entity growth, chunk hotspots, or loaded mods.</div>';
  document.querySelectorAll('[data-watch-open]').forEach(b=>b.onclick=()=>openWatchItem(watchItems.find(x=>x.id===b.dataset.watchOpen)));
  document.querySelectorAll('[data-watch-remove]').forEach(b=>b.onclick=()=>removeWatchItem(b.dataset.watchRemove));
}

