function enhanceTableByBodyId(bodyId){
  const tbody=$(bodyId);
  if(!tbody)return;
  const table=tbody.closest('table'),wrap=table&&table.closest('.tableWrap');
  if(!table||!wrap)return;
  table.classList.add('mobileTable');
  const headers=[...table.querySelectorAll('thead th')].map(x=>x.textContent.trim());
  table.querySelectorAll('tbody tr').forEach(row=>{
    [...row.children].forEach((td,i)=>td.dataset.label=headers[i]||'');
  });
  [...table.querySelectorAll('thead th')].forEach((th,index)=>{
    if(th.dataset.sortReady)return;
    th.dataset.sortReady='1';
    th.classList.add('sortable');
    th.innerHTML+=`<span class="sortMark">↕</span>`;
    th.onclick=()=>{
      const dir=th.dataset.sortDir==='asc'?'desc':'asc';
      [...table.querySelectorAll('thead th')].forEach(x=>delete x.dataset.sortDir);
      th.dataset.sortDir=dir;
      const rows=[...tbody.querySelectorAll(':scope > tr')].filter(r=>!r.classList.contains('expandRow'));
      rows.sort((a,b)=>{
        const av=(a.children[index]?.textContent||'').trim(),bv=(b.children[index]?.textContent||'').trim();
        const an=Number(av.replace(/[^0-9+-.]/g,'')),bn=Number(bv.replace(/[^0-9+-.]/g,''));
        const cmp=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'});
        return dir==='asc'?cmp:-cmp;
      });
      rows.forEach(r=>tbody.appendChild(r));
    };
  });
  if(!wrap.dataset.toolsReady){
    wrap.dataset.toolsReady='1';
    const tools=document.createElement('div');
    tools.className='tableTools';
    tools.innerHTML='<input placeholder="Filter this table…"><button data-table-copy>Copy</button><button data-table-csv>CSV</button><button data-table-json>JSON</button>';
    wrap.parentNode.insertBefore(tools,wrap);
    const input=tools.querySelector('input');
    input.oninput=()=>{
      const q=input.value.trim().toLowerCase();
      tbody.querySelectorAll(':scope > tr').forEach(row=>{
        if(row.classList.contains('expandRow'))return;
        row.style.display=!q||row.textContent.toLowerCase().includes(q)?'':'none';
      });
    };
    tools.querySelector('[data-table-copy]').onclick=()=>copyTable(table,'tsv');
    tools.querySelector('[data-table-csv]').onclick=()=>copyTable(table,'csv');
    tools.querySelector('[data-table-json]').onclick=()=>copyTable(table,'json');
  }
}

async function copyText(text,success='Copied.'){
  try{
    await navigator.clipboard.writeText(text);
    toast(success,'success');
  }catch{
    const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();
    try{document.execCommand('copy');toast(success,'success')}catch{toast('Browser blocked clipboard access.','error')}
    ta.remove();
  }
}

function copyTable(table,format){
  const headers=[...table.querySelectorAll('thead th')].map(x=>x.textContent.replace('↕','').trim());
  const rows=[...table.querySelectorAll('tbody tr')].filter(r=>!r.classList.contains('expandRow')&&r.style.display!=='none').map(r=>[...r.children].map(td=>td.textContent.trim()));
  if(format==='json'){
    const data=rows.map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]||''])));
    copyText(JSON.stringify(data,null,2),'Table JSON copied.');
    return;
  }
  const sep=format==='csv'?',':'\t';
  const quote=v=>format==='csv'?`"${String(v).replace(/"/g,'""')}"`:String(v);
  copyText([headers,...rows].map(r=>r.map(quote).join(sep)).join('\n'),format==='csv'?'Table CSV copied.':'Table copied.');
}

