function toggleLiveUpdates(){
  $('liveBtn').click();
}

function retryConnection(){
  $('offlineDetail').textContent='Retrying…';
  checkSession();
}

function toast(message,type='') {
  const host=$('toastHost');
  const el=document.createElement('div');
  el.className='toast '+type;
  el.textContent=message;
  host.appendChild(el);
  setTimeout(()=>{
    el.classList.add('leaving');
    const delay=(currentMotionPreference==='off'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)?0:180;
    setTimeout(()=>el.remove(),delay);
  },4020);
}

function markConnection(ok) {
  $('connectionDot').className='dot '+(ok?'online':'offline');
  $('connectionText').textContent=ok?'Connected':'Connection problem';
  setNavStatus('serverStatus',ok?'good':'bad',ok?'Dashboard connection healthy':'Dashboard connection problem');
  setNavStatus('console',ok?'good':'bad',ok?'Web Console reachable':'Web Console unavailable while dashboard connection is down');
  setNavStatus('web',ok?'good':'bad',ok?'Web dashboard listener reachable':'Web dashboard listener connection problem');
  if(ok){
    lastSuccessfulUpdate=Date.now();
    $('lastUpdate').textContent='Updated '+new Date().toLocaleTimeString();
    $('offlineBanner').classList.remove('visible');
  }else{
    $('offlineBanner').classList.add('visible');
    const age=lastSuccessfulUpdate?Math.max(0,Math.round((Date.now()-lastSuccessfulUpdate)/1000)):null;
    $('offlineDetail').textContent=age===null
      ? 'The browser could not reach the dashboard listener.'
      : `Displaying the last successful data. Last good response ${age}s ago.`;
    $('globalLivePulse').className='livePulse stale';
    $('globalLiveText').textContent='STALE';
  }
}

async function verifyDashboardConnection(){
  if(connectionProbeInFlight)return;
  connectionProbeInFlight=true;
  try{
    const r=await fetch('/api/session',{headers:{'Accept':'application/json'},cache:'no-store'});
    if(r.ok||r.status===401){
      consecutiveProbeFailures=0;
      markConnection(true);
      return;
    }
    consecutiveProbeFailures++;
  }catch{
    consecutiveProbeFailures++;
  }finally{
    connectionProbeInFlight=false;
  }
  if(consecutiveProbeFailures>=2)markConnection(false);
}

function acquireDashboardGetSlot(){
  return new Promise(resolve=>{
    if(activeDashboardGets<MAX_PARALLEL_DASHBOARD_GETS){activeDashboardGets++;resolve();return;}
    queuedDashboardGets.push(resolve);
  });
}
function releaseDashboardGetSlot(){
  activeDashboardGets=Math.max(0,activeDashboardGets-1);
  const next=queuedDashboardGets.shift();
  if(next){activeDashboardGets++;next();}
}

async function apiCore(path, options={}) {
  options=Object.assign({},options);
  options.headers = Object.assign({'Accept':'application/json'}, options.headers || {});
  if (options.method && options.method !== 'GET') {
    options.headers['Content-Type']='application/json';
    if (csrfToken) options.headers['X-CSRF-Token']=csrfToken;
  }

  let responseReceived=false;
  try {
    const r=await fetch(path,options);
    responseReceived=true;
    consecutiveProbeFailures=0;
    markConnection(true);
    let data={};
    try{data=await r.json();}catch{}
    if(r.status===401){showLogin();throw new Error('Authentication required');}
    if(!r.ok)throw new Error(data.error||data.message||`HTTP ${r.status}`);
    return data;
  } catch(e) {
    if(e?.name==='AbortError')throw e;
    // A failed section request does not prove the server/dashboard is offline.
    // Verify with a lightweight session probe before showing the global banner.
    if(!responseReceived && path!=='/api/session')verifyDashboardConnection();
    else if(!responseReceived && path==='/api/session'){
      consecutiveProbeFailures++;
      if(consecutiveProbeFailures>=2)markConnection(false);
    }
    throw e;
  }
}

function api(path, options={}) {
  const method=String(options.method||'GET').toUpperCase();
  if(method!=='GET')return apiCore(path,options);

  // Coalesce identical GETs already in flight so two UI components asking for the
  // same snapshot do not consume two server workers.
  const key=path;
  const existing=inFlightDashboardGets.get(key);
  if(existing)return existing;

  const request=(async()=>{
    await acquireDashboardGetSlot();
    try{return await apiCore(path,options);}
    finally{releaseDashboardGetSlot();}
  })();
  inFlightDashboardGets.set(key,request);
  request.then(
    ()=>{if(inFlightDashboardGets.get(key)===request)inFlightDashboardGets.delete(key);},
    ()=>{if(inFlightDashboardGets.get(key)===request)inFlightDashboardGets.delete(key);}
  );
  return request;
}

function showLogin() {
  document.body.classList.add('loginMode');
  document.body.classList.remove('loginAuthenticated');
  const loginView=$('loginView');
  if(loginView){loginView.style.display='block';loginView.classList.remove('isSubmitting','loginSuccess');}
  document.querySelector('.loginShell')?.classList.remove('loginHidden');
  $('app').style.display='none';
  csrfToken="";
  liveUpdates=false;
  if(liveTimer)clearInterval(liveTimer);
  liveTimer=null;
  if(consoleLiveTimer)clearInterval(consoleLiveTimer);
  consoleLiveTimer=null;consoleLiveEnabled=false;
  setTimeout(()=>{$('loginUser')?.focus();},20);
}

function setLoginBusy(busy){
  const loginView=$('loginView');
  const submit=$('loginForm')?.querySelector('button[type="submit"]');
  if(loginView)loginView.classList.toggle('isSubmitting',!!busy);
  if(submit){
    submit.disabled=!!busy;
    submit.classList.toggle('loading',!!busy);
    submit.setAttribute('aria-busy',busy?'true':'false');
    submit.textContent=busy?t('login.signingIn'):t('login.signin');
  }
}

async function playLoginSuccess(){
  const loginView=$('loginView');
  if(!loginView)return;
  loginView.classList.add('loginSuccess');
  document.body.classList.add('loginAuthenticated');
  await new Promise(resolve=>setTimeout(resolve,340));
}


function mobileNavViewport(){return window.matchMedia('(max-width:880px)').matches;}
function setMobileNavOpen(open){
  const shouldOpen=!!open&&mobileNavViewport();
  document.body.classList.toggle('mobileNavOpen',shouldOpen);
  const toggle=$('mobileNavToggle');if(toggle){toggle.setAttribute('aria-expanded',shouldOpen?'true':'false');toggle.setAttribute('aria-label',shouldOpen?'Close navigation':'Open navigation');}
  const backdrop=$('mobileNavBackdrop');if(backdrop)backdrop.setAttribute('aria-hidden',shouldOpen?'false':'true');
}
function initMobileNavigation(){
  const toggle=$('mobileNavToggle'),close=$('mobileNavClose'),backdrop=$('mobileNavBackdrop');
  if(toggle)toggle.onclick=()=>setMobileNavOpen(!document.body.classList.contains('mobileNavOpen'));
  if(close)close.onclick=()=>setMobileNavOpen(false);
  if(backdrop)backdrop.onclick=()=>setMobileNavOpen(false);
  if(document.body.dataset.mobileNavInitialized!=='1'){
    document.body.dataset.mobileNavInitialized='1';
    document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('mobileNavOpen'))setMobileNavOpen(false);});
    window.addEventListener('resize',()=>{if(!mobileNavViewport())setMobileNavOpen(false);},{passive:true});
  }
}

function setSection(section,load=true) {
  if(!$(section)) section='dashboard';
  const previousSection=currentSection;
  if(previousSection&&previousSection!==section)rememberSectionScroll(previousSection);
  currentSection=section;
  localStorage.setItem('nsu.section',section);
  if(mobileNavViewport())setMobileNavOpen(false);
  document.querySelectorAll('#nav button').forEach(x=>{const active=x.dataset.section===section;x.classList.toggle('active',active);if(x.dataset.section)x.setAttribute('aria-current',active?'page':'false');});
  revealActiveNavGroup(section);
  document.querySelectorAll('main section').forEach(x=>{
    const active=x.id===section;
    x.classList.toggle('active',active);
    if(active&&previousSection!==section){x.classList.remove('sectionEntering');void x.offsetWidth;x.classList.add('sectionEntering');setTimeout(()=>x.classList.remove('sectionEntering'),420);}
  });
  setBreadcrumb();
  updateCurrentPageStatus();
  $('notificationPanel').classList.remove('open');
  refreshGlobalStatus(false);
  setTimeout(enhanceImportantTables,60);
  if(previousSection!==section)restoreSectionScroll(section);

  if(!load)return;
  if(section==='dashboard')loadDashboard();
  if(section==='serverStatus')loadServerStatus(true);
  if(section==='reports')loadReports(true);
  if(section==='playerlist')loadPlayerListConfig();
  if(section==='playercommands')loadPlayerCommands(true);
  if(section==='warps'){loadPlayerCommands(false);loadWarps(true);}
  if(section==='anticheat'){loadAntiCheat(true);if(antiCheatActiveTab==='history')loadAntiCheatHistory(($('acHistoryPlayerFilter')?.value||'').trim());}
  if(section==='chatguard')loadChatGuard(true);
  if(section==='logIntelligence')loadLogIntelligence(true);
  if(section==='actionCenter')loadActionCenter(true);
  if(section==='performance')loadPerformanceCenter(true);
  if(section==='tickDebug')loadTickDebug(true);
  if(section==='memory')loadMemoryCenter(true);
  if(section==='optimizations')loadOptimizations();
  if(section==='blocklogger')loadBlockLoggerMaintenance();
  if(section==='animals'){loadAnimalStatus();loadAnimalRules();}
  if(section==='loginProtection')loadLoginProtection();
  if(section==='announcements')loadAnnouncements();
  if(section==='restarts')loadRestartSchedule(true);
  if(section==='chatDisplay')loadChatDisplay(true);
  if(section==='console')loadConsole(true);
  if(section==='webmap')loadWebMap(true);
  if(section==='customPatches')loadCustomPatches(true);
  if(section==='communityMotd')loadCommunityMotd(true);
  if(section!=='console'&&consoleLiveTimer){clearInterval(consoleLiveTimer);consoleLiveTimer=null;consoleLiveEnabled=false;if($('consoleLive'))$('consoleLive').textContent='Auto Refresh: OFF';}
  if(section==='compatibility')loadCompatibility(false);
  if(section==='mods')loadMods();
  if(section==='admin')loadAdmin(true);
  if(section==='databaseStorage')loadAdminDatabaseStorage(false);
  if(section==='health')loadSystemHealth(true);
  if(section==='operations')loadOperationsAudit(true);
  if(section==='customization')loadSuiteCustomization(true);
  if(section==='discord')loadDiscord(true);
  if(section==='profiler')loadProfiler();
  if(section==='web'){loadWebStatus();loadFeatureGates();if(currentSessionOwner)loadWebAccounts(true);}
}

function showApp(session) {
  document.body.classList.remove('loginMode');
  document.body.classList.add('loginAuthenticated');
  $('loginView').style.display='none';
  document.querySelector('.loginShell')?.classList.add('loginHidden');
  $('app').style.display='block';
  csrfToken=session.csrfToken||"";
  currentSessionUser=session.localAnonymous?"local":(session.username||"admin");
  currentSessionRole=session.role||(session.localAnonymous?"Owner":"Administrator");
  currentSessionOwner=!!session.owner||!!session.localAnonymous;
  safeDiagnosticsModeGlobal=!!session.safeDiagnosticsMode;
  if(safeDiagnosticsModeGlobal){
    liveUpdates=false;
    if(liveTimer)clearInterval(liveTimer);
    liveTimer=null;
    $('liveBtn').textContent=t('ui.liveOff');
    $('liveBtn').classList.remove('active');
  }
  $('headerUser').textContent=`${currentSessionUser} · ${currentSessionRole==='ReadOnly'?'Read Only':currentSessionRole}`;
  if($('readOnlyNotice'))$('readOnlyNotice').classList.toggle('visible',currentSessionRole==='ReadOnly');
  initNavIndicators();
  initPageStatusIndicators();
  initGlobalStatusStrip();
  initNavGroups();
  initMobileNavigation();
  initAntiCheatTabs();
  $('logoutBtn').style.display=session.localAnonymous?'none':'inline-block';
  if($('webAccountsCard'))$('webAccountsCard').style.display=currentSessionOwner?'block':'none';
  setGlobalLiveState();
  renderBlockLoggerSavedViews();
  renderDashboardWatchlist();
  loadSuiteCustomization(false);
  setSection(currentSection,true);
  refreshGlobalStatus(true);
  refreshNavIndicators(true);
  if(/\/leaderboard(?:\.html)?\/?$/i.test(location.pathname)) setTimeout(()=>openPanelLeaderboard(),0);
}

