function clearAnnouncementEditor(){
  announcementEditingId='';
  $('annName').value='';$('annMessage').value='';$('annEnabled').checked=true;$('annMode').value='interval';$('annInterval').value='60';$('annStartTime').value='';$('annDailyTimes').value='';$('annMaxRuns').value='0';
  $('annApplyEditor').textContent='Add / Update Rule';
}

function announcementScheduleText(r){
  if(String(r.mode||'interval').toLowerCase()==='daily')return `Daily at ${(r.dailyTimes||[]).join(', ')||'12:00'}`;
  return `Every ${Number(r.intervalMinutes||60)} min${r.startTime?` from ${r.startTime}`:''}`;
}

function restartFormatRemaining(seconds){
  seconds=Math.max(0,Number(seconds||0));
  const d=Math.floor(seconds/86400);seconds%=86400;
  const h=Math.floor(seconds/3600);seconds%=3600;
  const m=Math.floor(seconds/60);const sec=Math.floor(seconds%60);
  return d?`${d}d ${h}h ${m}m`:h?`${h}h ${m}m`:m?`${m}m ${sec}s`:`${sec}s`;
}
function renderRestartSchedule(){
  const d=restartScheduleData||{};
  if(!$('restartState'))return;
  $('restartState').textContent=d.available===false?'Service unavailable':(d.enabled?'Enabled':'Disabled');
  $('restartEnabled').checked=!!d.enabled;
  $('restartPrimaryTime').value=d.restartTimeUtc||'00:00:00';
  $('restartTimes').value=(d.restartTimesUtc||[]).join(', ');
  $('restartWarnings').value=(d.warningMinutes||[]).join(', ');
  $('restartReason').value=d.reason||'Scheduled server restart';
  $('restartGameAnnouncements').checked=d.announceInGame!==false;
  $('restartDiscordAnnouncements').checked=d.announceToDiscord!==false;
  const next=Number(d.nextRestartUnixMilliseconds||0);
  $('restartMetrics').innerHTML=
    metric('Scheduler',d.enabled?'Enabled':'Disabled',d.enabled?'good':'muted')+
    metric('Next restart',next?new Date(next).toLocaleString():'Not scheduled',next?'warn':'muted',d.nextRestartUtc||'UTC schedule')+
    metric('Remaining',next?restartFormatRemaining(d.remainingSeconds):'—')+
    metric('/restarttime',d.rootRestartTimeOwner||'Unregistered',d.rootRestartTimeOwner==='Newfies Server Essentials'?'good':'warn',d.fallbackCommand||'/nse restarttime');
  $('restartNext').innerHTML=next
    ? `<b>Next restart:</b> ${esc(d.nextRestartUtc||new Date(next).toISOString())} &nbsp; <span class="warn">(${esc(restartFormatRemaining(d.remainingSeconds))})</span>`
    : '<span class="muted">No automatic restart is currently scheduled.</span>';
  $('restartCompat').innerHTML=d.th3EssentialsDetected
    ? '<div class="infoBox"><b>Th3Essentials detected:</b> NSE leaves root <code>/restarttime</code> to Th3Essentials. NSE status remains available as <code>/nse restarttime</code>.</div>'
    : '<div class="infoBox">NSE owns <code>/restarttime</code> only when no other mod already registered it. The namespaced <code>/nse restarttime</code> fallback remains available.</div>';
  const custom=!!d.customRestartScheduled,customAt=Number(d.customRestartUnixMilliseconds||0);
  if($('restartCustomState'))$('restartCustomState').textContent=custom?'Pending':'No one-off restart scheduled.';
  if($('restartCustomSummary'))$('restartCustomSummary').innerHTML=custom
    ? `<b>One-off restart:</b> ${esc(d.customRestartUtc||new Date(customAt).toLocaleString())} · <span class="warn">${esc(restartFormatRemaining(d.customRestartRemainingSeconds))}</span><br><b>Reason:</b> ${esc(d.customRestartReason||'Maintenance')}`
    : 'This one-off schedule is runtime-only and does not modify the recurring UTC schedule.';
  if($('restartCustomCancel'))$('restartCustomCancel').disabled=!custom||currentSessionRole==='ReadOnly';
  if($('restartCustomSchedule'))$('restartCustomSchedule').disabled=currentSessionRole==='ReadOnly';
}
async function loadRestartSchedule(showLoading=true){
  if(showLoading&&$('restartState'))$('restartState').textContent='Loading…';
  try{restartScheduleData=await api('/api/restarts');renderRestartSchedule();}
  catch(e){if($('restartState'))$('restartState').textContent=e.message;}
}
function parseRestartTimes(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean)}
function parseRestartWarnings(value){return String(value||'').split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>0)}
async function saveRestartSchedule(){
  const payload={
    enabled:$('restartEnabled').checked,
    restartTimeUtc:$('restartPrimaryTime').value.trim()||'00:00:00',
    restartTimesUtc:parseRestartTimes($('restartTimes').value),
    warningMinutes:parseRestartWarnings($('restartWarnings').value),
    announceInGame:$('restartGameAnnouncements').checked,
    announceToDiscord:$('restartDiscordAnnouncements').checked,
    reason:$('restartReason').value.trim()||'Scheduled server restart'
  };
  try{const d=await api('/api/restarts/settings',{method:'POST',body:JSON.stringify(payload)});restartScheduleData=d.restarts||restartScheduleData;renderRestartSchedule();toast(d.message||'Automated restart settings saved.','success');}
  catch(e){toast(e.message,'error')}
}
async function restartScheduleAction(action,extra={}){
  const dangerous=action==='skip';
  if(dangerous&&!confirm('Skip the next scheduled automatic restart?'))return;
  try{const d=await api('/api/restarts/action',{method:'POST',body:JSON.stringify({action,...extra})});restartScheduleData=d.restarts||restartScheduleData;renderRestartSchedule();toast(d.message||'Restart schedule updated.','success');}
  catch(e){toast(e.message,'error')}
}
async function scheduleCustomRestart(){
  const minutes=Math.max(1,Math.min(1440,Math.round(Number($('restartCustomMinutes')?.value||10))));
  const reason=String($('restartCustomReason')?.value||'Maintenance').trim()||'Maintenance';
  if(!confirm(`Schedule a server restart in ${minutes} minute${minutes===1?'':'s'}?\n\nReason: ${reason}`))return;
  await restartScheduleAction('schedule-custom',{minutes,reason});
}

function renderAnnouncements(){
  const d=announcementData||{},rows=d.rules||[];
  $('annGlobalEnabled').checked=!!d.enabled;$('annPrefix').value=d.prefix||'';
  $('annState').textContent=`${Number(d.enabledRules||rows.filter(x=>x.enabled).length)}/${Number(d.totalRules||rows.length)} enabled · ${d.timezone||'server local time'}`;
  $('annMetrics').innerHTML=metric('Automation',d.enabled?'Enabled':'Disabled',d.enabled?'good':'warn')+metric('Rules',rows.length)+metric('Enabled rules',rows.filter(x=>x.enabled).length)+metric('Finite schedules',rows.filter(x=>Number(x.maxRuns||0)>0).length);
  $('annRows').innerHTML=rows.length?rows.map(r=>{
    const next=Number(r.nextRunUnixMilliseconds||0);const last=Number(r.lastRunUnixMilliseconds||0);const max=Number(r.maxRuns||0);
    return `<tr><td>${r.enabled?'<span class="badge low">ON</span>':'<span class="badge muted">OFF</span>'}</td><td><b>${esc(r.name||'Announcement')}</b><div class="small">${esc(r.message||'')}</div></td><td>${esc(announcementScheduleText(r))}</td><td>${Number(r.runsCompleted||0)}${max>0?` / ${max}`:' / ∞'}${last?`<div class="small">last ${esc(new Date(last).toLocaleString())}</div>`:''}</td><td>${next?esc(new Date(next).toLocaleString()):'—'}</td><td><div class="rowActions"><button class="iconBtn" data-ann-edit="${esc(r.id)}">Edit</button><button class="iconBtn" data-ann-test="${esc(r.id)}">Test</button><button class="iconBtn" data-ann-reset="${esc(r.id)}">Reset runs</button><button class="iconBtn" data-ann-delete="${esc(r.id)}">Delete</button></div></td></tr>`;
  }).join(''):'<tr><td colspan="6" class="muted">No announcements configured.</td></tr>';
  document.querySelectorAll('[data-ann-edit]').forEach(b=>b.onclick=()=>editAnnouncement(b.dataset.annEdit));
  document.querySelectorAll('[data-ann-test]').forEach(b=>b.onclick=()=>announcementAction('test',b.dataset.annTest));
  document.querySelectorAll('[data-ann-reset]').forEach(b=>b.onclick=()=>announcementAction('reset',b.dataset.annReset));
  document.querySelectorAll('[data-ann-delete]').forEach(b=>b.onclick=()=>deleteAnnouncement(b.dataset.annDelete));
}

async function loadAnnouncements(showLoading=true){
  if(showLoading)$('annState').textContent='Loading…';
  try{announcementData=await api('/api/announcements');renderAnnouncements();}
  catch(e){$('annState').textContent='Load failed';toast(e.message,'error');}
}

function editAnnouncement(id){
  const r=(announcementData.rules||[]).find(x=>String(x.id)===String(id));if(!r)return;
  announcementEditingId=r.id;$('annName').value=r.name||'';$('annMessage').value=r.message||'';$('annEnabled').checked=!!r.enabled;$('annMode').value=String(r.mode||'interval').toLowerCase()==='daily'?'daily':'interval';$('annInterval').value=String(Number(r.intervalMinutes||60));$('annStartTime').value=r.startTime||'';$('annDailyTimes').value=(r.dailyTimes||[]).join(', ');$('annMaxRuns').value=String(Number(r.maxRuns||0));$('annApplyEditor').textContent='Update Rule';
}

function editorAnnouncement(){
  const existing=(announcementData.rules||[]).find(x=>String(x.id)===String(announcementEditingId));
  return {id:announcementEditingId||Math.random().toString(36).slice(2,12),name:$('annName').value.trim()||'Announcement',enabled:$('annEnabled').checked,message:$('annMessage').value.trim(),mode:$('annMode').value,intervalMinutes:Math.max(1,Math.min(10080,Math.floor(Number($('annInterval').value||60)))),startTime:$('annStartTime').value||'',dailyTimes:String($('annDailyTimes').value||'').split(',').map(x=>x.trim()).filter(Boolean),maxRuns:Math.max(0,Math.floor(Number($('annMaxRuns').value||0))),runsCompleted:Number(existing?.runsCompleted||0),lastRunUnixMilliseconds:Number(existing?.lastRunUnixMilliseconds||0),nextRunUnixMilliseconds:Number(existing?.nextRunUnixMilliseconds||0)};
}

async function saveAnnouncements(){
  const payload={schemaVersion:1,enabled:$('annGlobalEnabled').checked,prefix:$('annPrefix').value.trim(),rules:announcementData.rules||[]};
  try{const d=await api('/api/announcements/save',{method:'POST',body:JSON.stringify(payload)});announcementData=d.announcements||announcementData;renderAnnouncements();toast(d.message||'Announcement schedule saved.','success');}
  catch(e){toast(e.message,'error');}
}

async function applyAnnouncementEditor(){
  const rule=editorAnnouncement();if(!rule.message){toast('Announcement message is required.','error');return;}
  if(rule.mode==='daily'&&!rule.dailyTimes.length){toast('Add at least one daily HH:mm time.','error');return;}
  const rows=[...(announcementData.rules||[])];const idx=rows.findIndex(x=>String(x.id)===String(rule.id));if(idx>=0)rows[idx]=rule;else rows.push(rule);announcementData.rules=rows;await saveAnnouncements();clearAnnouncementEditor();
}

async function deleteAnnouncement(id){if(!confirm('Delete this announcement rule?'))return;announcementData.rules=(announcementData.rules||[]).filter(x=>String(x.id)!==String(id));await saveAnnouncements();if(announcementEditingId===id)clearAnnouncementEditor();}
async function announcementAction(action,id){try{const d=await api('/api/announcements/action',{method:'POST',body:JSON.stringify({action,id})});toast(d.message||'Announcement action complete.','success');await loadAnnouncements(false);}catch(e){toast(e.message,'error');}}
$('restartRefresh').onclick=()=>loadRestartSchedule(true);
$('restartSave').onclick=saveRestartSchedule;
$('restartSkip').onclick=()=>restartScheduleAction('skip');
$('restartReload').onclick=()=>restartScheduleAction('reload');
if($('restartCustomSchedule'))$('restartCustomSchedule').onclick=scheduleCustomRestart;
if($('restartCustomCancel'))$('restartCustomCancel').onclick=()=>{if(confirm('Cancel the pending one-off restart?'))restartScheduleAction('cancel-custom');};
$('annRefresh').onclick=()=>loadAnnouncements(true);$('annSave').onclick=saveAnnouncements;$('annClear').onclick=clearAnnouncementEditor;$('annApplyEditor').onclick=applyAnnouncementEditor;

function consoleLineClass(line){
  const x=String(line||''),l=x.toLowerCase();
  if(/\[[^\]]*(fatal|error)[^\]]*\]|\bfatal\b|\berror\b|exception(:|\s)/i.test(x))return 'error';
  if(/\[[^\]]*warn(ing)?[^\]]*\]|\bwarning\b|\bwarn\b/i.test(x))return 'warning';
  if(/\bchat\b|\bmessage\b|broadcast|said:/i.test(x))return 'chat';
  if(/\bcommand\b|executed|caller|webconsole/i.test(x))return 'command';
  if(/\[[^\]]*debug[^\]]*\]|\bdebug\b|verbose/i.test(x))return 'debug';
  if(/\[[^\]]*(notification|event)[^\]]*\]|joined|left the game|server started|server shutdown/i.test(x))return 'event';
  return 'info';
}

function renderConsoleBlockEntityAlerts(snapshot){
  const host=$('consoleBlockAlerts');if(!host)return;
  const rows=(snapshot?.entries||[]);
  if(!rows.length){host.innerHTML='';return;}
  host.innerHTML=rows.map(x=>{
    const key=esc(x.key||'');
    const pos=`${Number(x.x||0)}, ${Number(x.y||0)}, ${Number(x.z||0)}${Number(x.dimension||0)?` · dim ${Number(x.dimension||0)}`:''}`;
    let controls=`<button data-console-bbe-inspect="${key}">Inspect</button>`;
    if(currentSessionRole!=='ReadOnly'){
      controls+=` <button data-console-bbe-teleport="${key}">Teleport</button>`;
      controls+=` <button data-console-bbe-stop="${key}">Stop Tracking</button>`;
      controls+=` <button class="danger" data-console-bbe-remove="${key}">Remove Block Entity</button>`;
      controls+=` <button class="danger" data-console-bbe-replace="${key}" data-block-code="${esc(x.blockCode||'')}">Replace Block</button>`;
    }
    return `<div class="consoleSpamAlert"><div class="alertHead"><div><div class="alertTitle">⚠ Block Entity Spam · ${Number(x.occurrences||0).toLocaleString()} errors</div><div class="alertMeta"><code>${esc(pos)}</code> · <b>${esc(x.blockCode||'')}</b> · <code>${esc(x.blockEntityType||'')}</code> · last ${x.lastSeenUnixMilliseconds?esc(new Date(Number(x.lastSeenUnixMilliseconds)).toLocaleTimeString()):'—'}</div></div><div class="spacer"></div><div class="rowActions">${controls}</div></div><div class="alertError">${esc(x.lastException||'Unknown exception')}<br>${esc(x.lastTopFrame||'')}</div></div>`;
  }).join('');
  document.querySelectorAll('[data-console-bbe-inspect]').forEach(b=>b.onclick=()=>inspectBadBlockEntity(b.dataset.consoleBbeInspect||''));
  document.querySelectorAll('[data-console-bbe-teleport]').forEach(b=>b.onclick=()=>teleportToBadBlockEntity(b.dataset.consoleBbeTeleport||''));
  document.querySelectorAll('[data-console-bbe-stop]').forEach(b=>b.onclick=async()=>{await badBlockEntityAction(b.dataset.consoleBbeStop||'','stop');await loadConsole(false);});
  document.querySelectorAll('[data-console-bbe-remove]').forEach(b=>b.onclick=async()=>{await removeBadBlockEntity(b.dataset.consoleBbeRemove||'');await loadConsole(false);});
  document.querySelectorAll('[data-console-bbe-replace]').forEach(b=>b.onclick=async()=>{await replaceBadBlockEntity(b.dataset.consoleBbeReplace||'',b.dataset.blockCode||'');await loadConsole(false);});
}

function collapseConsoleBlockEntitySpam(lines,hasAlerts){
  if(!hasAlerts)return {lines,suppressed:0};
  const kept=[];let suppress=false,suppressed=0;
  for(const raw of lines){
    const line=String(raw||'');
    const isHeader=line.includes('[Error] At position ')&&line.includes(' threw an error when ticked');
    if(isHeader){suppress=true;suppressed++;continue;}
    if(suppress){
      const trimmed=line.trimStart();
      const isStack=trimmed.startsWith('at ');
      const isException=line.includes('[Error] Exception:');
      if(isStack||isException||!line.includes('[')){suppressed++;continue;}
      suppress=false;
    }
    kept.push(line);
  }
  return {lines:kept,suppressed};
}

function renderConsole(d,keepPosition=false){
  const out=$('consoleOutput'),nearBottom=out.scrollHeight-out.scrollTop-out.clientHeight<70;const rawLines=d.lines||[];
  const alertRows=d.blockEntityAlerts?.entries||[];const collapsed=collapseConsoleBlockEntitySpam(rawLines,alertRows.length>0);const lines=collapsed.lines;
  $('consoleMetrics').innerHTML=metric('CPU',`${Number(d.cpuPercent||0).toFixed(1)}%`,Number(d.cpuPercent||0)>=90?'bad':Number(d.cpuPercent||0)>=75?'warn':'')+metric('RAM',`${Number(d.ramMb||0).toFixed(0)} MB`)+metric('Players',Number(d.playersOnline||0))+metric('Console input',d.commandInputEnabled?'ON':'OFF',d.commandInputEnabled?'warn':'good',d.commandInputEnabled&&d.commandInputExpiresUnixMilliseconds?`expires ${new Date(Number(d.commandInputExpiresUnixMilliseconds)).toLocaleTimeString()}`:'read-only');
  $('consoleState').textContent=`${lines.length} visible line(s)${collapsed.suppressed?` · ${collapsed.suppressed} block-entity spam line(s) collapsed into alert cards`:''} · ${d.logPath||'server-main.log'}`;
  renderConsoleBlockEntityAlerts(d.blockEntityAlerts||{});
  out.innerHTML=lines.map(line=>`<span class="consoleLine ${consoleLineClass(line)}">${esc(line)}</span>`).join('');
  $('consoleInputToggle').textContent=d.commandInputEnabled?'Console Input: ON':'Console Input: OFF';$('consoleInputToggle').classList.toggle('primary',!!d.commandInputEnabled);
  $('consoleCommand').disabled=!d.commandInputEnabled;$('consoleSend').disabled=!d.commandInputEnabled;$('consoleInputMode').disabled=!d.commandInputEnabled;$('consoleInputRow').classList.toggle('consoleInputOff',!d.commandInputEnabled);
  if(!keepPosition||nearBottom)out.scrollTop=out.scrollHeight;
}

async function loadConsole(showLoading=false){if(showLoading)$('consoleState').textContent='Loading…';try{renderConsole(await api('/api/console?lines=350'),true);}catch(e){$('consoleState').textContent='Load failed';toast(e.message,'error');}}
async function toggleConsoleInput(){const on=$('consoleInputToggle').textContent.includes('OFF');if(on&&!confirm('Enable web console input for 15 minutes? This allows the authenticated dashboard session to run Vintage Story server commands and broadcast server messages.'))return;try{await api('/api/console/input',{method:'POST',body:JSON.stringify({enabled:on})});await loadConsole(false);toast(on?'Console input enabled for 15 minutes.':'Console input disabled.','success');}catch(e){toast(e.message,'error');}}
async function sendConsoleCommand(){const command=$('consoleCommand').value.trim();if(!command)return;const mode=$('consoleInputMode').value||'auto';try{const d=await api('/api/console/command',{method:'POST',body:JSON.stringify({command,mode})});$('consoleCommand').value='';toast(d.message||d.status||'Console input sent.',d.success?'success':'error');setTimeout(()=>loadConsole(false),250);}catch(e){toast(e.message,'error');}}
async function consoleServerControl(action){
  if(action==='start'){toast('Start is unavailable from the in-process dashboard. Start the Vintage Story process from Stratum or your external host/supervisor.','warn');return;}
  const restart=action==='restart';
  const label=restart?'restart':'stop';
  if(!confirm(`Gracefully ${label} the server in 5 seconds?${restart?' The process must be relaunched by Stratum or your external supervisor.':''}`))return;
  const expected=restart?'RESTART':'SHUTDOWN';
  const confirmation=prompt(`Safety check: type ${expected} to ${label} the server:`,'')||'';
  if(confirmation.toUpperCase()!==expected)return;
  try{
    $('consoleRestartServer').disabled=true;$('consoleStopServer').disabled=true;
    const d=await api('/api/admin/shutdown',{method:'POST',body:JSON.stringify({action:restart?'restart':'schedule',duration:'5s',reason:restart?'Web console restart':'Web console stop',confirmation:expected})});
    $('consoleState').textContent=restart?'Restart scheduled…':'Shutdown scheduled…';
    toast(d.message||`Server ${label} scheduled.`,'success');
  }catch(e){
    $('consoleRestartServer').disabled=false;$('consoleStopServer').disabled=false;toast(e.message,'error');
  }
}
function toggleConsoleLive(){consoleLiveEnabled=!consoleLiveEnabled;$('consoleLive').textContent=`Auto Refresh: ${consoleLiveEnabled?'ON':'OFF'}`;$('consoleLive').classList.toggle('active',consoleLiveEnabled);if(consoleLiveTimer)clearInterval(consoleLiveTimer);consoleLiveTimer=consoleLiveEnabled?setInterval(()=>{if(!document.hidden&&currentSection==='console')loadConsole(false);},5000):null;if(consoleLiveEnabled)loadConsole(false);}
$('consoleRefresh').onclick=()=>loadConsole(true);$('consoleLive').onclick=toggleConsoleLive;$('consoleInputToggle').onclick=toggleConsoleInput;$('consoleSend').onclick=sendConsoleCommand;$('consoleStartServer').onclick=()=>consoleServerControl('start');$('consoleRestartServer').onclick=()=>consoleServerControl('restart');$('consoleStopServer').onclick=()=>consoleServerControl('stop');$('consoleCommand').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();sendConsoleCommand();}});
$('consoleInputMode').onchange=()=>{const m=$('consoleInputMode').value;$('consoleCommand').placeholder=m==='command'?'Vintage Story command, slash optional':m==='message'?'Server message to broadcast to online players':'Auto: /command executes; plain text broadcasts to players';};

async function loadActionCenter(showLoading=true){
  if(showLoading)$('actionState').textContent='Loading…';

  try{
    operationsData=await api('/api/operations/overview');
    updateNotifications(operationsData);
    renderActionCenter(operationsData);
    setTimeout(enhanceImportantTables,20);
  }catch(e){
    $('actionState').textContent='Load failed';
    $('actionRows').innerHTML=`<tr><td colspan="6" class="bad">${esc(e.message)}</td></tr>`;
  }
}

function renderActionCenter(d){
  const alerts=d.alerts||[];
  const actions=d.actions||[];
  const memory=d.memory||{};
  const playerLoad=d.playerLoad||{};

  const activeAlerts=alerts.filter(x=>x.status==='Active'||x.status==='Investigating');
  const openActions=actions.filter(x=>x.status==='Open'||x.status==='Investigating');

  $('actionState').textContent=d.diagnosticsEnabled
    ? `${activeAlerts.length} active alert(s) · ${openActions.length} open action(s)`
    : 'Diagnostics OFF';

  $('actionMetrics').innerHTML=
    metric('Active alerts',activeAlerts.length,activeAlerts.some(x=>x.severity==='Critical')?'bad':activeAlerts.length?'warn':'good')+
    metric('Open actions',openActions.length,openActions.length?'warn':'good')+
    metric('Memory score',memory.available?`${Number(memory.score||0)}/100`:'Learning',memory.state==='Critical'?'bad':memory.state==='Investigate'?'orange':memory.state==='Watch'?'warn':'good',memory.state||'')+
    metric('Comfortable player range',playerLoad.comfortableRange||'Insufficient history','','Observed, not a hard limit')+
    metric('Audit entries',Number(d.auditCount||0).toLocaleString())+
    metric('Config snapshots',(d.configSnapshots||[]).length);

  const scorecard=d.scorecard||[];
  $('scorecardRows').innerHTML=scorecard.length
    ? scorecard.map(x=>`<div class="card smartSignal ${String(x.state||'').toLowerCase().replace(/[^a-z]+/g,'')} clickableRow" data-score-target="${esc(x.targetSection||'performance')}">
        <div class="small">${esc(x.state)}</div>
        <div style="font-size:20px;font-weight:850">${esc(x.name)} · ${Number(x.score||0)}/100</div>
        <div class="small" style="margin-top:5px">${esc(x.reason||'')}</div>
      </div>`).join('')
    : '<div class="empty">Enable diagnostics to build the scorecard.</div>';

  document.querySelectorAll('[data-score-target]').forEach(card=>{
    card.onclick=()=>setSection(card.dataset.scoreTarget||'performance',true);
  });

  $('actionCount').textContent=`${openActions.length} open / ${actions.length} current`;
  $('actionRows').innerHTML=actions.length
    ? actions.map(x=>`<tr>
        <td class="${x.priority==='High'?'bad':x.priority==='Medium'?'warn':''}"><b>${esc(x.priority)}</b></td>
        <td>${esc(x.category)}</td>
        <td><b>${esc(x.title)}</b></td>
        <td class="codeCell" title="${esc(x.reason)}">${esc(x.reason)}</td>
        <td><b>${esc(x.status)}</b></td>
        <td><div class="actionStatus">
          <button data-action-open="${esc(x.targetSection||'performance')}">Open</button>
          <button data-action-status="${esc(x.id)}" data-status="Investigating">Investigating</button>
          <button data-action-status="${esc(x.id)}" data-status="Resolved">Resolved</button>
          <button data-action-status="${esc(x.id)}" data-status="Ignored">Ignore</button>
        </div></td>
      </tr>`).join('')
    : '<tr><td colspan="6" class="muted">No recommended actions currently require attention.</td></tr>';

  $('alertCount').textContent=`${activeAlerts.length} active / ${alerts.length} retained`;
  $('alertRows').innerHTML=alerts.length
    ? alerts.map(x=>`<tr>
        <td class="${severityClass(x.severity)}"><b>${esc(x.severity)}</b></td>
        <td>${esc(x.category)}</td>
        <td><b>${esc(x.title)}</b></td>
        <td class="codeCell" title="${esc(x.evidence)}">${esc(x.evidence)}</td>
        <td>${Number(x.occurrences||0).toLocaleString()}</td>
        <td>${esc(new Date(Number(x.lastSeenUnixMilliseconds||0)).toLocaleString())}</td>
        <td><b>${esc(x.status)}</b></td>
        <td><div class="actionStatus">
          <button data-alert-status="${esc(x.id)}" data-status="Investigating">Investigating</button>
          <button data-alert-status="${esc(x.id)}" data-status="Resolved">Resolved</button>
          <button data-alert-status="${esc(x.id)}" data-status="Ignored">Ignore</button>
          <button data-alert-remove="${esc(x.id)}" title="Delete this retained warning">Remove</button>
        </div></td>
      </tr>`).join('')
    : '<tr><td colspan="8" class="muted">No alerts have been recorded.</td></tr>';

  document.querySelectorAll('[data-action-open]').forEach(btn=>{
    btn.onclick=()=>setSection(btn.dataset.actionOpen||'performance',true);
  });
  document.querySelectorAll('[data-action-status]').forEach(btn=>{
    btn.onclick=()=>setOperationStatus('/api/operations/action-status',btn.dataset.actionStatus||'',btn.dataset.status||'Open');
  });
  document.querySelectorAll('[data-alert-status]').forEach(btn=>{
    btn.onclick=()=>setOperationStatus('/api/operations/alert-status',btn.dataset.alertStatus||'',btn.dataset.status||'Active');
  });
  document.querySelectorAll('[data-alert-remove]').forEach(btn=>{
    btn.onclick=()=>removeAlert(btn.dataset.alertRemove||'');
  });

  const rows=playerLoad.rows||[];
  const excludedLoadSamples=Number(playerLoad.excludedLifecycleSamples||0);
  $('playerLoadComfort').textContent=`Observed comfortable range: ${playerLoad.comfortableRange||'Insufficient history'}${excludedLoadSamples?` · ${excludedLoadSamples} lifecycle sample${excludedLoadSamples===1?'':'s'} filtered`:''}`;
  $('playerLoadRows').innerHTML=rows.length
    ? rows.map(x=>`<tr>
        <td><b>${esc(x.label)}</b></td>
        <td>${Number(x.samples||0).toLocaleString()}</td>
        <td>${Number(x.averageDelayMs||0).toFixed(1)}ms</td>
        <td class="${Number(x.delayMaxMs||0)>=250?'bad':Number(x.delayMaxMs||0)>=100?'warn':''}">${Number(x.delayMaxMs||0).toFixed(1)}ms</td>
        <td>${Number(x.averageCpuPercent||0).toFixed(1)}%</td>
        <td>${Number(x.cpuMaxPercent||0).toFixed(1)}%</td>
        <td>${Number(x.stallSamples||0).toLocaleString()}</td>
        <td>${Number(x.stallPercent||0).toFixed(1)}%</td>
      </tr>`).join('')
    : '<tr><td colspan="8" class="muted">Player-load history has not been collected yet.</td></tr>';

  const saves=d.worldSaves||[];
  $('worldSaveState').textContent=saves.length
    ? `${saves.length} retained · worst ${Math.max(...saves.map(x=>Number(x.observedMainThreadWindowMs||0))).toFixed(0)}ms`
    : 'No save observation yet';
  $('worldSaveRows').innerHTML=saves.length
    ? saves.slice(0,12).map(x=>`<tr>
        <td>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleString())}</td>
        <td class="${Number(x.observedMainThreadWindowMs||0)>=5000?'bad':Number(x.observedMainThreadWindowMs||0)>=2000?'orange':Number(x.observedMainThreadWindowMs||0)>=750?'warn':''}"><b>${Number(x.observedMainThreadWindowMs||0).toFixed(0)}ms</b></td>
        <td>${Number(x.players||0)}</td>
        <td>${Number(x.delayAtStartMs||0).toFixed(1)}ms</td>
        <td class="${severityClass(x.severity)}">${esc(x.severity)}</td>
      </tr>`).join('')
    : '<tr><td colspan="5" class="muted">Waiting for the next world save.</td></tr>';

  const network=d.networkSamples||[];
  $('networkState').textContent=network.length
    ? `${formatBytesRate(Number(network[0].sentBytesPerSecond||0))} out · ${formatBytesRate(Number(network[0].receivedBytesPerSecond||0))} in`
    : 'Collecting';
  $('networkRows').innerHTML=network.length
    ? network.slice(0,12).map(x=>`<tr>
        <td>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleTimeString())}</td>
        <td>${formatBytesRate(Number(x.sentBytesPerSecond||0))}</td>
        <td>${formatBytesRate(Number(x.receivedBytesPerSecond||0))}</td>
        <td>${Number(x.players||0)}</td>
      </tr>`).join('')
    : '<tr><td colspan="4" class="muted">Collecting network history.</td></tr>';

  renderInstrumentationCards(d.instrumentation||{});
}

function renderInstrumentationCards(d){
  const rows=[
    ['World Save Timing',d.worldSave],
    ['Block-Entity Cost',d.blockEntities],
    ['Network Diagnostics',d.network],
    ['Optimization Safety',d.optimizationSafety]
  ];

  $('instrumentationCards').innerHTML=rows.map(([title,x])=>{
    x=x||{};
    const measured=!!x.measuredNow;
    let extra='';
    if(title==='World Save Timing' && measured){
      extra=`<div class="small" style="margin-top:6px"><b>Last:</b> ${Number(x.lastObservedMs||0).toFixed(0)}ms · <b>Avg:</b> ${Number(x.averageObservedMs||0).toFixed(0)}ms · <b>Worst:</b> ${Number(x.worstObservedMs||0).toFixed(0)}ms</div>`;
    }
    if(title==='Network Diagnostics' && measured){
      extra=`<div class="small" style="margin-top:6px"><b>Out:</b> ${formatBytesRate(Number(x.sentBytesPerSecond||0))} · <b>In:</b> ${formatBytesRate(Number(x.receivedBytesPerSecond||0))} · ${Number(x.players||0)} player(s)</div>`;
    }
    return `<div class="card instrumentCard ${measured?'available':'ready'}">
      <div class="small">${esc(x.status||'Unknown')}</div>
      <div style="font-size:17px;font-weight:800">${esc(title)}</div>
      <div class="small" style="margin-top:6px">${esc(x.summary||'')}</div>
      ${extra}
      ${x.next?`<div class="nextAction"><b>Note:</b> ${esc(x.next)}</div>`:''}
    </div>`;
  }).join('');
}

function formatBytesRate(value){
  if(value>=1024*1024)return `${(value/(1024*1024)).toFixed(2)} MB/s`;
  if(value>=1024)return `${(value/1024).toFixed(1)} KB/s`;
  return `${value.toFixed(0)} B/s`;
}

async function setOperationStatus(path,id,status){
  try{
    await api(path,{method:'POST',body:JSON.stringify({id,status})});
    toast(`Status changed to ${status}.`,'success');
    await loadActionCenter(false);
  }catch(e){
    toast(e.message,'error');
  }
}

async function removeAlert(id){
  if(!id)return;
  if(!confirm('Remove this warning from retained alert history? If the condition is still present, diagnostics may create it again.'))return;
  try{
    await api('/api/operations/alert-remove',{method:'POST',body:JSON.stringify({id})});
    toast('Warning removed.','success');
    await loadActionCenter(false);
  }catch(e){
    toast(e.message,'error');
  }
}

