function renderMemoryCenter(d){
  const a=d.analysis||{};
  $('memoryState').textContent=d.diagnosticsEnabled
    ? `${esc(a.state||'Collecting')} · ${Number(a.sampleCount||0)} sample(s)`
    : 'Diagnostics OFF';
  const memoryState=String(a.state||'Collecting').toLowerCase();
  const memoryTone=!d.diagnosticsEnabled?'neutral':(memoryState==='critical'?'bad':(memoryState==='investigate'||memoryState==='watch'?'warn':'good'));
  setNavStatus('memory',memoryTone,d.diagnosticsEnabled?`Memory / GC ${a.state||'Collecting'} · score ${Number(a.score||0)}/100`:'Memory / GC diagnostics off');

  if(!d.diagnosticsEnabled){
    $('memoryHero').innerHTML='<div class="warning"><b>Diagnostic sampling is OFF.</b> Enable it to build memory/GC history. The expensive manual engine profiler remains separate.</div>';
  }else{
    const cls=a.state==='Critical'?'critical':a.state==='Investigate'?'investigate':a.state==='Watch'?'watch':'healthy';
    $('memoryHero').innerHTML=`<div class="smartHero">
      <div class="healthScore ${cls}">${Number(a.score||0)}</div>
      <div>
        <div class="small">MEMORY / GC HEALTH</div>
        <div style="font-size:20px;font-weight:800">${esc(a.state||'Collecting')}</div>
        <div>${esc(a.finding||'')}</div>
      </div>
    </div>`;
  }

  $('memoryMetrics').innerHTML=
    metric('Managed heap',`${Number(a.heapCurrentMb||0).toFixed(0)} MB`)+
    metric('Heap min / max',`${Number(a.heapMinimumMb||0).toFixed(0)} / ${Number(a.heapMaximumMb||0).toFixed(0)} MB`)+
    metric('Heap slope',`${Number(a.heapSlopeMbPerMinute||0)>=0?'+':''}${Number(a.heapSlopeMbPerMinute||0).toFixed(1)} MB/min`,Number(a.heapSlopeMbPerMinute||0)>=50?'warn':'')+
    metric('Private memory',`${Number(a.privateCurrentMb||0).toFixed(0)} MB`)+
    metric('Private slope',`${Number(a.privateSlopeMbPerMinute||0)>=0?'+':''}${Number(a.privateSlopeMbPerMinute||0).toFixed(1)} MB/min`,Number(a.privateSlopeMbPerMinute||0)>=100?'bad':Number(a.privateSlopeMbPerMinute||0)>=50?'warn':'')+
    metric('Native estimate',`${Number(a.estimatedNativeCurrentMb||0).toFixed(0)} MB`)+
    metric('Native slope',`${Number(a.estimatedNativeSlopeMbPerMinute||0)>=0?'+':''}${Number(a.estimatedNativeSlopeMbPerMinute||0).toFixed(1)} MB/min`,Number(a.estimatedNativeSlopeMbPerMinute||0)>=100?'bad':Number(a.estimatedNativeSlopeMbPerMinute||0)>=50?'warn':'')+
    metric('GC committed / fragmented',`${Number(a.gcCommittedCurrentMb||0).toFixed(0)} / ${Number(a.gcFragmentedCurrentMb||0).toFixed(0)} MB`)+
    metric('Gen0',`+${Number(a.gen0Increase||0)}`)+
    metric('Gen1',`+${Number(a.gen1Increase||0)}`)+
    metric('Gen2',`+${Number(a.gen2Increase||0)}`,Number(a.gen2Increase||0)>=6?'warn':'')+
    metric('Post-GC floor start',`${Number(a.estimatedPostGcFloorStartMb||0).toFixed(0)} MB`)+
    metric('Post-GC floor end',`${Number(a.estimatedPostGcFloorEndMb||0).toFixed(0)} MB`)+
    metric('Floor growth',`${Number(a.estimatedPostGcFloorGrowthMb||0)>=0?'+':''}${Number(a.estimatedPostGcFloorGrowthMb||0).toFixed(0)} MB`,Number(a.estimatedPostGcFloorGrowthMb||0)>=256?'bad':Number(a.estimatedPostGcFloorGrowthMb||0)>=128?'warn':'');

  $('memoryFinding').innerHTML=`<p><b>Finding:</b> ${esc(a.finding||'')}</p><p><b>Recommended:</b> ${esc(a.recommendation||'')}</p>`;
  renderMemoryInspector(d.inspector||{});
  renderMemoryChart();
}


function renderMemoryInspector(inspector){
  inspector=inspector||{};
  const current=inspector.current||{};
  const snapshots=Array.isArray(inspector.snapshots)?inspector.snapshots:[];
  const deep=inspector.deepCapture||{};

  $('memoryInspectorStatus').textContent=snapshots.length?`${snapshots.length} saved`:'Ready';
  $('memorySnapshotCount').textContent=`${snapshots.length} saved snapshot${snapshots.length===1?'':'s'}`;
  $('memoryInspectorSummary').innerHTML=
    metric('Current heap',`${Number(current.managedHeapMb||0).toFixed(0)} MB`)+
    metric('Private memory',`${Number(current.privateMemoryMb||0).toFixed(0)} MB`)+
    metric('GC committed',`${Number(current.gcCommittedMb||0).toFixed(0)} MB`)+
    metric('Fragmented',`${Number(current.gcFragmentedMb||0).toFixed(0)} MB`,Number(current.gcFragmentedMb||0)>=2048?'warn':'')+
    metric('Total allocated',`${Number(current.totalAllocatedMb||0).toFixed(0)} MB`)+
    metric('Gen2 collections',String(Number(current.gen2Collections||0)))+
    metric('Entities / chunks',`${Number(current.loadedEntities||0).toLocaleString()} / ${Number(current.loadedChunks||0).toLocaleString()}`)+
    metric('Players',String(Number(current.players||0)));

  const rows=snapshots.map(s=>`<tr>
    <td>${fmtAdminTime(s.unixMilliseconds)}</td>
    <td>${esc(s.label||'Memory snapshot')}</td>
    <td>${Number(s.managedHeapMb||0).toFixed(0)} MB</td>
    <td>${Number(s.privateMemoryMb||0).toFixed(0)} MB</td>
    <td>${Number(s.gcCommittedMb||0).toFixed(0)} MB</td>
    <td>${Number(s.gcFragmentedMb||0).toFixed(0)} MB</td>
    <td>${Number(s.gen2Collections||0)}</td>
    <td>${Number(s.players||0)}</td>
    <td><button class="danger mini" onclick="deleteMemoryInspectorSnapshot('${esc(s.id||'')}')">Delete</button></td>
  </tr>`).join('');
  $('memoryInspectorSnapshots').innerHTML=rows||'<tr><td colspan="9" class="muted">No snapshots captured.</td></tr>';

  const structures=Array.isArray(current.structures)?current.structures:[];
  $('memoryInspectorStructures').innerHTML=structures.map(x=>`<tr>
    <td>${esc(x.category||'')}</td><td>${esc(x.name||'')}</td><td><code>${esc(x.runtimeType||'')}</code></td>
    <td>${Number(x.count||0).toLocaleString()}</td><td class="small">${esc(x.note||'')}</td>
  </tr>`).join('')||'<tr><td colspan="5" class="muted">No tracked structures available.</td></tr>';

  $('memoryDeepCapture').innerHTML=`
    <p><b>${deep.available?'Deep capture tooling detected':'Deep capture tooling not detected'}</b></p>
    <p>${esc(deep.tool||'')}</p>
    <p>${esc(deep.note||'')}</p>
    <div class="warning" style="margin-top:8px">${esc(deep.warning||'Deep heap capture may pause the server.')}</div>`;

  const options=[{id:'__current',label:'Current live state',unixMilliseconds:Date.now()},...snapshots];
  const optionHtml=options.map(x=>`<option value="${esc(x.id)}">${esc(x.label||'Snapshot')} · ${x.id==='__current'?'now':fmtAdminTime(x.unixMilliseconds)}</option>`).join('');
  const a=$('memoryCompareA'),b=$('memoryCompareB');
  const oldA=a.value,oldB=b.value;
  a.innerHTML=optionHtml;b.innerHTML=optionHtml;
  if(options.some(x=>x.id===oldA))a.value=oldA;
  else a.value=snapshots.length>1?snapshots[1].id:(snapshots.length?snapshots[0].id:'__current');
  if(options.some(x=>x.id===oldB))b.value=oldB;
  else b.value='__current';
  renderMemoryInspectorComparison();
}

function memoryInspectorSnapshotById(id){
  const inspector=(memoryData&&memoryData.inspector)||{};
  if(id==='__current')return inspector.current||null;
  return (inspector.snapshots||[]).find(x=>x.id===id)||null;
}

function signedMemoryDelta(value){
  const n=Number(value||0);
  return `${n>=0?'+':''}${n.toFixed(1)} MB`;
}

function renderMemoryInspectorComparison(){
  const a=memoryInspectorSnapshotById($('memoryCompareA').value);
  const b=memoryInspectorSnapshotById($('memoryCompareB').value);
  if(!a||!b){$('memoryInspectorComparison').innerHTML='Capture at least one snapshot to compare memory state.';return;}
  const delta=(key)=>Number(b[key]||0)-Number(a[key]||0);
  const structureA=new Map((a.structures||[]).map(x=>[`${x.category}|${x.runtimeType}|${x.name}`,x]));
  const structureB=new Map((b.structures||[]).map(x=>[`${x.category}|${x.runtimeType}|${x.name}`,x]));
  const keys=new Set([...structureA.keys(),...structureB.keys()]);
  const growth=[...keys].map(k=>{
    const x=structureA.get(k)||{},y=structureB.get(k)||{};
    return {category:y.category||x.category||'',name:y.name||x.name||'',runtimeType:y.runtimeType||x.runtimeType||'',before:Number(x.count||0),after:Number(y.count||0),delta:Number(y.count||0)-Number(x.count||0)};
  }).filter(x=>x.delta!==0).sort((x,y)=>Math.abs(y.delta)-Math.abs(x.delta)).slice(0,10);
  const elapsed=Math.abs(Number(b.unixMilliseconds||0)-Number(a.unixMilliseconds||0));
  $('memoryInspectorComparison').innerHTML=`
    <div class="grid">
      ${metric('Heap Δ',signedMemoryDelta(delta('managedHeapMb')),delta('managedHeapMb')>256?'warn':'')}
      ${metric('Private Δ',signedMemoryDelta(delta('privateMemoryMb')),delta('privateMemoryMb')>512?'warn':'')}
      ${metric('Committed Δ',signedMemoryDelta(delta('gcCommittedMb')))}
      ${metric('Fragmented Δ',signedMemoryDelta(delta('gcFragmentedMb')),delta('gcFragmentedMb')>512?'warn':'')}
      ${metric('Native estimate Δ',signedMemoryDelta(delta('estimatedNativeMb')))}
      ${metric('Allocated since process start Δ',signedMemoryDelta(delta('totalAllocatedMb')))}
      ${metric('Gen2 Δ',`${delta('gen2Collections')>=0?'+':''}${delta('gen2Collections').toFixed(0)}`)}
      ${metric('Elapsed',`${(elapsed/60000).toFixed(1)} min`)}
    </div>
    <div class="compactNote" style="margin-top:10px">Growth is evidence to investigate, not automatic proof of a leak. Tracked structure counts cover Suite-owned collections and runtime context only.</div>
    <div class="tableWrap" style="margin-top:8px"><table><thead><tr><th>Tracked structure</th><th>Before</th><th>After</th><th>Δ</th></tr></thead><tbody>
      ${growth.map(x=>`<tr><td>${esc(x.category)} · ${esc(x.name)}<div class="small"><code>${esc(x.runtimeType)}</code></div></td><td>${x.before.toLocaleString()}</td><td>${x.after.toLocaleString()}</td><td class="${x.delta>0?'warnText':''}">${x.delta>0?'+':''}${x.delta.toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">No tracked structure count changes.</td></tr>'}
    </tbody></table></div>`;
}

async function captureMemoryInspectorSnapshot(){
  const label=($('memoryInspectorLabel').value||'').trim()||`Memory snapshot ${new Date().toLocaleTimeString()}`;
  try{
    await api('/api/operations/memory-snapshot',{method:'POST',body:JSON.stringify({action:'capture',label})});
    $('memoryInspectorLabel').value='';
    toast('Memory snapshot captured.','success');
    await loadMemoryCenter(false);
  }catch(e){toast(e.message,'error');}
}

async function deleteMemoryInspectorSnapshot(id){
  if(!id||!confirm('Delete this MemLeakInspector snapshot?'))return;
  try{
    await api('/api/operations/memory-snapshot',{method:'POST',body:JSON.stringify({action:'delete',id})});
    toast('Memory snapshot deleted.','success');
    await loadMemoryCenter(false);
  }catch(e){toast(e.message,'error');}
}

async function clearMemoryInspectorSnapshots(){
  if(!confirm('Clear all saved MemLeakInspector snapshots?'))return;
  try{
    const d=await api('/api/operations/memory-snapshot',{method:'POST',body:JSON.stringify({action:'clear'})});
    toast(`Cleared ${Number(d.removed||0)} memory snapshot(s).`,'success');
    await loadMemoryCenter(false);
  }catch(e){toast(e.message,'error');}
}

function renderMemoryChart(){
  const canvas=$('memoryChart');
  if(!canvas||!memoryData)return;

  const rows=memoryData.samples||[];
  const rect=canvas.getBoundingClientRect();
  const dpr=Math.min(2,window.devicePixelRatio||1);
  const w=Math.max(300,rect.width),h=Math.max(200,rect.height);
  canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);
  const ctx=canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,w,h);
  ctx.font='11px system-ui';

  if(!rows.length){
    ctx.fillStyle='#8492a0';
    ctx.fillText('No memory samples yet.',18,24);
    return;
  }

  const pad={l:62,r:12,t:14,b:28};
  const values=rows.map(x=>Number(x.managedHeapMb||0));
  let min=Math.min(...values),max=Math.max(...values);
  const range=Math.max(1,max-min);
  min=Math.max(0,min-range*.08);max=max+range*.08;
  const first=Number(rows[0].unixMilliseconds),last=Number(rows[rows.length-1].unixMilliseconds);
  const span=Math.max(1,last-first);
  const xFor=t=>pad.l+((Number(t)-first)/span)*(w-pad.l-pad.r);
  const yFor=v=>h-pad.b-((Number(v)-min)/(max-min))*(h-pad.t-pad.b);

  chartPlotBackground(ctx,pad,w,h,4,5);
  for(let i=0;i<=4;i++){
    const y=pad.t+(h-pad.t-pad.b)*i/4;
    const v=max-(max-min)*i/4;
    ctx.fillStyle='#748797';ctx.fillText(`${Math.round(v)}MB`,7,y+4);
  }
  const memoryPoints=rows.map(row=>[xFor(row.unixMilliseconds),yFor(row.managedHeapMb)]);
  chartAreaFill(ctx,memoryPoints,h-pad.b,'rgba(93,155,208,.09)');chartLine(ctx,memoryPoints,'#75afe0',2.2);chartEndPoint(ctx,memoryPoints,'#dcebf6');

  for(let i=1;i<rows.length;i++){
    if(Number(rows[i].gen2Collections||0)>Number(rows[i-1].gen2Collections||0)){
      const x=xFor(rows[i].unixMilliseconds);
      ctx.strokeStyle='#ffad66';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,h-pad.b);ctx.stroke();ctx.setLineDash([]);
    }
  }

  ctx.fillStyle='#7d8b99';
  [first,first+span/2,last].forEach((t,i)=>{
    ctx.fillText(new Date(t).toLocaleTimeString(),Math.max(pad.l,Math.min(w-75,pad.l+(w-pad.l-pad.r)*i/2-25)),h-8);
  });
}

async function loadSystemHealth(showLoading=true){
  if(showLoading)$('healthSummary').innerHTML='<div class="empty">Running self-test…</div>';
  try{
    healthData=await api('/api/health');
    renderSystemHealth(healthData);
    loadCollectionAudit();
  }catch(e){
    $('healthSummary').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
  }
}

async function loadCollectionAudit(){
  try{
    collectionAuditData=await api('/api/collection-audit');
    renderCollectionAudit(collectionAuditData);
  }catch(e){
    $('collectionAuditState').textContent='Audit unavailable';
    $('collectionAuditRows').innerHTML=`<tr><td colspan="6" class="bad">${esc(e.message)}</td></tr>`;
  }
}
