function renderOperationsAudit(overview,audit){
  const performanceSnapshots=overview.performanceSnapshots||[];
  const current=overview.currentPerformance||null;

  $('performanceSnapshotRows').innerHTML=performanceSnapshots.length
    ? performanceSnapshots.map(x=>{
        const m=x.metrics||{};
        return `<tr>
          <td>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleString())}</td>
          <td><b>${esc(x.label)}</b></td>
          <td>${Number(x.players||0)}</td>
          <td>${Number(m.healthScore||0)}/100</td>
          <td>${Number(m.delayMedianMs||0).toFixed(1)}ms</td>
          <td>${Number(m.cpuMedianPercent||0).toFixed(1)}%</td>
          <td>${Number(m.p95ProfileTickMs||0).toFixed(1)}ms</td>
          <td><button data-performance-compare="${esc(x.id)}">Compare Current</button></td>
        </tr>`;
      }).join('')
    : '<tr><td colspan="8" class="muted">No performance snapshots yet.</td></tr>';

  document.querySelectorAll('[data-performance-compare]').forEach(btn=>{
    btn.onclick=()=>comparePerformanceSnapshot(btn.dataset.performanceCompare||'',performanceSnapshots,current);
  });

  const snapshots=overview.configSnapshots||[];
  $('configSnapshotState').textContent=`${snapshots.length} stored snapshot(s)`;
  $('configSnapshotRows').innerHTML=snapshots.length
    ? snapshots.map(x=>`<tr>
        <td>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleString())}</td>
        <td><b>${esc(x.label)}</b></td>
        <td>${esc(x.createdBy)}</td>
        <td><span class="badge medium">BlockLogger</span> <span class="badge medium">Web</span> <span class="badge medium">Animals</span> <span class="badge medium">Login Protection</span></td>
        <td><button data-config-restore="${esc(x.id)}">Restore…</button></td>
      </tr>`).join('')
    : '<tr><td colspan="5" class="muted">No configuration snapshots yet. Create one before a major tuning or mod/config change.</td></tr>';

  document.querySelectorAll('[data-config-restore]').forEach(btn=>{
    btn.onclick=()=>restoreConfigSnapshot(btn.dataset.configRestore||'');
  });

  const rows=audit.rows||[];
  $('auditCount').textContent=`${Number(audit.count||0).toLocaleString()} retained`;
  $('auditSummary').innerHTML=`
    <p><b>${rows.length}</b> recent web administration events are shown below.</p>
    <p class="small">The audit records web logins/logouts and supported administrative actions performed through this dashboard. It is separate from BlockLogger's world interaction log.</p>`;

  $('auditRows').innerHTML=rows.length
    ? rows.map(x=>`<tr>
        <td>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleString())}</td>
        <td><b>${esc(x.actor)}</b></td>
        <td>${esc(x.remote)}</td>
        <td>${esc(x.action)}</td>
        <td class="codeCell" title="${esc(x.detail)}">${esc(x.detail)}</td>
        <td class="auditResult ${String(x.result||'').toLowerCase().includes('fail')?'bad':'good'}">${esc(x.result)}</td>
      </tr>`).join('')
    : '<tr><td colspan="6" class="muted">No audit entries recorded yet.</td></tr>';
}

