function comparePerformanceSnapshot(id,snapshots,current){
  const snap=(snapshots||[]).find(x=>x.id===id);
  if(!snap||!current){
    $('performanceCompareResult').innerHTML='<span class="warn">Current diagnostic metrics are not available.</span>';
    return;
  }

  const b=snap.metrics||{},a=current||{};
  const pct=(before,after,floor=1)=>{
    const denom=Math.max(Math.abs(Number(before||0)),floor);
    return (Number(after||0)-Number(before||0))*100/denom;
  };
  const lower=(name,before,after,suffix,floor=1)=>{
    const delta=pct(before,after,floor);
    const cls=delta>8?'bad':delta<-8?'good':'muted';
    return `<div>${esc(name)}: ${Number(before||0).toFixed(1)}${suffix} → ${Number(after||0).toFixed(1)}${suffix} <span class="${cls}">(${delta>=0?'+':''}${delta.toFixed(1)}%)</span></div>`;
  };

  const healthDelta=Number(a.healthScore||0)-Number(b.healthScore||0);
  $('performanceCompareResult').innerHTML=`
    <b>${esc(snap.label)} → Current</b>
    ${lower('Delay',b.delayMedianMs,a.delayMedianMs,'ms',5)}
    ${lower('CPU',b.cpuMedianPercent,a.cpuMedianPercent,'%',10)}
    ${lower('Heap',b.heapMedianMb,a.heapMedianMb,' MB',100)}
    ${lower('Entities',b.entityMedian,a.entityMedian,'',100)}
    ${lower('BL writer',b.writerMedianMs,a.writerMedianMs,'ms',5)}
    ${lower('Profile P95',b.p95ProfileTickMs,a.p95ProfileTickMs,'ms',10)}
    <div>Health: ${Number(b.healthScore||0)} → ${Number(a.healthScore||0)} <span class="${healthDelta< -5?'bad':healthDelta>5?'good':'muted'}">(${healthDelta>=0?'+':''}${healthDelta.toFixed(0)} points)</span></div>`;
}

