function performanceWindowSeconds(){
  const el=$('perfWindow');
  const value=Number(el?.value||1800);
  return [300,900,1800].includes(value)?value:1800;
}

function performanceWindowLabel(){
  const seconds=performanceWindowSeconds();
  return seconds===300?'5-minute':seconds===900?'15-minute':'30-minute';
}

async function loadPerformanceCenter(full=true){
  if(!full){
    await loadPerformanceOverview(true);
    return;
  }

  try{
    // One cached page snapshot replaces the old burst of seven main-thread-backed GETs.
    // Block activity stays separate because it is a database query with its own worker.
    const page=await api(`/api/performance/page-snapshot?window=${performanceWindowSeconds()}`);
    await Promise.allSettled([
      loadPerformanceOverview(true,page.overview||null),
      loadPerformanceTimeline(false,page.timeline||null),
      loadPerformanceEntityScan(false,page.entityScan||null),
      loadPerformanceEntityGrowth(false,page.entityGrowth||null),
      loadPerformanceEnvironment(false,page.environment||null),
      loadPerformanceProviders(false,page.providers||null),
      loadPerformanceConflicts(false,page.conflicts||null)
    ]);
  }catch(e){
    // Compatibility fallback for a mixed deployment during upgrades. Keep requests
    // sequential so the browser still does not stampede the web worker queue.
    await loadPerformanceOverview(true);
    await loadPerformanceTimeline(false);
    await loadPerformanceEntityScan(false);
    await loadPerformanceEntityGrowth(false);
    await loadPerformanceEnvironment(false);
    await loadPerformanceProviders(false);
    await loadPerformanceConflicts(false);
  }

  // Historical BlockLogger activity is open/refresh driven, never part of Live Updates.
  await loadPerformanceBlockActivity(false);
}

async function loadPerformanceOverview(showError=true,preloaded=null){
  try{
    const d=preloaded||await api(`/api/performance/overview?window=${performanceWindowSeconds()}`);
    performanceOverviewData=d;
    renderPerformanceOverview(d);
  }catch(e){
    if(showError)$('perfNotice').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
  }
}

function renderPerformanceOverview(d){
  if(!d||!d.available){
    $('perfNotice').innerHTML=`<div class="warning">${esc((d||{}).message||'Performance diagnostics unavailable.')}</div>`;
    $('perfMetrics').innerHTML='';
    if($('perfQuickRead'))$('perfQuickRead').innerHTML='<div class="empty">Performance diagnostics unavailable.</div>';
    if($('perfWindowSummary'))$('perfWindowSummary').innerHTML='';
    return;
  }

  const cur=d.current||{};
  const smart=d.smart||{};
  const diag=d.diagnosticSummary||{};
  const enabled=!!d.diagnosticsEnabled;

  $('perfNotice').innerHTML=!enabled
    ? '<div class="warning"><b>Diagnostic sampling is OFF.</b> Enable it to build automatic lag incidents and server-specific Smart Diagnosis. The expensive 10s/30s engine profiler remains separate and manual.</div>'
    : '<div class="infoBox"><b>Performance Center active.</b> Automatic diagnostics are lightweight. Major unexplained stalls can trigger a short cooldown-limited 3s engine profile to identify a likely mod; entity/chunk population scans remain manual-only.</div>';

  const score=smart.available?Number(smart.healthScore||0):null;
  $('perfMetrics').innerHTML=
    metric('Smart health',score===null?'Learning':`${score}/100`,score===null?'muted':score<55?'bad':score<75?'orange':score<90?'warn':'good',smart.available?`${smart.state||''} · ${smart.analysisConfidence||'Low'} confidence · data quality ${Number(smart.dataQualityScore||0)}/100 · ${smart.recoveryState||''}`:(smart.state||''))+
    metric('Main-thread delay',enabled?`${Number(cur.mainThreadDelayMs||0).toFixed(1)} ms`:'Off',Number(cur.mainThreadDelayMs||0)>=100?'bad':'')+
    metric('CPU',enabled?`${Number(cur.cpuPercent||0).toFixed(1)}%`:'Off',Number(cur.cpuPercent||0)>=90?'warn':'')+
    metric('Managed heap',enabled?`${Math.round(cur.managedHeapMb||0).toLocaleString()} MB`:'Off')+
    metric('Loaded entities',enabled?Number(cur.loadedEntities||0).toLocaleString():'Off')+
    metric('Loaded chunks',enabled?Number(cur.loadedChunks||0).toLocaleString():'Off')+
    metric('Lag incidents',Number(d.incidentCount||0).toLocaleString(),Number(d.incidentCount||0)>0?'warn':'good','rolling diagnostic window')+
    metric('Worst delay',enabled?`${Number(diag.worstDelayMs||0).toFixed(0)} ms`:'Off',Number(diag.worstDelayMs||0)>=250?'bad':Number(diag.worstDelayMs||0)>=100?'warn':'')+
    metric('Gen2 collections',enabled?`+${Number(diag.gen2Collections||0)}`:'Off')+
    metric('BL max queue',enabled?Number(diag.maxBlockLoggerQueue||0).toLocaleString():'Off');

  renderPerformanceQuickRead(d);

  const suiteTimings=d.suiteTimings||[];
  $('perfSuiteTimings').innerHTML=suiteTimings.length
    ? suiteTimings.slice().sort((a,b)=>Number(b.timePerMinuteMilliseconds||0)-Number(a.timePerMinuteMilliseconds||0)||Number(b.p95Milliseconds||0)-Number(a.p95Milliseconds||0)).slice(0,20).map(x=>`<tr>
        <td><b>${esc(x.name||'')}</b></td>
        <td>${Number(x.callsPerMinute||0).toLocaleString()}</td>
        <td class="${Number(x.timePerMinuteMilliseconds||0)>=1000?'bad':Number(x.timePerMinuteMilliseconds||0)>=250?'warn':''}"><b>${Number(x.timePerMinuteMilliseconds||0).toFixed(1)} ms</b></td>
        <td>${Number(x.lastMilliseconds||0).toFixed(2)} ms</td>
        <td>${Number(x.averageMilliseconds||0).toFixed(2)} ms</td>
        <td>${Number(x.p95Milliseconds||0).toFixed(2)} ms</td>
        <td>${Number(x.maxMilliseconds||0).toFixed(2)} ms</td>
        <td>${Number(x.samples||0).toLocaleString()}</td>
      </tr>`).join('')
    : '<tr><td colspan="8" class="muted">No suite timing samples yet.</td></tr>';

  const incidents=d.incidents||[];
  $('perfIncidentCount').textContent=`${incidents.length} grouped incident(s)`;
  if($('perfClearLagHistory'))$('perfClearLagHistory').disabled=!incidents.length;
  $('perfIncidents').innerHTML=incidents.length
    ? incidents.map(x=>{
        const ts=Number(x.startUnixMilliseconds||0);
        return `<tr class="clickableRow" data-perf-incident="${ts}">
          <td><input class="incidentCompareSelect" type="checkbox" data-incident-compare="${ts}" ${incidentCompareStarts.includes(ts)?'checked':''} title="Select up to two incidents to compare"></td>
          <td><b>${esc(new Date(ts).toLocaleString())}</b></td>
          <td>${Number(x.durationSeconds||0).toFixed(0)}s</td>
          <td class="${severityClass(x.severity)}">${incidentDot(x.severity)}<b>${esc(x.severity)}</b></td>
          <td><b>${esc(x.primaryCategory)}</b></td>
          <td>${x.likelyModId?`<b>${esc(x.likelyModName||x.likelyModId)}</b><div class="small"><code>${esc(x.likelyModId)}</code> · ${esc(x.modConfidence||'Low')}</div>`:'<span class="muted">Not attributed</span>'}</td>
          <td>${confidenceBadge(x.confidence)}</td>
          <td>${Number(x.worstDelayMs||0).toFixed(0)}ms</td>
          <td>${Number(x.maxCpuPercent||0).toFixed(0)}%</td>
          <td class="codeCell" title="${esc(x.evidence)}">${esc(x.evidence)}</td>
          <td class="codeCell" title="${esc(x.nextAction)}">${esc(x.nextAction)}</td>
        </tr>`;
      }).join('')
    : `<tr><td colspan="11" class="muted">${enabled?'No grouped lag incident is currently retained in the rolling window.':'Enable diagnostics to collect automatic lag incidents.'}</td></tr>`;

  document.querySelectorAll('[data-perf-incident]').forEach(row=>{
    row.onclick=e=>{
      if(e.target.matches('[data-incident-compare]'))return;
      openLagIncidentDrawer(Number(row.dataset.perfIncident||0));
    };
  });
  document.querySelectorAll('[data-incident-compare]').forEach(box=>{
    box.onchange=()=>{
      const ts=Number(box.dataset.incidentCompare||0);
      if(box.checked){
        if(incidentCompareStarts.length>=2){
          box.checked=false;
          toast('Select at most two incidents to compare.');
          return;
        }
        if(!incidentCompareStarts.includes(ts))incidentCompareStarts.push(ts);
      }else incidentCompareStarts=incidentCompareStarts.filter(x=>x!==ts);
      updateIncidentCompareButton();
    };
  });
  updateIncidentCompareButton();

  if(d.entityScan){
    performanceEntityScanData=d.entityScan;
    renderPerformanceEntityScan(d.entityScan);
  }
}


function renderPerformanceQuickRead(d){
  const host=$('perfQuickRead'),windowHost=$('perfWindowSummary');
  if(!host||!windowHost)return;

  const enabled=!!d.diagnosticsEnabled,cur=d.current||{},smart=d.smart||{},suite=d.suiteTimings||[];
  if(!enabled){
    host.innerHTML='<div class="card smartSignal watch"><div class="signalTitle">Diagnostics are off</div><div class="small">Enable lightweight diagnostics to identify current bottlenecks and build a rolling performance baseline.</div></div>';
    windowHost.innerHTML='';
    return;
  }

  const score=smart.available?Number(smart.healthScore||0):null;
  const overallClass=score===null?'info':score<55?'critical':score<75?'high':score<90?'watch':'info';
  const primary=(smart.primaryFinding||'').trim()||((smart.signals||[])[0]||{}).title||'No active bottleneck identified';
  const primaryDetail=smart.available
    ? `${smart.state||'Learning'} · ${smart.analysisConfidence||'Low'} confidence · data quality ${Number(smart.dataQualityScore||0)}/100`
    : 'Building the adaptive server baseline.';

  const hottest=suite.slice().sort((a,b)=>Number(b.timePerMinuteMilliseconds||0)-Number(a.timePerMinuteMilliseconds||0)||Number(b.p95Milliseconds||0)-Number(a.p95Milliseconds||0))[0];
  const suiteTime=hottest?Number(hottest.timePerMinuteMilliseconds||0):0;
  const suiteClass=suiteTime>=1000?'critical':suiteTime>=250?'watch':'info';
  const w=d.windowSummary||{};
  const droppedRecent=Number(w.blockLoggerDroppedIncrease||0),droppedTotal=Number(cur.blockLoggerDropped||0),queue=Number(cur.blockLoggerQueue||0),writer=Number(cur.blockLoggerWriterMs||0);
  const backClass=droppedRecent>0||queue>=1000||writer>=100?'critical':queue>=250||writer>=50?'watch':'info';
  const committed=Number(cur.gcCommittedMb||0),frag=Number(cur.gcFragmentedMb||0),fragPct=committed>0?(frag/committed*100):0;
  const memClass=fragPct>=30?'high':fragPct>=15?'watch':'info';
  const autoAttr=d.automaticModAttribution||{};
  const autoProfile=String(autoAttr.latestProfileKind||'').toLowerCase().includes('automatic');
  const autoMod=autoProfile
    ? (autoAttr.likelyModId?`${autoAttr.likelyModName||autoAttr.likelyModId} (${autoAttr.confidence||'Low'})`:'No strong mod match')
    : (autoAttr.enabled?'Armed':'Disabled');
  const autoSub=autoProfile
    ? (autoAttr.likelyModId?`${Number(autoAttr.tickSharePercent||0).toFixed(1)}% profiled tick share · max ${Number(autoAttr.maxSegmentMs||0).toFixed(1)} ms segment`:'The latest automatic burst completed without strong non-core mod attribution.')
    : (autoAttr.enabled?`${Number(autoAttr.profileDurationSeconds||3)}s capture after unexplained 750ms+ stall · ${Number(autoAttr.cooldownSeconds||300)}s cooldown`:'Safe Diagnostics Mode or policy has disabled automatic bursts.');

  host.innerHTML=`
    <div class="card smartSignal ${overallClass}"><div class="signalMeta"><b>Current diagnosis</b>${score===null?'':`<span class="badge ${score<75?'medium':'low'}">${score}/100</span>`}</div><div class="signalTitle">${esc(primary)}</div><div class="small">${esc(primaryDetail)}</div></div>
    <div class="card smartSignal ${suiteClass}"><div class="signalMeta"><b>Highest Suite workload</b></div><div class="signalTitle">${hottest?esc(hottest.name||'Unknown'):'No timing samples yet'}</div><div class="small">${hottest?`${suiteTime.toFixed(1)} ms recorded / min · ${Number(hottest.callsPerMinute||0).toLocaleString()} calls / min · P95 ${Number(hottest.p95Milliseconds||0).toFixed(2)} ms`:'Suite timing registry is still collecting samples.'}</div></div>
    <div class="card smartSignal ${backClass}"><div class="signalMeta"><b>BlockLogger backpressure</b></div><div class="signalTitle">${queue.toLocaleString()} queued · ${writer.toFixed(0)} ms writer</div><div class="small">Dropped in window: ${droppedRecent.toLocaleString()} · lifetime ${droppedTotal.toLocaleString()}. Queue and writer pressure are correlation evidence, not automatic blame.</div></div>
    <div class="card smartSignal ${memClass}"><div class="signalMeta"><b>Memory pressure</b></div><div class="signalTitle">${Math.round(Number(cur.privateMemoryMb||0)).toLocaleString()} MB private</div><div class="small">Managed ${Math.round(Number(cur.managedHeapMb||0)).toLocaleString()} MB · GC fragmentation ${fragPct.toFixed(1)}% · native estimate ${Math.round(Number(cur.estimatedNativeMb||0)).toLocaleString()} MB</div></div>
    <div class="card smartSignal ${autoProfile&&autoAttr.likelyModId?'watch':'info'}"><div class="signalMeta"><b>Automatic mod attribution</b></div><div class="signalTitle">${esc(autoMod)}</div><div class="small">${esc(autoSub)}</div></div>`;

  if(!w.available){windowHost.innerHTML='';return;}
  const signed=(v,digits=0,unit='')=>{const n=Number(v||0);return `${n>0?'+':''}${n.toFixed(digits)}${unit}`;};
  windowHost.innerHTML=
    metric('Window',`${Math.max(1,Math.round(Number(w.durationSeconds||0)/60))} min`,'',`${Number(w.sampleCount||0).toLocaleString()} samples`)+
    metric('Delay P95',`${Number(w.delayP95Ms||0).toFixed(1)} ms`,Number(w.delayP95Ms||0)>=100?'bad':Number(w.delayP95Ms||0)>=50?'warn':'good',`median ${Number(w.delayMedianMs||0).toFixed(1)} ms · max ${Number(w.delayMaxMs||0).toFixed(0)} ms`)+
    metric('CPU P95',`${Number(w.cpuP95Percent||0).toFixed(1)}%`,Number(w.cpuP95Percent||0)>=90?'bad':Number(w.cpuP95Percent||0)>=75?'warn':'',`average ${Number(w.cpuAveragePercent||0).toFixed(1)}% · max ${Number(w.cpuMaxPercent||0).toFixed(1)}%`)+
    metric('Heap change',signed(w.heapDeltaMb,0,' MB'),Number(w.heapDeltaMb||0)>=512?'warn':'',`private ${signed(w.privateMemoryDeltaMb,0,' MB')}`)+
    metric('Entity change',signed(w.entityDelta,0),Math.abs(Number(w.entityDelta||0))>=1000?'warn':'',`current ${Number(cur.loadedEntities||0).toLocaleString()}`)+
    metric('Slow samples',`${Number(w.delayOver100Count||0).toLocaleString()}` ,Number(w.delayOver250Count||0)>0?'warn':'good',`${Number(w.delayOver250Count||0).toLocaleString()} at 250ms+`)+
    metric('Gen2 collections',`+${Number(w.gen2CollectionsIncrease||0)}`,Number(w.gen2CollectionsIncrease||0)>=5?'warn':'')+
    metric('BL peak queue',Number(w.maxBlockLoggerQueue||0).toLocaleString(),Number(w.maxBlockLoggerQueue||0)>=1000?'bad':Number(w.maxBlockLoggerQueue||0)>=250?'warn':'',`writer max ${Number(w.maxBlockLoggerWriterMs||0).toFixed(0)} ms · dropped +${Number(w.blockLoggerDroppedIncrease||0).toLocaleString()}`);
}

function updateIncidentCompareButton(){
  const btn=$('perfCompareBtn');
  if(!btn)return;
  btn.textContent=`Compare Selected (${incidentCompareStarts.length}/2)`;
  btn.disabled=incidentCompareStarts.length!==2;
  if(incidentCompareStarts.length!==2)$('perfIncidentCompare').style.display='none';
}

function compareSelectedIncidents(){
  const incidents=(performanceOverviewData&&performanceOverviewData.incidents)||[];
  const selected=incidentCompareStarts.map(ts=>incidents.find(x=>Number(x.startUnixMilliseconds||0)===Number(ts))).filter(Boolean);
  if(selected.length!==2){
    toast('Select exactly two incidents.');
    return;
  }
  const [a,b]=selected;
  const row=(label,av,bv,fmt=v=>esc(v))=>`<div class="label">${esc(label)}</div><div>${fmt(av)}</div><div>${fmt(bv)}</div>`;
  const host=$('perfIncidentCompare');
  host.style.display='block';
  host.innerHTML=`<div class="cardHeader"><h3>Incident Comparison</h3><div class="spacer"></div><button id="incidentCompareClear">Clear</button></div>
    <div class="compareGrid">
      <div class="label">Metric</div>
      <div><b>${esc(new Date(Number(a.startUnixMilliseconds||0)).toLocaleString())}</b></div>
      <div><b>${esc(new Date(Number(b.startUnixMilliseconds||0)).toLocaleString())}</b></div>
      ${row('Severity',a.severity,b.severity)}
      ${row('Likely area',a.primaryCategory,b.primaryCategory)}
      ${row('Likely mod',a.likelyModId?`${a.likelyModName||a.likelyModId} (${a.modConfidence||'Low'})`:'Not attributed',b.likelyModId?`${b.likelyModName||b.likelyModId} (${b.modConfidence||'Low'})`:'Not attributed')}
      ${row('Confidence',a.confidence,b.confidence)}
      ${row('Duration',a.durationSeconds,b.durationSeconds,v=>`${Number(v||0).toFixed(0)}s`)}
      ${row('Worst delay',a.worstDelayMs,b.worstDelayMs,v=>`<b>${Number(v||0).toFixed(0)}ms</b>`)}
      ${row('Max CPU',a.maxCpuPercent,b.maxCpuPercent,v=>`${Number(v||0).toFixed(0)}%`)}
      ${row('Evidence',a.evidence,b.evidence)}
      ${row('Next action',a.nextAction,b.nextAction)}
    </div>
    <p class="small" style="margin-bottom:0">Comparison highlights recurring patterns; similar metrics are still correlation evidence, not automatic proof of the same root cause.</p>`;
  $('incidentCompareClear').onclick=()=>{
    incidentCompareStarts=[];
    host.style.display='none';
    document.querySelectorAll('[data-incident-compare]').forEach(x=>x.checked=false);
    updateIncidentCompareButton();
  };
  host.scrollIntoView({behavior:'smooth',block:'center'});
}

$('perfCompareBtn').onclick=compareSelectedIncidents;

let lagIncidentDrawerTimestamp=0;
let lagIncidentDrawerPayload=null;

function lagIncidentPhaseSummary(rows){
  const a=Array.isArray(rows)?rows:[];
  if(!a.length)return {samples:0};
  const avg=k=>a.reduce((n,x)=>n+Number(x[k]||0),0)/a.length;
  const max=k=>Math.max(...a.map(x=>Number(x[k]||0)));
  const first=a[0]||{},last=a[a.length-1]||{};
  return {
    samples:a.length,
    delayAvg:avg('mainThreadDelayMs'),delayMax:max('mainThreadDelayMs'),
    cpuAvg:avg('cpuPercent'),cpuMax:max('cpuPercent'),
    heapAvg:avg('managedHeapMb'),heapMax:max('managedHeapMb'),
    workingAvg:avg('workingSetMb'),privateAvg:avg('privateMemoryMb'),nativeAvg:avg('estimatedNativeMb'),
    entitiesAvg:avg('loadedEntities'),entitiesMax:max('loadedEntities'),chunksAvg:avg('loadedChunks'),chunksMax:max('loadedChunks'),
    playersMax:max('players'),queueMax:max('blockLoggerQueue'),writerMax:max('blockLoggerWriterMs'),dropsDelta:Number(last.blockLoggerDropped||0)-Number(first.blockLoggerDropped||0),
    gen0Delta:Number(last.gen0Collections||0)-Number(first.gen0Collections||0),gen1Delta:Number(last.gen1Collections||0)-Number(first.gen1Collections||0),gen2Delta:Number(last.gen2Collections||0)-Number(first.gen2Collections||0)
  };
}

function lagPhaseCard(title,s){
  s=s||{};
  const row=(k,v)=>`<div class="lagPhaseRow"><span>${esc(k)}</span><b>${v}</b></div>`;
  return `<div class="lagPhaseCard"><h4>${esc(title)}</h4>
    ${row('Samples',Number(s.samples||0).toLocaleString())}
    ${row('Delay avg / max',`${Number(s.delayAvg||0).toFixed(1)} / ${Number(s.delayMax||0).toFixed(1)} ms`)}
    ${row('CPU avg / max',`${Number(s.cpuAvg||0).toFixed(1)} / ${Number(s.cpuMax||0).toFixed(1)}%`)}
    ${row('Heap avg / max',`${Number(s.heapAvg||0).toFixed(0)} / ${Number(s.heapMax||0).toFixed(0)} MB`)}
    ${row('Working / private avg',`${Number(s.workingAvg||0).toFixed(0)} / ${Number(s.privateAvg||0).toFixed(0)} MB`)}
    ${row('Estimated native avg',`${Number(s.nativeAvg||0).toFixed(0)} MB`)}
    ${row('Entities avg / max',`${Number(s.entitiesAvg||0).toFixed(0)} / ${Number(s.entitiesMax||0).toFixed(0)}`)}
    ${row('Chunks avg / max',`${Number(s.chunksAvg||0).toFixed(0)} / ${Number(s.chunksMax||0).toFixed(0)}`)}
    ${row('Players max',Number(s.playersMax||0).toLocaleString())}
    ${row('BlockLogger queue / writer max',`${Number(s.queueMax||0).toLocaleString()} / ${Number(s.writerMax||0).toFixed(0)} ms`)}
    ${row('GC Δ 0 / 1 / 2',`+${Number(s.gen0Delta||0)} / +${Number(s.gen1Delta||0)} / +${Number(s.gen2Delta||0)}`)}
    ${row('Audit drops Δ',`${Number(s.dropsDelta||0)>=0?'+':''}${Number(s.dropsDelta||0)}`)}
  </div>`;
}

function closeLagIncidentDrawer(){
  const drawer=$('lagIncidentDrawer'),backdrop=$('lagIncidentBackdrop');
  if(drawer){drawer.classList.remove('open');drawer.style.display='none';drawer.setAttribute('aria-hidden','true');}
  if(backdrop){backdrop.classList.remove('open');backdrop.setAttribute('aria-hidden','true');}
  document.body.classList.remove('lagIncidentDrawerOpen');
}

function renderLagIncidentDrawer(d){
  const host=$('lagIncidentDrawerBody');if(!host)return;
  const x=d.incident||{};
  const before=lagIncidentPhaseSummary(x.before||[]),during=lagIncidentPhaseSummary(x.during||[]),after=lagIncidentPhaseSummary(x.after||[]);
  const causes=(x.causeScores||[]).slice().sort((a,b)=>Number(b.score||0)-Number(a.score||0));
  const db=x.database||{},web=x.webServer||{},audit=x.recentAdminActions||[];
  const growth=(d.entityGrowth||[]).slice(0,10),env=d.environment||null,scan=d.latestEntityScan||null;
  const severity=String(x.severity||'Watch'),sevClass=severity.toLowerCase()==='critical'?'critical':severity.toLowerCase()==='high'?'high':'watch';
  const samples=[...(x.before||[]).map(r=>({...r,_phase:'Before'})),...(x.during||[]).map(r=>({...r,_phase:'Incident'})),...(x.after||[]).map(r=>({...r,_phase:'After'}))].sort((a,b)=>Number(a.unixMilliseconds||0)-Number(b.unixMilliseconds||0));
  const rawRows=samples.map(r=>`<tr><td>${esc(r._phase)}</td><td>${esc(new Date(Number(r.unixMilliseconds||0)).toLocaleTimeString())}</td><td class="${Number(r.mainThreadDelayMs||0)>=250?'bad':Number(r.mainThreadDelayMs||0)>=100?'warn':''}"><b>${Number(r.mainThreadDelayMs||0).toFixed(1)}ms</b></td><td>${Number(r.cpuPercent||0).toFixed(1)}%</td><td>${Number(r.managedHeapMb||0).toFixed(0)} MB</td><td>${Number(r.workingSetMb||0).toFixed(0)} MB</td><td>${Number(r.loadedEntities||0).toLocaleString()}</td><td>${Number(r.loadedChunks||0).toLocaleString()}</td><td>${Number(r.blockLoggerQueue||0).toLocaleString()}</td><td>${Number(r.blockLoggerWriterMs||0)}ms</td><td>${Number(r.gen0Collections||0)}/${Number(r.gen1Collections||0)}/${Number(r.gen2Collections||0)}</td><td>${Number(r.blockLoggerDropped||0).toLocaleString()}</td></tr>`).join('');
  const topTypes=scan&&(scan.entityTypes||[]).slice(0,8);
  const topChunks=scan&&(scan.chunks||[]).slice(0,8);
  $('lagIncidentTitle').textContent=`${severity} Lag Spike`;
  $('lagIncidentSubtitle').textContent=`${new Date(Number(x.startUnixMilliseconds||lagIncidentDrawerTimestamp)).toLocaleString()} · archived black-box incident ${x.id||''}`;
  host.innerHTML=`
    <div class="lagDrawerHero">
      <div class="lagDrawerScore ${sevClass}"><div class="value">${Number(x.worstDelayMs||0).toFixed(0)}</div><div class="label">Worst delay ms</div></div>
      <div><div class="small">${esc(severity.toUpperCase())} · ${esc(x.confidence||'Low')} confidence · ${Number(x.durationSeconds||0).toFixed(0)}s grouped window</div><div style="font-size:22px;font-weight:880;margin:2px 0 5px">${esc(x.primaryCategory||'Unknown cause')}</div><div>${esc(x.evidence||'No diagnostic explanation was stored for this incident.')}</div><div class="small" style="margin-top:7px"><b>Next action:</b> ${esc(x.nextAction||'Reproduce the slowdown and run Incident Capture for deeper engine profiling.')}</div>${x.likelyModId?`<div class="compactNote" style="margin-top:8px"><b>Likely mod:</b> ${esc(x.likelyModName||x.likelyModId)} <code>${esc(x.likelyModId)}</code> · ${esc(x.modConfidence||'Low')} confidence${x.modEvidence?`<br>${esc(x.modEvidence)}`:''}${x.modAttributionSource?`<br><span class="small">Source: ${esc(x.modAttributionSource)}${x.modProfileCompletedUnixMilliseconds?` · profile ${esc(new Date(Number(x.modProfileCompletedUnixMilliseconds)).toLocaleString())}`:''}</span>`:''}</div>`:''}</div>
    </div>
    <div class="lagDrawerMetricGrid">
      <div class="lagDrawerMetric"><div class="label">Started</div><div class="value">${esc(new Date(Number(x.startUnixMilliseconds||0)).toLocaleTimeString())}</div><div class="sub">${esc(new Date(Number(x.startUnixMilliseconds||0)).toLocaleDateString())}</div></div>
      <div class="lagDrawerMetric"><div class="label">Duration</div><div class="value">${Number(x.durationSeconds||0).toFixed(0)}s</div><div class="sub">Ends ${esc(new Date(Number(x.endUnixMilliseconds||x.startUnixMilliseconds||0)).toLocaleTimeString())}</div></div>
      <div class="lagDrawerMetric"><div class="label">Max CPU</div><div class="value">${Number(x.maxCpuPercent||0).toFixed(1)}%</div><div class="sub">during grouped incident</div></div>
      <div class="lagDrawerMetric"><div class="label">Captured</div><div class="value">${x.capturedUnixMilliseconds?esc(new Date(Number(x.capturedUnixMilliseconds)).toLocaleTimeString()):'—'}</div><div class="sub">black-box archive completion</div></div>
    </div>
    <div class="card"><div class="cardHeader"><div><h3>Before / During / After</h3><div class="small">Raw rolling health samples summarized around the lag spike.</div></div></div><div class="lagPhaseGrid">${lagPhaseCard('30s Before',before)}${lagPhaseCard('Incident',during)}${lagPhaseCard('15s After',after)}</div></div>
    ${causes.length?`<div class="card" style="margin-top:10px"><div class="cardHeader"><div><h3>Ranked Cause Evidence</h3><div class="small">Correlation score and evidence captured at the time; this is triage evidence, not automatic proof.</div></div></div><div class="lagCauseGrid">${causes.map(c=>`<div class="lagCauseCard ${Number(c.score||0)>=70?'critical':Number(c.score||0)>=40?'high':Number(c.score||0)>=20?'watch':''}"><div class="cardHeader" style="margin-bottom:4px"><b>${esc(c.category||'Unknown')}</b><div class="spacer"></div>${confidenceBadge(c.confidence||'Low')}</div><div style="font-size:21px;font-weight:880">${Number(c.score||0)}/100</div><div class="small">${esc(c.evidence||'')}</div></div>`).join('')}</div></div>`:''}
    <div class="grid" style="margin-top:10px">
      <div class="card"><div class="cardHeader"><h3>SQLite / BlockLogger</h3></div><div class="small"><b>Queue:</b> ${Number(db.pendingEvents||0).toLocaleString()} / ${Number(db.queueCapacity||0).toLocaleString()}<br><b>Writer last / avg / P95 / max:</b> ${Number(db.lastBatchMilliseconds||0).toFixed(1)} / ${Number(db.averageBatchMilliseconds||0).toFixed(1)} / ${Number(db.p95BatchMilliseconds||0).toFixed(1)} / ${Number(db.maxBatchMilliseconds||0).toFixed(1)} ms<br><b>Query avg / P95 / max:</b> ${Number(db.averageQueryMilliseconds||0).toFixed(1)} / ${Number(db.p95QueryMilliseconds||0).toFixed(1)} / ${Number(db.maxQueryMilliseconds||0).toFixed(1)} ms<br><b>Rows/min:</b> ${Number(db.rowsPerMinute||0).toLocaleString()} · <b>Busy/locked:</b> ${Number(db.busyOrLockedErrors||0).toLocaleString()} · <b>Dropped:</b> ${Number(db.droppedEvents||0).toLocaleString()}<br><b>WAL:</b> ${fmtBytesCompact(db.walBytes||0)} · <b>DB:</b> ${fmtBytesCompact(db.databaseBytes||0)}</div></div>
      <div class="card"><div class="cardHeader"><h3>WebPanel / HTTP</h3></div><div class="small"><b>Request avg / P95 / max:</b> ${Number(web.averageRequestMilliseconds||0).toFixed(1)} / ${Number(web.p95RequestMilliseconds||0).toFixed(1)} / ${Number(web.maxRequestMilliseconds||0).toFixed(1)} ms<br><b>Queue wait avg / P95:</b> ${Number(web.averageQueueWaitMilliseconds||0).toFixed(1)} / ${Number(web.p95QueueWaitMilliseconds||0).toFixed(1)} ms<br><b>Workers:</b> ${Number(web.activeWorkers||0)} / ${Number(web.workerCount||0)} · <b>Queue:</b> ${Number(web.queueDepth||0)} / ${Number(web.queueCapacity||0)}<br><b>Main-thread wait / work avg:</b> ${Number(web.averageMainThreadWaitMilliseconds||0).toFixed(1)} / ${Number(web.averageMainThreadWorkMilliseconds||0).toFixed(1)} ms<br><b>Requests/min:</b> ${Number(web.requestsLastMinute||0).toLocaleString()} · <b>HTTP failures:</b> ${Number(web.failedRequests||web.httpFailures||0).toLocaleString()}</div></div>
    </div>
    ${audit.length?`<div class="card" style="margin-top:10px"><div class="cardHeader"><div><h3>Admin Actions Near Spike</h3><div class="small">Useful for spotting cleanup, teleport, configuration, inventory or server-control actions that overlap the event.</div></div></div><div class="acTimeline acTimelineCompact">${audit.slice(0,12).map(a=>`<div class="acTimelineItem accent"><div class="acTimelineDot"></div><div class="acTimelineWhen"><b>${esc(new Date(Number(a.unixMilliseconds||0)).toLocaleTimeString())}</b>${esc(a.actor||'')}</div><div class="acTimelineBody"><div class="title">${esc(a.action||'Admin action')}</div><div class="meta">${esc(a.result||'')} ${a.detail?`· ${esc(a.detail)}`:''}</div></div></div>`).join('')}</div></div>`:''}
    ${growth.length?`<div class="card" style="margin-top:10px"><div class="cardHeader"><div><h3>Entity Growth Evidence</h3><div class="small">Latest manual scan-to-scan growth rows retained by Performance Center.</div></div></div><div class="tableWrap"><table><thead><tr><th>Entity</th><th>Before</th><th>After</th><th>Δ</th><th>Change</th><th>Severity</th></tr></thead><tbody>${growth.map(g=>`<tr><td><code>${esc(g.code||'')}</code></td><td>${Number(g.before||0).toLocaleString()}</td><td>${Number(g.after||0).toLocaleString()}</td><td>${Number(g.delta||0)>=0?'+':''}${Number(g.delta||0).toLocaleString()}</td><td>${Number(g.percentChange||0)>=0?'+':''}${Number(g.percentChange||0).toFixed(1)}%</td><td class="${severityClass(g.severity)}"><b>${esc(g.severity||'')}</b></td></tr>`).join('')}</tbody></table></div></div>`:''}
    ${scan?`<div class="grid" style="margin-top:10px"><div class="card"><div class="cardHeader"><h3>Latest Manual Entity Scan</h3></div><div class="small"><b>Captured:</b> ${esc(new Date(Number(scan.unixMilliseconds||0)).toLocaleString())}<br><b>Total:</b> ${Number(scan.totalLoadedEntities||0).toLocaleString()} · positioned ${Number(scan.positionedEntities||0).toLocaleString()} · unpositioned ${Number(scan.unpositionedEntities||0).toLocaleString()}</div>${topTypes&&topTypes.length?`<div class="small" style="margin-top:7px"><b>Top types:</b><br>${topTypes.map(t=>`${esc(t.code||t.runtimeType||'unknown')} — ${Number(t.count||0).toLocaleString()} in ${Number(t.chunkCount||0).toLocaleString()} chunk(s)`).join('<br>')}</div>`:''}</div><div class="card"><div class="cardHeader"><h3>Highest-pressure Chunks</h3></div>${topChunks&&topChunks.length?`<div class="small">${topChunks.map(c=>`(${Number(c.chunkX||0)}, ${Number(c.chunkZ||0)}) dim ${Number(c.dimension||0)} — ${Number(c.entityCount||0)} entities, ${Number(c.playerCount||0)} players, pressure ${Number(c.pressureScore||0)}${c.topEntityTypes?` · ${esc(c.topEntityTypes)}`:''}`).join('<br>')}</div>`:'<div class="muted">No chunk hotspot rows in latest manual scan.</div>'}</div></div>`:''}
    ${env?`<div class="card" style="margin-top:10px"><div class="cardHeader"><div><h3>Nearby Mod-Environment Change</h3><div class="small">Closest retained mod fingerprint change within ±30 minutes.</div></div></div><div class="small"><b>Detected:</b> ${esc(new Date(Number(env.detectedUnixMilliseconds||0)).toLocaleString())}<br><b>Result:</b> ${esc(env.result||'')} · ${esc(env.confidence||'Low')} confidence · regression score ${Number(env.regressionScore||0).toFixed(1)}<br><b>Changed mods:</b> ${(env.changedMods||[]).length?(env.changedMods||[]).map(esc).join(' · '):'None listed'}<br><b>Reason:</b> ${esc(env.reason||'')}</div></div>`:''}
    <details class="card" style="margin-top:10px"><summary>Raw captured health samples (${samples.length})</summary><div class="small" style="margin:7px 0">Every before/during/after sample retained in this archived incident.</div><div class="tableWrap lagRawTable"><table><thead><tr><th>Phase</th><th>Time</th><th>Delay</th><th>CPU</th><th>Heap</th><th>Working set</th><th>Entities</th><th>Chunks</th><th>BL queue</th><th>Writer</th><th>GC 0/1/2</th><th>Drops</th></tr></thead><tbody>${rawRows||'<tr><td colspan="12" class="muted">No raw samples retained.</td></tr>'}</tbody></table></div></details>
  `;
}

function renderLagDiagnosticFallback(sample){
  const host=$('lagIncidentDrawerBody');if(!host)return;sample=sample||{};
  $('lagIncidentTitle').textContent=`${sample.severity||'Lag'} Spike`;
  $('lagIncidentSubtitle').textContent=`${new Date(Number(sample.unixMilliseconds||lagIncidentDrawerTimestamp)).toLocaleString()} · live diagnostic sample (no grouped archive)`;
  host.innerHTML=`<div class="warning"><b>This spike does not have a retained grouped black-box archive.</b> Showing every data point still available from the live diagnostic sample.</div>
    <div class="lagDrawerMetricGrid">
      <div class="lagDrawerMetric"><div class="label">Scheduler delay</div><div class="value">${Number(sample.delayMs||0).toFixed(1)} ms</div></div>
      <div class="lagDrawerMetric"><div class="label">CPU</div><div class="value">${Number(sample.cpuPercent||0).toFixed(1)}%</div></div>
      <div class="lagDrawerMetric"><div class="label">Managed heap</div><div class="value">${Number(sample.managedHeapMb||0).toFixed(0)} MB</div><div class="sub">private ${Number(sample.privateMemoryMb||0).toFixed(0)} MB · native est. ${Number(sample.estimatedNativeMb||0).toFixed(0)} MB</div></div>
      <div class="lagDrawerMetric"><div class="label">GC delta 0 / 1 / 2</div><div class="value">+${Number(sample.gen0Delta||0)} / +${Number(sample.gen1Delta||0)} / +${Number(sample.gen2Delta||0)}</div></div>
      <div class="lagDrawerMetric"><div class="label">Entities</div><div class="value">${Number(sample.loadedEntities||0).toLocaleString()}</div><div class="sub">${Number(sample.entityDelta||0)>=0?'+':''}${Number(sample.entityDelta||0)} near spike</div></div>
      <div class="lagDrawerMetric"><div class="label">Chunks</div><div class="value">${Number(sample.loadedChunks||0).toLocaleString()}</div><div class="sub">${Number(sample.chunkDelta||0)>=0?'+':''}${Number(sample.chunkDelta||0)} near spike</div></div>
      <div class="lagDrawerMetric"><div class="label">BlockLogger</div><div class="value">${Number(sample.blockLoggerQueue||0).toLocaleString()} queued</div><div class="sub">writer ${Number(sample.blockLoggerWriterMs||0)} ms · drops +${Number(sample.blockLoggerDroppedDelta||0)}</div></div>
    </div>
    <div class="card"><div class="cardHeader"><h3>Captured Evidence</h3></div><div>${esc(sample.evidence||'No additional correlation evidence was retained for this sample.')}</div></div>
    <div class="infoBox" style="margin-top:10px">For a full before/during/after archive, reproduce the issue with Performance diagnostics enabled or use <b>Tick Debugging → Capture Incident + Profile</b>.</div>`;
}

async function openLagIncidentDrawer(ts){
  lagIncidentDrawerTimestamp=Number(ts||0);
  lagIncidentDrawerPayload=null;
  const drawer=$('lagIncidentDrawer'),backdrop=$('lagIncidentBackdrop'),host=$('lagIncidentDrawerBody');
  if(!drawer||!backdrop||!host)return;
  drawer.style.display='block';drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');
  backdrop.classList.add('open');backdrop.setAttribute('aria-hidden','false');document.body.classList.add('lagIncidentDrawerOpen');
  $('lagIncidentTitle').textContent='Lag Spike Investigation';$('lagIncidentSubtitle').textContent=`Loading archived evidence near ${new Date(lagIncidentDrawerTimestamp).toLocaleString()}…`;host.innerHTML='<div class="empty">Loading every retained data source for this lag spike…</div>';
  try{
    const d=await api(`/api/performance/incident?start=${encodeURIComponent(lagIncidentDrawerTimestamp)}`);
    if(!d.found){
      const live=((lastProfilerPayload||{}).diagnosticIncidents||[]).slice().sort((a,b)=>Math.abs(Number(a.unixMilliseconds||0)-lagIncidentDrawerTimestamp)-Math.abs(Number(b.unixMilliseconds||0)-lagIncidentDrawerTimestamp))[0];
      if(live&&Math.abs(Number(live.unixMilliseconds||0)-lagIncidentDrawerTimestamp)<=5000){renderLagDiagnosticFallback(live);return;}
      host.innerHTML=`<div class="warning">${esc(d.message||'No archived black-box incident matched this marker.')}</div>`;return;
    }
    lagIncidentDrawerPayload=d;renderLagIncidentDrawer(d);
  }catch(e){host.innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;}
}

function lagIncidentTextSummary(){
  const d=lagIncidentDrawerPayload||{},x=d.incident||{};
  return [`${x.severity||'Lag'} incident — ${new Date(Number(x.startUnixMilliseconds||lagIncidentDrawerTimestamp)).toLocaleString()}`,`Worst delay: ${Number(x.worstDelayMs||0).toFixed(1)} ms`,`Duration: ${Number(x.durationSeconds||0).toFixed(0)} s`,`Max CPU: ${Number(x.maxCpuPercent||0).toFixed(1)}%`,`Primary category: ${x.primaryCategory||'Unknown'}`,`Confidence: ${x.confidence||'Low'}`,x.likelyModId?`Likely mod: ${x.likelyModName||x.likelyModId} (${x.modConfidence||'Low'} confidence)`:null,`Evidence: ${x.evidence||''}`,`Next action: ${x.nextAction||''}`].filter(Boolean).join('\n');
}

if($('lagIncidentClose'))$('lagIncidentClose').onclick=closeLagIncidentDrawer;
if($('lagIncidentBackdrop'))$('lagIncidentBackdrop').onclick=closeLagIncidentDrawer;
if($('lagIncidentCopy'))$('lagIncidentCopy').onclick=async()=>{try{await navigator.clipboard.writeText(lagIncidentTextSummary());toast('Lag-spike summary copied.','success');}catch(e){toast('Could not copy summary.','error');}};
if($('lagIncidentOpenTick'))$('lagIncidentOpenTick').onclick=()=>{closeLagIncidentDrawer();setSection('tickDebug',true);};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('lagIncidentDrawer')?.classList.contains('open'))closeLagIncidentDrawer();});

async function openPerformanceIncident(ts){
  selectedPerformanceIncidentStart=ts;
  setBreadcrumb(`Incident ${new Date(Number(ts||0)).toLocaleTimeString()}`);
  $('perfIncidentDetailCard').style.display='block';
  $('perfIncidentDetail').innerHTML='<div class="empty">Loading archived black-box context…</div>';

  try{
    const d=await api(`/api/performance/incident?start=${encodeURIComponent(ts)}`);
    if(!d.found){
      $('perfIncidentDetail').innerHTML=`<div class="warning">${esc(d.message||'Incident archive not found.')}</div>`;
      return;
    }

    const x=d.incident||{};
    const phase=(title,s)=>`<div class="incidentPhase">
      <h4>${esc(title)}</h4>
      <div>Samples <b>${Number((s||{}).samples||0)}</b></div>
      <div>Delay avg/max <b>${Number((s||{}).delayAvg||0).toFixed(1)} / ${Number((s||{}).delayMax||0).toFixed(1)} ms</b></div>
      <div>CPU avg/max <b>${Number((s||{}).cpuAvg||0).toFixed(1)} / ${Number((s||{}).cpuMax||0).toFixed(1)}%</b></div>
      <div>Heap avg <b>${Number((s||{}).heapAvg||0).toFixed(0)} MB</b></div>
      <div>Entities avg <b>${Number((s||{}).entitiesAvg||0).toFixed(0)}</b></div>
      <div>BL queue/writer max <b>${Number((s||{}).queueMax||0)} / ${Number((s||{}).writerMax||0)}ms</b></div>
    </div>`;

    const growth=(d.entityGrowth||[]).slice(0,5);
    const env=d.environment||null;
    const causes=(x.causeScores||[]).slice(0,6);
    const idb=x.database||{};
    const iweb=x.webServer||{};
    const iaudit=(x.recentAdminActions||[]).slice(0,8);

    $('perfIncidentDetail').innerHTML=`
      <div class="smartHero" style="margin-bottom:12px">
        <div class="healthScore ${String(x.severity||'Watch').toLowerCase()==='critical'?'critical':'investigate'}">${Number(x.worstDelayMs||0).toFixed(0)}</div>
        <div>
          <div class="small">ARCHIVED INCIDENT · ${esc(new Date(Number(x.startUnixMilliseconds||0)).toLocaleString())}</div>
          <div style="font-size:20px;font-weight:800">${esc(x.primaryCategory||'Unknown')} · ${esc(x.severity||'')}</div>
          ${x.likelyModId?`<div style="margin-top:5px"><span class="stateChip ${String(x.modConfidence||'').toLowerCase()==='high'?'warn':''}">Likely mod: ${esc(x.likelyModName||x.likelyModId)} · ${esc(x.modConfidence||'Low')} confidence</span></div>`:''}
          <div>${esc(x.evidence||'')}</div>
          ${x.modEvidence?`<div class="small" style="margin-top:5px"><b>Profiler evidence:</b> ${esc(x.modEvidence)}${x.modAttributionSource?` · ${esc(x.modAttributionSource)}`:''}</div>`:''}
          <div class="small" style="margin-top:5px"><b>Next:</b> ${esc(x.nextAction||'')}</div>
        </div>
      </div>
      <div class="incidentDetailGrid">
        ${phase('30s Before',d.beforeSummary)}
        ${phase('Incident',d.duringSummary)}
        ${phase('15s After',d.afterSummary)}
      </div>
      ${causes.length?`<div class="card" style="margin-top:10px"><div class="cardHeader"><h4>Ranked cause evidence</h4><div class="spacer"></div><span class="small">heuristic correlation, not automatic blame</span></div>
        <div class="smartGrid">${causes.map(c=>`<div class="smartSignal ${Number(c.score||0)>=70?'critical':Number(c.score||0)>=40?'high':Number(c.score||0)>=20?'watch':'info'}"><div class="signalMeta"><b>${esc(c.category)}</b><span class="badge ${String(c.confidence||'Low').toLowerCase()}">${esc(c.confidence)} confidence</span></div><div style="font-size:20px;font-weight:850">${Number(c.score||0)}/100</div><div class="small">${esc(c.evidence||'')}</div></div>`).join('')}</div>
      </div>`:''}
      <div class="grid" style="margin-top:10px">
        <div class="card"><h4>SQLite at capture</h4><div class="small">Queue <b>${Number(idb.pendingEvents||0).toLocaleString()}</b> / ${Number(idb.queueCapacity||0).toLocaleString()} · writer last/P95 <b>${Number(idb.lastBatchMilliseconds||0)} / ${Number(idb.p95BatchMilliseconds||0).toFixed(1)}ms</b> · query P95 <b>${Number(idb.p95QueryMilliseconds||0).toFixed(1)}ms</b> · rows/min <b>${Number(idb.rowsPerMinute||0).toLocaleString()}</b> · busy/locked <b>${Number(idb.busyOrLockedErrors||0)}</b> · drops <b>${Number(idb.droppedEvents||0)}</b></div></div>
        <div class="card"><h4>Web server near capture</h4><div class="small">P95 <b>${Number(iweb.p95RequestMilliseconds||0).toFixed(1)}ms</b> · queue P95 <b>${Number(iweb.p95QueueWaitMilliseconds||0).toFixed(1)}ms</b> · workers <b>${Number(iweb.activeWorkers||0)}/${Number(iweb.workerCount||0)}</b> · queue <b>${Number(iweb.queueDepth||0)}/${Number(iweb.queueCapacity||0)}</b> · main wait/work avg <b>${Number(iweb.averageMainThreadWaitMilliseconds||0).toFixed(1)} / ${Number(iweb.averageMainThreadWorkMilliseconds||0).toFixed(1)}ms</b> · ${Number(iweb.requestsLastMinute||0)} req/min</div></div>
      </div>
      ${iaudit.length?`<div class="card" style="margin-top:10px"><h4>Admin actions near incident</h4><div class="small">${iaudit.map(a=>`${esc(new Date(Number(a.unixMilliseconds||0)).toLocaleTimeString())} · ${esc(a.action)} · ${esc(a.result)}`).join('<br>')}</div></div>`:''}
      ${growth.length?`<div class="card" style="margin-top:10px"><h4>Nearby entity growth evidence</h4><div class="small">${growth.map(g=>`${esc(g.code)}: ${Number(g.delta)>=0?'+':''}${Number(g.delta)} (${Number(g.percentChange)>=0?'+':''}${Number(g.percentChange).toFixed(0)}%)`).join(' · ')}</div></div>`:''}
      ${env?`<div class="card" style="margin-top:10px"><h4>Nearby mod-environment change</h4><div class="small">${(env.changedMods||[]).map(esc).join(' · ')} · ${esc(env.result)} · ${esc(env.reason||'')}</div></div>`:''}`;

    $('perfIncidentDetailCard').scrollIntoView({behavior:'smooth',block:'center'});
  }catch(e){
    $('perfIncidentDetail').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
  }
}

async function loadPerformanceTimeline(showLoading=true,preloaded=null){
  if(showLoading)$('perfTimelineState').textContent=`Loading ${performanceWindowLabel()} timeline…`;
  try{
    performanceTimelineData=preloaded||await api(`/api/performance/timeline?window=${performanceWindowSeconds()}`);
    renderPerformanceTimeline();
  }catch(e){
    $('perfTimelineState').textContent=e.message;
  }
}

let performanceIncidentHitAreas=[];
function renderPerformanceTimeline(){
  const canvas=$('perfTimelineCanvas');
  if(!canvas||!performanceTimelineData)return;
  performanceIncidentHitAreas=[];

  const data=performanceTimelineData;
  const samples=data.samples||[];
  const rect=canvas.getBoundingClientRect();
  const dpr=Math.min(2,window.devicePixelRatio||1);
  const w=Math.max(300,rect.width),h=Math.max(200,rect.height);
  canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);
  const ctx=canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,w,h);
  ctx.font='10px system-ui';

  if(!samples.length){
    ctx.fillStyle='#8492a0';ctx.fillText('No performance samples yet.',18,24);
    return;
  }

  const pad={l:75,r:12,t:12,b:26};
  const first=Number(samples[0].unixMilliseconds),last=Number(samples[samples.length-1].unixMilliseconds);
  const span=Math.max(1,last-first);
  const xFor=t=>pad.l+((Number(t)-first)/span)*(w-pad.l-pad.r);
  const bands=[
    {label:'Delay',key:'mainThreadDelayMs',suffix:'ms'},
    {label:'CPU',key:'cpuPercent',suffix:'%'},
    {label:'Entities',key:'loadedEntities',suffix:''},
    {label:'Heap',key:'managedHeapMb',suffix:'MB'}
  ];
  const bh=(h-pad.t-pad.b)/bands.length;

  bands.forEach((band,bi)=>{
    const vals=samples.map(s=>Number(s[band.key]||0));
    let min=Math.min(...vals),max=Math.max(...vals);
    if(band.key==='mainThreadDelayMs'||band.key==='cpuPercent')min=0;
    if(max<=min)max=min+1;
    const top=pad.t+bi*bh,bottom=top+bh-6;
    ctx.fillStyle=bi%2===0?'#0c141a':'#0a1218';ctx.fillRect(pad.l,top,w-pad.l-pad.r,bh-6);
    ctx.strokeStyle='rgba(84,105,121,.22)';ctx.beginPath();ctx.moveTo(pad.l,bottom);ctx.lineTo(w-pad.r,bottom);ctx.stroke();
    ctx.fillStyle='#91a0ae';ctx.fillText(band.label,8,top+14);
    ctx.fillStyle='#708392';ctx.fillText(`${Math.round(max).toLocaleString()}${band.suffix}`,8,top+28);
    const bandPoints=samples.map(row=>{const x=xFor(row.unixMilliseconds);const v=Number(row[band.key]||0);const y=bottom-((v-min)/(max-min))*(bh-20);return[x,y];});
    chartAreaFill(ctx,bandPoints,bottom,'rgba(93,155,208,.055)');chartLine(ctx,bandPoints,'#75afe0',1.8);
  });

  (data.incidents||[]).forEach(x=>{
    const px=xFor(x.startUnixMilliseconds);
    performanceIncidentHitAreas.push({x:px,start:Number(x.startUnixMilliseconds||0),severity:String(x.severity||'Watch')});
    ctx.strokeStyle=String(x.severity||'').toLowerCase()==='critical'?'#ff7474':'#ffad66';
    ctx.globalAlpha=.85;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,h-pad.b);ctx.stroke();ctx.lineWidth=1;ctx.globalAlpha=1;
    ctx.fillStyle=String(x.severity||'').toLowerCase()==='critical'?'#ff7474':'#ffad66';ctx.beginPath();ctx.arc(px,pad.t+5,4,0,Math.PI*2);ctx.fill();
  });
  (data.environmentChanges||[]).forEach(x=>{
    const px=xFor(x.detectedUnixMilliseconds);
    ctx.strokeStyle='#c69cff';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,h-pad.b);ctx.stroke();ctx.setLineDash([]);
  });
  (data.entityScans||[]).forEach(x=>{
    const px=xFor(x.unixMilliseconds);
    ctx.strokeStyle='#8fda72';ctx.setLineDash([2,5]);ctx.beginPath();ctx.moveTo(px,pad.t);ctx.lineTo(px,h-pad.b);ctx.stroke();ctx.setLineDash([]);
  });

  ctx.fillStyle='#748392';
  [first,first+span/2,last].forEach((t,i)=>{
    const label=new Date(t).toLocaleTimeString();
    const px=pad.l+(w-pad.l-pad.r)*i/2;
    ctx.fillText(label,Math.max(pad.l,Math.min(w-80,px-25)),h-7);
  });

  $('perfTimelineState').textContent=`${performanceWindowLabel()} · ${samples.length} sample points · orange/red=lag (click for incident drawer) · purple=mod change · green=entity scan`;
}

if($('perfTimelineCanvas')){
  $('perfTimelineCanvas').addEventListener('mousemove',e=>{
    const canvas=$('perfTimelineCanvas'),rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left;
    const hit=performanceIncidentHitAreas.slice().sort((a,b)=>Math.abs(a.x-x)-Math.abs(b.x-x))[0];
    canvas.classList.toggle('lagIncidentMarkerHover',!!hit&&Math.abs(hit.x-x)<=9);
    canvas.title=hit&&Math.abs(hit.x-x)<=9?`${hit.severity} lag spike — click for full incident breakdown`:'';
  });
  $('perfTimelineCanvas').addEventListener('mouseleave',()=>{$('perfTimelineCanvas').classList.remove('lagIncidentMarkerHover');$('perfTimelineCanvas').title='';});
  $('perfTimelineCanvas').addEventListener('click',e=>{
    const canvas=$('perfTimelineCanvas'),rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left;
    const hit=performanceIncidentHitAreas.slice().sort((a,b)=>Math.abs(a.x-x)-Math.abs(b.x-x))[0];
    if(hit&&Math.abs(hit.x-x)<=10)openLagIncidentDrawer(hit.start);
  });
}

async function loadPerformanceEntityGrowth(showLoading=true,preloaded=null){
  if(showLoading)$('perfGrowthState').textContent='Loading growth history…';
  try{
    const d=preloaded||await api('/api/performance/entity-growth');
    const rows=d.rows||[];
    $('perfGrowthState').textContent=`${Number(d.scans||0)} stored scan(s)`;
    const flagged=rows.filter(x=>x.severity==='Critical'||x.severity==='High'||x.severity==='Watch');
    const biggest=rows.slice().sort((a,b)=>Number(b.delta||0)-Number(a.delta||0))[0]||null;
    $('perfGrowthSummary').innerHTML=
      metric('Stored scans',Number(d.scans||0).toLocaleString())+
      metric('Changed entity types',rows.length.toLocaleString())+
      metric('Flagged for review',flagged.length.toLocaleString(),flagged.some(x=>x.severity==='Critical')?'bad':flagged.length?'warn':'good')+
      metric('Largest increase',biggest?`${biggest.code} · ${Number(biggest.delta||0)>=0?'+':''}${Number(biggest.delta||0).toLocaleString()}`:'—',biggest&&Number(biggest.delta||0)>0?'warn':'');
    $('perfEntityGrowth').innerHTML=rows.length
      ? rows.slice(0,50).map((x,i)=>`<tr>
          <td><b>${esc(x.code)}</b></td>
          <td>${Number(x.before||0).toLocaleString()}</td>
          <td>${Number(x.after||0).toLocaleString()}</td>
          <td class="${Number(x.delta||0)>0?'warn':'good'}"><b>${Number(x.delta||0)>=0?'+':''}${Number(x.delta||0).toLocaleString()}</b></td>
          <td class="${Number(x.percentChange||0)>=40?'warn':''}"><b>${Number(x.percentChange||0)>=0?'+':''}${Number(x.percentChange||0).toFixed(1)}%</b></td>
          <td class="${severityClass(x.severity)}"><b>${esc(x.severity)}</b></td>
          <td class="codeCell" title="${esc(x.reason)}">${esc(x.reason)}</td>
          <td><div class="rowActions"><button class="iconBtn" data-growth-expand="${i}">Details</button><button class="iconBtn" data-growth-pin="${esc(x.code)}">Pin</button></div></td>
        </tr>
        <tr class="expandRow" id="growthDetail${i}" style="display:none"><td colspan="8"><div class="expandPanel">
          <div><b>${esc(x.code)}</b><div class="small">Before ${Number(x.before||0).toLocaleString()} → After ${Number(x.after||0).toLocaleString()}</div><div class="${severityClass(x.severity)}" style="margin-top:5px"><b>${esc(x.severity)}</b></div></div>
          <div><b>Why it was classified this way</b><div class="small" style="margin-top:4px">${esc(x.reason)}</div><div class="rowActions" style="margin-top:8px"><button class="iconBtn" data-growth-pin="${esc(x.code)}">Pin entity</button><button class="iconBtn" data-growth-animals>Open Animal Limiter</button><button class="iconBtn" data-growth-rescan>Run another scan</button></div></div>
        </div></td></tr>`).join('')
      : '<tr><td colspan="8"><div class="emptyAction"><b>Two manual entity scans are required.</b><br>Run a scan now, wait for the workload you want to compare, then run a second scan.<div style="margin-top:8px"><button id="growthEmptyScan">Run Entity / Chunk Scan</button></div></div></td></tr>';

    document.querySelectorAll('[data-growth-expand]').forEach(btn=>btn.onclick=()=>{
      const row=$(`growthDetail${btn.dataset.growthExpand}`);
      if(row)row.style.display=row.style.display==='none'?'table-row':'none';
    });
    document.querySelectorAll('[data-growth-pin]').forEach(btn=>btn.onclick=()=>addWatchItem('entity',btn.dataset.growthPin,btn.dataset.growthPin,'performance'));
    document.querySelectorAll('[data-growth-animals]').forEach(btn=>btn.onclick=()=>setSection('animals',true));
    document.querySelectorAll('[data-growth-rescan]').forEach(btn=>btn.onclick=()=>scanPerformanceEntities());
    if($('growthEmptyScan'))$('growthEmptyScan').onclick=()=>scanPerformanceEntities();
    setTimeout(enhanceImportantTables,20);
  }catch(e){
    $('perfGrowthState').textContent=e.message;
  }
}

async function loadPerformanceEnvironment(showLoading=true,preloaded=null){
  if(showLoading)$('perfEnvironmentState').textContent='Loading…';
  try{
    performanceEnvironmentData=preloaded||await api('/api/performance/environment');
    const history=performanceEnvironmentData.history||[];
    const current=performanceEnvironmentData.current||null;
    $('perfEnvironmentState').textContent=current
      ? `${(current.mods||[]).length} mods · fingerprint ${String(current.fingerprint||'').slice(0,10)}`
      : 'Waiting for diagnostics';

    $('perfEnvironmentHistory').innerHTML=history.length
      ? history.map(x=>`<tr>
          <td>${esc(new Date(Number(x.detectedUnixMilliseconds||0)).toLocaleString())}</td>
          <td class="codeCell" title="${esc((x.changedMods||[]).join(' | '))}">${(x.changedMods||[]).map(m=>`<span class="badge medium">${esc(m)}</span>`).join(' ')}</td>
          <td class="${String(x.result||'').toLowerCase()==='regressed'?'bad':String(x.result||'').toLowerCase()==='improved'?'good':'warn'}"><b>${esc(x.result)}</b></td>
          <td>${Number(x.regressionScore||0)>=0?'+':''}${Number(x.regressionScore||0).toFixed(1)}%</td>
          <td>${esc(x.confidence)}</td>
          <td class="codeCell" title="${esc(x.reason)}">${esc(x.reason)}</td>
        </tr>`).join('')
      : '<tr><td colspan="6" class="muted">No mod/version environment change has been recorded yet.</td></tr>';
  }catch(e){
    $('perfEnvironmentState').textContent=e.message;
  }
}

async function downloadPerformanceBundle(){
  const btn=$('perfDownloadBundle');
  btn.disabled=true;
  try{
    const r=await fetch('/api/performance/bundle',{headers:{'Accept':'application/zip'}});
    if(r.status===401){showLogin();throw new Error('Authentication required');}
    if(!r.ok){
      let message=`HTTP ${r.status}`;
      try{const j=await r.json();message=j.error||message;}catch{}
      throw new Error(message);
    }
    const blob=await r.blob();
    const disposition=r.headers.get('Content-Disposition')||'';
    const match=/filename="([^"]+)"/.exec(disposition);
    const name=match?match[1]:`newfies-diagnostics-${new Date().toISOString().replace(/[:.]/g,'-')}.zip`;
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1200);
    toast('Diagnostic Bundle v2 downloaded.','success');
  }catch(e){
    toast(e.message,'error');
  }finally{
    btn.disabled=false;
  }
}

function focusPerformanceIncident(ts){
  profilerRangeSeconds=1800;
  localStorage.setItem('nsu.profilerRange','1800');
  



document.querySelectorAll('#rangeButtons button').forEach(
    btn=>btn.classList.toggle('active',Number(btn.dataset.range)===1800)
  );
  chartHoverTimestamp=ts;
  setSection('profiler',true);
  setTimeout(()=>redrawProfilerCharts(),350);
}

async function loadPerformanceEntityScan(showLoading=true,preloaded=null){
  if(showLoading)$('perfLastScan').textContent='Loading last entity scan…';
  try{
    const d=preloaded||await api('/api/performance/entity-scan');
    if(d.available&&d.snapshot){
      performanceEntityScanData=d.snapshot;
      renderPerformanceEntityScan(d.snapshot);
    }else if(!performanceEntityScanData){
      $('perfLastScan').textContent='No entity/chunk scan yet';
    }
  }catch(e){
    if(showLoading)toast(e.message,'error');
  }
}

async function scanPerformanceEntities(){
  const btn=$('perfEntityScan');
  btn.disabled=true;
  $('perfLastScan').textContent='Scanning loaded entities…';
  try{
    const d=await api('/api/performance/entity-scan',{method:'POST',body:'{}'});
    performanceEntityScanData=d.snapshot||null;
    if(performanceEntityScanData)renderPerformanceEntityScan(performanceEntityScanData);
    await Promise.allSettled([
      loadPerformanceEntityGrowth(false),
      loadPerformanceTimeline(false)
    ]);
    toast('Manual entity/chunk hotspot scan complete.','success');
  }catch(e){
    toast(e.message,'error');
  }finally{
    btn.disabled=false;
  }
}

function renderPerformanceEntityScan(scan){
  const when=new Date(Number(scan.unixMilliseconds||0));
  $('perfLastScan').textContent=`Entity scan ${when.toLocaleTimeString()} · ${Number(scan.positionedEntities||0).toLocaleString()} positioned`;
  $('perfEntityCount').textContent=`${Number(scan.totalLoadedEntities||0).toLocaleString()} loaded`;
  const types=scan.entityTypes||[];
  $('perfEntityTypes').innerHTML=types.length
    ? types.slice(0,40).map(x=>`<tr>
        <td><b>${esc(x.code)}</b></td>
        <td>${esc(x.runtimeType)}</td>
        <td>${Number(x.count||0).toLocaleString()}</td>
        <td>${Number(x.chunkCount||0).toLocaleString()}</td>
        <td><button class="iconBtn" data-pin-entity="${esc(x.code)}">Pin</button></td>
      </tr>`).join('')
    : '<tr><td colspan="5" class="muted">No loaded entity types were found.</td></tr>';

  document.querySelectorAll('[data-pin-entity]').forEach(btn=>btn.onclick=()=>addWatchItem('entity',btn.dataset.pinEntity,btn.dataset.pinEntity,'performance'));

  const chunks=scan.chunks||[];
  $('perfChunkCount').textContent=`${chunks.length} retained hotspot chunk(s)`;
  $('perfChunks').innerHTML=chunks.length
    ? chunks.slice(0,60).map(x=>`<tr>
        <td><b>${Number(x.chunkX)}, ${Number(x.chunkZ)}</b></td>
        <td>${Number(x.dimension||0)}</td>
        <td class="${Number(x.pressureScore||0)>=250?'bad':Number(x.pressureScore||0)>=120?'warn':''}"><b>${Number(x.pressureScore||0)}</b></td>
        <td>${Number(x.entityCount||0).toLocaleString()}</td>
        <td>${Number(x.playerCount||0)}</td>
        <td>${Number(x.uniqueEntityTypes||0)}</td>
        <td class="codeCell" title="${esc(x.topEntityTypes)}">${esc(x.topEntityTypes)}</td>
        <td><div class="rowActions"><button class="iconBtn" data-open-chunk="${Number(x.chunkX)},${Number(x.chunkZ)},${Number(x.dimension||0)}">BlockLogger</button><button class="iconBtn" data-pin-chunk="${Number(x.chunkX)},${Number(x.chunkZ)},${Number(x.dimension||0)}">Pin</button></div></td>
      </tr>`).join('')
    : '<tr><td colspan="8" class="muted">No positioned chunk data was found.</td></tr>';

  document.querySelectorAll('[data-open-chunk]').forEach(btn=>btn.onclick=()=>{
    const [cx,cz,dim]=btn.dataset.openChunk.split(',').map(Number);
    openChunkInBlockLogger(cx,cz,dim);
  });
  document.querySelectorAll('[data-pin-chunk]').forEach(btn=>btn.onclick=()=>{
    const [cx,cz,dim]=btn.dataset.pinChunk.split(',').map(Number);
    addWatchItem('chunk',`${dim}:${cx}:${cz}`,`Chunk ${cx}, ${cz} · dim ${dim}`,'blocklogger',{chunkX:cx,chunkZ:cz,dimension:dim});
  });

  renderPerformanceHeatmap(chunks);
}

function renderPerformanceHeatmap(chunks){
  const host=$('perfHeatmap');
  if(!chunks||!chunks.length){
    host.innerHTML='<div class="empty" style="grid-column:1/-1">Run the manual entity/chunk hotspot scan.</div>';
    return;
  }

  const hottest=chunks[0];
  const dimension=Number(hottest.dimension||0);
  const cx=Number(hottest.chunkX||0),cz=Number(hottest.chunkZ||0);
  const sameDim=chunks.filter(x=>Number(x.dimension||0)===dimension);
  const map=new Map(sameDim.map(x=>[`${Number(x.chunkX)},${Number(x.chunkZ)}`,x]));
  const maxPressure=Math.max(1,...sameDim.map(x=>Number(x.pressureScore||0)));
  const cells=[];

  for(let dz=-3;dz<=3;dz++){
    for(let dx=-3;dx<=3;dx++){
      const x=cx+dx,z=cz+dz,row=map.get(`${x},${z}`);
      if(!row){
        cells.push(`<div class="heatCell empty" title="No hotspot data retained for this chunk"><div class="coord">${x},${z}</div><div>—</div></div>`);
        continue;
      }
      const ratio=Number(row.pressureScore||0)/maxPressure;
      const cls=ratio>=.75?'p4':ratio>=.5?'p3':ratio>=.25?'p2':'p1';
      cells.push(`<div class="heatCell ${cls}" data-heat-chunk="${x},${z},${dimension}" title="${esc(row.topEntityTypes||'')} · click to open BlockLogger near this chunk">
        <div class="coord">${x},${z}</div>
        <div class="count">${Number(row.entityCount||0).toLocaleString()}</div>
        <div>${Number(row.uniqueEntityTypes||0)} types · ${Number(row.playerCount||0)} players</div>
      </div>`);
    }
  }

  host.innerHTML=cells.join('');
  host.querySelectorAll('[data-heat-chunk]').forEach(cell=>cell.onclick=()=>{
    const [x,z,dim]=cell.dataset.heatChunk.split(',').map(Number);
    openChunkInBlockLogger(x,z,dim);
  });
}

function dotNetTicksToDate(ticks){
  const n=Number(ticks||0);
  if(!n)return null;
  const unixMs=(n-621355968000000000)/10000;
  return new Date(unixMs);
}

async function loadPerformanceBlockActivity(showLoading=true){
  if(showLoading)$('perfActivityCount').textContent='Loading…';
  try{
    const minutes=Number($('perfActivityWindow').value||30);
    const d=await api(`/api/performance/block-activity?minutes=${minutes}&limit=75`);
    const rows=d.rows||[];
    $('perfActivityCount').textContent=`${rows.length} hotspot(s) / ${d.minutes} min`;
    $('perfBlockActivity').innerHTML=rows.length
      ? rows.map(x=>{
          const last=dotNetTicksToDate(x.lastTimestampTicks);
          return `<tr>
            <td><b>${Number(x.x)}, ${Number(x.y)}, ${Number(x.z)}</b></td>
            <td>${esc(x.dimension)}</td>
            <td class="codeCell" title="${esc(x.blockCode)}">${esc(x.blockCode)}</td>
            <td class="${Number(x.eventCount||0)>=100?'warn':''}"><b>${Number(x.eventCount||0).toLocaleString()}</b></td>
            <td>${Number(x.distinctActions||0)}</td>
            <td>${last?esc(last.toLocaleString()):'—'}</td>
          </tr>`;
        }).join('')
      : '<tr><td colspan="6" class="muted">No BlockLogger block/container activity was found in this time window.</td></tr>';
  }catch(e){
    $('perfBlockActivity').innerHTML=`<tr><td colspan="6" class="bad">${esc(e.message)}</td></tr>`;
  }
}

async function loadPerformanceProviders(showLoading=true,preloaded=null){
  if(showLoading)$('perfProviders').innerHTML='<div class="empty">Loading providers…</div>';
  try{
    performanceProvidersData=preloaded||await api('/api/performance/providers');
    const providers=(performanceProvidersData||{}).providers||[];
    $('perfProviders').innerHTML=providers.map(x=>`<div class="card providerCard ${x.installed?'installed':'missing'}">
      <div class="small">${esc(x.role)}</div>
      <div style="font-size:17px;font-weight:800">${esc(x.name)} ${x.version?`<span class="small">${esc(x.version)}</span>`:''}</div>
      <div class="${x.installed?'good':'muted'}"><b>${x.installed?'INSTALLED':'NOT INSTALLED'}</b></div>
      <div class="small" style="margin-top:5px">${esc(x.detail)}</div>
    </div>`).join('');
  }catch(e){
    $('perfProviders').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
  }
}

async function loadPerformanceConflicts(showLoading=true,preloaded=null){
  if(showLoading)$('perfConflictSummary').textContent='Inspecting…';
  try{
    performanceConflictsData=preloaded||await api('/api/performance/conflicts');
    const d=performanceConflictsData||{};
    $('perfConflictSummary').textContent=d.harmonyDetected
      ? `${Number(d.patchedMethodCount||0).toLocaleString()} patched methods · ${Number(d.conflictCount||0).toLocaleString()} overlap(s)`
      : 'Harmony not detected';

    const rows=d.conflicts||[];
    $('perfConflicts').innerHTML=rows.length
      ? rows.slice(0,100).map(x=>`<tr>
          <td class="${severityClass(x.severity)}"><b>${esc(x.severity)}</b></td>
          <td class="codeCell" title="${esc(x.declaringType)}">${esc(x.declaringType)}</td>
          <td><b>${esc(x.method)}</b></td>
          <td class="patchOwners">${(x.owners||[]).map(o=>`<span class="badge medium">${esc(o)}</span>`).join(' ')}</td>
          <td class="codeCell" title="${esc(x.note)}">${esc(x.note)}</td>
        </tr>`).join('')
      : `<tr><td colspan="5" class="muted">${esc(d.message||'No multi-owner Harmony patch overlaps found.')}</td></tr>`;
  }catch(e){
    $('perfConflictSummary').textContent='Inspection failed';
    $('perfConflicts').innerHTML=`<tr><td colspan="5" class="bad">${esc(e.message)}</td></tr>`;
  }
}

