function tungstenSetBusy(value){
  tungstenBusy=value;
  document.querySelectorAll('#optimizations button').forEach(btn=>{
    const tungstenControl=btn.id.startsWith('tungsten') || btn.hasAttribute('data-tungsten-code') || btn.hasAttribute('data-tungsten-test');
    if(!tungstenControl)return;
    if(btn.id!=='tungstenRefresh')btn.disabled=value || !(tungstenStatusData&&tungstenStatusData.installed&&tungstenStatusData.commandRegistered);
  });
}

function recommendationBadge(rec){
  const level=String((rec||{}).level||'Not indicated');
  const cls=level==='High'?'high':level==='Medium'?'medium':level==='Low'?'low':'none';
  return `<span class="recBadge ${cls}">${esc(level)}${Number((rec||{}).score||0)>0?` · ${Number(rec.score)}`:''}</span>`;
}

function renderOptimizationExperiment(d){
  const pending=d.pendingExperiment||null;
  const history=d.experimentHistory||[];

  if(pending){
    const b=pending.baseline||{};
    $('optimizationExperiment').innerHTML=`
      <div><b>${esc(pending.providerName||'Optimizer')} · ${esc(pending.optimizationName)}</b> → ${pending.targetEnabled?'ENABLE':'DISABLE'}</div>
      <div class="warn" style="margin:5px 0"><b>${esc(pending.status)}</b></div>
      <div>${esc(pending.reason||'')}</div>
      <div class="small" style="margin-top:7px">
        Baseline: health ${Number(b.healthScore||0)}/100 · delay ${Number(b.delayMedianMs||0).toFixed(1)}ms ·
        CPU ${Number(b.cpuMedianPercent||0).toFixed(1)}% · writer ${Number(b.writerMedianMs||0).toFixed(1)}ms ·
        players ${Number(b.players||0)}
      </div>`;
  }else{
    const latest=history[0]||null;
    $('optimizationExperiment').innerHTML=latest
      ? `<div class="experimentResult ${String(latest.result||'').toLowerCase().replace(/[^a-z]+/g,'')}">${esc(latest.result)}</div>
         <div><b>${esc(latest.providerName||'Optimizer')} · ${esc(latest.optimizationName)}</b> · ${Number(latest.improvementScore||0)>=0?'+':''}${Number(latest.improvementScore||0).toFixed(1)}% weighted score · ${esc(latest.confidence)} confidence</div>
         <div class="small" style="margin-top:6px">${esc(latest.reason||'')}</div>`
      : 'No measured experiment is pending. Use <b>Measure ON</b> on one optimization after diagnostics have collected for at least 60 seconds.';
  }

  $('optimizationHistory').innerHTML=history.length
    ? history.map(x=>`<tr>
        <td><b>${esc(x.providerName||'Optimizer')} · ${esc(x.optimizationName)}</b></td>
        <td>${x.targetEnabled?'ON':'OFF'}</td>
        <td class="${String(x.result||'').toLowerCase()==='improved'?'good':String(x.result||'').toLowerCase()==='regressed'?'bad':'warn'}"><b>${esc(x.result)}</b></td>
        <td>${Number(x.improvementScore||0)>=0?'+':''}${Number(x.improvementScore||0).toFixed(1)}%</td>
        <td>${esc(x.confidence)}</td>
        <td class="codeCell" title="${esc(x.reason)}">${esc(x.reason)}</td>
      </tr>`).join('')
    : '<tr><td colspan="6" class="muted">No completed optimization measurements yet.</td></tr>';
}

function renderTungsten(){
  const d=tungstenStatusData||{};
  const installed=!!d.installed;
  const ready=installed&&!!d.commandRegistered;
  const safeModeLocked=!!d.safeDiagnosticsMode;
  const experimentLocked=!!d.pendingExperiment;

  $('tungstenBanner').innerHTML=`
    <div class="optStatusHero">
      <div class="optStatusIcon ${ready?'good':'bad'}">${ready?'✓':'!'}</div>
      <div>
        <div class="small">EXTERNAL OPTIMIZER INTEGRATION</div>
        <div style="font-size:21px;font-weight:800">${installed?`${esc(d.name||'Tungsten')} ${esc(d.version||'')}`:'Tungsten required for optimization controls'}</div>
        <div class="small">${esc(d.note||'')}</div>
        ${!installed?'<div class="warning" style="margin:8px 0 0"><b>Install Tungsten to use these 27 optimization toggles.</b> BlockLogger provides recommendations, measurement, and the web control surface, but it does not copy Tungsten&#39;s optimization patches. <a href="https://mods.vintagestory.at/show/mod/35001">Open Tungsten on the Vintage Story Mod DB</a>.</div>':''}
        ${safeModeLocked?'<div class="warning" style="margin:8px 0 0"><b>Safe Diagnostics Mode is ON.</b> Tungsten state-changing controls and manual engine profiling are locked. Read-only status/health/manifest/diagnostic dump actions remain available.</div>':''}
        ${installed&&!ready?'<div class="bad" style="margin-top:5px">Tungsten is loaded but its /tungsten command is not registered. Check the server log/version compatibility.</div>':''}
      </div>
    </div>`;

  $('tungstenAdvisorState').textContent=d.recommendationState||'';
  const opts=d.optimizations||[];
  const recommended=opts
    .filter(x=>Number((x.recommendation||{}).score||0)>0)
    .sort((a,b)=>Number((b.recommendation||{}).score||0)-Number((a.recommendation||{}).score||0))
    .slice(0,5);

  $('tungstenAdvisor').innerHTML=recommended.length
    ? recommended.map((x,i)=>`<div style="margin-bottom:9px">
        <b>${i+1}. ${esc(x.name)}</b> ${recommendationBadge(x.recommendation)}<br>
        <span class="small">${esc((x.recommendation||{}).reason||'')}</span>
      </div>`).join('')
    : (String(d.recommendationState||'').includes('OFF')
        ? 'Enable lightweight Profiler diagnostics and let them collect for at least 60 seconds. The advisor will then rank Tungsten optimizations using CPU, GC, entity, chunk, memory, and player-load evidence.'
        : 'No Tungsten optimization is strongly indicated by the current Smart Diagnosis. That is a useful result—avoid enabling optimizations just because they exist.');

  renderOptimizationExperiment(d);

  const categories=[...new Set(opts.map(x=>x.category).filter(Boolean))].sort();
  const currentCategory=$('tungstenCategory').value;
  $('tungstenCategory').innerHTML='<option value="">All categories</option>'+categories.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  if(categories.includes(currentCategory))$('tungstenCategory').value=currentCategory;

  const moduleValue=$('tungstenDiagModule').value;
  $('tungstenDiagModule').innerHTML='<option value="all">All modules</option>'+opts.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  if(moduleValue==='all'||opts.some(x=>x.code===moduleValue))$('tungstenDiagModule').value=moduleValue;

  const q=String($('tungstenFilter').value||'').trim().toLowerCase();
  const category=$('tungstenCategory').value;
  const rows=opts
    .filter(x=>
      (!category||x.category===category) &&
      (!q||[x.code,x.name,x.description,x.category,(x.recommendation||{}).reason].some(v=>String(v||'').toLowerCase().includes(q)))
    )
    .sort((a,b)=>Number((b.recommendation||{}).score||0)-Number((a.recommendation||{}).score||0));

  $('tungstenCount').textContent=`${rows.length} / ${opts.length}`;
  $('tungstenRows').innerHTML=rows.length
    ? rows.map(x=>`<tr>
        <td><b>${esc(x.name)}</b><div class="small">${esc(x.code)}</div></td>
        <td>${recommendationBadge(x.recommendation)}<div class="small" style="margin-top:4px;max-width:310px">${esc((x.recommendation||{}).reason||'')}</div></td>
        <td><span class="optCategory">${esc(x.category)}</span></td>
        <td>${esc(x.description)}</td>
        <td class="${x.commandAvailable?'good':'bad'}"><b>${x.commandAvailable?'YES':'NO'}</b></td>
        <td><div class="optActions">
          <button data-tungsten-code="${esc(x.code)}" data-enabled="true" class="primary" ${!ready||!x.commandAvailable||experimentLocked||safeModeLocked?'disabled':''}>ON</button>
          <button data-tungsten-code="${esc(x.code)}" data-enabled="false" ${!ready||!x.commandAvailable||experimentLocked||safeModeLocked?'disabled':''}>OFF</button>
          <button data-tungsten-test="${esc(x.code)}" ${!ready||!x.commandAvailable||experimentLocked||safeModeLocked?'disabled':''}>Measure ON</button>
        </div></td>
      </tr>`).join('')
    : '<tr><td colspan="6" class="muted">No optimization matches the current filter.</td></tr>';

  document.querySelectorAll('[data-tungsten-code]').forEach(btn=>{
    btn.onclick=()=>toggleTungstenOptimization(
      btn.dataset.tungstenCode||'',
      btn.dataset.enabled==='true');
  });
  document.querySelectorAll('[data-tungsten-test]').forEach(btn=>{
    btn.onclick=()=>measureTungstenOptimization(btn.dataset.tungstenTest||'');
  });

  const supports=d.supports||{};
  [
    'tungstenStatus','tungstenStats','tungstenReload',
    'tungstenStatsOn','tungstenStatsOff'
  ].forEach(id=>$(id).disabled=!ready);
  ['tungstenAllOn','tungstenAllOff'].forEach(id=>$(id).disabled=!ready||experimentLocked||safeModeLocked);
  $('tungstenHealth').disabled=!ready||!supports.health;
  $('tungstenManifest').disabled=!ready||!supports.manifest;
  $('tungstenBenchmarkOn').disabled=!ready||!supports.benchmarkHarness;
  $('tungstenBenchmarkOff').disabled=!ready||!supports.benchmarkHarness;
  $('tungstenFrameOn').disabled=!ready||!supports.frameProfiler;
  $('tungstenFrameOff').disabled=!ready||!supports.frameProfiler;
  $('tungstenDiagOn').disabled=!ready||!supports.diagnostics;
  $('tungstenDiagOff').disabled=!ready||!supports.diagnostics;
  $('tungstenDiagDump').disabled=!ready||!supports.diagnostics;
  $('tungstenDiagReset').disabled=!ready||!supports.diagnostics;
  $('optimizationEvaluate').disabled=!d.pendingExperiment;
}


async function loadTungsten(){
  $('tungstenBanner').innerHTML='<div class="empty">Checking Tungsten installation and command catalog…</div>';
  try{
    tungstenStatusData=await api('/api/optimizations/tungsten');
    renderTungsten();
  }catch(e){
    tungstenStatusData=null;
    $('tungstenBanner').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;
    $('tungstenRows').innerHTML='<tr><td colspan="6" class="bad">Unable to load Tungsten integration status.</td></tr>';
  }
}

