function fmtAdminDuration(seconds){
  seconds=Math.max(0,Number(seconds||0));
  if(seconds>=86400)return `${(seconds/86400).toFixed(1)}d`;
  if(seconds>=3600)return `${(seconds/3600).toFixed(1)}h`;
  if(seconds>=60)return `${(seconds/60).toFixed(1)}m`;
  return `${Math.round(seconds)}s`;
}

function fmtAdminTime(ms){
  ms=Number(ms||0);
  return ms>0?new Date(ms).toLocaleString():'—';
}

function fmtAdminRelativeTime(ms){
  ms=Number(ms||0);
  if(ms<=0)return 'Never';
  let seconds=Math.max(0,Math.floor((Date.now()-ms)/1000));
  if(seconds<60)return 'Just now';
  const minutes=Math.floor(seconds/60);
  if(minutes<60)return `${minutes}m ago`;
  const hours=Math.floor(minutes/60);
  if(hours<24)return `${hours}h ago`;
  const days=Math.floor(hours/24);
  if(days<30)return `${days}d ago`;
  const months=Math.floor(days/30);
  if(months<12)return `${months}mo ago`;
  return `${Math.floor(days/365)}y ago`;
}

function playerIdentityText(p,realKey='name'){
  const real=String(p?.[realKey]||'').trim();
  const nick=String(p?.nickname||'').trim();
  return nick&&(!real||nick.toLowerCase()!==real.toLowerCase())?`${nick} (${real})`:real;
}

function playerIdentityHtml(p,realKey='name',showUid=false){
  const real=String(p?.[realKey]||'').trim();
  const nick=String(p?.nickname||'').trim();
  const hasNick=!!nick&&(!real||nick.toLowerCase()!==real.toLowerCase());
  const uid=showUid?String(p?.playerUid||'').trim():'';
  if(hasNick)return `<b>${esc(nick)}</b><div class="small">${real?`Real: ${esc(real)}`:''}${real&&uid?' · ':''}${uid?esc(uid):''}</div>`;
  return `<b>${esc(real||nick||'Unknown')}</b>${uid?`<div class="small">${esc(uid)}</div>`:''}`;
}

function renderAdminPlayerList(){
  const onlineRows=adminPlayersData.filter(x=>!!x.online);
  const offlineRows=adminPlayersData.filter(x=>!x.online);
  $('adminOnlineCount').textContent=onlineRows.length;
  $('adminOfflineCount').textContent=offlineRows.length;
  document.querySelectorAll('#adminPlayerTabs button').forEach(btn=>btn.classList.toggle('active',btn.dataset.playerTab===adminPlayerTab));
  $('adminLastSeenFilter').disabled=adminPlayerTab==='online';

  const q=String($('adminPlayerFilter')?.value||'').trim().toLowerCase();
  const lastSeenWindow=Number($('adminLastSeenFilter')?.value||0);
  const sortMode=String($('adminPlayerSort')?.value||'recent');
  const now=Date.now();
  const visible=(adminPlayerTab==='online'?onlineRows:offlineRows).filter(p=>{
    if(q&&!`${p.nickname||''} ${p.name||''} ${p.playerUid||''} ${p.role||''}`.toLowerCase().includes(q))return false;
    if(adminPlayerTab==='offline'&&lastSeenWindow>0&&now-Number(p.lastSeenUnixMilliseconds||0)>lastSeenWindow*1000)return false;
    return true;
  }).slice();
  if(sortMode==='name')visible.sort((a,b)=>playerIdentityText(a).localeCompare(playerIdentityText(b)));
  else if(sortMode==='playtime')visible.sort((a,b)=>Number(b.totalPlaySeconds||0)-Number(a.totalPlaySeconds||0));
  else if(sortMode==='warnings')visible.sort((a,b)=>Number(b.activeWarnings||0)-Number(a.activeWarnings||0)||playerIdentityText(a).localeCompare(playerIdentityText(b)));
  else if(adminPlayerTab==='online')visible.sort((a,b)=>Number(a.afk)-Number(b.afk)||playerIdentityText(a).localeCompare(playerIdentityText(b)));
  else visible.sort((a,b)=>Number(b.lastSeenUnixMilliseconds||0)-Number(a.lastSeenUnixMilliseconds||0)||String(a.name||'').localeCompare(String(b.name||'')));

  $('adminPlayerTabSummary').textContent=adminPlayerTab==='online'
    ? `${visible.length}${q?` of ${onlineRows.length}`:''} online · ${onlineRows.filter(x=>x.afk).length} AFK`
    : `${visible.length}${(q||Number($('adminLastSeenFilter')?.value||0)>0)?` of ${offlineRows.length}`:''} offline · ${String($('adminPlayerSort')?.value||'recent')==='recent'?'newest Last Seen first':'sorted '+String($('adminPlayerSort')?.value||'recent')}`;

  $('adminPlayerRows').innerHTML=visible.length?visible.map(p=>{
    const restrictions=[p.muted?'Muted':'',p.banned?'Temp banned':'',p.frozen?'Frozen':'',p.jailed?'Jailed':''].filter(Boolean).join(', ')||'—';
    const status=p.online?(p.afk?'<span class="badge warn">AFK</span>':'<span class="badge ok">ONLINE</span>'):'<span class="badge">OFFLINE</span>';
    const lastSeen=p.online
      ? `<span class="badge ok">Now</span><div class="small">Session ${esc(fmtAdminDuration(p.sessionSeconds||0))}</div>`
      : `<b>${esc(fmtAdminRelativeTime(p.lastSeenUnixMilliseconds))}</b><div class="small">${esc(fmtAdminTime(p.lastSeenUnixMilliseconds))}</div>`;
    const playerListClient=p.online?(p.playerListClientDetected?`<span class="badge ok">Detected</span><div class="small">${esc(p.playerListClientVersion||'version unknown')}</div>`:'<span class="badge">Not detected</span>'):'—';
    return `<tr><td>${playerIdentityHtml(p,'name',true)}</td><td>${status}</td><td>${esc(p.role||'')}</td><td>${p.online?esc(p.pingMilliseconds)+' ms':'—'}</td><td>${playerListClient}</td><td>${lastSeen}</td><td>${esc(fmtAdminDuration(p.totalPlaySeconds))}</td><td>${esc(p.activeWarnings||0)}</td><td>${esc(restrictions)}</td><td><button onclick="selectAdminPlayer('${esc(p.playerUid)}')">Manage</button></td></tr>`;
  }).join(''):`<tr><td colspan="10" class="muted">No ${esc(adminPlayerTab)} players.</td></tr>`;
}

function setAdminPlayerTab(tab){
  if(tab!=='online' && tab!=='offline')return;
  adminPlayerTab=tab;
  localStorage.setItem('nsu.adminPlayerTab',tab);
  renderAdminPlayerList();
}

async function loadAdmin(showLoading=true,refreshSelected=true){
  if(showLoading){
    $('adminState').textContent='Loading…';
    $('adminPlayerRows').innerHTML='<tr><td colspan="10" class="muted">Loading players…</td></tr>';
  }
  try{
    const [players,status]=await Promise.all([api('/api/admin/players'),api('/api/admin/status')]);
    adminPlayersData=players.players||[];
    adminStatusData=status||{};
    const now=Date.now();
    const online=adminPlayersData.filter(x=>x.online).length;
    const afk=adminPlayersData.filter(x=>x.online&&x.afk).length;
    const seen7d=adminPlayersData.filter(x=>x.online||(Number(x.lastSeenUnixMilliseconds||0)>0&&now-Number(x.lastSeenUnixMilliseconds)<7*86400000)).length;
    const restricted=adminPlayersData.filter(x=>x.muted||x.banned||x.frozen||x.jailed).length;
    const warnings=adminPlayersData.reduce((n,x)=>n+Number(x.activeWarnings||0),0);
    const totalPlayerTimeSeconds=adminPlayersData.reduce((n,x)=>n+Math.max(0,Number(x.totalPlaySeconds||0)),0);
    $('adminMetrics').innerHTML=[
      ['Online Players',online,`${afk} AFK · ${adminPlayersData.length-online} offline`],
      ['Player List Clients',adminPlayersData.filter(x=>x.online&&x.playerListClientDetected).length,'Companion handshakes detected'],
      ['Supporter Nicknames',adminPlayersData.filter(x=>String(x.nickname||'').trim()).length,'Saved presentation-only nicknames'],
      ['Seen in 7 Days',seen7d,`${adminPlayersData.length} total tracked players`],
      ['Active Warnings',warnings,'Across tracked players'],
      ['Restricted Players',restricted,'Muted / banned / frozen / jailed'],
      ['Admin Audit',(status.audit||[]).length,'Recent entries loaded'],
      ['Total Player Time',fmtAdminDuration(totalPlayerTimeSeconds),`Combined tracked playtime · ${adminPlayersData.length} players`]
    ].map(x=>`<div class="card"><div class="metricLabel">${esc(x[0])}</div><div class="metricValue">${esc(x[1])}</div><div class="small">${esc(x[2])}</div></div>`).join('');

    renderAdminPlayerList();

    const m=status.maintenance||{};
    $('adminMaintenanceState').textContent=m.enabled?`ON · ${m.reason||'Maintenance'}${m.untilUnixMilliseconds?` · until ${fmtAdminTime(m.untilUnixMilliseconds)}`:''}`:'OFF';
    const sh=status.shutdown||{};
    $('adminShutdownState').textContent=Number(sh.atUnixMilliseconds||0)>Date.now()?`Scheduled ${fmtAdminTime(sh.atUnixMilliseconds)} · ${sh.reason||''}`:'Not scheduled';
    $('adminAuditRows').innerHTML=(status.audit||[]).length?(status.audit||[]).map(a=>`<tr><td>${esc(fmtAdminTime(a.unixMilliseconds))}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.targetName||'server')}</td><td>${esc(a.source)}</td><td>${esc(a.detail)}</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No administration audit entries yet.</td></tr>';
    const undo=status.undo||{};
    $('adminUndo').disabled=!undo.available;
    $('adminUndo').title=undo.available?`Undo: ${undo.description||''}`:'Nothing reversible to undo';
    $('adminState').textContent=`${online} online · ${adminPlayersData.length} tracked${undo.available?` · Undo: ${undo.description}`:''}`;

    if(refreshSelected&&adminSelectedPlayer)await selectAdminPlayer(adminSelectedPlayer,false);
  }catch(e){
    $('adminState').textContent=e.message;
    toast(e.message,'error');
  }
}

function dbStorageSeverityClass(value){
  value=String(value||'Info').toLowerCase();
  return value==='watch'||value==='warning'?'watch':'info';
}

function renderAdminDatabaseStorageGraph(){
  const canvas=$('adminDatabaseStorageGraph');
  const state=$('adminDatabaseStorageGraphState');
  if(!canvas)return;
  const dbs=(adminDatabaseStorageData?.databases||[]).filter(x=>x&&x.available!==false);
  const {ctx,w,h}=resizeCanvas(canvas);
  ctx.clearRect(0,0,w,h);
  adminDatabaseStorageGraphHitAreas=[];
  ctx.font='11px system-ui';

  if(!dbs.length){
    ctx.fillStyle='#8492a0';ctx.fillText('No database storage totals available.',18,26);
    if(state)state.textContent='No storage data';
    return;
  }

  const rows=dbs.map(db=>{
    const database=Math.max(0,Number(db.databaseBytes||0));
    const wal=Math.max(0,Number(db.walBytes||0));
    const shm=Math.max(0,Number(db.shmBytes||0));
    const backups=Math.max(0,Number(db.backupBytes||0));
    return{db,database,wal,shm,backups,total:database+wal+shm+backups};
  });
  const maxTotal=Math.max(1,...rows.map(x=>x.total));
  const totalAll=rows.reduce((n,x)=>n+x.total,0);
  const pad={l:145,r:86,t:26,b:34};
  const plotW=Math.max(80,w-pad.l-pad.r),plotH=Math.max(80,h-pad.t-pad.b);
  const rowH=plotH/Math.max(1,rows.length);
  const barH=Math.min(34,Math.max(22,rowH*.42));
  const colors={database:'#5d9bd0',wal:'#6fb8a8',shm:'#8794a0',backups:'#9a7cc1'};

  ctx.fillStyle='#0b1218';ctx.fillRect(pad.l,pad.t,plotW,plotH);
  ctx.strokeStyle='rgba(86,108,124,.18)';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){
    const x=pad.l+plotW*i/4;
    ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+plotH);ctx.stroke();
    const label=formatBytesTotal(maxTotal*i/4);
    ctx.fillStyle='#6f8292';ctx.font='10px system-ui';
    const tw=ctx.measureText(label).width;
    ctx.fillText(label,Math.max(pad.l,Math.min(w-pad.r-tw,x-tw/2)),h-9);
  }

  rows.forEach((row,i)=>{
    const cy=pad.t+rowH*i+rowH/2;
    const y=cy-barH/2;
    const name=String(row.db.name||row.db.key||'Database');
    ctx.font='11px system-ui';ctx.fillStyle=i===adminDatabaseStorageGraphHover?'#f0f6fb':'#c6d2dc';
    const label=name.length>22?name.slice(0,21)+'…':name;
    ctx.fillText(label,10,cy+4);

    ctx.fillStyle='#111b23';ctx.fillRect(pad.l,y,plotW,barH);
    ctx.strokeStyle=i===adminDatabaseStorageGraphHover?'#466984':'#263744';ctx.strokeRect(pad.l+.5,y+.5,plotW-1,barH-1);
    let x=pad.l;
    for(const key of ['database','wal','shm','backups']){
      const value=row[key];
      if(value<=0)continue;
      const segW=(value/maxTotal)*plotW;
      if(segW>0.4){ctx.fillStyle=colors[key];ctx.fillRect(x,y+1,Math.max(.5,segW),barH-2);}
      x+=segW;
    }
    ctx.font='11px system-ui';ctx.fillStyle='#d8e3eb';
    const totalLabel=formatBytesTotal(row.total);
    ctx.fillText(totalLabel,w-pad.r+10,cy+4);
    adminDatabaseStorageGraphHitAreas.push({index:i,x:0,y:pad.t+rowH*i,w,h:rowH,row});
  });

  if(state)state.textContent=`${formatBytesTotal(totalAll)} total`;
}

function renderAdminDatabaseStorage(){
  const d=adminDatabaseStorageData||{};
  const dbs=d.databases||[];
  const totalLive=dbs.reduce((n,x)=>n+Number(x.databaseBytes||0)+Number(x.walBytes||0)+Number(x.shmBytes||0),0);
  const totalBackups=dbs.reduce((n,x)=>n+Number(x.backupBytes||0),0);
  const totalFree=dbs.reduce((n,x)=>n+Number(x.freeBytes||0),0);
  const totalIndexes=dbs.reduce((n,x)=>n+Number(x.indexBytes||0),0);
  const analyzed=!!d.detailedAnalysisAvailable;
  const analyzedAt=Number(d.detailedAnalysisUnixMilliseconds||0);

  $('adminDatabaseStorageState').textContent=analyzed
    ? `Analyzed ${fmtAdminRelativeTime(analyzedAt)} · cached`
    : 'File totals only · analysis not run';
  $('adminDatabaseStorageSummary').innerHTML=[
    ['Live SQLite + WAL',formatBytesTotal(totalLive),'Current database files and sidecars'],
    ['Retained Backups',formatBytesTotal(totalBackups),`${dbs.reduce((n,x)=>n+Number(x.backupCount||0),0)} backup file(s)`],
    ['Reclaimable Free Pages',analyzed?formatBytesTotal(totalFree):'Analyze',analyzed?'Allocated DB pages currently unused':'Requires page analysis'],
    ['Index Footprint',analyzed?formatBytesTotal(totalIndexes):'Analyze',analyzed?'Indexes accelerate history/admin queries':'Requires page analysis']
  ].map(x=>`<div class="card"><div class="metricLabel">${esc(x[0])}</div><div class="metricValue" style="font-size:19px">${esc(x[1])}</div><div class="small">${esc(x[2])}</div></div>`).join('');
  renderAdminDatabaseStorageGraph();

  const recs=d.recommendations||[];
  $('adminDatabaseStorageRecommendations').innerHTML=recs.length
    ? recs.map(r=>`<div class="dbStorageRecommendation ${dbStorageSeverityClass(r.severity)}"><b>${esc(r.database||'Database')} · ${esc(r.area||'Storage')}</b><div>${esc(r.finding||'')}</div><div class="small" style="margin-top:4px"><b>Improve:</b> ${esc(r.improvement||'')}</div><div class="small"><b>Safety:</b> ${esc(r.safety||'Review first')}</div></div>`).join('')
    : '<div class="infoBox"><b>How to use this:</b> Analyze Storage calculates SQLite page ownership for each Suite table and its indexes. The recommendations explain which retention/configuration lever is safer than manually deleting database files or rows.</div>';

  $('adminDatabaseStorageDatabases').innerHTML=dbs.length?dbs.map(db=>{
    const live=Number(db.databaseBytes||0),wal=Number(db.walBytes||0),shm=Number(db.shmBytes||0),backups=Number(db.backupBytes||0);
    const rows=db.tables||[];
    const contents=db.contents||[];
    const contentView=contents.length?`<div class="dbStorageContents">
      <div class="dbStorageContentsHeader"><div><b>Stored contents</b><div class="small">What this SQLite database actually contains.</div></div><div class="spacer"></div><span class="small">${db.detailed?'Record counts and sizes are from the last analysis.':'Run Analyze Storage for approximate record counts and per-area size.'}</span></div>
      <div class="dbStorageContentGrid">${contents.map(x=>{
        const analyzed=!!x.analyzed;
        const present=x.present!==false;
        const stats=analyzed&&present
          ? `<div class="dbStorageContentStats"><span><b>${Number(x.approxRows||0).toLocaleString()}</b> approx. records</span><span><b>${esc(formatBytesTotal(x.totalBytes||0))}</b> incl. indexes</span></div>`
          : `<div class="dbStorageContentStats"><span>${present?'Size/count pending analysis':'Table not present'}</span></div>`;
        return `<div class="dbStorageContent ${present?'':'missing'}">
          <div class="dbStorageContentTop"><span class="dbStorageSubsystem">${esc(x.subsystem||'Suite')}</span><code>${esc(x.tableName||'')}</code></div>
          <b class="dbStorageContentTitle">${esc(x.displayName||x.tableName||'Data')}</b>
          <div class="small">${esc(x.description||'')}</div>
          <div class="dbStorageStoredFields"><b>Stores:</b> ${esc(x.storedFields||'Suite-managed data')}</div>
          ${stats}
        </div>`;
      }).join('')}</div>
    </div>`:'';
    const detail=db.detailed&&rows.length?`<div class="tableWrap dataScroll"><table>
      <thead><tr><th>Data area</th><th>Subsystem / stored fields</th><th>Approx. records</th><th>Table data</th><th>Indexes</th><th>Total</th><th>Share</th><th>What grows it / how to improve</th></tr></thead>
      <tbody>${rows.map(x=>{
        const pct=Math.max(0,Math.min(100,Number(x.percentOfDatabase||0)));
        return `<tr>
          <td><b>${esc(x.displayName||x.name||'')}</b><div class="small"><code>${esc(x.name||'')}</code></div></td>
          <td class="dbStorageFields"><b>${esc(x.subsystem||'Suite')}</b><div>${esc(x.storedFields||'Suite-managed data')}</div></td>
          <td>${Number(x.approxRows||0).toLocaleString()}</td>
          <td>${esc(formatBytesTotal(x.dataBytes))}</td>
          <td>${esc(formatBytesTotal(x.indexBytes))}</td>
          <td><b>${esc(formatBytesTotal(x.totalBytes))}</b></td>
          <td class="dbStorageShare"><b>${pct.toFixed(1)}%</b><div class="dbStorageBar"><span style="width:${pct.toFixed(1)}%"></span></div></td>
          <td class="dbStorageGuidance"><b>${esc(x.description||'')}</b><div>${esc(x.improvement||'')}</div><div class="growth"><b>Growth driver:</b> ${esc(x.growthDriver||'')}</div><div class="small"><b>Safety:</b> ${esc(x.safety||'Review first')}</div></td>
        </tr>`;
      }).join('')}</tbody></table></div>`
      : `<div class="emptyAction"><b>Detailed table usage has not been calculated for this database.</b><br>${esc(db.analysisMessage||'Press Analyze Storage to scan SQLite page metadata.')}</div>`;
    return `<div class="dbStorageDatabase">
      <div class="dbStorageDatabaseHeader"><div><h4>${esc(db.name||db.key||'Database')}</h4><div class="small"><code>${esc(db.fileName||'database unavailable')}</code>${db.retentionDays>0?` · ${Number(db.retentionDays)} day retention`:''}</div></div><div class="spacer"></div><div><b>${esc(formatBytesTotal(live))}</b><div class="small">live DB</div></div></div>
      ${contentView}
      <div class="dbStorageBreakdown">
        <div class="miniStat"><span class="small">Database file</span><b>${esc(formatBytesTotal(live))}</b></div>
        <div class="miniStat"><span class="small">WAL</span><b>${esc(formatBytesTotal(wal))}</b></div>
        <div class="miniStat"><span class="small">Shared memory</span><b>${esc(formatBytesTotal(shm))}</b></div>
        <div class="miniStat"><span class="small">Backups</span><b>${esc(formatBytesTotal(backups))}</b><span class="small">${Number(db.backupCount||0)} file(s)</span></div>
        <div class="miniStat"><span class="small">Free pages</span><b>${db.detailed?esc(formatBytesTotal(db.freeBytes)):'—'}</b></div>
        <div class="miniStat"><span class="small">SQLite overhead</span><b>${db.detailed?esc(formatBytesTotal(db.sqliteOverheadBytes)):'—'}</b></div>
      </div>
      ${detail}
    </div>`;
  }).join(''):'<div class="emptyAction"><b>No Suite SQLite databases are currently available.</b></div>';
}

async function loadAdminDatabaseStorage(runAnalysis=false){
  const analyzeBtn=$('adminDatabaseStorageAnalyze');
  try{
    if(runAnalysis){
      analyzeBtn.disabled=true;
      analyzeBtn.textContent='Analyzing…';
      $('adminDatabaseStorageState').textContent='Analyzing SQLite pages…';
    }
    adminDatabaseStorageData=await api('/api/admin/database-storage'+(runAnalysis?'/analyze':''),runAnalysis?{method:'POST',body:'{}'}:{});
    renderAdminDatabaseStorage();
    if(runAnalysis)toast('Database storage analysis complete.','success');
  }catch(e){
    $('adminDatabaseStorageState').textContent=e.message;
    toast(e.message,'error');
  }finally{
    if(analyzeBtn){analyzeBtn.disabled=false;analyzeBtn.textContent='Analyze Storage';}
  }
}

async function selectAdminPlayer(player,showLoading=true){
  adminSelectedPlayer=player||'';
  if(!adminSelectedPlayer)return;
  $('adminPlayerDetail').style.display='block';
  if(showLoading)$('adminPlayerTitle').textContent='Loading player…';
  try{
    const d=await api('/api/admin/player?player='+encodeURIComponent(adminSelectedPlayer));
    const p=d.player||{};
    adminSelectedPlayer=p.playerUid||adminSelectedPlayer;
    $('adminPlayerTitle').textContent=playerIdentityText(p)||adminSelectedPlayer;
    $('adminPlayerMeta').textContent=`${p.nickname?`Real account: ${p.name||'—'} · `:''}${p.online?'Online':'Offline'} · ${p.role||''} · ${p.gameMode||''}`;
    $('adminPlayerSummary').innerHTML=[
      ['Identity',playerIdentityText(p)||p.name||'—',p.nickname?`Supporter nickname · authoritative account: ${p.name||'—'}`:`Authoritative account · ${p.playerUid||''}`],
      ['Status',p.online?(p.afk?'AFK':'ONLINE'):'OFFLINE',p.online?`${p.pingMilliseconds||0} ms · idle ${fmtAdminDuration(p.idleSeconds||0)}`:'Not currently connected'],
      ['Last Seen',p.online?'Online now':fmtAdminRelativeTime(p.lastSeenUnixMilliseconds),p.online?`Session started ${fmtAdminTime(Date.now()-Number(p.sessionSeconds||0)*1000)}`:fmtAdminTime(p.lastSeenUnixMilliseconds)],
      ['First Seen',fmtAdminTime(p.firstSeenUnixMilliseconds),'First recorded by Server Essentials'],
      ['Position',p.position||'—',p.online?'Current server position':'Offline'],
      ['Health',p.online?`${Number(p.health||0).toFixed(1)} / ${Number(p.maxHealth||0).toFixed(1)}`:'—','Read from player entity'],
      ['Playtime',fmtAdminDuration(p.totalPlaySeconds),p.online?`Current session ${fmtAdminDuration(p.sessionSeconds)}`:'Accumulated server playtime'],
      ['Player List Client',p.online?(p.playerListClientDetected?'Detected':'Not detected'):'—',p.playerListClientDetected?`Newfie's Player List ${p.playerListClientVersion||'version unknown'}`:'Current connection has not sent a companion handshake'],
      ['Warnings',p.activeWarnings||0,'Active staff warnings'],
      ['Restrictions',[p.muted?'Muted':'',p.banned?'Temp banned':'',p.frozen?'Frozen':'',p.jailed?'Jailed':''].filter(Boolean).join(' · ')||'None','Suite-managed']
    ].map(x=>`<div class="card"><div class="metricLabel">${esc(x[0])}</div><div class="metricValue" style="font-size:18px">${esc(x[1])}</div><div class="small">${esc(x[2])}</div></div>`).join('');

    $('adminWarningCount').textContent=`${(d.warnings||[]).filter(x=>!x.removed).length} active`;
    $('adminWarningRows').innerHTML=(d.warnings||[]).length?(d.warnings||[]).map(w=>`<tr><td>#${esc(w.id)}</td><td>${esc(fmtAdminTime(w.unixMilliseconds))}</td><td>${esc(w.issuedBy)}</td><td>${esc(w.reason)}</td><td>${w.removed?'Removed':'Active'}</td><td>${w.removed?'':`<button onclick="adminRemoveWarning(${Number(w.id)})">Remove</button>`}</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No warnings.</td></tr>';
    $('adminNoteCount').textContent=`${(d.notes||[]).length} notes`;
    $('adminNoteRows').innerHTML=(d.notes||[]).length?(d.notes||[]).map(n=>`<tr><td>#${esc(n.id)}</td><td>${esc(fmtAdminTime(n.unixMilliseconds))}</td><td>${esc(n.author)}</td><td>${esc(n.text)}</td><td><button onclick="adminRemoveNote(${Number(n.id)})">Remove</button></td></tr>`).join(''):'<tr><td colspan="5" class="muted">No staff notes.</td></tr>';
    adminInventoryData=d.inventory||[];
    adminInventorySnapshots=d.inventorySnapshots||[];
    if(!p.online){adminSelectedInventorySlot=null;}
    renderAdminInventory();
    renderAdminInventorySnapshots();
    renderAdminInventoryHistory(d.history||[]);
    const blockActionNames=['Unknown','Block Break','Block Place','Block Use','Container Open','Container Take','Container Put','Entity Interact','Entity Spawn','Entity Death','Entity Despawn'];
    const unified=[];
    (d.history||[]).forEach(h=>unified.push({time:Number(h.unixMilliseconds||0),action:h.action,actor:h.actor,source:h.source,detail:h.detail}));
    (d.blockHistory||[]).forEach(h=>{
      const t=Date.parse(h.timestampUtc||'')||0;
      const action=typeof h.action==='number'?(blockActionNames[h.action]||`BlockLogger ${h.action}`):String(h.action||'BlockLogger');
      const detail=`${h.blockCode||''} @ ${h.x||0},${h.y||0},${h.z||0}${h.dimension?` · ${h.dimension}`:''}`;
      unified.push({time:t,action,actor:h.playerName||p.name||'',source:'BlockLogger',detail});
    });
    unified.sort((a,b)=>b.time-a.time);
    $('adminHistoryRows').innerHTML=unified.length?unified.slice(0,40).map(h=>`<tr><td>${esc(fmtAdminTime(h.time))}</td><td>${esc(h.action)}</td><td>${esc(h.actor)}</td><td>${esc(h.source)}</td><td>${esc(h.detail)}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No suite or BlockLogger history for this player.</td></tr>';
  }catch(e){toast(e.message,'error');}
}

function adminInventoryKey(i){return `${i.inventory}\n${Number(i.slot)}`;}

function renderAdminInventory(){
  const filter=String($('adminInventoryFilter').value||'').trim().toLowerCase();
  const occupied=adminInventoryData.filter(x=>!x.empty).length;
  $('adminInventoryCount').textContent=adminInventoryData.length?`${occupied} occupied / ${adminInventoryData.length} slots`:'Player offline or inventory unavailable';
  if(!adminInventoryData.length){
    $('adminInventoryGrid').innerHTML='<div class="muted">Player must be online to inspect inventory.</div>';
    renderAdminSelectedSlot();
    return;
  }
  const visible=adminInventoryData.filter(i=>{
    if(!filter)return true;
    return !i.empty && [i.name,i.code,i.inventory,i.section].some(v=>String(v||'').toLowerCase().includes(filter));
  });
  const groups={};
  for(const i of visible){
    const key=`${i.section||'Other'} · ${i.inventory||'inventory'}`;
    (groups[key]||(groups[key]=[])).push(i);
  }
  const order=['Hotbar','Backpack','Equipment','Crafting','Cursor','Other'];
  const keys=Object.keys(groups).sort((a,b)=>{
    const ai=order.findIndex(x=>a.startsWith(x)),bi=order.findIndex(x=>b.startsWith(x));
    return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b);
  });
  $('adminInventoryGrid').innerHTML=keys.length?keys.map(key=>{
    const rows=groups[key].sort((a,b)=>Number(a.slot)-Number(b.slot));
    return `<div class="inventorySection"><div class="inventorySectionTitle">${esc(key)}<span class="small">${rows.filter(x=>!x.empty).length}/${rows.length} occupied</span></div><div class="inventorySlotGrid">${rows.map(i=>{
      const selected=adminSelectedInventorySlot&&adminInventoryKey(adminSelectedInventorySlot)===adminInventoryKey(i);
      const label=i.empty?'Empty':`${i.stackSize}x ${i.name||i.code}`;
      const meta=i.empty?(i.storageType||''):`${i.code||''}${i.maxDurability?` · ${i.durability}/${i.maxDurability} dura`:''}`;
      return `<button class="invSlot ${i.empty?'empty':''} ${selected?'selected':''}" onclick="adminSelectInventorySlot('${encodeURIComponent(String(i.inventory||'')).replace(/'/g,'%27')}',${Number(i.slot)})"><div class="slotNo">#${Number(i.slot)}</div><div class="slotName">${esc(label)}</div><div class="slotMeta">${esc(meta)}</div></button>`;
    }).join('')}</div></div>`;
  }).join(''):'<div class="muted">No inventory slots match the filter.</div>';
  renderAdminSelectedSlot();
}

function adminSelectInventorySlot(encodedInventory,slot){
  const inventory=decodeURIComponent(encodedInventory||'');
  adminSelectedInventorySlot=adminInventoryData.find(i=>String(i.inventory)===inventory&&Number(i.slot)===Number(slot))||null;
  renderAdminInventory();
}

function renderAdminSelectedSlot(){
  const i=adminSelectedInventorySlot;
  if(!i){
    $('adminSelectedSlotState').textContent='None';
    $('adminSelectedSlotDetail').innerHTML='Select a slot above to inspect or edit it.';
    $('adminSelectedSlotActions').innerHTML='';
    return;
  }
  $('adminSelectedSlotState').textContent=`${i.inventory}[${i.slot}]`;
  if(i.empty){
    $('adminSelectedSlotDetail').innerHTML=`<b>Empty slot</b><div>Section: ${esc(i.section||'Other')}</div><div>Storage: ${esc(i.storageType||'—')}</div><div>Slot max: ${esc(i.maxSlotStackSize||0)}</div>`;
    $('adminSelectedSlotActions').innerHTML='<button onclick="adminGiveSelectedItem(false)">Give Selected Catalog Item Here</button>';
    return;
  }
  $('adminSelectedSlotDetail').innerHTML=`<b>${esc(i.name||i.code)}</b><div><code>${esc(i.code||'')}</code></div><div>Quantity: ${Number(i.stackSize||0)} / ${Number(i.maxStackSize||0)}</div><div>${i.maxDurability?`Durability: ${Number(i.durability||0)} / ${Number(i.maxDurability||0)}<br>`:''}Temperature: ${Number(i.temperature||0).toFixed(1)}°C</div><div class="small">Class ${esc(i.itemClass||'')} · Storage ${esc(i.storageType||'')}</div>`;
  $('adminSelectedSlotActions').innerHTML='<button onclick="adminEditInventoryQuantity()">Edit Quantity</button><button onclick="adminMoveInventorySlot()">Move / Swap</button><button onclick="adminReplaceSelectedItem()">Replace</button><button class="danger" onclick="adminRemoveSelectedInventorySlot()">Remove</button>';
}

async function adminInventoryMutation(payload,confirmText=''){
  if(!adminSelectedPlayer){toast('Select a player first.','error');return null;}
  if(confirmText&&!confirm(confirmText))return null;
  payload.player=adminSelectedPlayer;
  try{
    const d=await api('/api/admin/inventory/action',{method:'POST',body:JSON.stringify(payload)});
    toast(d.message||'Inventory action completed.','success');
    await selectAdminPlayer(adminSelectedPlayer,false);
    await loadAdmin(false);
    return d;
  }catch(e){
    toast(e.message,'error');
    if(String(e.message||'').toLowerCase().includes('changed while'))await selectAdminPlayer(adminSelectedPlayer,false);
    return null;
  }
}

async function adminEditInventoryQuantity(){
  const i=adminSelectedInventorySlot;if(!i||i.empty)return;
  const raw=prompt(`Set quantity for ${i.name} (${i.inventory}[${i.slot}]). 0 removes it:`,String(i.stackSize||1));
  if(raw===null)return;const quantity=Number(raw);if(!Number.isInteger(quantity)||quantity<0){toast('Quantity must be a whole number 0 or greater.','error');return;}
  await adminInventoryMutation({action:'quantity',inventory:i.inventory,slot:Number(i.slot),quantity,fingerprint:i.fingerprint},`Change ${i.name} from ${i.stackSize} to ${quantity}? A snapshot will be created automatically.`);
}

async function adminMoveInventorySlot(){
  const i=adminSelectedInventorySlot;if(!i||i.empty)return;
  const inv=prompt('Destination inventory ID:',String(i.inventory||''));if(inv===null||!inv.trim())return;
  const slotRaw=prompt('Destination slot number:',String(Number(i.slot)+1));if(slotRaw===null)return;
  const slot=Number(slotRaw);if(!Number.isInteger(slot)||slot<0){toast('Invalid destination slot.','error');return;}
  const dest=adminInventoryData.find(x=>String(x.inventory)===inv.trim()&&Number(x.slot)===slot);
  if(!dest){toast('That destination slot is not present in the current inventory view.','error');return;}
  await adminInventoryMutation({action:'move',inventory:i.inventory,slot:Number(i.slot),toInventory:dest.inventory,toSlot:Number(dest.slot),fingerprint:i.fingerprint,toFingerprint:dest.fingerprint},`Move/swap ${i.inventory}[${i.slot}] with ${dest.inventory}[${dest.slot}]? A snapshot will be created first.`);
}

async function adminRemoveSelectedInventorySlot(){
  const i=adminSelectedInventorySlot;if(!i||i.empty)return;
  await adminInventoryMutation({action:'remove',inventory:i.inventory,slot:Number(i.slot),fingerprint:i.fingerprint},`Remove ${i.stackSize}x ${i.name} from ${i.inventory}[${i.slot}]? A snapshot will be created automatically.`);
}

async function adminSearchItems(){
  const q=String($('adminItemSearch').value||'').trim();
  if(q.length<2){$('adminItemSearchResults').innerHTML='<div class="small" style="padding:8px">Enter at least two characters.</div>';return;}
  $('adminItemSearchResults').innerHTML='<div class="small" style="padding:8px">Searching…</div>';
  try{
    const d=await api('/api/admin/items?search='+encodeURIComponent(q)+'&limit=60');
    const items=d.items||[];
    $('adminItemSearchResults').innerHTML=items.length?items.map((x,idx)=>`<div class="itemSearchRow"><div class="grow"><b>${esc(x.name||x.code)}</b><div class="small"><code>${esc(x.code)}</code> · ${esc(x.itemClass)} · max ${Number(x.maxStackSize||1)}</div></div><button onclick="adminSelectCatalogItem(${idx})">Select</button></div>`).join(''):'<div class="small" style="padding:8px">No matching items/blocks.</div>';
    window.adminItemSearchCache=items;
  }catch(e){$('adminItemSearchResults').innerHTML=`<div class="bad" style="padding:8px">${esc(e.message)}</div>`;}
}

function adminSelectCatalogItem(index){
  const items=window.adminItemSearchCache||[];
  adminSelectedCatalogItem=items[Number(index)]||null;
  $('adminCatalogSelected').textContent=adminSelectedCatalogItem?`${adminSelectedCatalogItem.name} · ${adminSelectedCatalogItem.code}`:'No item selected';
  if(adminSelectedCatalogItem)$('adminGiveQuantity').max=String(Math.max(1,Number(adminSelectedCatalogItem.maxStackSize||1)));
}

function adminGiveQuantity(){
  const max=Math.max(1,Number(adminSelectedCatalogItem?.maxStackSize||1));
  const q=Math.max(1,Math.min(max,Math.floor(Number($('adminGiveQuantity').value||1))));
  $('adminGiveQuantity').value=String(q);return q;
}

async function adminGiveSelectedItem(auto){
  if(!adminSelectedCatalogItem){toast('Search for and select an item first.','error');return;}
  const q=adminGiveQuantity();
  if(auto){
    await adminInventoryMutation({action:'give',code:adminSelectedCatalogItem.code,quantity:q},`Give ${q}x ${adminSelectedCatalogItem.name} to this player? A snapshot will be created first.`);return;
  }
  const i=adminSelectedInventorySlot;if(!i||!i.empty){toast('Select an empty inventory slot first.','error');return;}
  await adminInventoryMutation({action:'give',inventory:i.inventory,slot:Number(i.slot),code:adminSelectedCatalogItem.code,quantity:q,fingerprint:i.fingerprint},`Give ${q}x ${adminSelectedCatalogItem.name} to ${i.inventory}[${i.slot}]?`);
}

async function adminReplaceSelectedItem(){
  const i=adminSelectedInventorySlot;if(!i){toast('Select a target slot first.','error');return;}
  if(!adminSelectedCatalogItem){toast('Search for and select a replacement item first.','error');return;}
  const q=adminGiveQuantity();
  await adminInventoryMutation({action:'replace',inventory:i.inventory,slot:Number(i.slot),code:adminSelectedCatalogItem.code,quantity:q,fingerprint:i.fingerprint},`Replace ${i.empty?'the empty slot':i.name} in ${i.inventory}[${i.slot}] with ${q}x ${adminSelectedCatalogItem.name}? A snapshot will be created first.`);
}

async function adminCreateInventorySnapshot(){
  if(!adminSelectedPlayer)return;
  const reason=prompt('Snapshot reason:','Manual inventory snapshot');if(reason===null)return;
  try{
    const d=await api('/api/admin/inventory/snapshot',{method:'POST',body:JSON.stringify({action:'create',player:adminSelectedPlayer,reason})});
    toast(d.message,'success');await selectAdminPlayer(adminSelectedPlayer,false);await loadAdmin(false);
  }catch(e){toast(e.message,'error');}
}

function renderAdminInventorySnapshots(){
  $('adminSnapshotCount').textContent=`${adminInventorySnapshots.length} retained`;
  $('adminSnapshotRows').innerHTML=adminInventorySnapshots.length?adminInventorySnapshots.map(x=>`<tr><td>#${Number(x.id)}</td><td>${esc(fmtAdminTime(x.unixMilliseconds))}</td><td>${esc(x.createdBy||'')}</td><td>${Number(x.occupiedSlots||0)}</td><td>${esc(x.reason||'')}</td><td><button onclick="adminCompareInventorySnapshot(${Number(x.id)})">Compare</button> <button class="danger" onclick="adminRestoreInventorySnapshot(${Number(x.id)})">Restore</button></td></tr>`).join(''):'<tr><td colspan="6" class="muted">No snapshots yet. A snapshot is also created automatically before each inventory edit.</td></tr>';
}

async function adminCompareInventorySnapshot(id){
  if(!adminSelectedPlayer)return;
  $('adminSnapshotCompareState').textContent=`Comparing #${id}…`;
  try{
    const d=await api('/api/admin/inventory/compare?player='+encodeURIComponent(adminSelectedPlayer)+'&id='+Number(id));
    const rows=d.differences||[];
    $('adminSnapshotCompareState').textContent=rows.length?`${rows.length} changed slots vs #${id}`:`No changes vs #${id}`;
    $('adminSnapshotCompareRows').innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.inventory)}</td><td>${Number(r.slot)}</td><td>${esc(r.snapshotItem)}</td><td>${esc(r.currentItem)}</td><td class="inventoryDiff${esc(r.change)}">${esc(r.change)}</td></tr>`).join(''):'<tr><td colspan="5" class="ok">Current inventory matches this snapshot.</td></tr>';
  }catch(e){$('adminSnapshotCompareState').textContent='Compare failed';toast(e.message,'error');}
}

async function adminRestoreInventorySnapshot(id){
  if(!adminSelectedPlayer)return;
  if(!confirm(`Restore inventory snapshot #${id}? The current inventory will be snapshotted first so this restore can be rolled back.`))return;
  try{
    const d=await api('/api/admin/inventory/snapshot',{method:'POST',body:JSON.stringify({action:'restore',player:adminSelectedPlayer,id:Number(id)})});
    toast(d.message,'success');await selectAdminPlayer(adminSelectedPlayer,false);await loadAdmin(false);
  }catch(e){toast(e.message,'error');}
}

function renderAdminInventoryHistory(history){
  const rows=(history||[]).filter(h=>String(h.action||'').startsWith('inventory-'));
  $('adminInventoryHistoryRows').innerHTML=rows.length?rows.slice(0,80).map(h=>`<tr><td>${esc(fmtAdminTime(h.unixMilliseconds))}</td><td>${esc(h.actor)}</td><td>${esc(h.action)}</td><td>${esc(h.source)}</td><td>${esc(h.detail)}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No inventory administration history for this player yet.</td></tr>';
}

async function adminCopyPlayerSummary(){
  if(!adminSelectedPlayer){toast('Select a player first.','error');return;}
  const p=adminPlayersData.find(x=>String(x.playerUid)===String(adminSelectedPlayer));
  if(!p){toast('Player summary unavailable.','error');return;}
  const text=[
    `Player: ${playerIdentityText(p)} (${p.playerUid})`,
    `Status: ${p.online?'Online'+(p.afk?' / AFK':''):'Offline'}`,
    `Role: ${p.role||'—'} / Game mode: ${p.gameMode||'—'}`,
    `Last Seen: ${p.online?'Online now':fmtAdminTime(p.lastSeenUnixMilliseconds)+' ('+fmtAdminRelativeTime(p.lastSeenUnixMilliseconds)+')'}`,
    `First Seen: ${fmtAdminTime(p.firstSeenUnixMilliseconds)}`,
    `Total playtime: ${fmtAdminDuration(p.totalPlaySeconds)}`,
    `Warnings: ${p.activeWarnings||0}`,
    `Restrictions: ${[p.muted?'Muted':'',p.banned?'Temp banned':'',p.frozen?'Frozen':'',p.jailed?'Jailed':''].filter(Boolean).join(', ')||'None'}`
  ].join('\n');
  try{await navigator.clipboard.writeText(text);}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();}
  toast('Player summary copied.','success');
}

async function postAdminAction(payload){
  const d=await api('/api/admin/action',{method:'POST',body:JSON.stringify(payload)});
  toast(d.message||'Admin action completed.','success');
  await loadAdmin(false);
}

async function adminPromptAction(action){
  if(!adminSelectedPlayer){toast('Select a player first.','error');return;}
  const player=adminSelectedPlayer;
  try{
    if(action==='warn'){
      const reason=prompt('Warning reason:',''); if(reason===null||!reason.trim())return;
      await postAdminAction({action,player,reason}); return;
    }
    if(action==='mute'||action==='tempban'||action==='freeze'){
      const def=action==='freeze'?'permanent':'30m';
      const duration=prompt(`${action==='tempban'?'Temporary ban':action==='mute'?'Mute':'Freeze'} duration (30m, 6h, 3d, 2w${action!=='tempban'?', permanent':''}):`,def); if(duration===null||!duration.trim())return;
      const reason=prompt('Reason:',''); if(reason===null)return;
      if(!confirm(`Confirm ${action} for selected player?`))return;
      await postAdminAction({action,player,duration,reason}); return;
    }
    if(action==='jail'){
      const duration=prompt('Jail duration (10m, 2h, 3d, 1w, permanent):','30m'); if(duration===null||!duration.trim())return;
      const reason=prompt('Jail reason:',''); if(reason===null)return;
      if(!confirm('Confirm jail for selected player?'))return;
      await postAdminAction({action,player,duration,reason}); return;
    }
    if(action==='note'){
      const note=prompt('Staff note (not visible to the player):',''); if(note===null||!note.trim())return;
      await postAdminAction({action:'note',player,note}); return;
    }
    const labels={unmute:'clear mute',unban:'clear temporary ban',unfreeze:'unfreeze',unjail:'release from jail',kick:'kick',heal:'heal',feed:'feed',revive:'revive',smite:'smite with lightning',sendback:'send back',allowcharselonce:'allow one character re-selection'};
    let reason='';
    if(action==='kick'){reason=prompt('Kick reason:','Kicked by staff')||''; if(!reason)return;}
    if(action==='smite'){const entered=prompt('Smite reason (optional):',''); if(entered===null)return; reason=entered;}
    if(!confirm(`Confirm ${labels[action]||action} for the selected player?`))return;
    await postAdminAction({action,player,reason});
  }catch(e){toast(e.message,'error');}
}

async function adminRemoveWarning(id){
  if(!confirm(`Remove warning #${id}?`))return;
  try{await postAdminAction({action:'unwarn',player:adminSelectedPlayer,id});}catch(e){toast(e.message,'error');}
}
async function adminRemoveNote(id){
  if(!confirm(`Remove staff note #${id}?`))return;
  try{await postAdminAction({action:'note-remove',player:adminSelectedPlayer,id});}catch(e){toast(e.message,'error');}
}

async function adminUndoLast(){
  if(!confirm('Undo the most recent reversible suite admin action?'))return;
  try{await postAdminAction({action:'undo',player:''});}catch(e){toast(e.message,'error');}
}

async function adminMaintenance(enabled){
  try{
    if(!enabled){if(!confirm('Disable maintenance mode?'))return; const d=await api('/api/admin/maintenance',{method:'POST',body:JSON.stringify({enabled:false})});toast(d.message,'success');await loadAdmin(false);return;}
    const duration=prompt('Optional maintenance duration (for example 30m or 2h). Leave blank for manual off:','30m'); if(duration===null)return;
    const reason=prompt('Maintenance reason:','Server maintenance'); if(reason===null)return;
    if(!confirm('Enable maintenance mode? New non-staff connections will be rejected.'))return;
    const confirmation=prompt('Safety check: type MAINTENANCE to continue:','')||'';if(confirmation.toUpperCase()!=='MAINTENANCE')return;
    const d=await api('/api/admin/maintenance',{method:'POST',body:JSON.stringify({enabled:true,duration:duration.trim(),reason,confirmation})});toast(d.message,'success');await loadAdmin(false);
  }catch(e){toast(e.message,'error');}
}

async function adminShutdown(schedule,restart=false){
  try{
    if(!schedule){if(!confirm('Cancel the scheduled shutdown?'))return; const d=await api('/api/admin/shutdown',{method:'POST',body:JSON.stringify({action:'cancel'})});toast(d.message,'success');await loadAdmin(false);return;}
    const duration=prompt(`${restart?'Restart':'Shutdown'} delay (for example 10m, 30s, 1h):`,'10m'); if(duration===null||!duration.trim())return;
    const reason=prompt(`${restart?'Restart':'Shutdown'} reason:`,'Server maintenance'); if(reason===null)return;
    if(!confirm(`Schedule a clean server ${restart?'restart':'shutdown'} in ${duration}?${restart?' The host/supervisor must restart the process.':''}`))return;
    const expected=restart?'RESTART':'SHUTDOWN';const confirmation=prompt(`Safety check: type ${expected} to continue:`,'')||'';if(confirmation.toUpperCase()!==expected)return;
    const d=await api('/api/admin/shutdown',{method:'POST',body:JSON.stringify({action:restart?'restart':'schedule',duration,reason,confirmation})});toast(d.message,'success');await loadAdmin(false);
  }catch(e){toast(e.message,'error');}
}

async function adminCleanup(confirmRun){
  try{
    if(confirmRun&&!confirm('Remove loaded dropped-item entities now? This cannot be undone.'))return;
    let confirmation='';if(confirmRun){confirmation=prompt('Safety check: type CLEANUP to continue:','')||'';if(confirmation.toUpperCase()!=='CLEANUP')return;}
    const d=await api('/api/admin/cleanup',{method:'POST',body:JSON.stringify({confirm:!!confirmRun,maxRemove:100000,confirmation})});
    $('adminCleanupState').textContent=d.dryRun?`Loaded ${d.loadedEntities||0} · creatures ${d.creatures||0} · inanimate ${d.inanimateEntities||0} · dead/despawning ${d.deadOrDespawning||0} · dropped ${d.droppedItems||0}`:`Removed ${d.removed||0} dropped items`;
    toast(d.dryRun?`Scan: ${d.loadedEntities||0} loaded entities, ${d.droppedItems||0} dropped items.`:`Removed ${d.removed||0} dropped items.`,'success');
    await loadAdmin(false);
  }catch(e){toast(e.message,'error');}
}

function logImpactClass(impact){
  impact=String(impact||'').toLowerCase();
  return impact==='critical'?'bad':impact==='high'?'orange':impact==='moderate'?'warn':impact==='low'?'muted':'';
}

function preflightClass(sev){
  sev=String(sev||'').toLowerCase();
  return sev==='critical'?'bad':sev==='high'?'orange':sev==='watch'?'warn':sev==='ok'?'good':'';
}

async function loadServerStatus(showLoading=true){
  if(showLoading)$('serverStatusState').textContent='Loading server status…';
  document.querySelectorAll('[data-player-days]').forEach(btn=>btn.classList.toggle('active',Number(btn.dataset.playerDays)===playerAnalyticsDays));
  try{
    serverStatusData=await api(`/api/server-status?days=${playerAnalyticsDays}`);
    playerAnalyticsData=serverStatusData.analytics||{};
    renderServerStatus();
    renderPlayerAnalytics();
  }catch(e){
    $('serverStatusState').textContent=e.message;
    if(showLoading)toast(e.message,'error');
  }
}

function formatBytesTotal(value){
  value=Math.max(0,Number(value||0));
  if(value>=1024*1024*1024)return `${(value/(1024*1024*1024)).toFixed(2)} GB`;
  if(value>=1024*1024)return `${(value/(1024*1024)).toFixed(2)} MB`;
  if(value>=1024)return `${(value/1024).toFixed(1)} KB`;
  return `${value.toFixed(0)} B`;
}

function renderServerStatus(){
  const d=serverStatusData||{},srv=d.server||{},m=d.maintenance||{},sh=d.shutdown||{},r=d.reports||{},players=d.onlinePlayers||[];
  const updated=d.generatedUnixMilliseconds?new Date(Number(d.generatedUnixMilliseconds)).toLocaleTimeString():'—';
  setNavStatus('serverStatus','good','Server status endpoint healthy');
  setReportsNavState(r.open,r.investigating);
  $('serverStatusState').textContent=`${Number(srv.onlinePlayers||0)} online · uptime ${fmtAdminDuration(Number(srv.uptimeSeconds||0))} · updated ${updated}`;
  $('serverStatusMetrics').innerHTML=
    metric('Online players',Number(srv.onlinePlayers||0).toLocaleString())+
    metric('Server uptime',fmtAdminDuration(Number(srv.uptimeSeconds||0)))+
    metric('Average ping',`${Number(srv.averagePingMilliseconds||0).toFixed(0)} ms`)+
    metric('Peak ping',`${Number(srv.maxPingMilliseconds||0).toFixed(0)} ms`)+
    metric('Network out',formatBytesRate(Number(srv.sentBytesPerSecond||0)))+
    metric('Network in',formatBytesRate(Number(srv.receivedBytesPerSecond||0)))+
    metric('Loaded mods',Number(srv.loadedMods||0).toLocaleString())+
    metric('Tracked players',Number(srv.trackedPlayers||0).toLocaleString());

  const maintenanceText=m.enabled
    ? `<span class="warn"><b>Maintenance ON</b></span> · ${esc(m.reason||'Maintenance')}${Number(m.untilUnixMilliseconds||0)>0?` · until ${esc(fmtAdminTime(m.untilUnixMilliseconds))}`:''}`
    : '<span class="good"><b>Maintenance OFF</b></span>';
  const shutdownText=Number(sh.atUnixMilliseconds||0)>Date.now()
    ? `<span class="warn"><b>Scheduled server action</b></span> · ${esc(fmtAdminTime(sh.atUnixMilliseconds))} · ${esc(sh.reason||'')}`
    : '<span class="muted">No shutdown/restart scheduled.</span>';
  $('serverStatusOpsMeta').textContent=`${Number(r.open||0)} open report(s) · ${Number(r.investigating||0)} investigating`;
  $('serverStatusOps').innerHTML=`
    <div style="margin-bottom:9px">${maintenanceText}</div>
    <div style="margin-bottom:9px">${shutdownText}</div>
    <div><b>Traffic totals:</b> ${esc(formatBytesTotal(srv.totalSentBytes))} sent · ${esc(formatBytesTotal(srv.totalReceivedBytes))} received</div>
    <div style="margin-top:7px"><b>World runtime:</b> ${esc(fmtAdminDuration(Number(srv.worldPlayTimeSeconds||0)))} · <b>Server timezone:</b> ${esc(srv.serverTimeZone||'Local')}</div>
    <div style="margin-top:7px"><b>Reports:</b> ${Number(r.open||0)} open · ${Number(r.investigating||0)} investigating · ${Number(r.total||0)} total</div>`;

  $('serverStatusOnlineMeta').textContent=`${players.length} currently online`;
  $('serverStatusOnlineRows').innerHTML=players.length?players.map(p=>`<tr><td>${playerIdentityHtml(p,'name',false)}</td><td>${Number(p.pingMilliseconds||0)} ms</td><td>${p.afk?'<span class="badge medium">AFK</span>':'<span class="badge high">ACTIVE</span>'}</td><td>${esc(fmtAdminDuration(Number(p.sessionSeconds||0)))}</td><td>${esc(p.role||'')}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No players are currently online.</td></tr>';
}

function renderPlayerAnalytics(){
  const d=playerAnalyticsData||{}, daily=d.daily||[], hourly=d.last24Hours||d.todayHourly||[], g=serverStatusData?.growth||{};
  $('playerAnalyticsState').textContent=`${Number(d.currentPlayers||0)} online · ${daily.length} daily bucket(s) · updated ${d.generatedUnixMilliseconds?new Date(Number(d.generatedUnixMilliseconds)).toLocaleTimeString():'—'}`;
  $('playerAnalyticsTimezone').textContent=`Server local time: ${d.serverTimeZone||'Local'}`;
  const weekGrowth=Number(g.newPlayerWeekGrowthPercent||0);
  const weekGrowthText=`${weekGrowth>=0?'+':''}${weekGrowth.toFixed(0)}% vs prior 7d`;
  $('playerAnalyticsMetrics').innerHTML=
    metric('Online now',Number(d.currentPlayers||0).toLocaleString())+
    metric('Peak today',Number(d.todayHigh||0).toLocaleString())+
    metric('Average today',Number(d.todayAverage||0).toFixed(1))+
    metric('New players · 24h',Number(g.newPlayers24Hours||0).toLocaleString())+
    metric('New players · 7d',`${Number(g.newPlayers7Days||0).toLocaleString()} · ${weekGrowthText}`)+
    metric('New players · 30d',Number(g.newPlayers30Days||0).toLocaleString())+
    metric('Active players · 24h',Number(g.activePlayers24Hours||0).toLocaleString())+
    metric('Active players · 7d',Number(g.activePlayers7Days||0).toLocaleString())+
    metric('Active players · 30d',Number(g.activePlayers30Days||0).toLocaleString())+
    metric('Returning players · 7d',Number(g.returningPlayers7Days||0).toLocaleString())+
    metric('7-day return rate',`${Number(g.sevenDayReturnRate||0).toFixed(1)}% · cohort ${Number(g.sevenDayReturnCohort||0)}`)+
    metric('30-day concurrency peak',Number(g.peakPlayers30Days||0).toLocaleString())+
    metric('Avg daily peak · 30d',Number(g.averageDailyPeak30Days||0).toFixed(1))+
    metric('Total known players',Number(g.totalKnownPlayers||0).toLocaleString());

  const observedHours=hourly.filter(x=>x.average!==null&&x.average!==undefined);
  const peakHour=observedHours.length?observedHours.reduce((a,b)=>Number(b.high||0)>Number(a.high||0)?b:a):null;
  const peakDay=daily.length?daily.reduce((a,b)=>Number(b.high||0)>Number(a.high||0)?b:a):null;
  const newRows=g.dailyNewPlayers||[];
  const newPeak=newRows.length?newRows.reduce((a,b)=>Number(b.count||0)>Number(a.count||0)?b:a):null;
  $('playerDailyMeta').textContent=peakDay?`30-day peak ${Number(peakDay.high||0)} on ${peakDay.date}`:'No daily history yet';
  $('playerHourlyMeta').textContent=peakHour?`24h peak ${Number(peakHour.high||0)} at ${peakHour.label}`:'No hourly history yet';
  $('playerNewMeta').textContent=newPeak?`Best acquisition day: ${Number(newPeak.count||0)} new on ${newPeak.date}`:'No new-player history yet';
  redrawPlayerAnalyticsCharts();
}

function drawPlayerChartGrid(ctx,w,h,pad,maxValue){
  const plotH=Math.max(1,h-pad.t-pad.b),plotW=Math.max(1,w-pad.l-pad.r);
  const yMax=Math.max(1,Math.ceil(maxValue));
  ctx.font='10px system-ui';
  chartPlotBackground(ctx,pad,w,h,4,6);
  ctx.fillStyle='#748797';
  for(let i=0;i<=4;i++){
    const y=pad.t+plotH*i/4;
    const value=yMax-(yMax*i/4);
    ctx.fillText(String(Math.round(value)),Math.max(4,pad.l-34),y+3);
  }
  return{plotH,plotW,yMax,yFor:v=>pad.t+(1-clamp(Number(v||0)/yMax,0,1))*plotH};
}

function drawDailyPlayerChart(){
  const canvas=$('playerDailyChart');
  if(!canvas)return;
  const rows=(playerAnalyticsData?.daily||[]);
  const {ctx,w,h}=resizeCanvas(canvas);
  ctx.clearRect(0,0,w,h);
  const pad={l:42,r:12,t:14,b:34};
  if(!rows.length){ctx.fillStyle='#8492a0';ctx.font='11px system-ui';ctx.fillText('No player-count history yet.',18,26);return;}

  const maxValue=Math.max(1,...rows.map(x=>Number(x.high||0)));
  const g=drawPlayerChartGrid(ctx,w,h,pad,maxValue);
  const xFor=i=>pad.l+(rows.length<=1?g.plotW/2:(i/(rows.length-1))*g.plotW);

  const highPoints=rows.map((row,i)=>[xFor(i),g.yFor(row.high)]);
  const lowPoints=rows.map((row,i)=>[xFor(i),g.yFor(row.low)]);
  ctx.save();ctx.beginPath();highPoints.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));[...lowPoints].reverse().forEach(([x,y])=>ctx.lineTo(x,y));ctx.closePath();ctx.fillStyle='rgba(103,159,203,.10)';ctx.fill();ctx.restore();
  chartLine(ctx,highPoints,'#75afe0',2.2);chartLine(ctx,lowPoints,'#7fbf79',1.8);chartEndPoint(ctx,highPoints,'#dcebf6');

  ctx.fillStyle='#748392';ctx.font='10px system-ui';
  const stride=Math.max(1,Math.ceil(rows.length/6));
  rows.forEach((row,i)=>{
    if(i%stride!==0&&i!==rows.length-1)return;
    const x=xFor(i);const parts=String(row.date||'').split('-');const label=parts.length===3?`${parts[1]}/${parts[2]}`:String(row.date||'');
    const tw=ctx.measureText(label).width;ctx.fillText(label,clamp(x-tw/2,pad.l,w-pad.r-tw),h-10);
  });
}

function drawHourlyPlayerChart(){
  const canvas=$('playerHourlyChart');
  if(!canvas)return;
  const rows=(playerAnalyticsData?.last24Hours||playerAnalyticsData?.todayHourly||[]);
  const {ctx,w,h}=resizeCanvas(canvas);
  ctx.clearRect(0,0,w,h);
  const pad={l:42,r:12,t:14,b:34};
  const valid=rows.map((x,i)=>({...x,_index:i})).filter(x=>x.average!==null&&x.average!==undefined);
  if(!valid.length){ctx.fillStyle='#8492a0';ctx.font='11px system-ui';ctx.fillText('No observed player-count hours yet.',18,26);return;}

  const maxValue=Math.max(1,...valid.map(x=>Math.max(Number(x.high||0),Number(x.average||0))));
  const g=drawPlayerChartGrid(ctx,w,h,pad,maxValue);
  const xFor=i=>pad.l+(rows.length<=1?g.plotW/2:(i/(rows.length-1))*g.plotW);

  ctx.save();ctx.strokeStyle='rgba(214,170,97,.48)';ctx.lineWidth=1;
  valid.forEach(row=>{const x=xFor(row._index),y1=g.yFor(row.low||0),y2=g.yFor(row.high||0);ctx.beginPath();ctx.moveTo(x,y1);ctx.lineTo(x,y2);ctx.stroke();});ctx.restore();
  const avgPoints=valid.map(row=>[xFor(row._index),g.yFor(row.average||0)]);
  chartAreaFill(ctx,avgPoints,pad.t+g.plotH,'rgba(93,155,208,.09)');chartLine(ctx,avgPoints,'#75afe0',2.2);chartEndPoint(ctx,avgPoints,'#dcebf6');

  ctx.fillStyle='#748392';ctx.font='10px system-ui';
  rows.forEach((row,i)=>{
    if(i%4!==0&&i!==rows.length-1)return;
    const label=String(row.label||'');const x=xFor(i),tw=ctx.measureText(label).width;
    ctx.fillText(label,clamp(x-tw/2,pad.l,w-pad.r-tw),h-10);
  });
}

function drawNewPlayerChart(){
  const canvas=$('playerNewChart');
  if(!canvas)return;
  const rows=(serverStatusData?.growth?.dailyNewPlayers||[]);
  const {ctx,w,h}=resizeCanvas(canvas);
  ctx.clearRect(0,0,w,h);
  const pad={l:42,r:12,t:14,b:34};
  if(!rows.length){ctx.fillStyle='#8492a0';ctx.font='11px system-ui';ctx.fillText('No first-seen player history yet.',18,26);return;}
  const maxValue=Math.max(1,...rows.map(x=>Number(x.count||0)));
  const g=drawPlayerChartGrid(ctx,w,h,pad,maxValue);
  const xFor=i=>pad.l+(rows.length<=1?g.plotW/2:(i/(rows.length-1))*g.plotW);
  const points=rows.map((row,i)=>[xFor(i),g.yFor(row.count||0)]);
  chartAreaFill(ctx,points,pad.t+g.plotH,'rgba(93,155,208,.09)');chartLine(ctx,points,'#75afe0',2.2);chartEndPoint(ctx,points,'#dcebf6');
  ctx.fillStyle='#748392';ctx.font='10px system-ui';
  const stride=Math.max(1,Math.ceil(rows.length/6));
  rows.forEach((row,i)=>{if(i%stride!==0&&i!==rows.length-1)return;const parts=String(row.date||'').split('-');const label=parts.length===3?`${parts[1]}/${parts[2]}`:String(row.date||'');const x=xFor(i),tw=ctx.measureText(label).width;ctx.fillText(label,clamp(x-tw/2,pad.l,w-pad.r-tw),h-10);});
}

function redrawPlayerAnalyticsCharts(){
  if(!playerAnalyticsData)return;
  drawDailyPlayerChart();
  drawHourlyPlayerChart();
  drawNewPlayerChart();
}

