$('serverStatusReports').onclick=()=>setSection('reports',true);
$('serverStatusPlayers').onclick=()=>setSection('admin',true);
$('serverStatusOperations').onclick=()=>setSection('operations',true);
$('serverStatusProfiler').onclick=()=>setSection('profiler',true);
$('serverStatusCopy').onclick=async()=>{
  const d=serverStatusData||{},s=d.server||{},a=d.analytics||{},r=d.reports||{};
  const text=[
    'Newfies Server Essentials - Server Status',
    `Online: ${Number(s.onlinePlayers||0)} / tracked ${Number(s.trackedPlayers||0)}`,
    `Uptime: ${fmtAdminDuration(Number(s.uptimeSeconds||0))}`,
    `Ping: avg ${Number(s.averagePingMilliseconds||0).toFixed(0)} ms / max ${Number(s.maxPingMilliseconds||0).toFixed(0)} ms`,
    `Today players: low ${Number(a.todayLow||0)} / avg ${Number(a.todayAverage||0).toFixed(1)} / high ${Number(a.todayHigh||0)}`,
    `Network: ${formatBytesRate(Number(s.sentBytesPerSecond||0))} out / ${formatBytesRate(Number(s.receivedBytesPerSecond||0))} in`,
    `Reports: ${Number(r.open||0)} open / ${Number(r.investigating||0)} investigating`
  ].join('\n');
  await copyText(text,'Server status copied.');
};
document.querySelectorAll('[data-player-days]').forEach(btn=>btn.onclick=()=>{
  playerAnalyticsDays=Number(btn.dataset.playerDays||30);
  localStorage.setItem('nsu.playerAnalyticsDays',String(playerAnalyticsDays));
  loadServerStatus(true);
});

function reportStatusClass(status){
  const s=String(status||'').toLowerCase();
  return s==='resolved'?'reportStatusResolved':s==='investigating'?'reportStatusInvestigating':'reportStatusOpen';
}

async function loadReports(showLoading=true){
  if(showLoading)$('reportsState').textContent='Loading reports…';
  document.querySelectorAll('[data-report-status]').forEach(btn=>btn.classList.toggle('active',btn.dataset.reportStatus===reportFilter));
  try{
    reportsData=await api(`/api/reports?status=${encodeURIComponent(reportFilter)}&limit=500`);
    renderReports();
  }catch(e){
    $('reportsState').textContent=e.message;
    if(showLoading)toast(e.message,'error');
  }
}

function renderReports(){
  const d=reportsData||{}, rows=d.reports||[];
  setReportsNavState(d.openCount,d.investigatingCount);
  $('reportsState').textContent=`${Number(d.openCount||0)} open · ${Number(d.investigatingCount||0)} investigating · ${Number(d.resolvedCount||0)} resolved`;
  $('reportsMetrics').innerHTML=
    metric('Open',Number(d.openCount||0).toLocaleString(),Number(d.openCount||0)?'warn':'good')+
    metric('Investigating',Number(d.investigatingCount||0).toLocaleString(),Number(d.investigatingCount||0)?'good':'')+
    metric('Resolved',Number(d.resolvedCount||0).toLocaleString())+
    metric('Total reports',Number(d.totalCount||0).toLocaleString());
  $('reportRootCommand').textContent=d.rootCommandRegisteredBySuite
    ? '/report owned by Newfies Server Essentials'
    : `/report left to ${d.rootCommandOwner||'another provider'} · /nse report is available`;
  $('reportsQueueMeta').textContent=`Showing ${rows.length} ${reportFilter==='all'?'report(s)':reportFilter+' report(s)'}`;
  $('reportsRows').innerHTML=rows.length?rows.map(r=>`<tr class="clickableRow" data-report-id="${Number(r.id||0)}">
    <td><b>#${Number(r.id||0)}</b></td>
    <td class="${reportStatusClass(r.status)}"><b>${esc(r.status||'Open')}</b></td>
    <td>${esc(r.reporterName||'Unknown')}</td>
    <td class="reportReason" title="${esc(r.reason||'')}"><b>${esc(r.reason||'')}</b></td>
    <td>${esc(r.assignedStaff||'Unassigned')}</td>
    <td>${esc(fmtAdminRelativeTime(r.updatedUnixMilliseconds||r.createdUnixMilliseconds))}<div class="small">${esc(fmtAdminTime(r.updatedUnixMilliseconds||r.createdUnixMilliseconds))}</div></td>
  </tr>`).join(''):'<tr><td colspan="6" class="muted">No reports in this queue.</td></tr>';
  document.querySelectorAll('[data-report-id]').forEach(row=>row.onclick=()=>showReport(Number(row.dataset.reportId||0)));

  if(selectedReportId){
    const selected=rows.find(x=>Number(x.id)===Number(selectedReportId));
    if(selected)renderReportDetail(selected);
    else if(reportFilter!=='all')$('reportDetail').innerHTML='<div class="emptyAction"><b>The selected report is outside this filter.</b><br>Switch to All to view it again.</div>';
  }
}

function showReport(id){
  selectedReportId=Number(id||0);
  const row=(reportsData?.reports||[]).find(x=>Number(x.id)===selectedReportId);
  if(row)renderReportDetail(row);
}

function renderReportDetail(r){
  const notes=r.notes||[], events=r.events||[];
  const status=String(r.status||'Open');
  $('reportDetail').innerHTML=`
    <div class="cardHeader"><h3>Report #${Number(r.id||0)}</h3><div class="spacer"></div><span class="${reportStatusClass(status)}"><b>${esc(status)}</b></span></div>
    <div class="grid" style="grid-template-columns:repeat(2,minmax(140px,1fr));margin-bottom:12px">
      <div><div class="metricLabel">Reporter</div><b>${esc(r.reporterName||'Unknown')}</b></div>
      <div><div class="metricLabel">Type</div><b>General issue</b></div>
      <div><div class="metricLabel">Assigned</div><b>${esc(r.assignedStaff||'Unassigned')}</b></div>
      <div><div class="metricLabel">Created</div><b>${esc(fmtAdminTime(r.createdUnixMilliseconds))}</b></div>
    </div>
    <div class="card" style="background:#10171d;margin-bottom:12px"><div class="metricLabel">Issue</div><div style="margin-top:7px;white-space:normal">${esc(r.reason||'')}</div></div>
    <div class="rowActions" style="margin-bottom:12px">
      <button onclick="reportAssignMe()">Assign to Me</button>
      <button onclick="reportAssignCustom()">Assign…</button>
      <button onclick="reportAction('unassign')">Unassign</button>
      ${status!=='Investigating'?'<button onclick="reportAction(\'investigate\')">Investigating</button>':''}
      ${status!=='Resolved'?'<button class="primary" onclick="reportAction(\'resolve\')">Resolve</button>':'<button onclick="reportAction(\'reopen\')">Reopen</button>'}
      <button onclick="reportAddNote()">Add Note</button>
      <button onclick="openReportPlayer()">Open Player</button>
    </div>
    <div class="cardHeader"><h4>Private Notes</h4><div class="spacer"></div><span class="small">${notes.length}</span></div>
    <div style="margin-bottom:14px">${notes.length?notes.slice().reverse().map(n=>`<div class="reportTimelineItem"><b>${esc(n.author||'Staff')}</b> <span class="small">${esc(fmtAdminTime(n.unixMilliseconds))}</span><div style="margin-top:4px;white-space:normal">${esc(n.text||'')}</div></div>`).join(''):'<div class="small">No private staff notes yet.</div>'}</div>
    <div class="cardHeader"><h4>Timeline</h4><div class="spacer"></div><span class="small">${events.length} event(s)</span></div>
    <div class="reportTimeline">${events.length?events.slice().reverse().map(e=>`<div class="reportTimelineItem"><b>${esc(e.action||'Update')}</b> · ${esc(e.actor||'Staff')} <span class="small">${esc(fmtAdminTime(e.unixMilliseconds))}</span><div class="small" style="margin-top:3px;white-space:normal">${esc(e.detail||'')}</div></div>`).join(''):'<div class="small">No timeline events.</div>'}</div>`;
}

async function reportAction(action,value='',note=''){
  if(!selectedReportId)return;
  try{
    const result=await api('/api/reports/action',{method:'POST',body:JSON.stringify({id:selectedReportId,action,value,note})});
    toast(result.message||'Report updated.','success');
    await loadReports(false);
  }catch(e){toast(e.message,'error');}
}

function reportAssignMe(){
  const me=String($('headerUser')?.textContent||'admin').trim()||'admin';
  reportAction('assign',me);
}

function reportAssignCustom(){
  const staff=prompt('Assign this report to staff member:','');
  if(staff===null||!staff.trim())return;
  reportAction('assign',staff.trim());
}

function reportAddNote(){
  const note=prompt('Private staff note:','');
  if(note===null||!note.trim())return;
  reportAction('note','',note.trim());
}

async function openReportPlayer(){
  const row=(reportsData?.reports||[]).find(x=>Number(x.id)===Number(selectedReportId));
  if(!row)return;
  setSection('admin',false);
  await loadAdmin(true);
  const key=row.targetUid||row.targetName||'';
  if(key)await selectAdminPlayer(key,true);
}

$('reportsRefresh').onclick=()=>loadReports(true);
document.querySelectorAll('[data-report-status]').forEach(btn=>btn.onclick=()=>{
  reportFilter=btn.dataset.reportStatus||'open';
  localStorage.setItem('nsu.reportFilter',reportFilter);
  loadReports(true);
});

async function loadLogIntelligence(showLoading=true){
  if(showLoading)$('logState').textContent='Loading log intelligence…';
  try{
    logIntelligenceData=await api('/api/log-intelligence');
    renderLogIntelligence();
  }catch(e){
    $('logState').textContent=e.message;
    if(showLoading)toast(e.message,'error');
  }
}

function renderLogIntelligence(){
  const d=logIntelligenceData||{}, cats=d.categories||[], issues=d.issues||[], pf=d.preflight||{}, changes=pf.modChanges||{};
  const score=Number(d.score||0), state=d.state||'Unknown';
  $('logState').textContent=`${state} · ${Number(d.uniqueIssues||0)} unique issue(s) · last scan ${d.lastScanUnixMilliseconds?new Date(Number(d.lastScanUnixMilliseconds)).toLocaleTimeString():'not yet'}`;
  $('logHero').innerHTML=`<div class="smartHero"><div class="healthScore ${score>=90?'healthy':score>=75?'watch':score>=50?'investigate':'critical'}">${score}</div><div><h3 style="margin-bottom:5px">Log Health — ${esc(state)}</h3><div class="small">Current source: <code>${esc(d.currentLogPath||'server-main.log not found yet')}</code></div><div class="small" style="margin-top:5px">Live collection tails only new data. Archived logs are scanned only when you press <b>Scan Archived Logs</b>.</div></div></div>`;
  $('logMetrics').innerHTML=
    metric('Critical',Number(d.critical||0).toLocaleString(),Number(d.critical||0)?'bad':'good')+
    metric('High',Number(d.high||0).toLocaleString(),Number(d.high||0)?'orange':'good')+
    metric('Moderate',Number(d.moderate||0).toLocaleString(),Number(d.moderate||0)?'warn':'good')+
    metric('Low',Number(d.low||0).toLocaleString())+
    metric('Occurrences',Number(d.totalOccurrences||0).toLocaleString())+
    metric('Unique signatures',Number(d.uniqueIssues||0).toLocaleString());

  renderBadBlockEntities();
  if($('logIssueClearAll'))$('logIssueClearAll').disabled=currentSessionRole==='ReadOnly'||issues.length===0;

  $('logCategoryRows').innerHTML=cats.length?cats.map(x=>`<tr><td><b>${esc(x.category)}</b></td><td>${Number(x.occurrences||0).toLocaleString()}</td><td>${Number(x.uniqueIssues||0).toLocaleString()}</td><td class="${logImpactClass(x.impact)}"><b>${esc(x.impact)}</b></td></tr>`).join(''):'<tr><td colspan="4" class="muted">No actionable warnings/errors have been grouped yet.</td></tr>';

  $('logIssueRows').innerHTML=issues.length?issues.map((x,i)=>`<tr class="clickableRow" data-log-issue="${i}"><td class="${logImpactClass(x.impact)}"><b>${esc(x.impact)}</b></td><td>${esc(x.category)}</td><td class="codeCell"><b>${esc(x.title)}</b></td><td>${Number(x.occurrences||0).toLocaleString()}</td><td>${esc(x.likelyModName||x.likelyModId||'Unattributed')}</td><td>${esc(x.attributionConfidence||'Low')}</td><td>${x.lastSeenUnixMilliseconds?esc(new Date(Number(x.lastSeenUnixMilliseconds)).toLocaleString()):'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No actionable issue signatures found.</td></tr>';
  document.querySelectorAll('[data-log-issue]').forEach(row=>row.onclick=()=>showLogIssue(Number(row.dataset.logIssue||0)));

  $('preflightState').textContent=`${pf.status||'Unknown'} · ${Number(pf.loadedModCount||0)} loaded mods · game ${pf.loadedGameVersion||'unknown'} / target ${pf.targetGameVersion||'unknown'}`;
  $('preflightMetrics').innerHTML=
    metric('Preflight status',pf.status||'Unknown',pf.status==='Critical'?'bad':pf.status==='Investigate'?'orange':pf.status==='Watch'?'warn':'good')+
    metric('Critical checks',Number(pf.critical||0).toLocaleString(),Number(pf.critical||0)?'bad':'good')+
    metric('High checks',Number(pf.high||0).toLocaleString(),Number(pf.high||0)?'orange':'good')+
    metric('Watch checks',Number(pf.watch||0).toLocaleString(),Number(pf.watch||0)?'warn':'good');
  const checks=pf.checks||[];
  $('preflightRows').innerHTML=checks.length?checks.map(x=>`<tr><td class="${preflightClass(x.severity)}"><b>${esc(x.severity)}</b></td><td>${esc(x.category)}</td><td><b>${esc(x.title)}</b></td><td>${esc(x.detail)}</td><td>${esc(x.recommendedAction||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No preflight checks available.</td></tr>';

  const added=changes.added||[], removed=changes.removed||[], updated=changes.updated||[];
  const list=(title,rows,klass)=>`<div class="card"><h4 class="${klass}">${title} (${rows.length})</h4><div class="small logListScroll" style="margin-top:7px">${rows.length?rows.map(x=>`<div>${esc(x)}</div>`).join(''):'None'}</div></div>`;
  $('logModChanges').innerHTML=`<div class="grid">${list('Added',added,'good')}${list('Updated',updated,'warn')}${list('Removed',removed,'bad')}</div>${changes.hasPreviousManifest?'':'<div class="infoBox" style="margin-top:10px">This boot established the first loaded-mod baseline. The next recorded boot will show additions, removals and version/file changes.</div>'}`;
  enhanceTableByBodyId('logIssueRows');
  enhanceTableByBodyId('preflightRows');
}

function renderBadBlockEntities(){
  const d=((logIntelligenceData||{}).badBlockEntities||{}), rows=d.entries||[];
  $('badBeState').textContent=`${Number(d.tracking||0)} active · ${Number(d.stopped||0)} stopped · ${Number(d.totalOccurrences||0).toLocaleString()} captured tick error(s)`;
  $('badBeRows').innerHTML=rows.length?rows.map(x=>{
    const key=esc(x.key||''), active=x.tracking!==false;
    const pos=`${Number(x.x||0)}, ${Number(x.y||0)}, ${Number(x.z||0)}${Number(x.dimension||0)?` · dim ${Number(x.dimension||0)}`:''}`;
    const when=`${x.firstSeenUnixMilliseconds?esc(new Date(Number(x.firstSeenUnixMilliseconds)).toLocaleString()):'—'}<br><span class="small">${x.lastSeenUnixMilliseconds?esc(new Date(Number(x.lastSeenUnixMilliseconds)).toLocaleString()):'—'}</span>`;
    let controls=`<button data-bbe-inspect="${key}">Inspect</button>`;
    if(currentSessionRole!=='ReadOnly'){
      controls+=` <button data-bbe-teleport="${key}">Teleport</button>`;
      controls+=active?` <button data-bbe-stop="${key}">Stop Tracking</button>`:` <button data-bbe-resume="${key}">Resume</button>`;
      controls+=` <button class="danger" data-bbe-remove="${key}">Remove Block Entity</button>`;
      controls+=` <button class="danger" data-bbe-replace="${key}" data-block-code="${esc(x.blockCode||'')}">Replace Block</button>`;
    }
    const lastAction=x.lastAction?`<div class="small" style="margin-top:5px">${esc(x.lastAction)}${x.lastActionBy?` · ${esc(x.lastActionBy)}`:''}</div>`:'';
    return `<tr><td class="${active?'warn':'muted'}"><b>${active?'Tracking':'Stopped'}</b>${lastAction}</td><td><code>${esc(pos)}</code></td><td><b>${esc(x.blockCode||'')}</b><div class="small"><code>${esc(x.blockEntityType||'')}</code></div></td><td><b>${Number(x.occurrences||0).toLocaleString()}</b></td><td>${when}</td><td class="codeCell">${esc(x.lastException||'Unknown exception')}<div class="small">${esc(x.lastTopFrame||'')}</div></td><td><div class="rowActions">${controls}</div></td></tr>`;
  }).join(''):'<tr><td colspan="6" class="muted">No block-entity tick exceptions have been captured from the live server log.</td></tr>';

  document.querySelectorAll('[data-bbe-inspect]').forEach(b=>b.onclick=()=>inspectBadBlockEntity(b.dataset.bbeInspect||''));
  document.querySelectorAll('[data-bbe-teleport]').forEach(b=>b.onclick=()=>teleportToBadBlockEntity(b.dataset.bbeTeleport||''));
  document.querySelectorAll('[data-bbe-stop]').forEach(b=>b.onclick=()=>badBlockEntityAction(b.dataset.bbeStop||'','stop'));
  document.querySelectorAll('[data-bbe-resume]').forEach(b=>b.onclick=()=>badBlockEntityAction(b.dataset.bbeResume||'','resume'));
  document.querySelectorAll('[data-bbe-remove]').forEach(b=>b.onclick=()=>removeBadBlockEntity(b.dataset.bbeRemove||''));
  document.querySelectorAll('[data-bbe-replace]').forEach(b=>b.onclick=()=>replaceBadBlockEntity(b.dataset.bbeReplace||'',b.dataset.blockCode||''));
  const clearAll=$('badBeClearAll');
  if(clearAll){
    clearAll.disabled=currentSessionRole==='ReadOnly';
    clearAll.onclick=async()=>{
      if(currentSessionRole==='ReadOnly')return;
      if(!confirm('Remove ALL saved Bad Block Entity Tracker entries? This clears tracker history only; it does NOT remove blocks or block entities from the world.'))return;
      const ok=await badBlockEntityAction('','clearall');
      if(ok)toast('Bad Block Entity Tracker entries cleared. World data was not changed.','success');
    };
  }
  enhanceTableByBodyId('badBeRows');
}

async function inspectBadBlockEntity(key){
  try{
    const d=await api(`/api/log-intelligence/block-entity?key=${encodeURIComponent(key)}`);
    if(!d.success){toast(d.error||'Block inspection failed.','error');return}
    const r=d.record||{}, live=d.live||{};
    $('badBeDetail').style.display='block';
    $('badBeDetail').innerHTML=`<div class="cardHeader"><h3>Block Entity Inspection</h3><div class="spacer"></div><button id="badBeDetailClose">Close</button></div>
      <div class="grid">
        ${metric('Position',`${Number(r.x||0)}, ${Number(r.y||0)}, ${Number(r.z||0)} · dim ${Number(r.dimension||0)}`)}
        ${metric('Logged block',r.blockCode||'—',live.blockMatchesLogged?'good':'warn')}
        ${metric('Live block',live.currentBlockCode||'—',live.blockMatchesLogged?'good':'warn')}
        ${metric('Block ID',Number(live.blockId||0).toLocaleString())}
        ${metric('Logged BE',r.blockEntityType||'—',live.blockEntityMatchesLogged?'good':'warn')}
        ${metric('Live BE',live.blockEntityPresent?(live.blockEntityClass||'Present'):'None',live.blockEntityPresent?(live.blockEntityMatchesLogged?'good':'warn'):'bad')}
      </div>
      <div class="infoBox" style="margin-top:10px"><b>Last captured exception</b><br>${esc(r.lastException||'Unknown')}<br><code>${esc(r.lastTopFrame||'')}</code></div>
      ${live.blockMatchesLogged?'':'<div class="warning" style="margin-top:10px"><b>Safety mismatch:</b> the live block no longer matches the tracked block. Remove/Replace actions will refuse to run until you refresh against the correct tracked state.</div>'}`;
    $('badBeDetailClose').onclick=()=>{$('badBeDetail').style.display='none'};
    $('badBeDetail').scrollIntoView({behavior:'smooth',block:'nearest'});
  }catch(e){toast(e.message,'error')}
}

async function badBlockEntityAction(key,action,value=''){
  try{
    const d=await api('/api/log-intelligence/block-entity/action',{method:'POST',body:JSON.stringify({key,action,value})});
    if(d.snapshot){
      if(!logIntelligenceData)logIntelligenceData={};
      logIntelligenceData.badBlockEntities=d.snapshot;
      renderBadBlockEntities();
    }
    toast(d.message||'Action completed.',d.success?'success':'error');
    if(currentSection==='console')setTimeout(()=>loadConsole(false),100);
    if(currentSection==='webmap')setTimeout(()=>loadWebMap(false),100);
    return !!d.success;
  }catch(e){toast(e.message,'error');return false}
}

async function teleportToBadBlockEntity(key){
  if(currentSessionRole==='ReadOnly')return;
  const player=prompt('Online player name or UID to teleport to this block entity:',currentSessionUser||'');
  if(player===null||!player.trim())return;
  await badBlockEntityAction(key,'teleport',player.trim());
}

async function removeBadBlockEntity(key){
  if(currentSessionRole==='ReadOnly')return;
  if(!confirm('Remove ONLY the block entity at this position? The block will remain, but it may become non-functional. This discards the block-entity state.'))return;
  const ok=await badBlockEntityAction(key,'remove');
  if(ok)await inspectBadBlockEntity(key);
}

async function replaceBadBlockEntity(key,currentBlockCode){
  if(currentSessionRole==='ReadOnly')return;
  const target=prompt('Replacement block code. Use the same code to reset/recreate the block and its block entity, or game:air to remove it:',currentBlockCode||'game:air');
  if(target===null||!target.trim())return;
  if(!confirm(`Replace this block with "${target.trim()}"? Existing block-entity state will be discarded and NO item drops will be created.`))return;
  const ok=await badBlockEntityAction(key,'replace',target.trim());
  if(ok)await inspectBadBlockEntity(key);
}

function showLogIssue(index){
  const x=((logIntelligenceData||{}).issues||[])[index];
  if(!x)return;
  const samples=x.samples||[];
  $('logIssueDetail').style.display='block';
  $('logIssueDetail').innerHTML=`<div class="cardHeader"><h3>${esc(x.category)} — ${esc(x.impact)}</h3><div class="spacer"></div><button id="logIssueClose">Close</button></div>
    <p><b>Signature:</b> <code>${esc(x.signature||'')}</code></p>
    <p><b>Likely owner:</b> ${esc(x.likelyModName||x.likelyModId||'Unattributed')} · ${esc(x.attributionConfidence||'Low')} confidence</p>
    <p><b>Occurrences:</b> ${Number(x.occurrences||0).toLocaleString()} · <b>First seen:</b> ${x.firstSeenUnixMilliseconds?esc(new Date(Number(x.firstSeenUnixMilliseconds)).toLocaleString()):'—'} · <b>Last seen:</b> ${x.lastSeenUnixMilliseconds?esc(new Date(Number(x.lastSeenUnixMilliseconds)).toLocaleString()):'—'}</p>
    <div class="infoBox"><b>Diagnosis</b><br>${esc(x.diagnosis||'')}</div>
    <div class="infoBox"><b>Health / profiler correlation</b><br>${esc(x.healthCorrelation||'')}</div>
    <div class="warning"><b>Recommended action</b><br>${esc(x.recommendedFix||'')}</div>
    <h4 style="margin:12px 0 8px">Captured context</h4>
    ${samples.length?samples.map(s=>`<div style="margin-bottom:10px"><div class="small">${esc(s.sourceFile||'')} · ${s.archived?'archived':'live'} · ${s.unixMilliseconds?esc(new Date(Number(s.unixMilliseconds)).toLocaleString()):''}</div><pre class="status" style="margin-top:5px;max-height:260px;overflow:auto">${esc(s.context||'')}</pre></div>`).join(''):'<div class="muted">No context sample retained.</div>'}`;
  $('logIssueClose').onclick=()=>{$('logIssueDetail').style.display='none'};
  $('logIssueDetail').scrollIntoView({behavior:'smooth',block:'nearest'});
}

async function runLogScan(includeArchived){
  const button=includeArchived?$('logScanArchived'):$('logScanCurrent');
  button.disabled=true;
  $('logState').textContent=includeArchived?'Scanning current + archived logs…':'Scanning current log…';
  try{
    logIntelligenceData=await api('/api/log-intelligence/scan',{method:'POST',body:JSON.stringify({includeArchived})});
    renderLogIntelligence();
    toast(includeArchived?'Archived log scan completed.':'Current log scan completed.','success');
  }catch(e){toast(e.message,'error')}finally{button.disabled=false}
}

async function runLogPreflight(){
  $('logRunPreflight').disabled=true;
  $('preflightState').textContent='Running preflight…';
  try{
    await api('/api/log-intelligence/preflight',{method:'POST',body:'{}'});
    await loadLogIntelligence(false);
    toast('Startup preflight re-checked.','success');
  }catch(e){toast(e.message,'error')}finally{$('logRunPreflight').disabled=false}
}

$('logRefresh').onclick=()=>loadLogIntelligence(true);
$('logScanCurrent').onclick=()=>runLogScan(false);
$('logScanArchived').onclick=()=>runLogScan(true);
$('logRunPreflight').onclick=()=>runLogPreflight();
if($('logIssueClearAll'))$('logIssueClearAll').onclick=async()=>{
  if(currentSessionRole==='ReadOnly')return;
  if(!confirm('Clear ALL retained Issue Signatures? This does not delete server log files, startup preflight results, audit history, or Bad Block Entity Tracker history.'))return;
  try{
    const d=await api('/api/log-intelligence/issues/clear',{method:'POST',body:'{}'});
    logIntelligenceData=d.logIntelligence||await api('/api/log-intelligence');
    if($('logIssueDetail'))$('logIssueDetail').style.display='none';
    renderLogIntelligence();
    toast(d.message||'Issue signatures cleared.','success');
  }catch(e){toast(e.message,'error')}
};

function resolveWebMapUrl(d){
  const configured=String(d?.mapUrl||'').trim();
  if(configured)return configured;
  const port=Number(d?.port||0);
  if(port>0)return `http://${window.location.hostname}:${port}/`;
  return '';
}

function fmtDurationMs(ms,calculating=false){if(calculating||!Number.isFinite(ms)||ms<0)return 'Calculating…';let sec=Math.max(0,Math.round(ms/1000)),h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),r=sec%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(r).padStart(2,'0')}`:`${m}:${String(r).padStart(2,'0')}`}

function webMapExportScheduleStateHtml(d){
  if(d?.exportTerrainOnStart===true)return '<span class="warn"><b>QUEUED FOR NEXT START</b></span>';
  if(d?.automaticStartupExportEnabled===true){
    const days=Math.max(1,Number(d.automaticStartupExportIntervalDays||7));
    if(d?.automaticStartupExportDue===true)return `<span class="warn"><b>AUTO DUE NEXT START · ${days}d</b></span>`;
    const due=Number(d?.nextAutomaticStartupExportUnixMilliseconds||0);
    return `<span class="good"><b>AUTO ${days}d</b></span>${due>0?` · next due ${esc(fmtAdminTime(due))}`:''}`;
  }
  return '<span class="good"><b>OFF</b></span>';
}

function webMapTerrainPhaseLabel(phase){const p=String(phase||'working').toLowerCase();return ({coverage:'Scanning explored terrain',rendering:'Rendering terrain',overview:'Building overview',pyramid:'Building zoom levels',finalizing:'Publishing map cache',complete:'Map update complete',cancelled:'Export cancelled',failed:'Export failed',waiting:'Waiting'})[p]||p.replace(/[-_]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function webMapTerrainProgressPercent(t){const direct=Number(t?.progressPercent);if(Number.isFinite(direct))return Math.max(0,Math.min(100,direct));const total=Number(t?.totalTiles||0),done=Number(t?.writtenTiles||0);return total>0?Math.max(0,Math.min(100,5+(done/total)*85)):0}
function renderWebMapTerrainProgress(t){const box=$('webMapTerrainProgress');if(!box)return;const active=t?.state==='exporting';box.classList.toggle('active',active);if(!active)return;const pct=webMapTerrainProgressPercent(t),phase=webMapTerrainPhaseLabel(t?.phase);$('webMapTerrainProgressTitle').textContent=phase;$('webMapTerrainProgressPct').textContent=`${pct.toFixed(pct<10?1:0)}%`;$('webMapTerrainProgressFill').style.width=`${pct.toFixed(2)}%`;const elapsed=Number(t?.startedUnixMilliseconds||0)>0?Date.now()-Number(t.startedUnixMilliseconds):Number(t?.totalElapsedMilliseconds||0);const eta=Number(t?.estimatedRemainingMilliseconds);const parts=[`${Number(t?.writtenTiles||0).toLocaleString()} / ${Number(t?.totalTiles||0).toLocaleString()} tiles`,`${Number(t?.processedChunkColumns||0).toLocaleString()} chunk columns`,`elapsed ${fmtDurationMs(elapsed)}`,`ETA ${fmtDurationMs(eta,eta<0)}`];$('webMapTerrainProgressMeta').innerHTML=parts.map(x=>`<span>${esc(x)}</span>`).join('')}
function scheduleWebMapTerrainProgressPoll(){if(webMapTerrainProgressTimer||document.hidden||currentSection!=='webmap'||webMapData?.terrain?.state!=='exporting')return;webMapTerrainProgressTimer=setTimeout(pollWebMapTerrainProgress,1000)}
async function pollWebMapTerrainProgress(){webMapTerrainProgressTimer=null;if(document.hidden||currentSection!=='webmap')return;try{const t=await api('/api/webmap/terrain/status');if(!webMapData)webMapData={};webMapData.terrain=t;renderWebMapTerrainProgress(t);$('webMapTerrainState').textContent=`${t.state||'unknown'}${t.serverLockActive?' · GAME SERVER LOCKED':''}`;$('webMapTerrainMessage').textContent=(t.message||'')+(t.lastError?` Error: ${t.lastError}`:'');if(t.state==='exporting'){scheduleWebMapTerrainProgressPoll()}else{await loadWebMap(false)}}catch{if(webMapData?.terrain?.state==='exporting')scheduleWebMapTerrainProgressPoll()}}

function renderWebMap(d){
  webMapData=d||{};
  const readOnly=currentSessionRole==='ReadOnly';
  ['webMapSave','webMapTurnOff','webMapEnabled','webMapBind','webMapPort','webMapTitle','webMapPublicUrl','webMapDashboardUrl','webMapShowActivity','webMapShowPlayers','webMapShowWaypoints','webMapShowBadBe','webMapShowLeaderboards','webMapLeaderboardShowPlaytime','webMapLeaderboardShowXSkills','webMapLeaderboardTopPlayers','webMapLeaderboardRefreshSeconds','webMapExportNormalTerrain','webMapExportSepiaTerrain','webMapExportTopographicTerrain','webMapExportTerrainOnStart','webMapAutomaticStartupExportEnabled','webMapAutomaticStartupExportIntervalDays','webMapUseIncrementalTerrainExport','webMapLockDuringTerrainExport','webMapSaveExportSchedule','webMapUpdateTerrain','webMapForceTerrainExport','webMapTerrainTileSize','webMapActivityWindow','webMapActivityLimit','webMapPlayerMajorWaypointLimit','webMapPlayerMinorWaypointLimit','webMapMaximumZoomOutSpanBlocks','webMapDefaultViewSpanBlocks'].forEach(id=>{if($(id))$(id).disabled=readOnly;});
  if($('webMapShowPlayers'))$('webMapShowPlayers').disabled=readOnly;
  if($('webMapUpdateTerrain'))$('webMapUpdateTerrain').disabled=readOnly||d.enabled===false||d.terrain?.state==='exporting';if($('webMapForceTerrainExport'))$('webMapForceTerrainExport').disabled=readOnly||d.enabled===false||d.terrain?.state==='exporting';if($('webMapTurnOff'))$('webMapTurnOff').disabled=readOnly||d.enabled===false;
  if($('webMapExportScheduleState'))$('webMapExportScheduleState').innerHTML=webMapExportScheduleStateHtml(d);
  ['webMapWaypointName','webMapWaypointX','webMapWaypointY','webMapWaypointZ','webMapWaypointDimension','webMapWaypointType','webMapWaypointIcon','webMapWaypointColor','webMapWaypointDescription','webMapWaypointSave','webMapWaypointClear'].forEach(id=>{if($(id))$(id).disabled=readOnly;});
  const url=resolveWebMapUrl(d);
  setNavStatus('webmap',d.running?'good':(d.enabled?'bad':'neutral'),d.running?'Web Map listener running':(d.enabled?'Web Map enabled but listener stopped':'Web Map disabled'));
  $('webMapState').textContent=`${d.running?'Listening':'Stopped'} · ${d.bindAddress||'0.0.0.0'}:${Number(d.port||0)}${d.lastError?` · ${d.lastError}`:''}`;
  $('webMapMetrics').innerHTML=
    metric('Native host',d.running?'Running':'Stopped',d.running?'good':d.enabled?'bad':'warn')+
    metric('Map port',Number(d.port||0))+
    metric('Terrain',esc(d.terrain?.state||'pending'),d.terrain?.state==='ready'?'good':d.terrain?.state==='failed'?'bad':'warn')+
    metric('Terrain tiles',Number(d.terrainManifest?.tileCount||d.terrain?.writtenTiles||0))+
    metric('Dirty map chunks',Number(d.pendingDirtyMapChunks||0),Number(d.pendingDirtyMapChunks||0)>0?'warn':'good')+
    metric('Next-start export',d.exportTerrainOnStart===true?'QUEUED':'Off',d.exportTerrainOnStart===true?'warn':'good')+
    metric('Automatic startup',d.automaticStartupExportEnabled===true?(d.automaticStartupExportDue===true?'DUE':`Every ${Number(d.automaticStartupExportIntervalDays||7)}d`):'Off',d.automaticStartupExportDue===true?'warn':d.automaticStartupExportEnabled===true?'good':'')+
    metric('Incremental startup',d.useIncrementalTerrainExport!==false?'On':'Off',d.useIncrementalTerrainExport!==false?'good':'warn')+
    metric('Player layer privacy',d.showPlayers===true?'Publishing':'Off',d.showPlayers===true?'warn':'good')+
    metric('Players cache',Number((d.players||[]).length))+
    metric('Waypoints',Number((d.waypoints||[]).length),Number((d.waypoints||[]).length)>0?'good':'')+
    metric('Activity points',Number((d.activity||[]).length))+
    metric('Bad BE markers',Number((d.badBlockEntities||[]).length),Number((d.badBlockEntities||[]).length)?'warn':'good')+
    metric('Browser refresh',`${Number(d.publicRefreshSeconds||30)}s`);
  $('webMapEnabled').checked=d.enabled!==false;
  $('webMapBind').value=d.bindAddress||'0.0.0.0';
  $('webMapPort').value=Number(d.port||9466);
  $('webMapTitle').value=d.title||"Newfie's Server Map";
  $('webMapPublicUrl').value=d.mapUrl||'';
  $('webMapDashboardUrl').value=d.dashboardUrl||'';
  $('webMapShowActivity').checked=d.showActivity===true;
  $('webMapShowPlayers').checked=d.showPlayers===true;
  $('webMapShowWaypoints').checked=d.showWaypoints!==false;
  if($('webMapShowLeaderboards'))$('webMapShowLeaderboards').checked=d.showLeaderboards!==false;
  if($('webMapLeaderboardShowPlaytime'))$('webMapLeaderboardShowPlaytime').checked=d.leaderboardShowPlaytime!==false;
  if($('webMapLeaderboardShowXSkills'))$('webMapLeaderboardShowXSkills').checked=d.leaderboardShowXSkills!==false;
  if($('webMapLeaderboardTopPlayers'))$('webMapLeaderboardTopPlayers').value=Math.max(3,Number(d.leaderboardTopPlayers??5));
  if($('webMapLeaderboardRefreshSeconds'))$('webMapLeaderboardRefreshSeconds').value=Math.max(30,Number(d.leaderboardRefreshSeconds??60));
  $('webMapShowBadBe').checked=d.showBadBlockEntities===true;
  if($('webMapExportNormalTerrain'))$('webMapExportNormalTerrain').checked=d.exportNormalTerrain!==false;
  if($('webMapExportSepiaTerrain'))$('webMapExportSepiaTerrain').checked=d.exportSepiaTerrain!==false;
  if($('webMapExportTopographicTerrain'))$('webMapExportTopographicTerrain').checked=d.exportTopographicTerrain!==false;
  $('webMapExportTerrainOnStart').checked=d.exportTerrainOnStart===true;
  if($('webMapAutomaticStartupExportEnabled'))$('webMapAutomaticStartupExportEnabled').checked=d.automaticStartupExportEnabled===true;
  if($('webMapAutomaticStartupExportIntervalDays'))$('webMapAutomaticStartupExportIntervalDays').value=Math.max(1,Number(d.automaticStartupExportIntervalDays||7));
  $('webMapUseIncrementalTerrainExport').checked=d.useIncrementalTerrainExport!==false;
  $('webMapLockDuringTerrainExport').checked=d.lockServerDuringTerrainExport!==false;
  $('webMapTerrainTileSize').value=Number(d.terrainTileSize||256);
  const terrain=d.terrain||{};
  $('webMapTerrainState').textContent=`${terrain.state||'unknown'}${terrain.serverLockActive?' · GAME SERVER LOCKED':''}`;
  $('webMapTerrainMetrics').innerHTML=metric('Mode',esc(terrain.exportMode||'pending'),String(terrain.exportMode||'').includes('incremental')?'good':String(terrain.exportMode||'').includes('full')?'warn':'')+metric('Phase',esc(webMapTerrainPhaseLabel(terrain.phase||terrain.state||'waiting')),terrain.state==='exporting'?'warn':terrain.state==='ready'?'good':'')+metric('Progress',`${webMapTerrainProgressPercent(terrain).toFixed(0)}%`,terrain.state==='exporting'?'warn':terrain.state==='ready'?'good':'')+metric('Trigger',esc(terrain.trigger||'startup'))+metric('ETA',terrain.state==='exporting'?fmtDurationMs(Number(terrain.estimatedRemainingMilliseconds||0),Number(terrain.estimatedRemainingMilliseconds)<0):'—',terrain.state==='exporting'?'warn':'')+metric('Avg / tile',Number(terrain.averageMillisecondsPerTile||0)>0?`${Number(terrain.averageMillisecondsPerTile).toFixed(0)} ms`:'—')+metric('Rendered tiles',`${Number(terrain.writtenTiles||0).toLocaleString()} / ${Number(terrain.totalTiles||0).toLocaleString()}`)+metric('Reused tiles',Number(terrain.reusedTiles||0).toLocaleString(),'good')+metric('Dirty chunks',Number(terrain.dirtyChunkCount||0).toLocaleString(),Number(terrain.dirtyChunkCount||0)>0?'warn':'good')+metric('Chunk loads',Number(terrain.processedChunkColumns||0).toLocaleString())+metric('Coverage scan',`${Number(terrain.coverageScanMilliseconds||0).toLocaleString()} ms`)+metric('World reads',`${Number(terrain.worldReadMilliseconds||0).toLocaleString()} ms`)+metric('Render',`${Number(terrain.renderMilliseconds||0).toLocaleString()} ms`)+metric('PNG writes',`${Number(terrain.pngWriteMilliseconds||0).toLocaleString()} ms`)+metric('Overview',`${Number(terrain.overviewMilliseconds||0).toLocaleString()} ms`)+metric('LOD cache',`${Number(terrain.lodWriteMilliseconds||0).toLocaleString()} ms`)+metric('Total',`${Number(terrain.totalElapsedMilliseconds||0).toLocaleString()} ms`)+metric('Last export time',Number(d.lastTerrainExportDurationMilliseconds||0)>0?fmtDurationMs(Number(d.lastTerrainExportDurationMilliseconds||0)):'Never','good')+metric('Pooled tile buffer',`${(Number(terrain.peakWorkingBufferBytes||0)/1048576).toFixed(2)} MiB`)+metric('Palette cache',Number(terrain.blockColorCacheEntries||0).toLocaleString())+metric('Overview resolution',`${Number(d.terrainManifest?.overviewCellSizeBlocks||terrain.overviewCellSizeBlocks||0)||'—'} blocks/px`)+metric('Tile size',`${Number(terrain.tileSize||d.terrainTileSize||256)} px`)+metric('Last success',terrain.lastSuccessfulUnixMilliseconds?fmtAdminTime(terrain.lastSuccessfulUnixMilliseconds):'Never',terrain.lastError?'bad':'good');
  $('webMapTerrainMessage').textContent=(terrain.message||'')+(terrain.lastError?` Error: ${terrain.lastError}`:'');
  renderWebMapTerrainProgress(terrain);
  if(terrain.state==='exporting')scheduleWebMapTerrainProgressPoll();
  $('webMapActivityWindow').value=Number(d.activityWindowMinutes||60);
  $('webMapActivityLimit').value=Number(d.maxActivityMarkers||150);
  if($('webMapPlayerMajorWaypointLimit'))$('webMapPlayerMajorWaypointLimit').value=Math.max(0,Number(d.playerMajorWaypointLimit??5));
  if($('webMapPlayerMinorWaypointLimit'))$('webMapPlayerMinorWaypointLimit').value=Math.max(0,Number(d.playerMinorWaypointLimit??10));
  if($('webMapMaximumZoomOutSpanBlocks'))$('webMapMaximumZoomOutSpanBlocks').value=Math.max(2048,Number(d.maximumZoomOutSpanBlocks??50000));
  if($('webMapDefaultViewSpanBlocks'))$('webMapDefaultViewSpanBlocks').value=Math.max(512,Number(d.defaultViewSpanBlocks??8000));
  const liveGateNote=d.showPlayers===true?' Live player coordinates are currently enabled on the public map.':' Live player coordinates are currently disabled.';
  $('webMapNote').textContent=(d.note||'')+liveGateNote+(url?` Public map: ${url}`:'');
  const players=d.players||[];
  $('webMapPlayerRows').innerHTML=players.length?players.map(x=>`<tr><td><b>${esc(x.name||'')}</b></td><td><code>${Number(x.x||0).toFixed(1)}, ${Number(x.y||0).toFixed(1)}, ${Number(x.z||0).toFixed(1)}</code></td><td>${esc(String(x.dimension??''))}</td><td>${Number(x.pingMilliseconds||0)} ms</td><td>${fmtAdminDuration(Number(x.totalPlaySeconds||0))}<div class="small">session ${fmtAdminDuration(Number(x.sessionSeconds||0))}</div></td></tr>`).join(''):`<tr><td colspan="5" class="muted">${d.showPlayers===true?'No players are currently online or the player snapshot has not populated yet.':'Player layer is disabled.'}</td></tr>`;
  const waypoints=d.waypoints||[];
  $('webMapWaypointRows').innerHTML=waypoints.length?waypoints.map(w=>{
    const pos=`${Number(w.x||0).toFixed(1)}, ${Number(w.y||0).toFixed(1)}, ${Number(w.z||0).toFixed(1)}`;
    const dot=`<span style="display:inline-block;width:11px;height:11px;background:${/^#[0-9a-fA-F]{6}$/.test(w.color||'')?w.color:'#38bdf8'};transform:rotate(45deg);margin-right:7px;border:1px solid #e2e8f0"></span>`;
    let controls=`<button data-map-waypoint-edit="${esc(w.id||'')}">Edit</button>`;
    if(currentSessionRole!=='ReadOnly')controls+=` <button class="danger" data-map-waypoint-delete="${esc(w.id||'')}">Delete</button>`;
    return `<tr><td>${dot}<b>${esc(w.name||'')}</b> <span class="small">${esc((w.type||'major').toUpperCase())} · ${esc((w.icon||'pin').toUpperCase())}${w.isPlayerWaypoint?' · PLAYER':''}</span><div class="small">${esc(w.description||'')}</div></td><td><code>${esc(pos)}</code><div class="small">Dimension ${Number(w.dimension||0)}</div></td><td>${w.updatedUnixMilliseconds?fmtAdminTime(w.updatedUnixMilliseconds):'—'}<div class="small">${esc(w.updatedBy||w.createdBy||'')}</div></td><td><div class="rowActions">${controls}</div></td></tr>`;
  }).join(''):'<tr><td colspan="4" class="muted">No Web Map waypoints have been created for this world.</td></tr>';
  const bes=d.badBlockEntities||[];
  $('webMapBadBeRows').innerHTML=bes.length?bes.map(x=>{
    const key=esc(x.key||''),pos=`${Number(x.x||0)}, ${Number(x.y||0)}, ${Number(x.z||0)}`;
    let controls=`<button data-map-bbe-inspect="${key}">Inspect</button>`;
    if(currentSessionRole!=='ReadOnly')controls+=` <button data-map-bbe-teleport="${key}">Teleport</button>`;
    return `<tr><td><code>${esc(pos)}</code></td><td><b>${esc(x.blockCode||'')}</b><div class="small">${esc(x.blockEntityType||'')}</div></td><td class="warn"><b>${Number(x.occurrences||0).toLocaleString()}</b></td><td><div class="rowActions">${controls}</div></td></tr>`;
  }).join(''):'<tr><td colspan="4" class="muted">Bad block layer is disabled or no tracked faults exist.</td></tr>';
  const activity=d.activity||[];
  $('webMapActivityRows').innerHTML=activity.length?activity.map(x=>`<tr><td><code>${Number(x.x||0)}, ${Number(x.y||0)}, ${Number(x.z||0)}</code><div class="small">${esc(String(x.dimension??''))}</div></td><td>${esc(x.blockCode||'')}</td><td><b>${Number(x.eventCount||0).toLocaleString()}</b><div class="small">${Number(x.distinctActions||0)} action types</div></td><td><button data-map-copy="${Number(x.x||0)} ${Number(x.y||0)} ${Number(x.z||0)}">Copy coords</button></td></tr>`).join(''):'<tr><td colspan="4" class="muted">Activity layer is disabled, BlockLogger is unavailable, or the cache has not populated yet.</td></tr>';
  document.querySelectorAll('[data-map-waypoint-edit]').forEach(b=>b.onclick=()=>editWebMapWaypoint(b.dataset.mapWaypointEdit||''));
  document.querySelectorAll('[data-map-waypoint-delete]').forEach(b=>b.onclick=()=>deleteWebMapWaypoint(b.dataset.mapWaypointDelete||''));
  document.querySelectorAll('[data-map-bbe-inspect]').forEach(b=>b.onclick=()=>inspectBadBlockEntity(b.dataset.mapBbeInspect||''));
  document.querySelectorAll('[data-map-bbe-teleport]').forEach(b=>b.onclick=()=>teleportToBadBlockEntity(b.dataset.mapBbeTeleport||''));
  document.querySelectorAll('[data-map-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.mapCopy||'');toast('Coordinates copied.','success')}catch{toast('Could not copy coordinates.','error')}});
}

async function loadWebMap(showLoading=true){
  if(showLoading)$('webMapState').textContent='Loading…';
  try{renderWebMap(await api('/api/webmap'));}
  catch(e){$('webMapState').textContent='Load failed';toast(e.message,'error');}
}

async function saveWebMap(){
  if(currentSessionRole==='ReadOnly')return;
  const payload={
    enabled:$('webMapEnabled').checked,
    bindAddress:$('webMapBind').value.trim()||'0.0.0.0',
    port:Number($('webMapPort').value||9466),
    title:$('webMapTitle').value.trim(),
    publicUrl:$('webMapPublicUrl').value.trim(),
    dashboardUrl:$('webMapDashboardUrl').value.trim(),
    showActivity:$('webMapShowActivity').checked,
    allowLivePlayerData:$('webMapShowPlayers').checked,
    showPlayers:$('webMapShowPlayers').checked,
    showWaypoints:$('webMapShowWaypoints').checked,
    showBadBlockEntities:$('webMapShowBadBe').checked,
    showLeaderboards:$('webMapShowLeaderboards')?$('webMapShowLeaderboards').checked:true,
    leaderboardShowPlaytime:$('webMapLeaderboardShowPlaytime')?$('webMapLeaderboardShowPlaytime').checked:true,
    leaderboardShowXSkills:$('webMapLeaderboardShowXSkills')?$('webMapLeaderboardShowXSkills').checked:true,
    leaderboardTopPlayers:Math.max(3,Math.min(20,Number($('webMapLeaderboardTopPlayers')?.value??5))),
    leaderboardRefreshSeconds:Math.max(30,Math.min(300,Number($('webMapLeaderboardRefreshSeconds')?.value??60))),
    exportNormalTerrain:$('webMapExportNormalTerrain')?$('webMapExportNormalTerrain').checked:true,
    exportSepiaTerrain:$('webMapExportSepiaTerrain')?$('webMapExportSepiaTerrain').checked:true,
    exportTopographicTerrain:$('webMapExportTopographicTerrain')?$('webMapExportTopographicTerrain').checked:true,
    exportTerrainOnStart:$('webMapExportTerrainOnStart').checked,
    automaticStartupExportEnabled:$('webMapAutomaticStartupExportEnabled')?$('webMapAutomaticStartupExportEnabled').checked:false,
    automaticStartupExportIntervalDays:Math.max(1,Math.min(365,Number($('webMapAutomaticStartupExportIntervalDays')?.value||7))),
    useIncrementalTerrainExport:$('webMapUseIncrementalTerrainExport').checked,
    lockServerDuringTerrainExport:$('webMapLockDuringTerrainExport').checked,
    terrainTileSize:Number($('webMapTerrainTileSize').value||256),
    activityWindowMinutes:Number($('webMapActivityWindow').value||60),
    maxActivityMarkers:Number($('webMapActivityLimit').value||150),
    playerMajorWaypointLimit:Math.max(0,Math.min(100,Number($('webMapPlayerMajorWaypointLimit')?.value??5))),
    playerMinorWaypointLimit:Math.max(0,Math.min(100,Number($('webMapPlayerMinorWaypointLimit')?.value??10))),
    maximumZoomOutSpanBlocks:Math.max(2048,Math.min(100000,Number($('webMapMaximumZoomOutSpanBlocks')?.value??50000))),
    defaultViewSpanBlocks:Math.max(512,Math.min(Number($('webMapMaximumZoomOutSpanBlocks')?.value??50000),Number($('webMapDefaultViewSpanBlocks')?.value??8000)))
  };
  if(!payload.exportNormalTerrain&&!payload.exportSepiaTerrain&&!payload.exportTopographicTerrain){toast('Select at least one terrain export layer.','error');return;}
  try{await api('/api/webmap/config',{method:'POST',body:JSON.stringify(payload)});toast('Native Web Map settings saved. Terrain export layer choices apply to the next terrain update/rebuild.','success');await loadWebMap(false);}
  catch(e){toast(e.message,'error');}
}


async function turnWebMapOff(){
  if(currentSessionRole==='ReadOnly'||webMapData?.enabled===false)return;
  const exporting=webMapData?.terrain?.state==='exporting';
  const message=exporting?'Turn the Native Web Map OFF and cancel the active forced terrain export? The current chunk load will finish, then the previous published terrain cache will be kept.':'Turn the Native Web Map OFF? The listener will stop immediately and queued terrain exports will remain paused.';
  if(!confirm(message))return;
  $('webMapEnabled').checked=false;
  await saveWebMap();
}

async function saveWebMapExportSchedule(){
  if(currentSessionRole==='ReadOnly')return;
  const payload={
    exportTerrainOnStart:$('webMapExportTerrainOnStart').checked,
    automaticStartupExportEnabled:$('webMapAutomaticStartupExportEnabled')?$('webMapAutomaticStartupExportEnabled').checked:false,
    automaticStartupExportIntervalDays:Math.max(1,Math.min(365,Number($('webMapAutomaticStartupExportIntervalDays')?.value||7))),
    useIncrementalTerrainExport:$('webMapUseIncrementalTerrainExport').checked,
    lockServerDuringTerrainExport:$('webMapLockDuringTerrainExport').checked
  };
  try{await api('/api/webmap/export-schedule',{method:'POST',body:JSON.stringify(payload)});toast('Export schedule saved without changing the Web Map enabled/listener settings.','success');await loadWebMap(false);}
  catch(e){toast(e.message,'error');}
}

async function updateWebMapTerrain(){
  if(currentSessionRole==='ReadOnly')return;
  try{
    const r=await api('/api/webmap/terrain/update',{method:'POST',body:'{}'});
    toast(r.message||'Changed terrain update started.','success');
    await loadWebMap(false);
  }catch(e){toast(e.message,'error');}
}

async function forceWebMapTerrainExport(){
  if(currentSessionRole==='ReadOnly')return;
  if(!confirm('Run a FULL terrain rebuild while the game server is running? This recreates the entire explored terrain cache and may temporarily increase disk/CPU load.'))return;
  try{
    const r=await api('/api/webmap/terrain/force',{method:'POST',body:'{}'});
    toast(r.message||'Full terrain rebuild started.','success');
    await loadWebMap(false);
  }catch(e){toast(e.message,'error');}
}

function clearWebMapWaypointForm(){
  $('webMapWaypointId').value='';
  $('webMapWaypointName').value='';
  $('webMapWaypointX').value='';$('webMapWaypointY').value='';$('webMapWaypointZ').value='';
  $('webMapWaypointDimension').value='0';if($('webMapWaypointType'))$('webMapWaypointType').value='major';if($('webMapWaypointIcon'))$('webMapWaypointIcon').value='pin';$('webMapWaypointColor').value='#38bdf8';$('webMapWaypointDescription').value='';
  $('webMapWaypointSave').textContent='Add Waypoint';
}

function editWebMapWaypoint(id){
  const w=(webMapData?.waypoints||[]).find(x=>String(x.id||'')===String(id||''));if(!w)return;
  $('webMapWaypointId').value=w.id||'';$('webMapWaypointName').value=w.name||'';
  $('webMapWaypointX').value=Number(w.x||0);$('webMapWaypointY').value=Number(w.y||0);$('webMapWaypointZ').value=Number(w.z||0);
  $('webMapWaypointDimension').value=Number(w.dimension||0);if($('webMapWaypointType'))$('webMapWaypointType').value=(w.type==='minor'?'minor':'major');if($('webMapWaypointIcon'))$('webMapWaypointIcon').value=w.icon||'pin';$('webMapWaypointColor').value=/^#[0-9a-fA-F]{6}$/.test(w.color||'')?w.color:'#38bdf8';$('webMapWaypointDescription').value=w.description||'';
  $('webMapWaypointSave').textContent='Save Waypoint';
  $('webMapWaypointName').focus();
}

async function saveWebMapWaypoint(){
  if(currentSessionRole==='ReadOnly')return;
  const x=Number($('webMapWaypointX').value),y=Number($('webMapWaypointY').value),z=Number($('webMapWaypointZ').value);
  const name=$('webMapWaypointName').value.trim();
  if(!name){toast('Waypoint name is required.','error');return}
  if(!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(z)){toast('Enter valid X, Y and Z coordinates.','error');return}
  const payload={id:$('webMapWaypointId').value.trim(),name,description:$('webMapWaypointDescription').value.trim(),type:$('webMapWaypointType')?.value||'major',icon:$('webMapWaypointIcon')?.value||'pin',x,y,z,dimension:Number($('webMapWaypointDimension').value||0),color:$('webMapWaypointColor').value||'#38bdf8'};
  try{await api('/api/webmap/waypoint/save',{method:'POST',body:JSON.stringify(payload)});toast(payload.id?'Waypoint updated.':'Waypoint created.','success');clearWebMapWaypointForm();await loadWebMap(false)}catch(e){toast(e.message,'error')}
}

async function deleteWebMapWaypoint(id){
  if(currentSessionRole==='ReadOnly'||!id)return;
  const w=(webMapData?.waypoints||[]).find(x=>String(x.id||'')===String(id));
  if(!confirm(`Delete waypoint "${w?.name||'this waypoint'}"?`))return;
  try{await api('/api/webmap/waypoint/delete',{method:'POST',body:JSON.stringify({id})});toast('Waypoint deleted.','success');if($('webMapWaypointId').value===id)clearWebMapWaypointForm();await loadWebMap(false)}catch(e){toast(e.message,'error')}
}

function openWebMap(){
  const url=resolveWebMapUrl(webMapData||{});if(!url){toast('Map host is not configured.','error');return;}
  window.open(url,'_blank','noopener,noreferrer');
}

$('webMapRefresh').onclick=()=>loadWebMap(true);$('webMapSave').onclick=saveWebMap;$('webMapTurnOff').onclick=turnWebMapOff;$('webMapOpen').onclick=openWebMap;$('webMapSaveExportSchedule').onclick=saveWebMapExportSchedule;$('webMapUpdateTerrain').onclick=updateWebMapTerrain;$('webMapForceTerrainExport').onclick=forceWebMapTerrainExport;$('webMapWaypointSave').onclick=saveWebMapWaypoint;$('webMapWaypointClear').onclick=clearWebMapWaypointForm;

function customPatchFormPayload(){
  return {
    id:($('patchId')?.value||'').trim(),
    name:($('patchName')?.value||'').trim(),
    enabled:!!$('patchEnabled')?.checked,
    assemblyName:($('patchAssembly')?.value||'').trim(),
    typeName:($('patchType')?.value||'').trim(),
    methodName:($('patchMethod')?.value||'').trim(),
    parameterTypes:String($('patchParameters')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),
    mode:$('patchMode')?.value||'Observe',
    throttleMilliseconds:Math.max(50,Math.min(60000,Math.floor(Number($('patchThrottle')?.value||250)))),
    notes:($('patchNotes')?.value||'').trim()
  };
}
function clearCustomPatchForm(){
  if($('patchId'))$('patchId').value='';
  if($('patchName'))$('patchName').value='';
  if($('patchEnabled'))$('patchEnabled').checked=false;
  if($('patchAssembly'))$('patchAssembly').value='';
  if($('patchType'))$('patchType').value='';
  if($('patchMethod'))$('patchMethod').value='';
  if($('patchParameters'))$('patchParameters').value='';
  if($('patchMode'))$('patchMode').value='Observe';
  if($('patchThrottle'))$('patchThrottle').value='250';
  if($('patchNotes'))$('patchNotes').value='';
  if($('patchEditorState'))$('patchEditorState').textContent='New patch · disabled until you explicitly enable it.';
}
function fillCustomPatchForm(def){
  def=def||{};
  $('patchId').value=def.id||'';$('patchName').value=def.name||'';$('patchEnabled').checked=!!def.enabled;
  $('patchAssembly').value=def.assemblyName||'';$('patchType').value=def.typeName||'';$('patchMethod').value=def.methodName||'';
  $('patchParameters').value=(def.parameterTypes||[]).join(', ');$('patchMode').value=def.mode||'Observe';
  $('patchThrottle').value=Number(def.throttleMilliseconds||250);$('patchNotes').value=def.notes||'';
  $('patchEditorState').textContent=def.id?'Editing saved patch. Save reapplies enabled Patch Studio definitions.':'Generated template · review target before saving.';
  window.scrollTo({top:Math.max(0,$('customPatches').offsetTop-90),behavior:'smooth'});
}
function renderCustomPatches(){
  const d=customPatchesData||{}, rows=d.patches||[], suggestions=d.suggestions||[];
  if($('patchStudioState'))$('patchStudioState').textContent=d.available===false?'Unavailable':`${rows.length} patch definition(s) · ${d.harmonyId||'Patch Studio'}`;
  if($('patchStudioMetrics'))$('patchStudioMetrics').innerHTML=
    metric('Definitions',rows.length)+metric('Enabled',rows.filter(x=>x.definition?.enabled).length,rows.some(x=>x.definition?.runtimeStatus==='Error')?'warn':'good')+
    metric('Applied',rows.filter(x=>x.definition?.runtimeStatus==='Applied').length,'good')+metric('Errors',rows.filter(x=>x.definition?.runtimeStatus==='Error').length,rows.some(x=>x.definition?.runtimeStatus==='Error')?'bad':'good');
  const body=$('patchRows');
  if(body)body.innerHTML=rows.length?rows.map((r,i)=>{const x=r.definition||{},status=x.runtimeStatus||'Disabled',state=status==='Applied'?'good':status==='Error'?'bad':x.enabled?'warn':'muted';return `<tr><td><b>${esc(x.name||'Unnamed')}</b><div class="small">${esc(x.notes||'')}</div></td><td><code>${esc(x.assemblyName||'')}</code><div class="small"><code>${esc(x.typeName||'')}.${esc(x.methodName||'')}(${esc((x.parameterTypes||[]).join(', '))})</code></div></td><td><b>${esc(x.mode||'Observe')}</b>${String(x.mode||'').toLowerCase()==='throttlevoid'?`<div class="small">${Number(x.throttleMilliseconds||0)} ms</div>`:''}</td><td class="${state}"><b>${esc(status)}</b><div class="small">${esc(x.runtimeMessage||'')}</div></td><td>${Number(r.calls||0).toLocaleString()} calls<div class="small">${Number(r.skipped||0).toLocaleString()} skipped · avg ${Number(r.averageMilliseconds||0).toFixed(2)} ms · max ${Number(r.maxMilliseconds||0).toFixed(2)} ms</div></td><td><div class="rowActions"><button data-patch-edit="${i}">Edit</button><button data-patch-toggle="${esc(x.id||'')}" data-patch-enabled="${x.enabled?'1':'0'}">${x.enabled?'Disable':'Enable'}</button><button class="danger" data-patch-delete="${esc(x.id||'')}">Delete</button></div></td></tr>`}).join(''):'<tr><td colspan="6" class="muted">No custom patches. Generate or create one above.</td></tr>';
  const sugg=$('patchSuggestions');
  if(sugg)sugg.innerHTML=suggestions.length?suggestions.map(x=>`<tr><td><b>${esc(x.title||'Suggestion')}</b><div class="small">${esc(x.source||'Profiler')} · ${esc(x.confidence||'Low')} confidence</div></td><td>${esc(x.detail||'')}</td><td>${esc(x.recommendation||'')}</td></tr>`).join(''):'<tr><td colspan="3" class="muted">No profiler-backed patch suggestions yet. Run a manual profile during the slowdown to generate evidence.</td></tr>';
  document.querySelectorAll('[data-patch-edit]').forEach(btn=>btn.onclick=()=>{const row=rows[Number(btn.dataset.patchEdit||-1)];if(row)fillCustomPatchForm(row.definition)});
  document.querySelectorAll('[data-patch-toggle]').forEach(btn=>btn.onclick=()=>customPatchAction(btn.dataset.patchEnabled==='1'?'disable':'enable',btn.dataset.patchToggle||''));
  document.querySelectorAll('[data-patch-delete]').forEach(btn=>btn.onclick=()=>{if(confirm('Delete this custom patch definition?'))customPatchAction('delete',btn.dataset.patchDelete||'')});
}
async function loadCustomPatches(showLoading=true){
  if(showLoading&&$('patchStudioState'))$('patchStudioState').textContent='Loading Patch Studio…';
  try{customPatchesData=await api('/api/custom-patches');renderCustomPatches();setPageStatus('customPatches',(customPatchesData?.patches||[]).some(x=>x.definition?.runtimeStatus==='Error')?'warn':'good',`${(customPatchesData?.patches||[]).length} patch definition(s)`)}catch(e){if($('patchStudioState'))$('patchStudioState').textContent='Load failed';setPageStatus('customPatches','bad',e.message);toast(e.message,'error')}
}
async function generateCustomPatch(){
  const p=customPatchFormPayload();
  if(!p.typeName||!p.methodName||!p.assemblyName){toast('Enter assembly, type and method before generating a template.','error');return}
  try{const d=await api('/api/custom-patches/generate',{method:'POST',body:JSON.stringify(p)});if(d.generated)fillCustomPatchForm(d.generated);toast(d.message||'Template generated.','success')}catch(e){toast(e.message,'error')}
}
async function saveCustomPatch(){
  if(currentSessionRole==='ReadOnly'){toast('Read-only accounts cannot change patches.','error');return}
  if(!currentSessionOwner){toast('Only the panel Owner can save or apply runtime patches.','error');return}
  const p=customPatchFormPayload();
  if(!p.name||!p.assemblyName||!p.typeName||!p.methodName){toast('Name, assembly, type and method are required.','error');return}
  if(p.enabled&&!confirm('This definition is enabled. Saving it will immediately reapply Patch Studio Harmony patches. Continue?'))return;
  try{const d=await api('/api/custom-patches/save',{method:'POST',body:JSON.stringify(p)});toast(d.message||'Patch saved.','success');customPatchesData=d.snapshot||await api('/api/custom-patches');renderCustomPatches();clearCustomPatchForm()}catch(e){toast(e.message,'error')}
}
async function customPatchAction(action,id){
  if(!currentSessionOwner){toast('Only the panel Owner can enable, disable, or delete runtime patches.','error');return}
  if(action==='enable'&&!confirm('Enable and apply this runtime patch now? Use Observe first whenever possible.'))return;
  try{const d=await api('/api/custom-patches/action',{method:'POST',body:JSON.stringify({action,id})});toast(d.message||'Patch updated.','success');customPatchesData=d.snapshot||await api('/api/custom-patches');renderCustomPatches()}catch(e){toast(e.message,'error')}
}
if($('patchRefresh'))$('patchRefresh').onclick=()=>loadCustomPatches(true);
if($('patchGenerate'))$('patchGenerate').onclick=generateCustomPatch;
if($('patchSave'))$('patchSave').onclick=saveCustomPatch;
if($('patchClear'))$('patchClear').onclick=clearCustomPatchForm;


function contentPatchFormPayload(){
  return {
    id:($('contentPatchId')?.value||'').trim(),
    name:($('contentPatchName')?.value||'').trim(),
    enabled:!!$('contentPatchEnabled')?.checked,
    file:($('contentPatchFile')?.value||'').trim(),
    operation:$('contentPatchOperation')?.value||'add',
    path:($('contentPatchPath')?.value||'').trim(),
    fromPath:($('contentPatchFromPath')?.value||'').trim(),
    valueJson:String($('contentPatchValue')?.value||'null').trim()||'null',
    side:$('contentPatchSide')?.value??'server',
    dependsOnModId:($('contentPatchDependsOn')?.value||'').trim(),
    invertDependency:!!$('contentPatchInvertDependency')?.checked,
    notes:($('contentPatchNotes')?.value||'').trim()
  };
}
function clearContentPatchForm(){
  if($('contentPatchId'))$('contentPatchId').value='';
  if($('contentPatchName'))$('contentPatchName').value='';
  if($('contentPatchPreset'))$('contentPatchPreset').value='generic';
  if($('contentPatchFile'))$('contentPatchFile').value='';
  if($('contentPatchOperation'))$('contentPatchOperation').value='add';
  if($('contentPatchPath'))$('contentPatchPath').value='/';
  if($('contentPatchFromPath'))$('contentPatchFromPath').value='';
  if($('contentPatchValue'))$('contentPatchValue').value='null';
  if($('contentPatchSide'))$('contentPatchSide').value='server';
  if($('contentPatchDependsOn'))$('contentPatchDependsOn').value='';
  if($('contentPatchInvertDependency'))$('contentPatchInvertDependency').checked=false;
  if($('contentPatchIngredient'))$('contentPatchIngredient').value='A';
  if($('contentPatchQuantity'))$('contentPatchQuantity').value='1';
  if($('contentPatchCode'))$('contentPatchCode').value='game:stick';
  if($('contentPatchRecipeEnabled'))$('contentPatchRecipeEnabled').checked=true;
  if($('contentPatchEnabled'))$('contentPatchEnabled').checked=false;
  if($('contentPatchNotes'))$('contentPatchNotes').value='';
}
function fillContentPatchForm(def){
  def=def||{};
  $('contentPatchId').value=def.id||'';$('contentPatchName').value=def.name||'';$('contentPatchEnabled').checked=!!def.enabled;
  $('contentPatchFile').value=def.file||'';$('contentPatchOperation').value=def.operation||'add';$('contentPatchPath').value=def.path||'/';
  $('contentPatchFromPath').value=def.fromPath||'';$('contentPatchValue').value=def.valueJson??'null';$('contentPatchSide').value=def.side??'server';$('contentPatchDependsOn').value=def.dependsOnModId||'';$('contentPatchInvertDependency').checked=!!def.invertDependency;$('contentPatchNotes').value=def.notes||'';
  window.scrollTo({top:Math.max(0,$('customPatches').offsetTop-90),behavior:'smooth'});
}
function renderContentPatches(){
  const d=contentPatchesData||{},rows=d.patches||[];
  if($('contentPatchState'))$('contentPatchState').textContent=d.available===false?'Unavailable':`${rows.length} definition(s)${d.restartRequired?' · RESTART REQUIRED':''}`;
  const body=$('contentPatchRows');
  if(body)body.innerHTML=rows.length?rows.map((x,i)=>`<tr><td><b>${esc(x.name||'Unnamed')}</b><div class="small">${esc(x.notes||'')}</div></td><td><code>${esc(x.file||'')}</code><div class="small"><code>${esc(x.path||'/')}</code></div></td><td><b>${esc(x.operation||'add')}</b><div class="small">${esc(x.side||'both')}</div></td><td class="${x.enabled?'good':'muted'}"><b>${x.enabled?'Enabled':'Disabled'}</b>${d.restartRequired?'<div class="small warn">restart pending</div>':''}</td><td><div class="rowActions"><button data-content-edit="${i}">Edit</button><button data-content-toggle="${esc(x.id||'')}" data-content-enabled="${x.enabled?'1':'0'}">${x.enabled?'Disable':'Enable'}</button><button class="danger" data-content-delete="${esc(x.id||'')}">Delete</button></div></td></tr>`).join(''):'<tr><td colspan="5" class="muted">No JSON/content patches yet.</td></tr>';
  document.querySelectorAll('[data-content-edit]').forEach(btn=>btn.onclick=()=>{const row=rows[Number(btn.dataset.contentEdit||-1)];if(row)fillContentPatchForm(row)});
  document.querySelectorAll('[data-content-toggle]').forEach(btn=>btn.onclick=()=>contentPatchAction(btn.dataset.contentEnabled==='1'?'disable':'enable',btn.dataset.contentToggle||''));
  document.querySelectorAll('[data-content-delete]').forEach(btn=>btn.onclick=()=>{if(confirm('Delete this JSON/content patch? A restart is required to remove any already-loaded effect.'))contentPatchAction('delete',btn.dataset.contentDelete||'')});
}
async function loadContentPatches(showLoading=true){
  if(showLoading&&$('contentPatchState'))$('contentPatchState').textContent='Loading JSON patches…';
  try{contentPatchesData=await api('/api/content-patches');renderContentPatches();const runtimeErr=(customPatchesData?.patches||[]).some(x=>x.definition?.runtimeStatus==='Error');setPageStatus('customPatches',runtimeErr||contentPatchesData?.restartRequired?'warn':'good',contentPatchesData?.restartRequired?'JSON patch restart pending':`${(customPatchesData?.patches||[]).length} runtime · ${(contentPatchesData?.patches||[]).length} JSON`)}catch(e){if($('contentPatchState'))$('contentPatchState').textContent='Load failed';toast(e.message,'error')}
}
async function generateContentPatch(){
  const preset=$('contentPatchPreset')?.value||'generic';
  const p={...contentPatchFormPayload(),preset,ingredientKey:($('contentPatchIngredient')?.value||'A').trim(),quantity:Math.max(1,Math.floor(Number($('contentPatchQuantity')?.value||1))),code:($('contentPatchCode')?.value||'').trim(),enabled:!!$('contentPatchRecipeEnabled')?.checked,dependsOnModId:($('contentPatchDependsOn')?.value||'').trim(),invertDependency:!!$('contentPatchInvertDependency')?.checked};
  if(!p.file){toast('Enter the target asset file first.','error');return}
  try{const d=await api('/api/content-patches/generate',{method:'POST',body:JSON.stringify(p)});if(d.generated)fillContentPatchForm(d.generated);toast(d.message||'Template generated.','success')}catch(e){toast(e.message,'error')}
}
async function saveContentPatch(){
  if(!currentSessionOwner){toast('Only the panel Owner can save generated content patches.','error');return}
  const p=contentPatchFormPayload();
  if(!p.name||!p.file||!p.path){toast('Name, target asset file, and JSON pointer path are required.','error');return}
  if(p.enabled&&!confirm('Save this enabled JSON/content patch? It will be written into the managed patch mod and will take effect after the next server restart.'))return;
  try{const d=await api('/api/content-patches/save',{method:'POST',body:JSON.stringify(p)});toast(d.message||'Content patch saved.','success');contentPatchesData=d.snapshot||await api('/api/content-patches');renderContentPatches();clearContentPatchForm()}catch(e){toast(e.message,'error')}
}
async function contentPatchAction(action,id){
  if(!currentSessionOwner){toast('Only the panel Owner can change generated content patches.','error');return}
  try{const d=await api('/api/content-patches/action',{method:'POST',body:JSON.stringify({action,id})});toast(d.message||'Content patch updated.','success');contentPatchesData=d.snapshot||await api('/api/content-patches');renderContentPatches()}catch(e){toast(e.message,'error')}
}
if($('contentPatchGenerate'))$('contentPatchGenerate').onclick=generateContentPatch;
if($('contentPatchSave'))$('contentPatchSave').onclick=saveContentPatch;
if($('contentPatchClear'))$('contentPatchClear').onclick=clearContentPatchForm;

async function loadCompatibility(deep=false){
  $('compatState').textContent=deep?'Running deep Harmony inspection…':'Loading compatibility checks…';
  try{
    compatibilityData=await api(deep?'/api/compatibility/deep':'/api/compatibility');
    const d=compatibilityData,checks=d.checks||[],commands=d.commandOwnership||[],h=d.harmony||{};
    setCompatibilityNavState(d);
    $('compatState').textContent=`${d.summary||'Unknown'} · ${Number(d.loadedModCount||0)} loaded mods${deep?' · deep scan complete':''}`;
    $('compatMetrics').innerHTML=
      metric('Compatibility',d.summary||'Unknown',d.summary==='Conflict'?'bad':d.summary==='Watch'?'warn':'good')+
      metric('Critical',Number(d.criticalCount||0),Number(d.criticalCount||0)>0?'bad':'good')+
      metric('Watch',Number(d.watchCount||0),Number(d.watchCount||0)>0?'warn':'good')+
      metric('Loaded mods',Number(d.loadedModCount||0).toLocaleString())+
      metric('Harmony overlaps',deep?Number(h.conflictCount||0).toLocaleString():'Manual',deep&&Number(h.conflictCount||0)>0?'warn':'');
    $('compatChecks').innerHTML=checks.length?checks.map(x=>`<tr><td class="${x.severity==='Critical'?'bad':x.severity==='Watch'?'warn':x.severity==='OK'?'good':''}"><b>${esc(x.severity)}</b></td><td>${esc(x.category)}</td><td><b>${esc(x.title)}</b></td><td>${esc(x.detail)}</td><td>${esc(x.action||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No compatibility checks.</td></tr>';
    $('compatCommands').innerHTML=commands.map(x=>`<tr><td><code>${esc(x.command)}</code></td><td><b>${esc(x.owner)}</b></td><td>${esc(x.suiteFallback||'—')}</td><td class="${x.status==='OK'?'good':''}">${esc(x.status)}</td></tr>`).join('');
    $('compatHarmonyState').textContent=deep?`${Number(h.patchedMethodCount||0)} patched method(s) · ${Number(h.conflictCount||0)} overlap(s)`:String(h.message||'Manual deep scan not run.');
    const rows=h.conflicts||[];
    $('compatHarmony').innerHTML=rows.length?rows.slice(0,200).map(x=>`<tr><td class="${x.severity==='High'?'warn':''}"><b>${esc(x.severity)}</b></td><td><code>${esc(x.declaringType)}.${esc(x.method)}</code><div class="small">${esc(x.signature||'')}</div></td><td>${(x.owners||[]).map(o=>`<code>${esc(o)}</code>`).join('<br>')}</td><td>${esc(x.note||'')}</td></tr>`).join(''):`<tr><td colspan="4" class="${deep?'good':'muted'}">${deep?'No multi-owner Harmony overlaps found in the inspected set.':'Deep Harmony scan not run.'}</td></tr>`;
  }catch(e){$('compatState').textContent='Load failed';toast(e.message,'error');}
}
$('compatRefresh').onclick=()=>loadCompatibility(false);
$('compatDeep').onclick=()=>loadCompatibility(true);

async function loadMods(showLoading=true){
  if(showLoading){
    $('modsCount').textContent='Loading…';
    $('modsRows').innerHTML='<tr><td colspan="11" class="muted">Loading mod inventory, profiler attribution and cached update status…</td></tr>';
  }
  try{
    const [d,u]=await Promise.all([api('/api/server/mods'),api('/api/mod-updates').catch(()=>({mods:[]}))]);
    loadedMods=d.mods||[];
    modUpdatesData=u||{mods:[]};
    const checked=Number(modUpdatesData.checkedUnixMilliseconds||0);
    $('modsUpdateState').textContent=checked?`${Number(modUpdatesData.updateCount||0)} update(s) · checked ${new Date(checked).toLocaleString()}${modUpdatesData.restartRequired?' · RESTART REQUIRED':''}${modUpdatesData.lastWarning?' · '+modUpdatesData.lastWarning:''}`:'Updates not checked yet';
    loadedModsMeta=d||{};
    const completed=Number(d.profileCompletedUnixMilliseconds||0);
    $('modsProfileState').innerHTML=d.profileAvailable
      ? `<b>Last manual profile:</b> ${completed?esc(new Date(completed).toLocaleString()):'available'} · ${Number(d.profileDurationSeconds||0)}s · P95 ${Number(d.profileP95TickMs||0).toFixed(1)}ms · max ${Number(d.profileMaxTickMs||0).toFixed(1)}ms. <span class="muted">Impact scores are evidence-weighted and confidence-adjusted; click a row for the exact markers.</span>`
      : 'No manual engine profile has been captured yet. <b>Run Profile 10s or Profile 30s while the slowdown is happening.</b> Until then every mod remains Not measured.';
    renderMods();
    if(selectedModPerformanceId && loadedMods.some(x=>String(x.modId).toLowerCase()===selectedModPerformanceId.toLowerCase())){
      openModPerformance(selectedModPerformanceId,false);
    }
  }catch(e){
    $('modsCount').textContent='Load failed';
    $('modsRows').innerHTML=`<tr><td colspan="11" class="bad">${esc(e.message)}</td></tr>`;
  }
}

function setModsTab(tab,persist=true){
  modsActiveTab=tab==='updates'?'updates':'installed';
  if(persist)localStorage.setItem('nsu.modsTab',modsActiveTab);
  document.querySelectorAll('[data-mod-tab]').forEach(b=>b.classList.toggle('active',b.dataset.modTab===modsActiveTab));
  const installed=$('modsInstalledPanel'),updates=$('modsUpdatesPanel');
  if(installed)installed.style.display=modsActiveTab==='installed'?'block':'none';
  if(updates)updates.style.display=modsActiveTab==='updates'?'block':'none';
  renderMods();
}

function updateModsUpdateNotification(){
  const count=Number(modUpdatesData.updateCount||0);
  setModUpdatesNavState(modUpdatesData);
  const badge=$('modsUpdatesBadge');
  if(badge){badge.textContent=String(count);badge.style.display=count>0?'inline-block':'none';}
  const button=document.querySelector('[data-mod-tab="updates"]');
  if(button)button.title=count>0?`${count} compatible mod update${count===1?'':'s'} available`:'No compatible mod updates available from the latest check';
}

function renderAvailableModUpdates(){
  updateModsUpdateNotification();
  const checked=Number(modUpdatesData.checkedUnixMilliseconds||0);
  const q=String($('modsFilter')?.value||'').trim().toLowerCase();
  const updates=(modUpdatesData.mods||[]).filter(u=>u?.status==='Update').filter(u=>{
    if(!q)return true;
    const m=loadedMods.find(x=>String(x.modId||'').toLowerCase()===String(u.modId||'').toLowerCase())||{};
    return [u.modId,u.installedVersion,u.recommendedVersion,u.detail,m.name,m.fileName].some(v=>String(v||'').toLowerCase().includes(q));
  });
  const total=Number(modUpdatesData.updateCount||updates.length);
  const summary=$('modsUpdatesSummary');
  if(summary){
    if(!checked)summary.textContent='Updates not checked yet.';
    else if(total>0)summary.textContent=`${total} update${total===1?'':'s'} available · checked ${new Date(checked).toLocaleString()}`;
    else summary.textContent=`No updates available · checked ${new Date(checked).toLocaleString()}`;
  }
  const body=$('modsUpdateRows');
  if(body){
    if(!checked){
      body.innerHTML='<tr><td colspan="6" class="muted">Run Check Updates to find compatible updates.</td></tr>';
    }else if(!updates.length){
      body.innerHTML=q?'<tr><td colspan="6" class="muted">No available updates match the current filter.</td></tr>':'<tr><td colspan="6" class="good">All checked loaded mods are current for this Vintage Story version.</td></tr>';
    }else{
      body.innerHTML=updates.map((u,i)=>{
        const m=loadedMods.find(x=>String(x.modId||'').toLowerCase()===String(u.modId||'').toLowerCase())||{};
        const pageUrl=String(u.modPageUrl||('https://mods.vintagestory.at/'+encodeURIComponent(String(u.modId||''))));
        const actions=`<div class="rowActions"><button class="iconBtn" data-open-mod-page="${esc(pageUrl)}">Open page</button>${u.autoUpdateSupported?`<button class="iconBtn primary" data-update-mod="${esc(u.modId)}">Update</button>`:`<button class="iconBtn" disabled title="${esc(u.autoUpdateReason||'Automatic update is unavailable for this package.')}">Manual only</button>`}</div>`;
        return `<tr><td><b>${i+1}</b></td><td><b>${esc(u.modId||'')}</b><div class="small">${esc(m.name||'')}</div></td><td>${esc(u.installedVersion||m.version||'—')}</td><td><span class="updateBadge update">${esc(u.recommendedVersion||'?')}</span></td><td class="codeCell" title="${esc(m.fileName||'')}">${esc(m.fileName||'—')}</td><td class="small" style="white-space:normal;min-width:280px">${esc(u.detail||'Compatible update available.')}</td><td>${actions}</td></tr>`;
      }).join('');
    }
  }
  if(modsActiveTab==='updates')$('modsCount').textContent=checked?`${updates.length} shown · ${total} update${total===1?'':'s'} available`:'Updates not checked yet';
  document.querySelectorAll('#modsUpdatesPanel [data-open-mod-page]').forEach(btn=>btn.onclick=(ev)=>{ev.stopPropagation();const url=String(btn.dataset.openModPage||'');if(url)window.open(url,'_blank','noopener,noreferrer');});
  document.querySelectorAll('#modsUpdatesPanel [data-update-mod]').forEach(btn=>btn.onclick=(ev)=>{ev.stopPropagation();stageModUpdate(btn.dataset.updateMod||'',btn);});
}

function modImpactBadge(x){
  const label=String(x.impact||'Not measured');
  const score=Number(x.impactScore||0);
  const cls=label==='Severe'?'critical':label==='High'?'high':label==='Moderate'?'medium':label==='Low'?'low':'muted';
  return `<span class="badge ${cls}">${esc(label)}</span>${x.measured?` <b>${score}</b>/100`:''}`;
}

function modUpdateFor(modId){return (modUpdatesData.mods||[]).find(x=>String(x.modId||'').toLowerCase()===String(modId||'').toLowerCase())||null;}
function modUpdateBadge(x){
  if(x.core)return '<span class="updateBadge unknown">Core</span>';
  const u=modUpdateFor(x.modId);if(!u)return '<span class="updateBadge unknown">Not checked</span>';
  if(u.status==='Update')return `<span class="updateBadge update">${esc(u.installedVersion||x.version)} → ${esc(u.recommendedVersion||'?')}</span>`;
  if(u.status==='Staged')return `<span class="updateBadge current" title="${esc(u.detail||'Update staged; restart required.')}">Restart required</span>`;
  if(u.status==='Current')return '<span class="updateBadge current">Current</span>';
  return `<span class="updateBadge unknown" title="${esc(u.detail||u.status||'Unknown')}">${esc(u.status||'Unknown')}</span>`;
}

function modUpdateActions(x){
  if(x.core)return '';
  const u=modUpdateFor(x.modId);
  const pageUrl=String(u?.modPageUrl||('https://mods.vintagestory.at/'+encodeURIComponent(String(x.modId||''))));
  let html=`<div class="small" style="display:flex;gap:5px;flex-wrap:wrap;margin-top:5px"><button class="iconBtn" data-open-mod-page="${esc(pageUrl)}" title="Open this mod on the official Vintage Story Mod DB">Open page</button>`;
  if(u?.status==='Update'){
    if(u.autoUpdateSupported)html+=`<button class="iconBtn primary" data-update-mod="${esc(x.modId)}" title="Download, validate, back up and stage ${esc(u.recommendedVersion||'the compatible update')}">Update</button>`;
    else html+=`<button class="iconBtn" disabled title="${esc(u.autoUpdateReason||'Automatic update is unavailable for this package.')}">Manual only</button>`;
  }
  html+='</div>';
  return html;
}

async function checkModUpdates(){
  const btn=$('modsCheckUpdates');btn.disabled=true;btn.textContent='Checking…';$('modsUpdateState').textContent='Contacting official Vintage Story Mod DB…';
  try{modUpdatesData=await api('/api/mod-updates/check',{method:'POST',body:'{}'});const checked=Number(modUpdatesData.checkedUnixMilliseconds||0);$('modsUpdateState').textContent=`${Number(modUpdatesData.updateCount||0)} update(s) · ${Number(modUpdatesData.currentCount||0)} current · checked ${checked?new Date(checked).toLocaleString():'now'}${modUpdatesData.restartRequired?' · RESTART REQUIRED':''}${modUpdatesData.lastWarning?' · '+modUpdatesData.lastWarning:''}`;renderMods();toast(modUpdatesData.lastWarning?`Update check completed with warnings: ${modUpdatesData.lastWarning}`:`Mod update check complete: ${Number(modUpdatesData.updateCount||0)} update(s) available.`,modUpdatesData.lastWarning?'warn':'success');}
  catch(e){$('modsUpdateState').textContent='Update check failed';toast(e.message,'error');}
  finally{btn.disabled=false;btn.textContent='Check Updates';}
}

async function stageModUpdate(modId,button){
  const u=modUpdateFor(modId);
  if(!u||u.status!=='Update')return;
  const from=u.installedVersion||loadedMods.find(x=>String(x.modId).toLowerCase()===String(modId).toLowerCase())?.version||'?';
  const to=u.recommendedVersion||'?';
  const warning=`Stage ${modId} ${from} → ${to}?\n\nNSE will download the official compatible Mod DB release, validate its mod ID/version, check required dependencies, back up the current ZIP outside the Mods folder, and replace the package on disk.\n\nThe running server will keep the old code until you restart it.`;
  if(!confirm(warning))return;
  const oldText=button?.textContent||'Update';if(button){button.disabled=true;button.textContent='Staging…';}
  try{
    const r=await api('/api/mod-updates/apply',{method:'POST',body:JSON.stringify({modId})});
    modUpdatesData=await api('/api/mod-updates');
    const checked=Number(modUpdatesData.checkedUnixMilliseconds||0);
    $('modsUpdateState').textContent=`${Number(modUpdatesData.updateCount||0)} update(s) · checked ${checked?new Date(checked).toLocaleString():'recently'}${modUpdatesData.restartRequired?' · RESTART REQUIRED':''}`;
    renderMods();
    toast(r.message||`${modId} update staged. Restart required.`,'success');
  }catch(e){toast(`Update failed: ${e.message}`,'error');if(button){button.disabled=false;button.textContent=oldText;}}
}

function renderMods(){
  const q=String($('modsFilter').value||'').trim().toLowerCase();
  const thirdParty=!!$('modsThirdParty').checked;
  const measuredOnly=!!$('modsMeasuredOnly').checked;
  const rows=loadedMods.filter(x=>{
    if(thirdParty&&x.core)return false;
    if(measuredOnly&&!x.measured)return false;
    if(!q)return true;
    const u=modUpdateFor(x.modId);
    return [x.modId,x.name,x.version,x.type,x.side,x.fileName,x.topMarker,x.impact,u?.status,u?.recommendedVersion]
      .some(v=>String(v||'').toLowerCase().includes(q));
  });

  const measuredCount=loadedMods.filter(x=>x.measured).length;
  if(modsActiveTab==='installed')$('modsCount').textContent=`${rows.length} shown · ${measuredCount}/${loadedMods.length} measured`;
  $('modsRows').innerHTML=rows.length
    ? rows.map((x,i)=>`<tr class="clickableRow" data-mod-performance="${esc(x.modId)}" title="Open measured tick/profile evidence for ${esc(x.modId)}">
        <td><b>${i+1}</b></td>
        <td>${modImpactBadge(x)}</td>
        <td><b>${esc(x.modId)}</b>${x.core?' <span class="badge high">core</span>':''}<div class="small">${esc(x.name||'')}</div><button class="iconBtn" data-pin-mod="${esc(x.modId)}" title="Pin this mod to Dashboard">Pin</button></td>
        <td>${esc(x.version||'—')}</td>
        <td>${modUpdateBadge(x)}${modUpdateActions(x)}</td>
        <td>${x.measured?`<b>${Number(x.tickShare||0).toFixed(1)}%</b>`:'—'}</td>
        <td>${x.measured?`${Number(x.maxSingleMs||0).toFixed(1)}ms`:'—'}</td>
        <td>${x.measured?Number(x.slowSegments||0):'—'}</td>
        <td>${x.measured?confidenceBadge(x.confidence):'<span class="muted">none</span>'}</td>
        <td class="codeCell" title="${esc(x.topMarker||'')}">${x.measured?esc(x.topMarker||'No named marker'):'Run a profile'}</td>
        <td>${Number(x.systems||0)}</td>
      </tr>`).join('')
    : '<tr><td colspan="11" class="muted">No loaded mod matches the current filters.</td></tr>';

  document.querySelectorAll('[data-mod-performance]').forEach(row=>row.onclick=()=>openModPerformance(row.dataset.modPerformance||'',true));
  document.querySelectorAll('[data-pin-mod]').forEach(btn=>btn.onclick=(ev)=>{ev.stopPropagation();addWatchItem('mod',btn.dataset.pinMod,btn.dataset.pinMod,'mods');});
  document.querySelectorAll('[data-open-mod-page]').forEach(btn=>btn.onclick=(ev)=>{ev.stopPropagation();const url=String(btn.dataset.openModPage||'');if(url)window.open(url,'_blank','noopener,noreferrer');});
  document.querySelectorAll('#modsInstalledPanel [data-update-mod]').forEach(btn=>btn.onclick=(ev)=>{ev.stopPropagation();stageModUpdate(btn.dataset.updateMod||'',btn);});
  renderAvailableModUpdates();
  document.querySelectorAll('[data-mod-tab]').forEach(btn=>btn.classList.toggle('active',btn.dataset.modTab===modsActiveTab));
  if($('modsInstalledPanel'))$('modsInstalledPanel').style.display=modsActiveTab==='installed'?'block':'none';
  if($('modsUpdatesPanel'))$('modsUpdatesPanel').style.display=modsActiveTab==='updates'?'block':'none';
  setTimeout(enhanceImportantTables,20);
}

async function openModPerformance(modId,scroll=true){
  if(!modId)return;
  selectedModPerformanceId=modId;
  const host=$('modPerformanceDetail');
  host.style.display='block';
  host.innerHTML='<div class="muted">Loading profiler evidence…</div>';
  if(scroll)host.scrollIntoView({behavior:'smooth',block:'start'});
  try{
    const payload=await api('/api/server/mods/detail?modId='+encodeURIComponent(modId));
    const m=payload.mod||{};
    const d=payload.details||{};
    const summary=d.summary||null;
    const listRow=loadedMods.find(x=>String(x.modId).toLowerCase()===String(modId).toLowerCase())||{};
    const hotspots=d.hotspots||[];
    const phases=d.phases||[];
    const slow=d.slowTicks||[];
    const off=d.offThreadReports||[];
    const profileWhen=Number(d.profileCompletedUnixMilliseconds||0);

    const hotspotRows=hotspots.length?hotspots.map(x=>`<tr>
      <td class="codeCell" title="${esc(x.code)}"><b>${esc(x.code)}</b></td>
      <td>${Number(x.totalMs||0).toFixed(1)}ms</td><td>${Number(x.maxSingleMs||0).toFixed(1)}ms</td>
      <td>${Number(x.calls||0).toLocaleString()}</td><td>${Number(x.percentOfProfileTickTime||0).toFixed(1)}%</td>
      <td>${confidenceBadge(x.attributionConfidence)}</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No individual tick marker was attributed to this mod in the retained profile.</td></tr>';
    const phaseRows=phases.length?phases.map(x=>`<tr><td class="codeCell" title="${esc(x.code)}">${esc(x.code)}</td><td>${Number(x.averagePerTickMs||0).toFixed(2)}ms</td><td>${Number(x.maxSingleMs||0).toFixed(1)}ms</td><td>${Number(x.totalMs||0).toFixed(1)}ms</td><td>${Number(x.percentOfProfileTickTime||0).toFixed(1)}%</td></tr>`).join(''):'<tr><td colspan="5" class="muted">No root tick phase was directly attributed to this mod.</td></tr>';
    const slowRows=slow.length?slow.map(x=>`<tr><td><b>${Number(x.tickMs||0).toFixed(1)}ms</b></td><td class="codeCell" title="${esc(x.topCauseSummary)}">${esc(x.topCauseSummary)}</td></tr>`).join(''):'<tr><td colspan="2" class="muted">This mod was not named in the retained worst-tick summaries.</td></tr>';
    const offRows=off.length?off.map(x=>`<tr><td><b>${Number(x.durationMs||0).toFixed(1)}ms</b></td><td>${confidenceBadge(x.confidence)}</td><td class="codeCell" title="${esc(x.summary)}">${esc(x.summary)}</td></tr>`).join(''):'<tr><td colspan="3" class="muted">No off-thread slow-profile report was attributed to this mod.</td></tr>';

    host.innerHTML=`
      <div class="cardHeader"><div><h3 style="margin:0">${esc(m.name||modId)} <span class="small">${esc(modId)} ${esc(m.version||'')}</span></h3><div class="small">${esc(m.fileName||'')} · ${Number(m.systems||0)} ModSystem(s) · ${esc(m.side||'')}</div></div><div class="spacer"></div>${modImpactBadge(listRow)} <button id="modDetailClose">Close</button></div>
      <div class="grid" style="margin-top:10px">
        <div class="card"><h4>Measured impact</h4>${summary?`<div style="font-size:28px;font-weight:800">${Number(listRow.impactScore||0)}/100</div><div>${esc(listRow.impact||'')}</div><div class="small" style="margin-top:8px">Tick share <b>${Number(summary.percentOfProfileTickTime||0).toFixed(1)}%</b> · total ${Number(summary.totalMs||0).toFixed(1)}ms · max segment ${Number(summary.maxSingleMs||0).toFixed(1)}ms · ${Number(summary.slowSegments||0)} segment(s) ≥10ms · ${confidenceBadge(summary.confidence)}</div>`:`<div class="muted">${d.profileAvailable?'A profile exists, but no profiler work was attributed to this mod. That means <b>no measured attribution</b>, not proof of zero cost.':'No manual profile exists yet.'}</div>`}</div>
        <div class="card"><h4>Profile context</h4><div class="small">${d.profileAvailable?`Captured ${profileWhen?esc(new Date(profileWhen).toLocaleString()):'previously'} for ${Number(d.profileDurationSeconds||0)}s · ${Number(d.profileTickCount||0)} ticks<br>Average tick ${Number(d.profileAverageTickMs||0).toFixed(1)}ms · P95 ${Number(d.profileP95TickMs||0).toFixed(1)}ms · P99 ${Number(d.profileP99TickMs||0).toFixed(1)}ms · max ${Number(d.profileMaxTickMs||0).toFixed(1)}ms`:'Run a 10s/30s profile while the performance issue is active.'}</div></div>
      </div>
      <div class="card" style="margin-top:10px"><h4>What part of the mod used tick time?</h4><p class="small">These are the exact FrameProfiler markers attributed back to this mod. The first rows are the strongest evidence for which subsystem, behavior, event handler, or code path consumed time.</p><div class="tableWrap"><table><thead><tr><th>Profiler marker / path</th><th>Total</th><th>Max</th><th>Calls</th><th>Tick share</th><th>Confidence</th></tr></thead><tbody>${hotspotRows}</tbody></table></div></div>
      <div class="grid" style="margin-top:10px">
        <div class="card"><h4>Attributed tick phases</h4><div class="tableWrap"><table><thead><tr><th>Phase</th><th>Avg/tick</th><th>Max</th><th>Total</th><th>Share</th></tr></thead><tbody>${phaseRows}</tbody></table></div></div>
        <div class="card"><h4>Worst ticks naming this mod</h4><div class="tableWrap"><table><thead><tr><th>Tick</th><th>Leading profiler causes</th></tr></thead><tbody>${slowRows}</tbody></table></div></div>
      </div>
      <div class="card" style="margin-top:10px"><h4>Off-thread evidence</h4><div class="tableWrap"><table><thead><tr><th>Duration</th><th>Confidence</th><th>Worker-thread report</th></tr></thead><tbody>${offRows}</tbody></table></div></div>
      <p class="small" style="margin-top:10px"><b>Interpretation:</b> ${esc(payload.note||'')} Impact score combines measured tick share, maximum segment, repeated ≥10ms segments and off-thread stalls, then reduces the score when ownership confidence is weaker.</p>`;
    $('modDetailClose').onclick=()=>{host.style.display='none';selectedModPerformanceId='';};
  }catch(e){host.innerHTML=`<div class="bad"><b>Could not load mod evidence:</b> ${esc(e.message)}</div>`;}
}

