const chartDefs=[
  {canvas:'chartDelay',tip:'tipDelay',meta:'metaDelay',key:'mainThreadDelayMs',label:'Delay',suffix:'ms',zeroBase:true,thresholds:[50,100],incidents:true},
  {canvas:'chartCpu',tip:'tipCpu',meta:'metaCpu',key:'cpuPercent',label:'CPU',suffix:'%',zeroBase:true,fixedMax:100,thresholds:[90]},
  {canvas:'chartHeap',tip:'tipHeap',meta:'metaHeap',key:'managedHeapMb',label:'Heap',suffix:' MB',zeroBase:false},
  {canvas:'chartEntities',tip:'tipEntities',meta:'metaEntities',key:'loadedEntities',label:'Entities',suffix:'',zeroBase:false,integer:true},
  {canvas:'chartQueue',tip:'tipQueue',meta:'metaQueue',key:'blockLoggerQueue',label:'Queue',suffix:'',zeroBase:true,integer:true,thresholds:[1000]},
  {canvas:'chartWriter',tip:'tipWriter',meta:'metaWriter',key:'blockLoggerWriterMs',label:'Writer',suffix:'ms',zeroBase:true,integer:true,thresholds:[100]}
];

function fmtValue(v,def){
  if(def.integer)return Math.round(v).toLocaleString()+def.suffix;
  if(Math.abs(v)>=1000)return Math.round(v).toLocaleString()+def.suffix;
  return Number(v).toFixed(v<10?1:0)+def.suffix;
}

function chartStats(samples,key){
  const vals=samples.map(x=>Number(x[key]||0)).filter(Number.isFinite);
  if(!vals.length)return{current:0,avg:0,max:0,min:0};
  return{
    current:vals[vals.length-1],
    avg:vals.reduce((a,b)=>a+b,0)/vals.length,
    max:Math.max(...vals),
    min:Math.min(...vals)
  };
}

function setChartMeta(def,samples){
  const st=chartStats(samples,def.key);
  $(def.meta).innerHTML=`<span>Now <b>${fmtValue(st.current,def)}</b></span><span>Avg <b>${fmtValue(st.avg,def)}</b></span><span>Max <b>${fmtValue(st.max,def)}</b></span>`;
}

function nearestIndexByTime(samples,target){
  if(!samples.length)return-1;
  let lo=0,hi=samples.length-1;
  while(lo<hi){
    const mid=Math.floor((lo+hi)/2);
    if(Number(samples[mid].unixMilliseconds)<target)lo=mid+1;else hi=mid;
  }
  if(lo>0){
    const a=Math.abs(Number(samples[lo].unixMilliseconds)-target);
    const b=Math.abs(Number(samples[lo-1].unixMilliseconds)-target);
    if(b<a)return lo-1;
  }
  return lo;
}

function resizeCanvas(canvas){
  const rect=canvas.getBoundingClientRect();
  const dpr=Math.min(2,window.devicePixelRatio||1);
  const width=Math.max(200,Math.floor(rect.width*dpr));
  const height=Math.max(120,Math.floor(rect.height*dpr));
  if(canvas.width!==width||canvas.height!==height){
    canvas.width=width;canvas.height=height;
  }
  const ctx=canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  return{ctx,w:rect.width,h:rect.height};
}

function chartPlotBackground(ctx,pad,w,h,rows=4,cols=4){
  const pw=Math.max(1,w-pad.l-pad.r),ph=Math.max(1,h-pad.t-pad.b);
  ctx.save();
  ctx.fillStyle='#0b1218';ctx.fillRect(pad.l,pad.t,pw,ph);
  ctx.strokeStyle='rgba(86,108,124,.22)';ctx.lineWidth=1;
  for(let i=0;i<=rows;i++){const y=pad.t+ph*i/rows;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();}
  ctx.strokeStyle='rgba(86,108,124,.11)';
  for(let i=1;i<cols;i++){const x=pad.l+pw*i/cols;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();}
  ctx.restore();
}

function chartAreaFill(ctx,points,bottom,fill='rgba(93,155,208,.10)'){
  if(!points.length)return;
  ctx.save();ctx.beginPath();ctx.moveTo(points[0][0],bottom);
  points.forEach(([x,y])=>ctx.lineTo(x,y));
  ctx.lineTo(points[points.length-1][0],bottom);ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.restore();
}

function chartLine(ctx,points,color='#71aee0',width=2){
  if(!points.length)return;
  ctx.save();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();
  points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();ctx.restore();
}

function chartEndPoint(ctx,points,color='#dcebf6'){
  if(!points.length)return;const [x,y]=points[points.length-1];
  ctx.save();ctx.fillStyle=color;ctx.strokeStyle='#0b1218';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();
}

function drawHealthChart(def,samples,incidents){
  const canvas=$(def.canvas),tip=$(def.tip);
  const {ctx,w,h}=resizeCanvas(canvas);
  ctx.clearRect(0,0,w,h);

  const pad={l:44,r:10,t:10,b:26};
  const pw=Math.max(1,w-pad.l-pad.r),ph=Math.max(1,h-pad.t-pad.b);
  ctx.font='10px system-ui';
  ctx.lineWidth=1;

  if(!samples.length){
    ctx.fillStyle='#8492a0';ctx.fillText('No samples in this range',pad.l,pad.t+18);
    tip.style.display='none';
    return;
  }

  const vals=samples.map(x=>Number(x[def.key]||0));
  let minVal=def.zeroBase?0:Math.min(...vals);
  let maxVal=def.fixedMax||Math.max(...vals,1);

  if(!def.zeroBase){
    const span=Math.max(1,maxVal-minVal);
    minVal=Math.max(0,minVal-span*.15);
    maxVal=maxVal+span*.15;
  }else{
    maxVal=Math.max(maxVal*1.12,1);
  }

  if(def.thresholds){
    for(const t of def.thresholds)maxVal=Math.max(maxVal,t*1.08);
  }
  if(maxVal<=minVal)maxVal=minVal+1;

  const firstTime=Number(samples[0].unixMilliseconds);
  const lastTime=Number(samples[samples.length-1].unixMilliseconds);
  const timeSpan=Math.max(1,lastTime-firstTime);
  const xForTime=t=>pad.l+clamp((t-firstTime)/timeSpan,0,1)*pw;
  const yForValue=v=>pad.t+(1-clamp((v-minVal)/(maxVal-minVal),0,1))*ph;

  chartPlotBackground(ctx,pad,w,h,4,4);
  ctx.fillStyle='#748797';
  for(let i=0;i<=4;i++){
    const y=pad.t+ph*i/4;
    const value=maxVal-(maxVal-minVal)*i/4;
    ctx.fillText(fmtValue(value,def),3,y+3);
  }

  if(def.thresholds){
    ctx.save();ctx.setLineDash([5,5]);ctx.font='9px system-ui';
    def.thresholds.forEach((t,idx)=>{
      const y=yForValue(t);const critical=idx===def.thresholds.length-1;
      ctx.strokeStyle=critical?'rgba(208,91,91,.62)':'rgba(206,168,80,.56)';
      ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();
      ctx.setLineDash([]);ctx.fillStyle=critical?'#cf8585':'#cbb879';ctx.fillText(fmtValue(t,def),pad.l+5,Math.max(pad.t+9,y-4));ctx.setLineDash([5,5]);
    });
    ctx.restore();
  }

  if(def.incidents){
    (incidents||[]).forEach(x=>{
      const t=Number(x.unixMilliseconds||0);
      if(t<firstTime||t>lastTime)return;
      const xPos=xForTime(t);
      ctx.strokeStyle=String(x.severity||'').toLowerCase()==='critical'?'#ff7474':'#ffad66';
      ctx.globalAlpha=.58;
      ctx.beginPath();ctx.moveTo(xPos,pad.t);ctx.lineTo(xPos,pad.t+ph);ctx.stroke();
      ctx.globalAlpha=1;
    });
  }

  const seriesPoints=samples.map(row=>[xForTime(Number(row.unixMilliseconds)),yForValue(Number(row[def.key]||0))]);
  chartAreaFill(ctx,seriesPoints,pad.t+ph,'rgba(93,155,208,.085)');
  chartLine(ctx,seriesPoints,'#75afe0',2.2);
  chartEndPoint(ctx,seriesPoints,'#dcebf6');

  const timeLabels=[firstTime,firstTime+timeSpan/2,lastTime];
  ctx.fillStyle='#748392';
  timeLabels.forEach((t,i)=>{
    const label=new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:profilerRangeSeconds<=300?'2-digit':undefined});
    const x=pad.l+pw*i/2;
    const width=ctx.measureText(label).width;
    ctx.fillText(label,clamp(x-width/2,pad.l,pad.l+pw-width),h-7);
  });

  if(chartHoverTimestamp!==null){
    const idx=nearestIndexByTime(samples,chartHoverTimestamp);
    if(idx>=0){
      const row=samples[idx];
      const x=xForTime(Number(row.unixMilliseconds));
      const y=yForValue(Number(row[def.key]||0));
      ctx.strokeStyle='#dbe8f4';ctx.lineWidth=1;
      ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,pad.t+ph);ctx.stroke();
      ctx.fillStyle='#dbe8f4';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();

      let extra='';
      if(def.incidents){
        const near=(incidents||[]).find(e=>Math.abs(Number(e.unixMilliseconds)-Number(row.unixMilliseconds))<=1800);
        if(near)extra=`<br><span class="${severityClass(near.severity)}"><b>${esc(near.severity)}</b></span> ${esc(near.evidence)}`;
      }

      tip.innerHTML=`<b>${esc(def.label)}: ${esc(fmtValue(Number(row[def.key]||0),def))}</b><br>${esc(new Date(Number(row.unixMilliseconds)).toLocaleString())}${extra}`;
      tip.style.display='block';
      const left=clamp(x+10,6,w-220);
      const top=clamp(y-48,6,h-82);
      tip.style.left=left+'px';tip.style.top=top+'px';
    }
  }else{
    tip.style.display='none';
  }
}

function redrawProfilerCharts(){
  if(!lastProfilerPayload)return;
  const samples=lastProfilerPayload.samples||[];
  const incidents=lastProfilerPayload.diagnosticIncidents||[];
  chartDefs.forEach(def=>{
    setChartMeta(def,samples);
    drawHealthChart(def,samples,incidents);
  });
}

chartDefs.forEach(def=>{
  const canvas=$(def.canvas);
  canvas.addEventListener('mousemove',e=>{
    if(!lastProfilerPayload)return;
    const samples=lastProfilerPayload.samples||[];
    if(!samples.length)return;
    const rect=canvas.getBoundingClientRect();
    const padLeft=44,padRight=10;
    const x=clamp(e.clientX-rect.left-padLeft,0,Math.max(1,rect.width-padLeft-padRight));
    const ratio=x/Math.max(1,rect.width-padLeft-padRight);
    const first=Number(samples[0].unixMilliseconds),last=Number(samples[samples.length-1].unixMilliseconds);
    chartHoverTimestamp=first+(last-first)*ratio;
    if(def.incidents){
      const incidents=lastProfilerPayload.diagnosticIncidents||[];
      const hit=incidents.map(i=>({i,px:padLeft+((Number(i.unixMilliseconds||0)-first)/Math.max(1,last-first))*Math.max(1,rect.width-padLeft-padRight)})).sort((a,b)=>Math.abs(a.px-(e.clientX-rect.left))-Math.abs(b.px-(e.clientX-rect.left)))[0];
      canvas.classList.toggle('lagIncidentMarkerHover',!!hit&&Math.abs(hit.px-(e.clientX-rect.left))<=9);
      canvas.title=hit&&Math.abs(hit.px-(e.clientX-rect.left))<=9?`${hit.i.severity||'Lag'} spike — click for full incident breakdown`:'';
    }
    redrawProfilerCharts();
  });
  canvas.addEventListener('mouseleave',()=>{
    chartHoverTimestamp=null;canvas.classList.remove('lagIncidentMarkerHover');canvas.title='';
    redrawProfilerCharts();
  });
  if(def.incidents)canvas.addEventListener('click',e=>{
    if(!lastProfilerPayload)return;const samples=lastProfilerPayload.samples||[],incidents=lastProfilerPayload.diagnosticIncidents||[];if(!samples.length||!incidents.length)return;
    const rect=canvas.getBoundingClientRect(),padLeft=44,padRight=10,first=Number(samples[0].unixMilliseconds),last=Number(samples[samples.length-1].unixMilliseconds),plot=Math.max(1,rect.width-padLeft-padRight),cx=e.clientX-rect.left;
    const hit=incidents.map(i=>({i,px:padLeft+((Number(i.unixMilliseconds||0)-first)/Math.max(1,last-first))*plot})).sort((a,b)=>Math.abs(a.px-cx)-Math.abs(b.px-cx))[0];
    if(hit&&Math.abs(hit.px-cx)<=10)openLagIncidentDrawer(Number(hit.i.unixMilliseconds||0));
  });
});

window.addEventListener('resize',()=>{
  if(chartResizeTimer)clearTimeout(chartResizeTimer);
  chartResizeTimer=setTimeout(()=>{
    redrawProfilerCharts();
    renderPerformanceTimeline();
    renderMemoryChart();
    redrawPlayerAnalyticsCharts();
    renderAdminDatabaseStorageGraph();
  },100);
});

function confidenceBadge(v){
  const x=String(v||'Low').toLowerCase();
  return `<span class="badge ${x}">${esc(v||'Low')}</span>`;
}

function renderDiagnosis(p){
  const d=p.diagnosticSummary||{};
  const smart=p.smartAnalysis||{};
  const state=smart.available?String(smart.state||'Watch'):String(d.state||'Disabled');
  const stateClass=state==='Critical'?'bad':state==='Investigate'?'orange':state==='Watch'?'warn':'good';
  const score=smart.available?Number(smart.healthScore||0):null;

  $('profDiagnosis').innerHTML=`
    <div class="card diagnosisMain">
      <div class="smartHero">
        ${score===null?'':`<div class="healthScore ${String(state).toLowerCase()}">${score}</div>`}
        <div>
          <div class="state ${stateClass}">${esc(state)}</div>
          <div><b>${esc(smart.primaryFinding||d.summary||'No diagnostic evidence yet.')}</b></div>
          <div class="small" style="margin-top:6px">${smart.available?`Finding confidence: ${esc(smart.primaryConfidence||'Low')} · Analysis confidence: ${esc(smart.analysisConfidence||'Low')} · data quality ${Number(smart.dataQualityScore||0)}/100 · ${esc(smart.recoveryState||'Unknown')}`:'Rolling five-minute correlation summary.'}</div>
        </div>
      </div>
    </div>
    <div class="card diagMetric"><div class="small">Worst delay</div><div class="value">${Number(d.worstDelayMs||0).toFixed(1)}ms</div></div>
    <div class="card diagMetric"><div class="small">CPU avg / max</div><div class="value">${Number(d.averageCpuPercent||0).toFixed(0)}% / ${Number(d.maxCpuPercent||0).toFixed(0)}%</div></div>
    <div class="card diagMetric"><div class="small">Gen2 GC</div><div class="value">+${Number(d.gen2Collections||0)}</div></div>
    <div class="card diagMetric"><div class="small">BL max queue</div><div class="value">${Number(d.maxBlockLoggerQueue||0).toLocaleString()}</div></div>
    <div class="card diagMetric"><div class="small">BL max writer</div><div class="value">${Number(d.maxBlockLoggerWriterMs||0)}ms</div></div>`;
}

function renderSmartAnalysis(p){
  const smart=p.smartAnalysis||{};
  const signals=smart.signals||[];
  const trends=smart.trends||[];
  const groups=smart.incidentGroups||[];
  const baseline=smart.baseline||{};

  $('smartFindingCount').textContent=smart.available?`${signals.length} finding(s)`:'not available';

  $('smartSignals').innerHTML=signals.length
    ? signals.slice(0,8).map(x=>{
        const sev=String(x.severity||'Watch').toLowerCase();
        return `<div class="card smartSignal ${sev}">
          <div class="signalMeta">
            <span class="badge ${String(x.confidence||'Low').toLowerCase()}">${esc(x.confidence||'Low')} confidence</span>
            <span class="${severityClass(x.severity)}"><b>${esc(x.severity)}</b></span>
            <span class="small">${esc(x.category)}</span>
          </div>
          <div class="signalTitle">${esc(x.title)}</div>
          <div class="small">${esc(x.evidence)}</div>
          <div class="nextAction"><b>Next:</b> ${esc(x.nextAction)}</div>
        </div>`;
      }).join('')
    : '<div class="empty">No strong smart finding currently stands out.</div>';

  const recs=smart.recommendations||[];
  $('smartRecommendations').innerHTML=recs.length
    ? `<ol style="margin:0;padding-left:20px">${recs.map(x=>`<li style="margin:0 0 8px">${esc(x)}</li>`).join('')}</ol>`
    : 'No targeted next step is currently required. Keep diagnostics running if the server is intermittently slow.';

  $('baselineSamples').textContent=baseline.sampleCount?`${baseline.sampleCount} learned sample(s)`:'learning';
  $('adaptiveBaseline').innerHTML=baseline.sampleCount
    ? `<div class="tableWrap"><table class="baselineTable">
        <thead><tr><th>Signal</th><th>Learned normal</th><th>Adaptive anomaly</th><th>Recent median</th></tr></thead>
        <tbody>
          <tr><td>Scheduler delay</td><td>${Number(baseline.delayMedianMs||0).toFixed(1)}ms</td><td>${Number(baseline.delayAnomalyMs||0).toFixed(1)}ms</td><td>${Number(smart.recentDelayMedianMs||0).toFixed(1)}ms</td></tr>
          <tr><td>CPU</td><td>${Number(baseline.cpuMedianPercent||0).toFixed(1)}%</td><td>${Number(baseline.cpuAnomalyPercent||0).toFixed(1)}%</td><td>${Number(smart.recentCpuMedianPercent||0).toFixed(1)}%</td></tr>
          <tr><td>Managed heap</td><td>${Number(baseline.heapMedianMb||0).toFixed(0)} MB</td><td>trend-based</td><td>${Number(smart.recentHeapMedianMb||0).toFixed(0)} MB</td></tr>
          <tr><td>Loaded entities</td><td>${Number(baseline.entityMedian||0).toFixed(0)}</td><td>jump/trend-based</td><td>${Number(smart.recentEntityMedian||0).toFixed(0)}</td></tr>
          <tr><td>BL queue</td><td>${Number(baseline.queueMedian||0).toFixed(0)}</td><td>${Number(baseline.queueAnomaly||0).toFixed(0)}</td><td>${Number(smart.recentQueueMedian||0).toFixed(0)}</td></tr>
          <tr><td>BL writer</td><td>${Number(baseline.writerMedianMs||0).toFixed(1)}ms</td><td>${Number(baseline.writerAnomalyMs||0).toFixed(1)}ms</td><td>${Number(smart.recentWriterMedianMs||0).toFixed(1)}ms</td></tr>
        </tbody>
      </table></div>`
    : 'The analyzer needs more samples before it can distinguish unusual behavior from this server’s normal background load.';

  $('smartTrends').innerHTML=trends.length
    ? trends.map(x=>`<div class="smartSignal ${String(x.severity||'Watch').toLowerCase()}" style="padding:9px 10px;margin-bottom:8px">
        <b>${esc(x.name)}</b> <span class="${severityClass(x.severity)}">${esc(x.severity)}</span><br>
        <span class="small">${Number(x.slopePerMinute||0)>=0?'+':''}${Number(x.slopePerMinute||0).toFixed(1)} ${esc(x.unit)} · net ${Number(x.netChange||0)>=0?'+':''}${Number(x.netChange||0).toFixed(1)} · ${esc(x.interpretation)}</span>
      </div>`).join('')
    : 'No meaningful sustained upward memory/entity/queue trend is currently detected.';

  $('incidentGroupCount').textContent=`${groups.length} grouped incident(s)`;
  if($('profClearLagGroups'))$('profClearLagGroups').disabled=!groups.length;
  $('incidentGroups').innerHTML=groups.length
    ? groups.map((x,i)=>`<tr class="clickableRow" data-incident-ts="${Number(x.startUnixMilliseconds||0)}" title="${esc(x.evidence)}">
        <td><b>${esc(new Date(Number(x.startUnixMilliseconds||0)).toLocaleTimeString())}</b></td>
        <td>${Number(x.durationSeconds||0).toFixed(0)}s</td>
        <td class="${severityClass(x.severity)}">${incidentDot(x.severity)}<b>${esc(x.severity)}</b></td>
        <td><b>${esc(x.primaryCategory)}</b></td>
        <td>${x.likelyModId?`<b>${esc(x.likelyModName||x.likelyModId)}</b><br><span class="small"><code>${esc(x.likelyModId)}</code> · ${esc(x.modConfidence||'Low')}</span>`:'<span class="muted">Not attributed</span>'}</td>
        <td>${confidenceBadge(x.confidence)}</td>
        <td>${Number(x.worstDelayMs||0).toFixed(0)}ms</td>
        <td>${Number(x.maxCpuPercent||0).toFixed(0)}%</td>
        <td>+${Number(x.gen2Collections||0)}</td>
        <td class="codeCell" title="${esc(x.nextAction)}">${esc(x.nextAction)}</td>
      </tr>`).join('')
    : '<tr><td colspan="10" class="muted">No grouped lag incidents in the selected diagnostic history.</td></tr>';

  document.querySelectorAll('[data-incident-ts]').forEach(row=>{
    row.onclick=()=>{
      const ts=Number(row.dataset.incidentTs||0);
      chartHoverTimestamp=ts;
      redrawProfilerCharts();
      setSection('performance',true);
      setTimeout(()=>openPerformanceIncident(ts),80);
    };
  });

  renderSavedBaselineComparison(smart,p);
}

function snapshotForBaseline(p){
  const smart=p.smartAnalysis||{};
  return {
    savedAt:Date.now(),
    healthScore:Number(smart.healthScore||0),
    state:smart.state||'Unknown',
    delayMedian:Number(smart.recentDelayMedianMs||0),
    cpuMedian:Number(smart.recentCpuMedianPercent||0),
    heapMedian:Number(smart.recentHeapMedianMb||0),
    entityMedian:Number(smart.recentEntityMedian||0),
    queueMedian:Number(smart.recentQueueMedian||0),
    writerMedian:Number(smart.recentWriterMedianMs||0),
    profileP95:Number((p.lastProfile||{}).p95TickMs||0),
    profileP99:Number((p.lastProfile||{}).p99TickMs||0),
    profileMax:Number((p.lastProfile||{}).maxTickMs||0),
    topMods:(p.modHotspots||[]).slice(0,10).map(x=>({
      modId:x.modId,
      totalMs:Number(x.totalMs||0),
      maxSingleMs:Number(x.maxSingleMs||0),
      share:Number(x.percentOfProfileTickTime||0),
      confidence:x.confidence
    }))
  };
}

function deltaCell(current,old,suffix='',lowerIsBetter=true){
  const delta=Number(current||0)-Number(old||0);
  const cls=Math.abs(delta)<0.01?'deltaNeutral':((lowerIsBetter?delta>0:delta<0)?'deltaUpBad':'deltaDownGood');
  return `<span class="${cls}">${delta>=0?'+':''}${delta.toFixed(Math.abs(delta)>=100?0:1)}${suffix}</span>`;
}

function renderSavedBaselineComparison(smart,p){
  if(!savedBaseline){
    $('baselineSavedAt').textContent='';
    $('baselineCompare').innerHTML='Press <b>Save Baseline</b> during a known-good period. The browser will remember it locally and compare later captures against it.';
    return;
  }

  $('baselineSavedAt').textContent='saved '+new Date(savedBaseline.savedAt).toLocaleString();
  const lp=p.lastProfile||{};
  $('baselineCompare').innerHTML=`<div class="tableWrap"><table>
    <thead><tr><th>Metric</th><th>Saved good</th><th>Current</th><th>Change</th></tr></thead>
    <tbody>
      <tr><td>Health score</td><td>${savedBaseline.healthScore}/100</td><td>${Number(smart.healthScore||0)}/100</td><td>${deltaCell(Number(smart.healthScore||0),savedBaseline.healthScore,'',false)}</td></tr>
      <tr><td>Delay median</td><td>${savedBaseline.delayMedian.toFixed(1)}ms</td><td>${Number(smart.recentDelayMedianMs||0).toFixed(1)}ms</td><td>${deltaCell(smart.recentDelayMedianMs,savedBaseline.delayMedian,'ms')}</td></tr>
      <tr><td>CPU median</td><td>${savedBaseline.cpuMedian.toFixed(1)}%</td><td>${Number(smart.recentCpuMedianPercent||0).toFixed(1)}%</td><td>${deltaCell(smart.recentCpuMedianPercent,savedBaseline.cpuMedian,'%')}</td></tr>
      <tr><td>Heap median</td><td>${savedBaseline.heapMedian.toFixed(0)} MB</td><td>${Number(smart.recentHeapMedianMb||0).toFixed(0)} MB</td><td>${deltaCell(smart.recentHeapMedianMb,savedBaseline.heapMedian,' MB')}</td></tr>
      <tr><td>Entities median</td><td>${savedBaseline.entityMedian.toFixed(0)}</td><td>${Number(smart.recentEntityMedian||0).toFixed(0)}</td><td>${deltaCell(smart.recentEntityMedian,savedBaseline.entityMedian,'')}</td></tr>
      <tr><td>BL queue median</td><td>${savedBaseline.queueMedian.toFixed(0)}</td><td>${Number(smart.recentQueueMedian||0).toFixed(0)}</td><td>${deltaCell(smart.recentQueueMedian,savedBaseline.queueMedian,'')}</td></tr>
      <tr><td>Profile P95</td><td>${savedBaseline.profileP95.toFixed(1)}ms</td><td>${Number(lp.p95TickMs||0).toFixed(1)}ms</td><td>${deltaCell(lp.p95TickMs,savedBaseline.profileP95,'ms')}</td></tr>
    </tbody>
  </table></div>`;
}

$('profSaveBaseline').onclick=()=>{
  if(!lastProfilerPayload || !(lastProfilerPayload.smartAnalysis||{}).available){
    toast('Smart Analysis needs collected samples before saving a baseline.','error');
    return;
  }
  savedBaseline=snapshotForBaseline(lastProfilerPayload);
  localStorage.setItem('nsu.smartBaseline',JSON.stringify(savedBaseline));
  renderSavedBaselineComparison(lastProfilerPayload.smartAnalysis||{},lastProfilerPayload);
  toast('Known-good baseline saved in this browser.','success');
};

$('profClearBaseline').onclick=()=>{
  savedBaseline=null;
  localStorage.removeItem('nsu.smartBaseline');
  if(lastProfilerPayload)renderSavedBaselineComparison(lastProfilerPayload.smartAnalysis||{},lastProfilerPayload);
  toast('Saved baseline cleared.');
};

let tickDebugRequestInFlight=false;
let tickDebugLastPayload=null;

function fmtRate(bytesPerSecond){
  const n=Number(bytesPerSecond||0);
  if(n>=1024*1024)return `${(n/1024/1024).toFixed(2)} MB/s`;
  if(n>=1024)return `${(n/1024).toFixed(1)} KB/s`;
  return `${n.toFixed(0)} B/s`;
}
function fmtBytesCompact(bytes){
  const n=Number(bytes||0);
  if(n>=1024*1024*1024)return `${(n/1024/1024/1024).toFixed(2)} GB`;
  if(n>=1024*1024)return `${(n/1024/1024).toFixed(1)} MB`;
  if(n>=1024)return `${(n/1024).toFixed(1)} KB`;
  return `${n.toFixed(0)} B`;
}
function tickDebugMetric(label,value,state='good',sub=''){
  return `<div class="metric ${state}"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div>${sub?`<div class="small">${esc(sub)}</div>`:''}</div>`;
}
function renderTickDebug(d){
  tickDebugLastPayload=d||{};
  const enabled=d.enabled!==false;
  const slow=d.slowTickCapture||{},last=d.lastAction||{},prof=d.profiler||{},diag=prof.diagnosticSummary||{},attr=d.modAttribution||{};
  const delay=Number(d.currentMainThreadDelayMs||0),budget=Number(d.tickBudgetMs||0);
  const delayState=budget>0&&delay>budget?'bad':delay>Math.max(20,budget*.5)?'warn':'good';
  $('tickDebugMetrics').innerHTML=
    tickDebugMetric('Tick budget',`${budget.toFixed(0)} ms`,'good','Configured server TickTime')+
    tickDebugMetric('Main-thread delay',`${delay.toFixed(1)} ms`,delayState,'Lightweight scheduler sample')+
    tickDebugMetric('Network out',fmtRate(d.sendBytesPerSecond),'good',`${fmtBytesCompact(d.totalSentBytes)} total`)+
    tickDebugMetric('Network in',fmtRate(d.receiveBytesPerSecond),'good',`${fmtBytesCompact(d.totalReceivedBytes)} total`)+
    tickDebugMetric('Loaded entities',Number(d.loadedEntities||0).toLocaleString(),Number(d.loadedEntities||0)>5000?'warn':'good')+
    tickDebugMetric('Loaded chunks',Number(d.loadedChunks||0).toLocaleString(),'good');
  const state=slow.running
    ? `${slow.incidentCapture?'Incident capture':'Slow-tick capture'} running · ≥${Number(slow.thresholdMs||0)}ms · ${Number(slow.remainingSeconds||0)}s remaining`
    : 'No native slow-tick capture is running.';
  $('tickDebugState').textContent=state;
  const safeMode=!!d.safeDiagnosticsMode;
  setNavStatus('tickDebug',enabled?'good':'neutral',enabled?'Tick Debugging enabled':'Tick Debugging disabled');
  if($('tickDebugNavState')){$('tickDebugNavState').textContent=enabled?'ON':'OFF';$('tickDebugNavState').className='navInlineState '+(enabled?'good':'neutral');}
  if($('tickDebugEnabledToggle')){$('tickDebugEnabledToggle').textContent=enabled?'Tick Debugging: ON':'Tick Debugging: OFF';$('tickDebugEnabledToggle').className=enabled?'primary':'warnButton';$('tickDebugEnabledToggle').disabled=currentSessionRole==='ReadOnly';}
  $('tickDebugStart').disabled=!enabled||!!slow.running||safeMode;
  $('tickDebugIncident').disabled=!enabled||!!slow.running||!!prof.running||!prof.enabled||safeMode;
  $('tickDebugEnableDiagnostics').style.display=prof.enabled?'none':'';
  $('tickDebugEnableDiagnostics').disabled=!enabled;
  $('tickDebugStop').disabled=!slow.running;
  $('tickDebugDump').disabled=!enabled||safeMode;
  $('tickDebugHandlers').disabled=!enabled;
  $('tickDebugMainThread').disabled=!enabled;
  $('tickDebugProfileState').textContent=safeMode?'Safe Diagnostics Mode is enabled: heavy captures, automatic attribution bursts, and detailed dumps are locked.':(!prof.enabled?'Lightweight profiler diagnostics are disabled. Enable them before using Incident Capture.':(prof.running?`Engine profile running · ${Number(prof.remainingSeconds||0)}s remaining`:(d.lastIncidentSummary||'Engine profiler idle.')));
  const attrHost=$('tickDebugModAttribution');
  if(attrHost){
    attrHost.innerHTML=attr.available
      ? `<div class="cardHeader"><div><h3>Likely Mod Attribution</h3><div class="small">Latest ${esc(attr.profileKind||'engine')} profile · ${attr.profileCompletedUnixMilliseconds?esc(new Date(Number(attr.profileCompletedUnixMilliseconds)).toLocaleString()):''}</div></div><div class="spacer"></div>${confidenceBadge(attr.confidence||'Low')}<button id="tickDebugClearAttribution" class="miniClear" title="Clear retained mod-attribution results">Clear</button></div><div style="font-size:22px;font-weight:850">${esc(attr.modName||attr.modId)}</div><div class="small"><code>${esc(attr.modId||'')}</code> · ${Number(attr.tickSharePercent||0).toFixed(1)}% of profiled tick time · max segment ${Number(attr.maxSegmentMs||0).toFixed(1)}ms · ${Number(attr.slowSegments||0)} segment(s) ≥10ms</div><div class="compactNote" style="margin-top:8px">${esc(attr.note||'')}</div><div class="small" style="margin-top:6px"><b>Top marker:</b> <code>${esc(attr.topMarker||'')}</code></div>${Number(attr.worstProfileTickMs||0)>0?`<div class="compactNote" style="margin-top:8px"><b>Worst profiled tick:</b> ${Number(attr.worstProfileTickMs||0).toFixed(1)}ms<br><span class="small">${esc(attr.worstProfileTickTopCauses||'No per-tick cause summary available.')}</span></div>`:''}`
      : `<div class="cardHeader"><div><h3>Likely Mod Attribution</h3><div class="small">Measured engine-profiler ownership only.</div></div><div class="spacer"></div><button id="tickDebugClearAttribution" class="miniClear" title="Clear retained mod-attribution results">Clear</button></div><div class="empty">${esc(attr.note||'No strong mod attribution is available yet. Run Incident Capture during the slowdown.')}</div>`;
    if($('tickDebugClearAttribution'))$('tickDebugClearAttribution').onclick=()=>clearProfilerList('mods',true);
  }
  $('tickDebugActionOutput').textContent=last.output||'No native debug command has been run from this page yet.';
  $('tickDebugSlowOutput').textContent=slow.lastExcerpt||'No slow-tick capture has completed yet.';
  $('tickDebugLogPath').textContent=slow.logPath||'Current server log path will appear when a capture starts.';
  if($('tickDebugClearAction'))$('tickDebugClearAction').disabled=!String(last.output||'').trim();
  if($('tickDebugClearSlow'))$('tickDebugClearSlow').disabled=!String(slow.lastExcerpt||'').trim()&&!String(d.lastIncidentSummary||'').trim();
  $('tickDebugStatus').textContent=`Updated ${new Date().toLocaleTimeString()} · CPU ${Number(d.cpuPercent||0).toFixed(0)}% · ${Number(d.players||0)} player(s) · lag markers are clickable in Performance/Profiler graphs`;
}
async function loadTickDebug(showLoading=true){
  if(tickDebugRequestInFlight)return;
  tickDebugRequestInFlight=true;
  if(showLoading&&$('tickDebugStatus'))$('tickDebugStatus').textContent='Loading native tick diagnostics…';
  try{renderTickDebug(await api('/api/tick-debug'));}
  catch(e){if($('tickDebugStatus'))$('tickDebugStatus').textContent=e.message;}
  finally{tickDebugRequestInFlight=false;}
}
async function startTickDebugCapture(incident=false){
  const threshold=clamp(Number($('tickDebugThreshold').value||100),20,1000);
  const duration=clamp(Number($('tickDebugDuration').value||30),5,incident?30:120);
  const endpoint=incident?'/api/tick-debug/incident':'/api/tick-debug/slow-start';
  try{
    const r=await api(endpoint,{method:'POST',body:JSON.stringify({thresholdMs:threshold,durationSeconds:duration})});
    toast(r.message||'Native tick capture started.','success');
    await loadTickDebug(false);
  }catch(e){toast(e.message,'error');}
}
async function stopTickDebugCapture(){
  try{const r=await api('/api/tick-debug/slow-stop',{method:'POST',body:'{}'});toast(r.message||'Capture stopped.','success');await loadTickDebug(false);}catch(e){toast(e.message,'error');}
}
async function runTickDebugAction(action){
  try{
    const r=await api('/api/tick-debug/action',{method:'POST',body:JSON.stringify({action})});
    toast(r.message||'Native debug command completed.','success');
    await loadTickDebug(false);
  }catch(e){toast(e.message,'error');await loadTickDebug(false);}
}

