function profilerPointsForRange(){
  if(profilerRangeSeconds<=60)return 120;
  if(profilerRangeSeconds<=300)return 240;
  if(profilerRangeSeconds<=900)return 300;
  return 360;
}

function setRange(seconds){
  profilerRangeSeconds=clamp(Number(seconds)||300,60,1800);
  localStorage.setItem('nsu.profilerRange',String(profilerRangeSeconds));
  document.querySelectorAll('#rangeButtons button').forEach(btn=>btn.classList.toggle('active',Number(btn.dataset.range)===profilerRangeSeconds));
  chartHoverTimestamp=null;
  loadProfiler(true);
}
document.querySelectorAll('#rangeButtons button').forEach(btn=>btn.onclick=()=>setRange(btn.dataset.range));

async function loadProfiler(showLoading=true){
  if(profilerRequestInFlight)return;
  profilerRequestInFlight=true;
  if(showLoading)$('profState').textContent='Loading diagnostics…';

  try{
    const q=new URLSearchParams({window:String(profilerRangeSeconds),points:String(profilerPointsForRange())});
    const p=await api('/api/profiler?'+q);
    lastProfilerPayload=p;
    $('profState').textContent=p.profileRunning
      ? `Engine profile running · about ${p.profileRemainingSeconds}s remaining`
      : (p.enabled?`Diagnostics enabled · graph window ${Math.round(profilerRangeSeconds/60)}m`:'Diagnostics disabled');

    renderDiagnosis(p);
    renderSmartAnalysis(p);
    redrawProfilerCharts();

    $('profMods').innerHTML=(p.modHotspots||[]).length
      ? (p.modHotspots||[]).slice(0,18).map(x=>`<tr class="${x.modId&&x.modId!=='<unattributed>'?'clickableRow':''}" ${x.modId&&x.modId!=='<unattributed>'?`data-mod-id="${esc(x.modId)}"`:''}><td><b>${esc(x.modId||'unattributed')}</b></td><td>${Number(x.totalMs||0).toFixed(1)}ms</td><td>${Number(x.maxSingleMs||0).toFixed(1)}ms</td><td>${Number(x.slowSegments||0)}</td><td>${Number(x.percentOfProfileTickTime||0).toFixed(1)}%</td><td>${confidenceBadge(x.confidence)}</td></tr>`).join('')
      : '<tr><td colspan="6" class="muted">Run Profile 10s or Profile 30s to generate per-mod attribution.</td></tr>';
    if($('profClearMods'))$('profClearMods').disabled=!(p.modHotspots||[]).length;

    document.querySelectorAll('[data-mod-id]').forEach(row=>{
      row.onclick=()=>openModFilter(row.dataset.modId||'');
    });

    $('profTicks').innerHTML=(p.profileSlowTicks||[]).length
      ? (p.profileSlowTicks||[]).slice(0,15).map(x=>`<tr><td class="bad"><b>${Number(x.tickMs||0).toFixed(1)}ms</b></td><td class="codeCell" title="${esc(x.topCauseSummary)}">${esc(x.topCauseSummary)}</td></tr>`).join('')
      : '<tr><td colspan="2" class="muted">No ≥50ms ticks captured in the latest engine profile.</td></tr>';
    if($('profClearTicks'))$('profClearTicks').disabled=!(p.profileSlowTicks||[]).length;

    const incidents=p.diagnosticIncidents||[];
    $('incidentCount').textContent=`${incidents.length} event(s) in selected range`;
    if($('profClearLagSamples'))$('profClearLagSamples').disabled=!incidents.length;
    $('profIncidents').innerHTML=incidents.length
      ? incidents.slice(0,40).map(x=>{
          const entityDelta=Number(x.entityDelta||0),chunkDelta=Number(x.chunkDelta||0);
          return `<tr class="clickableRow" data-prof-lag="${Number(x.unixMilliseconds||0)}" data-prof-lag-index="${incidents.indexOf(x)}">
            <td><b>${esc(new Date(Number(x.unixMilliseconds||0)).toLocaleTimeString())}</b></td>
            <td class="${severityClass(x.severity)}">${incidentDot(x.severity)}<b>${esc(x.severity)}</b></td>
            <td>${Number(x.delayMs||0).toFixed(0)}ms</td>
            <td>${Number(x.cpuPercent||0).toFixed(0)}%</td>
            <td>+${Number(x.gen0Delta||0)}/+${Number(x.gen1Delta||0)}/+${Number(x.gen2Delta||0)}</td>
            <td>${Number(x.blockLoggerQueue||0).toLocaleString()} / ${Number(x.blockLoggerWriterMs||0)}ms</td>
            <td>${Number(x.loadedEntities||0).toLocaleString()} (${entityDelta>=0?'+':''}${entityDelta})</td>
            <td>${Number(x.loadedChunks||0).toLocaleString()} (${chunkDelta>=0?'+':''}${chunkDelta})</td>
            <td class="codeCell" title="${esc(x.evidence)}">${esc(x.evidence)}</td>
          </tr>`;
        }).join('')
      : '<tr><td colspan="9" class="muted">No correlated lag events recorded in the selected graph range.</td></tr>';

    document.querySelectorAll('[data-prof-lag-index]').forEach(row=>{
      row.onclick=()=>{
        const x=incidents[Number(row.dataset.profLagIndex||0)]||{};
        openLagIncidentDrawer(Number(x.unixMilliseconds||0));
      };
    });
  }catch(e){
    $('profState').textContent=e.message;
    toast(e.message,'error');
  }finally{
    profilerRequestInFlight=false;
  }
}

