  if($('acConnectionTimeline'))$('acConnectionTimeline').innerHTML=acTimelineHtml(list.map(x=>({utc:x.utc,title:`${x.playerName||'Player'} · ${x.stage||'Connection'} · ${x.code||x.action||'event'}`,detail:x.detail||'',meta:`${x.action||'Observe'} · status ${x.status||'—'} · client ${x.clientInstalled?(x.clientVersion||'connected'):'not handshaken'}`,action:x.action,code:x.code})),24);
