  if($('acModDbHealthGrid'))$('acModDbHealthGrid').innerHTML=metric('Server startup baseline',baseTotal?`${baseFresh}/${baseTotal} fresh`:'No eligible server mods',baseTotal?(baseReady?'good':'warn'):'')+metric('Baseline pending',basePending,basePending?'warn':'good')+metric('Baseline resolved',baseResolved,baseResolved?'good':'')+metric('Baseline not on DB',baseNotFound,baseNotFound?'':'good')+metric('Baseline unavailable',baseUnavailable,baseUnavailable?'warn':'good')+metric('Server = official',baseOfficial,baseOfficial?'good':'')+metric('Custom server builds',baseCustom,baseCustom?'warn':'good')+metric('Server package diagnostics',baseDiagnostic,baseDiagnostic?'warn':'good')+metric('Baseline queued',x.serverBaselineLastQueuedUtc?acRelativeAge(x.serverBaselineLastQueuedUtc).text:'—',x.serverBaselineLastQueuedUtc?'good':'')+metric('Cache entries',Number(x.cacheEntries||0))+metric('Fresh',Number(x.fresh||0),'good')+metric('Stale',Number(x.stale||0),Number(x.stale||0)?'warn':'')+metric('Resolved',Number(x.resolved||0),'good')+metric('Not on DB',Number(x.notFound||0))+metric('Unavailable',Number(x.unavailable||0),Number(x.unavailable||0)?'warn':'good')+metric('Pending',Number(x.pending||0),Number(x.pending||0)?'warn':'')+metric('Last resolved',x.lastResolvedUtc?acRelativeAge(x.lastResolvedUtc).text:'—',x.lastResolvedUtc?'good':'');
