  const unique=new Set(all.map(x=>`${String(x.mod.modId||'').toLowerCase()}@${String(x.mod.version||'').toLowerCase()}`));
  const modified=all.filter(x=>x.state.key==='modified').length;
  const diagnostic=all.filter(x=>x.state.key==='diagnostic').length;
  const approvedCustom=all.filter(x=>x.state.key==='approved').length;
  const pending=all.filter(x=>x.state.key==='pending').length;
  const unavailable=all.filter(x=>x.state.key==='unavailable'||!x.player.packageMetricsSupported).length;
