    const modId=String(x.mod.modId||'').toLowerCase(),version=String(x.mod.version||'').toLowerCase();
    const releaseKey=`${modId}@${version}`;
    const fingerprint=String(x.mod.contentSha256||x.mod.sha256||'').toLowerCase()||'unavailable';
    const key=`${releaseKey}|${fingerprint}`;
    if(!clusters.has(key))clusters.set(key,{modId:x.mod.modId||'',version:x.mod.version||'',fingerprint,rows:[],states:[]});
    const c=clusters.get(key);c.rows.push(x);c.states.push(x.state);
    if(!releaseFingerprints.has(releaseKey))releaseFingerprints.set(releaseKey,new Set());
