const suiteNativeCheckedDescriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'checked');
function suiteLinkedLabel(cb){
  if(!cb?.id)return null;
  const safeId=window.CSS&&typeof CSS.escape==='function'?CSS.escape(cb.id):cb.id.replace(/([\"'\[\]#. :>+~*^$|=()])/g,'\\$1');
  return document.querySelector(`label[for="${safeId}"]`);
}
function syncSuiteSwitchState(cb){
  if(!cb?.classList?.contains('suiteSwitchInput'))return;
  const on=!!cb.checked;
  cb.setAttribute('aria-checked',on?'true':'false');
  const track=cb.nextElementSibling?.classList.contains('suiteSwitchTrack')?cb.nextElementSibling:null;
  if(track){
    track.classList.toggle('isOn',on);
    track.dataset.state=on?'on':'off';
    track.setAttribute('aria-label',on?'On':'Off');
  }
  const wrappingLabel=cb.parentElement?.tagName==='LABEL'?cb.parentElement:null;
  const linkedLabel=suiteLinkedLabel(cb);
  wrappingLabel?.classList.toggle('switchOn',on);
  linkedLabel?.classList.toggle('switchOn',on);
}
function bindSuiteSwitchState(cb){
  if(cb.dataset.suiteSwitchStateBound)return;
  const sync=()=>syncSuiteSwitchState(cb);
  cb.addEventListener('change',sync);
  cb.addEventListener('input',sync);
  if(suiteNativeCheckedDescriptor?.get&&suiteNativeCheckedDescriptor?.set){
    try{
      Object.defineProperty(cb,'checked',{
        configurable:true,
        enumerable:!!suiteNativeCheckedDescriptor.enumerable,
        get(){return suiteNativeCheckedDescriptor.get.call(this);},
        set(value){suiteNativeCheckedDescriptor.set.call(this,value);syncSuiteSwitchState(this);}
      });
    }catch{}
  }
  cb.dataset.suiteSwitchStateBound='1';
}
function syncAllSuiteSwitches(root=document){
  const scope=root?.querySelectorAll?root:document;
  if(root?.matches?.('input.suiteSwitchInput'))syncSuiteSwitchState(root);
  scope.querySelectorAll('input.suiteSwitchInput').forEach(syncSuiteSwitchState);
}
function enhanceToggleSwitches(root=document){
  const scope=root?.querySelectorAll?root:document;
  const boxes=[];
  if(root?.matches?.('input[type="checkbox"]'))boxes.push(root);
  boxes.push(...scope.querySelectorAll('input[type="checkbox"]'));
  boxes.forEach(cb=>{
    const wrappingLabel=cb.parentElement?.tagName==='LABEL'?cb.parentElement:null;
    const linkedLabel=suiteLinkedLabel(cb);
    const forced=cb.matches('[data-field="enabled"],.discordRouteEnabled');
    const label=wrappingLabel||linkedLabel;
    if(!label&&!forced)return; // multi-select/compare checkboxes remain normal checkboxes

    cb.setAttribute('role','switch');
    cb.classList.add('suiteSwitchInput');

    if(!cb.nextElementSibling?.classList.contains('suiteSwitchTrack')){
      const track=document.createElement('span');
      track.className='suiteSwitchTrack';
      track.setAttribute('aria-hidden','true');
      cb.insertAdjacentElement('afterend',track);
      if(!wrappingLabel){
        track.addEventListener('click',e=>{e.preventDefault();if(!cb.disabled){cb.click();cb.focus();}});
      }
    }

    if(wrappingLabel){
      const wasBlock=wrappingLabel.style.display==='block'||getComputedStyle(wrappingLabel).display==='block';
      wrappingLabel.classList.add('switchToggle');
      if(wasBlock)wrappingLabel.classList.add('switchBlock');
    }else if(linkedLabel){
      linkedLabel.classList.add('linkedSwitchLabel');
    }else{
      cb.parentElement?.classList.add('switchCell');
    }

    bindSuiteSwitchState(cb);
    syncSuiteSwitchState(cb);
  });
}
let suiteSwitchObserver=null;
function initToggleSwitchObserver(){
  suiteSwitchObserver?.disconnect();
  suiteSwitchObserver=new MutationObserver(muts=>{
    muts.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===Node.ELEMENT_NODE)enhanceToggleSwitches(n);}));
  });
  suiteSwitchObserver.observe(document.body,{subtree:true,childList:true});
  document.addEventListener('reset',()=>setTimeout(()=>syncAllSuiteSwitches(),0),true);
}
