function panelAccountRoleLabel(role){return role==='ReadOnly'?'Read Only':(role||'Administrator');}

async function loadWebAccounts(showLoading=true){
  if(!currentSessionOwner){if($('webAccountsCard'))$('webAccountsCard').style.display='none';return;}
  if($('webAccountsCard'))$('webAccountsCard').style.display='block';
  if(showLoading)$('webAccountRows').innerHTML='<tr><td colspan="6" class="muted">Loading accounts…</td></tr>';
  try{
    const d=await api('/api/web/accounts');
    const owner=d.owner||{};
    const rows=d.accounts||[];
    $('webAccountCount').textContent=`${rows.length} / ${Number(d.maximum||50)} additional`;
    $('webOwnerAccount').innerHTML=`<b>${esc(owner.username||'admin')}</b> <span class="badge low">Owner</span> · ${owner.passwordConfigured?'password configured':'<span class="warn">password not configured</span>'}<br><span class="small">The Owner account is managed with <code>/serverutils web username</code> and <code>/serverutils web password</code> and cannot be deleted here.</span>`;
    $('webAccountRows').innerHTML=rows.length?rows.map(a=>{
      const created=Number(a.createdUnixMilliseconds||0);
      const last=Number(a.lastLoginUnixMilliseconds||0);
      const locked=!!a.locked;
      const state=!a.enabled?'<span class="badge muted">Disabled</span>':locked?'<span class="badge high">Locked</span>':'<span class="badge low">Enabled</span>';
      const login=last?`${esc(new Date(last).toLocaleString())}${a.lastLoginRemote?`<div class="small">${esc(a.lastLoginRemote)}</div>`:''}`:'Never';
      const role=a.role||'Administrator';
      return `<tr>
        <td><b>${esc(a.username||'')}</b></td>
        <td>${esc(panelAccountRoleLabel(role))}</td>
        <td>${state}</td>
        <td>${created?esc(new Date(created).toLocaleString()):'—'}</td>
        <td>${login}</td>
        <td><div class="rowActions">
          <button class="iconBtn" data-webacct-toggle="${esc(a.id)}" data-enabled="${a.enabled?'1':'0'}">${a.enabled?'Disable':'Enable'}</button>
          <button class="iconBtn" data-webacct-role="${esc(a.id)}" data-role="${esc(role)}">${role==='ReadOnly'?'Make Admin':'Make Read Only'}</button>
          ${locked?`<button class="iconBtn" data-webacct-unlock="${esc(a.id)}">Unlock</button>`:''}
          <button class="iconBtn" data-webacct-reset-select="${esc(a.id)}">Reset Password</button>
          <button class="iconBtn danger" data-webacct-delete="${esc(a.id)}" data-name="${esc(a.username||'')}">Delete</button>
        </div></td>
      </tr>`;
    }).join(''):'<tr><td colspan="6" class="muted">No additional panel accounts. The Owner account is still active.</td></tr>';
    $('webAccountResetUser').innerHTML='<option value="">Select account…</option>'+rows.map(a=>`<option value="${esc(a.id)}">${esc(a.username||'')}</option>`).join('');

    document.querySelectorAll('[data-webacct-toggle]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctToggle,b.dataset.enabled==='1'?'disable':'enable'));
    document.querySelectorAll('[data-webacct-role]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctRole,'role',b.dataset.role==='ReadOnly'?'Administrator':'ReadOnly'));
    document.querySelectorAll('[data-webacct-unlock]').forEach(b=>b.onclick=()=>webAccountAction(b.dataset.webacctUnlock,'unlock'));
    document.querySelectorAll('[data-webacct-reset-select]').forEach(b=>b.onclick=()=>{$('webAccountResetUser').value=b.dataset.webacctResetSelect||'';$('webAccountResetPassword').focus();});
    document.querySelectorAll('[data-webacct-delete]').forEach(b=>b.onclick=()=>{if(confirm(`Delete panel account ${b.dataset.name||''}? Any active sessions for that user will be signed out.`))webAccountAction(b.dataset.webacctDelete,'delete');});
  }catch(e){$('webAccountRows').innerHTML=`<tr><td colspan="6" class="bad">${esc(e.message)}</td></tr>`;}
}

async function createWebAccount(){
  const username=$('webAccountUsername').value.trim();
  const password=$('webAccountPassword').value;
  const role=$('webAccountRole').value;
  if(!username||password.length<10){toast('Enter a valid username and a password of at least 10 characters.','error');return;}
  try{
    const d=await api('/api/web/accounts/create',{method:'POST',body:JSON.stringify({username,password,role})});
    $('webAccountUsername').value='';$('webAccountPassword').value='';
    toast(d.message||'Panel account created.','success');
    await loadWebAccounts(false);
  }catch(e){toast(e.message,'error');}
}

async function webAccountAction(id,action,value='',password=''){
  if(!id)return;
  try{
    const d=await api('/api/web/accounts/action',{method:'POST',body:JSON.stringify({id,action,value,password})});
    toast(d.message||'Panel account updated.','success');
    await loadWebAccounts(false);
  }catch(e){toast(e.message,'error');}
}

async function resetWebAccountPassword(){
  const id=$('webAccountResetUser').value;
  const password=$('webAccountResetPassword').value;
  if(!id){toast('Select an account first.','error');return;}
  if(password.length<10){toast('The new password must be at least 10 characters.','error');return;}
  await webAccountAction(id,'password','',password);
  $('webAccountResetPassword').value='';
}

$('webAccountsRefresh').onclick=()=>loadWebAccounts(true);
$('webAccountCreate').onclick=createWebAccount;
$('webAccountResetPasswordBtn').onclick=resetWebAccountPassword;

const featureGateLabels={
  blocklogger:'BlockLogger audit/storage', ingamegui:'In-game admin GUI', admin:'Administration', anticheat:'Anti-Cheat server', afk:'AFK Mode',
  animallimiter:'Animal Limiter', loginprotection:'Login Protection', webdashboard:'Web Dashboard', webconsole:'Web Console', webmap:'Web Map',
  announcements:'Announcements', reports:'Reports & Tickets', analytics:'Player Analytics', diagnostics:'Profiler / Diagnostics',
  modupdates:'Mod Update Checker', logintelligence:'Log Intelligence', performancecenter:'Performance Center', operationscenter:'Operations Center'
};

async function loadFeatureGates(){
  if(!$('featureGateRows'))return;
  $('featureGateRows').innerHTML='<div class="empty">Loading feature gates…</div>';
  try{
    const d=await api('/api/features');
    const rows=d.features||[];
    const activeMap=Object.fromEntries((d.activeFeatures||[]).map(x=>[String(x.name||''),!!x.enabled]));
    $('featureGateRows').innerHTML=rows.map(f=>{
      const name=String(f.name||'');
      const enabled=!!f.enabled;
      const active=Object.prototype.hasOwnProperty.call(activeMap,name)?activeMap[name]:enabled;
      const pending=active!==enabled;
      const label=featureGateLabels[name]||name;
      const disabled=currentSessionRole==='ReadOnly'?'disabled':'';
      const stateText=pending?`${active?'ON':'OFF'} → ${enabled?'ON':'OFF'}`:(enabled?'ON':'OFF');
      const stateClass=pending?'warn':(enabled?'low':'muted');
      const pendingText=pending?'<div class="small warn" style="margin:0 0 10px">Pending restart</div>':'';
      return `<div class="card" style="padding:12px"><div class="cardHeader"><b>${esc(label)}</b><span class="badge ${stateClass}">${stateText}</span></div><div class="small" style="margin:6px 0 10px">${esc(name)}</div>${pendingText}<button data-feature-gate="${esc(name)}" data-enabled="${enabled?'1':'0'}" ${disabled}>${enabled?'Turn Off':'Turn On'}</button></div>`;
    }).join('')||'<div class="empty">No feature gates returned.</div>';
    document.querySelectorAll('[data-feature-gate]').forEach(b=>b.onclick=()=>setFeatureGate(b.dataset.featureGate,b.dataset.enabled!=='1'));
  }catch(e){$('featureGateRows').innerHTML=`<div class="bad">${esc(e.message)}</div>`;}
}

async function setFeatureGate(feature,enabled){
  if(!feature)return;
  const action=enabled?'enable':'disable';
  if(!confirm(`${action[0].toUpperCase()+action.slice(1)} ${feature}? The change takes full effect after a server restart.`))return;
  try{
    const d=await api('/api/features',{method:'POST',body:JSON.stringify({feature,enabled})});
    toast(d.message||'Feature gate saved. Restart required.','success');
    await loadFeatureGates();
  }catch(e){toast(e.message,'error');}
}

$('featureGatesRefresh').onclick=()=>loadFeatureGates();

function roleColorMapToText(map){
  return Object.entries(map||{}).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))).map(([role,color])=>`${role}=${color}`).join('\n');
}
function parseRoleColorMap(text){
  const out={};
  for(const raw of String(text||'').split(/\r?\n/)){
    const line=raw.trim(); if(!line)continue;
    const eq=line.indexOf('='); if(eq<=0)continue;
    const role=line.slice(0,eq).trim(); let color=line.slice(eq+1).trim();
    if(!role||role.length>64)continue;
    if(!color.startsWith('#'))color='#'+color;
    if(!/^#[0-9a-f]{6}$/i.test(color))continue;
    out[role]=color.toUpperCase();
    if(Object.keys(out).length>=64)break;
  }
  return out;
}
function renderChatDisplayRoleColorPreview(){
  const target=$('chatDisplayRoleColorPreview'); if(!target)return;
  const map=parseRoleColorMap($('chatDisplayRoleColors')?.value||'');
  const entries=Object.entries(map);
  target.innerHTML=entries.length?entries.map(([role,color])=>`<span style="display:inline-flex;align-items:center;gap:5px;margin:2px 12px 2px 0"><span style="width:10px;height:10px;border-radius:50%;background:${esc(color)};display:inline-block"></span><b style="color:${esc(color)}">${esc(role)}</b> <code>${esc(color)}</code></span>`).join(''):'No custom role colors configured.';
}

async function loadPlayerListConfig(){
  try{
    const d=await api('/api/playerlist/config');
    $('playerListServerName').value=String(d.serverName||'');
    const opacity=Math.max(30,Math.min(95,Number(d.backgroundOpacityPercent||72)));
    $('playerListOpacity').value=String(opacity);
    $('playerListOpacityValue').textContent=`${opacity}%`;
    const scale=Math.max(80,Math.min(135,Math.round(Number(d.layoutScale||1)*100)));
    $('playerListScale').value=String(scale);
    $('playerListScaleValue').textContent=`${(scale/100).toFixed(2)}×`;
    $('playerListAccent').value=/^#[0-9a-f]{6}$/i.test(String(d.accentHex||''))?String(d.accentHex):'#d6ae63';
    $('playerListAlignment').value=String(d.alignment||'CenterTop');
    $('playerListOffsetX').value=String(Number(d.offsetX||0));
    $('playerListOffsetY').value=String(Number(d.offsetY??22));
    $('playerListRowsPerColumn').value=String(Number(d.rowsPerColumn||8));
    $('playerListMaxColumns').value=String(Number(d.maxColumns||4));
    $('playerListShowRoles').checked=d.showRoles!==false;
    $('playerListShowPing').checked=d.showPing!==false;
    $('playerListShowSession').checked=d.showSessionTime!==false;
    $('playerListShowInitials').checked=d.showPlayerInitials!==false;
    $('playerListShowCapacity').checked=d.showCapacityBar!==false;
    $('playerListShowHeaders').checked=!!d.showColumnHeaders;
    $('playerListCompactRows').checked=!!d.compactRows;
    $('playerListShowPingBars').checked=d.showPingBars!==false;
    $('playerListShowFooter').checked=!!d.showFooterHint;
    $('playerListReservedEnabled').checked=!!d.reservedSlotsEnabled;
    $('playerListReservedCount').value=String(Number(d.reservedSlots||0));
    $('playerListReservedCount').max=String(Math.max(0,Number(d.maxClients||256)));
    $('playerListReservedRoles').value=Array.isArray(d.reservedSlotRoles)?d.reservedSlotRoles.join('\n'):'';
    $('playerListReservedMessage').value=String(d.reservedSlotsFullMessage||'Only reserved slots are left on this server.');
    const roleList=Array.isArray(d.configuredRoles)?d.configuredRoles:[];
    $('playerListConfiguredRoles').innerHTML=roleList.length?`Server roles: ${roleList.map(r=>`<code>${esc(r.code||r.name||'')}</code>${r.name&&r.name!==r.code?` (${esc(r.name)})`:''}`).join(' · ')}`:'No server roles reported.';
    const maxClients=Number(d.maxClients||0),publicLimit=Number(d.publicSlotLimit||maxClients),publicOnline=Number(d.publicOnline||0),reservedOnline=Number(d.reservedEligibleOnline||0),rejects=Number(d.reservedSlotRejections||0);
    $('playerListReservedState').textContent=d.reservedSlotsEnabled?`ON · ${Number(d.reservedSlots||0)} reserved`:'OFF';
    $('playerListReservedSummary').innerHTML=[
      ['Server capacity',maxClients,`${publicLimit} public · ${Number(d.reservedSlots||0)} reserved`],
      ['Public players',publicOnline,`${Math.max(0,publicLimit-publicOnline)} public slot(s) remaining`],
      ['Reserved-role players',reservedOnline,'Players whose role may use reserved capacity'],
      ['Rejected joins',rejects,'Non-reserved joins rejected since server start']
    ].map(x=>`<div class="card"><div class="metricLabel">${esc(x[0])}</div><div class="metricValue" style="font-size:18px">${esc(x[1])}</div><div class="small">${esc(x[2])}</div></div>`).join('');
    $('playerListDebugLogging').checked=!!d.debugLogging;
    $('playerListEffectiveName').textContent=`Effective header: ${d.effectiveServerName||'(unnamed server)'} · Config: ${d.configFile||'NewfiesPlayerList.json'} · Schema ${Number(d.configSchemaVersion||6)} · Style ${Number(d.styleVersion||5)}`;
    $('playerListConfigState').textContent=d.available?'Backend ready':'Backend unavailable';

    const requests=Number(d.requestsReceived||0),responses=Number(d.responsesSent||0),throttled=Number(d.requestsThrottled||0);
    const buildFailures=Number(d.requestBuildFailures||0),sendFailures=Number(d.responseSendFailures||0);
    const snapshotAge=Number(d.cachedSnapshotAgeMs??-1);
    const responseGap=Math.max(0,requests-responses-throttled);
    const debugItems=[
      ['Backend',d.available?'READY':'UNAVAILABLE',d.available?'PlayerList service is registered':'PlayerList service is not running'],
      ['Network channel',d.backendChannel||'newfies-public-playerlist-v1',`Protocol ${Number(d.protocolVersion||1)} · Companion ${d.companionModId||'newfiesplayerlist'} ${d.companionRecommendedVersion||''}`],
      ['Backend build',d.backendBuild||'—',`Cache ${Number(d.snapshotCacheMs||750)}ms · Throttle ${Number(d.requestThrottleMs||750)}ms`],
      ['Roster source',d.rosterSource||'—',`${Number(d.cachedPlayerCount||0)} players in cached roster`],
      ['Snapshot age',snapshotAge<0?'Not built':`${snapshotAge} ms`,'Roster cache refreshes on demand and roster changes'],
      ['Client hellos',Number(d.clientHellosReceived||0),'Handshake count since this server start'],
      ['Requests',requests,`${responses} responses sent`],
      ['Throttled',throttled,'Requests rejected by the anti-spam interval'],
      ['Unanswered',responseGap,responseGap>0?'Requests not accounted for by response/throttle counters':'No unexplained request gap'],
      ['Build failures',buildFailures,buildFailures?'Check the server log for roster build exceptions':'No roster build failures'],
      ['Send failures',sendFailures,sendFailures?'Check the server log for network send exceptions':'No response send failures'],
      ['Role name colors',d.useRoleNameColors?'ON':'OFF',`${Object.keys(d.roleNameColors||{}).length} shared override(s) · managed in Chat Display`],
      ['Reserved slots',d.reservedSlotsEnabled?`${Number(d.reservedSlots||0)} RESERVED`:'OFF',`${Number(d.publicSlotLimit||0)} public slots · ${Number(d.reservedSlotRejections||0)} rejected join(s)`],
      ['Debug logging',d.debugLogging?'ON':'OFF','Extra PlayerList backend log entries']
    ];
    $('playerListDebugGrid').innerHTML=debugItems.map(x=>`<div class="card"><div class="metricLabel">${esc(x[0])}</div><div class="metricValue" style="font-size:18px">${esc(x[1])}</div><div class="small">${esc(x[2])}</div></div>`).join('');

    const healthy=!!d.available&&buildFailures===0&&sendFailures===0&&responseGap===0;
    $('playerListDiagnosticState').textContent=healthy?'Healthy':(d.available?'Needs attention':'Unavailable');
    $('playerListBackendHelp').className=(sendFailures>0||buildFailures>0||responseGap>0)?'warning':'infoBox';
    $('playerListBackendHelp').innerHTML=sendFailures>0
      ? '<b>Response send failures detected.</b> Requests reached the suite, but Vintage Story rejected or failed the server-to-client response. Check <code>[ServerEssentials/PlayerList]</code> in the server log.'
      : buildFailures>0
        ? '<b>Roster build failures detected.</b> Check the server log for the underlying exception. Enable <b>Debug logging</b> above for additional PlayerList traces.'
        : responseGap>0
          ? '<b>Some requests are not accounted for.</b> Enable <b>Debug logging</b>, reproduce with Tab, then inspect <code>[ServerEssentials/PlayerList]</code> in the server log.'
          : responses>0
            ? '<b>Round trip confirmed.</b> The suite backend is receiving and answering player-list requests normally.'
            : requests>0
              ? '<b>Requests are arriving but no responses are recorded.</b> Check the server log for handler/send errors.'
              : '<b>No roster requests recorded yet.</b> Hold Tab in game, then Refresh this page. If the companion reports <code>NotConnected</code>, verify the running Server Essentials DLL advertises the same PlayerList channel.';
  }catch(e){
    $('playerListConfigState').textContent=e.message;
    $('playerListDiagnosticState').textContent='Failed to load';
    $('playerListDebugGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`;
  }
}

async function savePlayerListConfig(){
  const body={
    serverName:String($('playerListServerName').value||'').trim(),
    backgroundOpacity:Math.max(.30,Math.min(.95,Number($('playerListOpacity').value||72)/100)),
    layoutScale:Math.max(.80,Math.min(1.35,Number($('playerListScale').value||100)/100)),
    accentHex:String($('playerListAccent').value||'#d6ae63'),
    alignment:String($('playerListAlignment').value||'CenterTop'),
    offsetX:Number($('playerListOffsetX').value||0),
    offsetY:Number($('playerListOffsetY').value||22),
    rowsPerColumn:Number($('playerListRowsPerColumn').value||8),
    maxColumns:Number($('playerListMaxColumns').value||4),
    showRoles:!!$('playerListShowRoles').checked,
    showPing:!!$('playerListShowPing').checked,
    showSessionTime:!!$('playerListShowSession').checked,
    showPlayerInitials:!!$('playerListShowInitials').checked,
    showCapacityBar:!!$('playerListShowCapacity').checked,
    showColumnHeaders:!!$('playerListShowHeaders').checked,
    compactRows:!!$('playerListCompactRows').checked,
    showPingBars:!!$('playerListShowPingBars').checked,
    showFooterHint:!!$('playerListShowFooter').checked,
    reservedSlotsEnabled:!!$('playerListReservedEnabled').checked,
    reservedSlots:Number($('playerListReservedCount').value||0),
    reservedSlotRoles:String($('playerListReservedRoles').value||''),
    reservedSlotsFullMessage:String($('playerListReservedMessage').value||'Only reserved slots are left on this server.').trim(),
    debugLogging:!!$('playerListDebugLogging').checked
  };
  try{
    const d=await api('/api/playerlist/config',{method:'POST',body:JSON.stringify(body)});
    toast(d.message||'Player-list configuration saved.','success');
    await loadPlayerListConfig();
  }catch(e){toast(e.message,'error')}
}

