  $('discordPlayerInfoCommands').onchange=e=>postDiscordSetting('commands.playerinfoenabled','bool',e.target.checked);
  $('discordStaffCommands').onchange=e=>postDiscordSetting('commands.staffenabled','bool',e.target.checked);
  $('discordRestartCommands').onchange=e=>postDiscordSetting('commands.restartenabled','bool',e.target.checked);
  $('discordAdminAuditEnabled').onchange=e=>postDiscordSetting('adminaudit.enabled','bool',e.target.checked);
  $('discordAntiCheatEnabled').onchange=e=>postDiscordSetting('anticheat.enabled','bool',e.target.checked);
  $('discordMotdEnabled').onchange=e=>postDiscordSetting('motd.enabled','bool',e.target.checked);
  $('discordLinkEnabled').onchange=e=>postDiscordSetting('link.enabled','bool',e.target.checked);
  $('discordLinkCommands').onchange=e=>postDiscordSetting('commands.linkenabled','bool',e.target.checked);
  $('discordLinkMultiple').onchange=e=>postDiscordSetting('link.allowmultiplevs','bool',e.target.checked);
  $('discordLinkLog').onchange=e=>postDiscordSetting('link.logchanges','bool',e.target.checked);
  $('discordSaveGuild').onclick=()=>postDiscordSetting('transport.guildid','string',$('discordGuildId').value);
  $('discordSaveInvite').onclick=()=>postDiscordSetting('transport.inviteurl','string',$('discordInviteUrl').value);
  $('discordSaveChatChannel').onclick=()=>postDiscordSetting('chat.channelid','string',$('discordChatChannel').value);
  $('discordSaveAdminChannel').onclick=()=>postDiscordSetting('adminaudit.channelid','string',$('discordAdminChannel').value);
  $('discordSaveAntiCheatChannel').onclick=()=>postDiscordSetting('anticheat.channelid','string',$('discordAntiCheatChannel').value);
  $('discordSaveMotdAnnouncements').onclick=()=>postDiscordSetting('motd.announcementschannelid','string',$('discordMotdAnnouncementsChannel').value);
  $('discordSaveMotdUpdates').onclick=()=>postDiscordSetting('motd.updateschannelid','string',$('discordMotdUpdatesChannel').value);
  $('discordSaveMotdEvents').onclick=()=>postDiscordSetting('motd.eventschannelid','string',$('discordMotdEventsChannel').value);
  $('discordSaveMotdMaxItems').onclick=()=>postDiscordSetting('motd.maxitemsperfeed','int',$('discordMotdMaxItems').value);
  $('discordSaveCodeLength').onclick=()=>postDiscordSetting('link.codelength','int',$('discordCodeLength').value);
  $('discordSaveCodeExpiry').onclick=()=>postDiscordSetting('link.codeexpiryseconds','int',$('discordCodeExpiry').value);
  $('discordSaveCodeCooldown').onclick=()=>postDiscordSetting('link.codecooldownseconds','int',$('discordCodeCooldown').value);
