let chatGuardData=null;
function chatGuardRule(c,key){return (c&&c[key])||{};}
function chatGuardTime(ms){const n=Number(ms||0);return n>0?new Date(n).toLocaleString():'—';}
function chatGuardLines(value){return String(value||'').split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean);}
function chatGuardVersionAtLeast(major,minor,patch){
  const parts=String(chatGuardData?.version||'0.0.0').split('.').map(x=>Number.parseInt(x,10)||0);
  if(parts[0]!==major)return parts[0]>major;
  if(parts[1]!==minor)return parts[1]>minor;
  return parts[2]>=patch;
}
function setChatGuardRule(prefix,rule){
  const r=rule||{};
  const enabled=$(prefix+'Enabled');if(enabled)enabled.checked=r.Enabled!==false;
  const action=$(prefix+'Action');if(action)action.value=r.Action||'Warn';
  const mute=$(prefix+'Mute');if(mute)mute.value=Number(r.MuteMinutes||5);
}
function chatGuardRuleHit(rule){
  const stats=Array.isArray(chatGuardData?.ruleStats)?chatGuardData.ruleStats:[];
  const row=stats.find(x=>String(x.Rule||'').toLowerCase()===String(rule||'').toLowerCase());
  return Number(row?.Matches||0);
}
function renderChatGuardRecent(){
  if(!$('cgRecentRows'))return;
  const recent=Array.isArray(chatGuardData?.recent)?chatGuardData.recent:[];
  const q=String($('cgRecentSearch')?.value||'').trim().toLowerCase();
  const action=String($('cgRecentAction')?.value||'').trim().toLowerCase();
  const filtered=recent.filter(x=>{
    if(action&&String(x.Action||'').toLowerCase()!==action)return false;
    if(!q)return true;
    return [x.PlayerName,x.PlayerUid,x.Rule,x.Action,x.Detail,x.MessagePreview,x.Actor].some(v=>String(v||'').toLowerCase().includes(q));
  });
  $('cgRecentRows').innerHTML=filtered.length?filtered.slice(0,100).map(x=>`<tr><td>${esc(chatGuardTime(Number(x.TimestampUtcMs||0)))}</td><td>${esc(x.PlayerName||x.PlayerUid||'—')}</td><td>${esc(x.Rule||'—')}</td><td>${esc(x.Action||'—')}</td><td>${esc(x.Detail||'')}</td><td>${esc(x.MessagePreview||'')}</td></tr>`).join(''):'<tr><td colspan="6" class="muted">No moderation activity matches this filter.</td></tr>';
}
function renderChatGuardTestResult(test){
  const host=$('cgTestResult');if(!host)return;
  if(!test||!test.DryRun){host.innerHTML=chatGuardVersionAtLeast(2,1,1)?'Enter a message and run a dry test.':'Requires ChatGuard 2.1.1+.';return;}
  const checks=Array.isArray(test.Checks)?test.Checks:[];
  const summary=test.Matched?`Would match <b>${esc(test.Rule||'—')}</b> → <b>${esc(test.Action||'—')}</b><br>${esc(test.Detail||'')}`:`<b>No enforced match.</b><br>${esc(test.Detail||'')}`;
  const rows=checks.map(x=>`<div class="small" style="margin-top:4px"><b class="${x.Matched?'bad':'good'}">${x.Matched?'MATCH':'PASS'}</b> · ${esc(x.Rule||'—')} — ${esc(x.Detail||'')}</div>`).join('');
  host.innerHTML=summary+(test.Exempt?'<br><span class="small">Target is exempt from enforcement.</span>':'')+(rows?`<div style="margin-top:10px">${rows}</div>`:'');
}
let chatGuardTab='moderation';
function setChatGuardTab(tab){
  chatGuardTab=tab==='banned'?'banned':'moderation';
  if($('cgMainPanel'))$('cgMainPanel').style.display=chatGuardTab==='moderation'?'':'none';
  if($('cgBannedPanel'))$('cgBannedPanel').style.display=chatGuardTab==='banned'?'':'none';
  if($('cgTabModeration'))$('cgTabModeration').classList.toggle('active',chatGuardTab==='moderation');
  if($('cgTabBanned'))$('cgTabBanned').classList.toggle('active',chatGuardTab==='banned');
}
function chatGuardBannedTerms(){
  const c=chatGuardData?.config||{},terms=chatGuardRule(c,'BlockedTerms');
  return Array.isArray(terms.Terms)?terms.Terms:[];
}
function syncChatGuardBannedEditor(){
  const terms=chatGuardRule(chatGuardData?.config||{},'BlockedTerms');
  if($('cgBannedEnabled'))$('cgBannedEnabled').checked=terms.Enabled!==false;
  if($('cgBannedAction'))$('cgBannedAction').value=terms.Action||'Block';
  if($('cgBannedMute'))$('cgBannedMute').value=Number(terms.MuteMinutes||5);
  renderChatGuardBannedRows();
}
function renderChatGuardBannedRows(){
  if(!$('cgBannedRows'))return;
  const q=String($('cgBannedSearch')?.value||'').trim().toLowerCase();
  const rows=chatGuardBannedTerms().filter(x=>!q||String(x).toLowerCase().includes(q));
  $('cgBannedRows').innerHTML=rows.length?rows.map(term=>`<tr><td><code>${esc(term)}</code></td><td><button data-cg-banned-remove="${encodeURIComponent(term)}" ${currentSessionRole==='ReadOnly'?'disabled':''}>Remove</button></td></tr>`).join(''):'<tr><td colspan="2" class="muted">No banned words or phrases match this view.</td></tr>';
  document.querySelectorAll('[data-cg-banned-remove]').forEach(b=>b.onclick=()=>removeChatGuardBanned(decodeURIComponent(b.dataset.cgBannedRemove||'')));
}
function addChatGuardBanned(values){
  if(currentSessionRole==='ReadOnly')return;
  const c=chatGuardData?.config;if(!c)return;
  c.BlockedTerms=c.BlockedTerms||{};
  const existing=Array.isArray(c.BlockedTerms.Terms)?c.BlockedTerms.Terms:[];
  const map=new Map(existing.map(x=>[String(x).toLowerCase(),String(x)]));
  values.map(x=>String(x||'').trim()).filter(Boolean).forEach(x=>{if(x.length<=120&&!map.has(x.toLowerCase()))map.set(x.toLowerCase(),x)});
  c.BlockedTerms.Terms=[...map.values()].slice(0,500);
  if($('cgTermsList'))$('cgTermsList').value=c.BlockedTerms.Terms.join('\n');
  if($('cgBannedAdd'))$('cgBannedAdd').value='';
  if($('cgBannedBulk'))$('cgBannedBulk').value='';
  renderChatGuardBannedRows();
}
function removeChatGuardBanned(term){
  const c=chatGuardData?.config;if(!c?.BlockedTerms)return;
  c.BlockedTerms.Terms=(c.BlockedTerms.Terms||[]).filter(x=>String(x).toLowerCase()!==String(term).toLowerCase());
  if($('cgTermsList'))$('cgTermsList').value=c.BlockedTerms.Terms.join('\n');
  renderChatGuardBannedRows();
}
function applyBannedControlsToMainRule(){
  if(!chatGuardData?.config)return;
  const terms=chatGuardData.config.BlockedTerms=chatGuardData.config.BlockedTerms||{};
  terms.Enabled=!!$('cgBannedEnabled')?.checked;
  terms.Action=$('cgBannedAction')?.value||'Block';
  terms.MuteMinutes=Math.max(1,Math.min(10080,Math.round(Number($('cgBannedMute')?.value||5))));
  if($('cgTermsEnabled'))$('cgTermsEnabled').checked=terms.Enabled;
  if($('cgTermsAction'))$('cgTermsAction').value=terms.Action;
  if($('cgTermsMute'))$('cgTermsMute').value=terms.MuteMinutes;
  if($('cgTermsList'))$('cgTermsList').value=(terms.Terms||[]).join('\n');
}

function renderChatGuard(){
  const d=chatGuardData||{};
  const c=d.config||{};
  if(!$('cgState'))return;
  const available=!!d.available;
  const supports211=chatGuardVersionAtLeast(2,1,1);
  const supportsTester=chatGuardVersionAtLeast(2,1,1);
  const warningsList=Array.isArray(d.warnings)?d.warnings:[];
  const warnedPlayers=warningsList.filter(x=>Number(x.ActiveWarnings||0)>0).length;
  $('cgState').textContent=available?`ChatGuard ${d.version||''} · ${d.enabled?'Enabled':'Disabled'} · ${d.mode||'—'}`:'Standalone ChatGuard is not installed.';
  setNavStatus('chatguard',!available?'neutral':(!d.enabled?'neutral':(String(d.mode).toLowerCase()==='logonly'?'warn':'good')),!available?'Standalone ChatGuard not installed':`${d.enabled?'Enabled':'Disabled'} · ${d.mode||'—'}`);
  setNavBadge('chatguard',Number(d.activeMutes||0)+warnedPlayers,(Number(d.activeMutes||0)+warnedPlayers)>0?'attention':'info',`${Number(d.activeMutes||0)} active mute(s) · ${warnedPlayers} warned player(s)`);
  $('cgMetrics').innerHTML=
    metric('Module',available?`v${d.version||'?'}`:'Not installed',available?'good':'')+
    metric('Mode',available?(d.enabled?(d.mode||'—'):'Disabled'):'—',available&&d.enabled?(String(d.mode).toLowerCase()==='logonly'?'warn':'good'):'')+
    metric('Scanned',Number(d.scannedMessages||0).toLocaleString())+
    metric('Rule matches',Number(d.matchedRules||0).toLocaleString(),Number(d.matchedRules||0)>0?'warn':'')+
    metric('Blocked',Number(d.blockedMessages||0).toLocaleString(),Number(d.blockedMessages||0)>0?'warn':'')+
    metric('Warnings issued',Number(d.warningsIssued||0).toLocaleString())+
    metric('Warned players',warnedPlayers,warnedPlayers>0?'warn':'good')+
    metric('Mutes issued',Number(d.mutesIssued||0).toLocaleString())+
    metric('Active mutes',Number(d.activeMutes||0),Number(d.activeMutes||0)>0?'warn':'good');
  if(!available){$('cgUnavailable').style.display='block';return;}else $('cgUnavailable').style.display='none';

  $('cgEnabled').checked=c.Enabled!==false;
  $('cgMode').value=c.Mode||'Enforce';
  $('cgNotify').checked=c.NotifyPlayers!==false;
  $('cgPrefix').value=c.NotificationPrefix||'[ChatGuard]';
  $('cgExemptRoles').value=Array.isArray(c.ExemptRoleCodes)?c.ExemptRoleCodes.join(', '):'';
  $('cgExemptUids').value=Array.isArray(c.ExemptPlayerUids)?c.ExemptPlayerUids.join('\n'):'';
  $('cgAuditPreview').value=Number(c.AuditMessagePreviewCharacters??160);

  const spam=chatGuardRule(c,'Spam');setChatGuardRule('cgSpam',spam);$('cgSpamMax').value=Number(spam.MaxMessages||5);$('cgSpamWindow').value=Number(spam.WindowSeconds||4);
  const repeat=chatGuardRule(c,'Repeat');setChatGuardRule('cgRepeat',repeat);$('cgRepeatMax').value=Number(repeat.MaxRepeats||3);$('cgRepeatWindow').value=Number(repeat.WindowSeconds||20);
  const caps=chatGuardRule(c,'Caps');setChatGuardRule('cgCaps',caps);$('cgCapsLetters').value=Number(caps.MinLetters||12);$('cgCapsPercent').value=Number(caps.MaxUppercasePercent||75);
  const links=chatGuardRule(c,'Links');setChatGuardRule('cgLinks',links);$('cgLinksAllowed').value=Array.isArray(links.AllowedDomains)?links.AllowedDomains.join('\n'):'';
  const mentions=chatGuardRule(c,'Mentions');setChatGuardRule('cgMentions',mentions);$('cgMentionsMax').value=Number(mentions.MaxMentions||5);
  const length=chatGuardRule(c,'Length');setChatGuardRule('cgLength',length);$('cgLengthMax').value=Number(length.MaxCharacters||500);
  const terms=chatGuardRule(c,'BlockedTerms');setChatGuardRule('cgTerms',terms);$('cgTermsList').value=Array.isArray(terms.Terms)?terms.Terms.join('\n'):'';
  syncChatGuardBannedEditor();
  setChatGuardTab(chatGuardTab);
  const escalation=c.Escalation||{};$('cgEscalationEnabled').checked=escalation.Enabled!==false;$('cgEscalationWindow').value=Number(escalation.WarningWindowMinutes||60);$('cgEscalationWarnings').value=Number(escalation.WarningsBeforeMute||3);$('cgEscalationMute').value=Number(escalation.MuteMinutes||10);

  const hitMap={cgHitSpam:'Spam',cgHitRepeat:'Repeat',cgHitCaps:'Caps',cgHitLinks:'Link',cgHitMentions:'MentionSpam',cgHitLength:'MessageLength',cgHitTerms:'BlockedTerm'};
  Object.entries(hitMap).forEach(([id,rule])=>{if($(id))$(id).textContent=chatGuardRuleHit(rule).toLocaleString();});
  const stats=Array.isArray(d.ruleStats)?d.ruleStats:[];
  const hot=stats.slice().sort((a,b)=>Number(b.Matches||0)-Number(a.Matches||0)).filter(x=>Number(x.Matches||0)>0).slice(0,4);
  if($('cgRuleHits'))$('cgRuleHits').innerHTML=hot.length?`Top session hits: ${hot.map(x=>`<b>${esc(x.Rule||'Rule')}</b> ${Number(x.Matches||0).toLocaleString()}`).join(' · ')}`:'No rule matches recorded this session.';
  const posture=!d.enabled?'Disabled':String(d.mode||'').toLowerCase()==='logonly'?'Observe only':'Enforcing';
  if($('cgPostureChip')){$('cgPostureChip').textContent=posture;$('cgPostureChip').className='badge '+(!d.enabled?'':String(d.mode||'').toLowerCase()==='logonly'?'warn':'good');}
  if($('cgPosture'))$('cgPosture').innerHTML=!d.enabled?'<b>Moderation is disabled.</b> ChatGuard will not automatically process rule actions.':String(d.mode||'').toLowerCase()==='logonly'?'<b>LogOnly mode.</b> Rule matches are observed and audited, but automatic sanctions are not enforced.':'<b>Enforce mode.</b> Enabled rules can block, warn, mute, or kick according to their configured actions.';
  const online=Array.isArray(d.onlinePlayers)?d.onlinePlayers:[];
  if($('cgOnlinePlayers'))$('cgOnlinePlayers').innerHTML=online.map(x=>`<option value="${esc(x.PlayerName||'')}">${esc((x.Role||'')+(x.Exempt?' · exempt':''))}</option>`).join('');
  renderChatGuardTestResult(d.test);
  renderChatGuardRecent();

  const mutes=Array.isArray(d.mutes)?d.mutes:[];
  $('cgMuteRows').innerHTML=mutes.length?mutes.map(x=>{
    const duration=x.Permanent?'Permanent':chatGuardTime(Number(x.ExpiresUtcMs||0));
    return `<tr><td>${esc(x.PlayerName||x.PlayerUid||'—')}<br><span class="small"><code>${esc(x.PlayerUid||'')}</code></span></td><td class="${x.Permanent?'bad':''}"><b>${esc(duration)}</b></td><td>${esc(x.Reason||'')}</td><td>${esc(x.Actor||'')}</td><td><button class="smallButton" data-cg-unmute="${esc(x.PlayerUid||'')}" data-cg-name="${esc(x.PlayerName||'')}">Unmute</button></td></tr>`;
  }).join(''):'<tr><td colspan="5" class="muted">No active ChatGuard mutes.</td></tr>';

  const warningWindow=Number(escalation.WarningWindowMinutes||60);
  const warningThreshold=Number(escalation.WarningsBeforeMute||3);
  $('cgWarningRows').innerHTML=warningsList.length?warningsList.filter(x=>Number(x.ActiveWarnings||0)>0).map(x=>{
    const times=Array.isArray(x.WarningUtcMs)?x.WarningUtcMs.map(Number).filter(Number.isFinite):[];
    const oldest=times.length?Math.min(...times):0;
    const expires=oldest?oldest+warningWindow*60000:0;
    return `<tr><td>${esc(x.PlayerName||x.PlayerUid||'—')}<br><span class="small"><code>${esc(x.PlayerUid||'')}</code></span></td><td><b>${Number(x.ActiveWarnings||0)}/${warningThreshold}</b></td><td>${warningWindow} min</td><td>${esc(expires?chatGuardTime(expires):'—')}</td><td>${supports211?`<button class="smallButton" data-cg-clearwarnings="${esc(x.PlayerUid||'')}" data-cg-name="${esc(x.PlayerName||'')}">Clear</button>`:'<span class="small">Requires ChatGuard 2.1.1+</span>'}</td></tr>`;
  }).join(''):'<tr><td colspan="5" class="muted">No active ChatGuard warnings.</td></tr>';

  document.querySelectorAll('[data-cg-unmute]').forEach(btn=>btn.onclick=()=>{
    const reason=window.prompt('Reason for unmuting this player:','Manual staff unmute');
    if(reason===null)return;
    chatGuardAction('unmute',btn.dataset.cgUnmute||'',btn.dataset.cgName||'',0,reason,false);
  });
  document.querySelectorAll('[data-cg-clearwarnings]').forEach(btn=>btn.onclick=()=>{
    const reason=window.prompt('Reason for clearing this player\'s warnings:','Manual warning reset');
    if(reason===null)return;
    chatGuardAction('clearwarnings',btn.dataset.cgClearwarnings||'',btn.dataset.cgName||'',0,reason,false);
  });
  const ro=currentSessionRole==='ReadOnly';
  document.querySelectorAll('#chatguard input,#chatguard select,#chatguard textarea,#chatguard button').forEach(el=>{if(el.id!=='cgRefresh'&&el.id!=='cgManualInspect')el.disabled=ro;});
  $('cgRefresh').disabled=false;
  $('cgManualInspect').disabled=false;
  if($('cgManualPermanent')){
    $('cgManualPermanent').disabled=ro||!supports211;
    $('cgManualPermanent').title=supports211?'Permanent mute supported by ChatGuard 2.1.1+.':'Update ChatGuard to 2.1.1+ for permanent mutes from the Suite WebPanel.';
  }
  if($('cgTestRun')){$('cgTestRun').disabled=ro||!supportsTester;$('cgTestRun').title=supportsTester?'Dry-run the current rules without changing state.':'ChatGuard 2.1.1+ supports the Rule Tester.';}
}
function inspectChatGuardTarget(){
  const target=String($('cgManualTarget')?.value||'').trim();
  const host=$('cgManualInfo');
  if(!host)return;
  if(!target){host.innerHTML='<b>Enter a player name or UID.</b>';return;}
  const key=target.toLowerCase();
  const mutes=Array.isArray(chatGuardData?.mutes)?chatGuardData.mutes:[];
  const warnings=Array.isArray(chatGuardData?.warnings)?chatGuardData.warnings:[];
  const mute=mutes.find(x=>String(x.PlayerUid||'').toLowerCase()===key||String(x.PlayerName||'').toLowerCase()===key);
  const warning=warnings.find(x=>String(x.PlayerUid||'').toLowerCase()===key||String(x.PlayerName||'').toLowerCase()===key);
  const c=chatGuardData?.config||{}, escalation=c.Escalation||{};
  const name=mute?.PlayerName||warning?.PlayerName||target;
  const uid=mute?.PlayerUid||warning?.PlayerUid||'No retained ChatGuard record';
  const muteText=mute?(mute.Permanent?`Permanent — ${mute.Reason||'no reason'}`:`Until ${chatGuardTime(Number(mute.ExpiresUtcMs||0))} — ${mute.Reason||'no reason'}`):'None';
  const wc=Number(warning?.ActiveWarnings||0);
  host.innerHTML=`<b>${esc(name)}</b><br><span class="small">UID: <code>${esc(uid)}</code></span><br>Mute: <b>${esc(muteText)}</b><br>Warnings: <b>${wc}/${Number(escalation.WarningsBeforeMute||3)}</b> active in a ${Number(escalation.WarningWindowMinutes||60)} minute window.${!mute&&!warning?'<br><span class="small">No active/persisted ChatGuard sanction is present for this lookup. New warns/mutes still require the player online.</span>':''}`;
}

function buildChatGuardConfig(){
  const base=JSON.parse(JSON.stringify(chatGuardData?.config||{}));
  base.SchemaVersion=1;base.Enabled=!!$('cgEnabled').checked;base.Mode=$('cgMode').value;base.NotifyPlayers=!!$('cgNotify').checked;base.NotificationPrefix=$('cgPrefix').value||'[ChatGuard]';base.ExemptRoleCodes=chatGuardLines($('cgExemptRoles').value);base.ExemptPlayerUids=chatGuardLines($('cgExemptUids').value);base.AuditMessagePreviewCharacters=Number($('cgAuditPreview').value||0);
  const rule=(prefix,extra={})=>Object.assign({Enabled:!!$(prefix+'Enabled').checked,Action:$(prefix+'Action').value,MuteMinutes:Number($(prefix+'Mute').value||5)},extra);
  base.Spam=rule('cgSpam',{MaxMessages:Number($('cgSpamMax').value||5),WindowSeconds:Number($('cgSpamWindow').value||4)});
  base.Repeat=rule('cgRepeat',{MaxRepeats:Number($('cgRepeatMax').value||3),WindowSeconds:Number($('cgRepeatWindow').value||20)});
  base.Caps=rule('cgCaps',{MinLetters:Number($('cgCapsLetters').value||12),MaxUppercasePercent:Number($('cgCapsPercent').value||75)});
  base.Links=rule('cgLinks',{AllowedDomains:chatGuardLines($('cgLinksAllowed').value)});
  base.Mentions=rule('cgMentions',{MaxMentions:Number($('cgMentionsMax').value||5)});
  base.Length=rule('cgLength',{MaxCharacters:Number($('cgLengthMax').value||500)});
  base.BlockedTerms=rule('cgTerms',{Terms:chatGuardLines($('cgTermsList').value)});
  base.Escalation={Enabled:!!$('cgEscalationEnabled').checked,WarningWindowMinutes:Number($('cgEscalationWindow').value||60),WarningsBeforeMute:Number($('cgEscalationWarnings').value||3),MuteMinutes:Number($('cgEscalationMute').value||10)};
  return base;
}
async function loadChatGuard(showLoading=true){
  if(showLoading&&$('cgState'))$('cgState').textContent='Loading…';
  try{chatGuardData=await api('/api/chatguard');renderChatGuard();}
  catch(e){if($('cgState'))$('cgState').textContent=e.message;if(showLoading)toast(e.message,'error');}
}
async function saveChatGuard(){
  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change ChatGuard settings.','error');return;}
  try{chatGuardData=await api('/api/chatguard/settings',{method:'POST',body:JSON.stringify(buildChatGuardConfig())});renderChatGuard();toast(chatGuardData.message||'ChatGuard settings saved.','success');}
  catch(e){toast(e.message,'error');}
}
async function testChatGuard(){
  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot run the ChatGuard tester.','error');return;}
  if(!chatGuardVersionAtLeast(2,1,1)){toast('The Rule Tester requires ChatGuard 2.1.1 or newer.','error');return;}
  const message=String($('cgTestMessage')?.value||'');
  const targetName=String($('cgTestTarget')?.value||'').trim();
  if(!message.trim()){toast('Enter a message to test.','error');return;}
  try{chatGuardData=await api('/api/chatguard/test',{method:'POST',body:JSON.stringify({targetName,message})});renderChatGuard();toast('ChatGuard dry-run complete.','success');}
  catch(e){toast(e.message,'error');}
}
async function chatGuardAction(action,targetUid='',targetName='',minutes=0,reason='',permanent=false){
  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot run ChatGuard actions.','error');return;}
  if((permanent||action==='clearwarnings')&&!chatGuardVersionAtLeast(2,1,1)){toast('This action requires ChatGuard 2.1.1 or newer.','error');return;}
  try{
    chatGuardData=await api('/api/chatguard/action',{method:'POST',body:JSON.stringify({action,targetUid,targetName,minutes,reason,permanent})});
    renderChatGuard();
    inspectChatGuardTarget();
    toast(chatGuardData.message||'ChatGuard action completed.','success');
  }catch(e){toast(e.message,'error');}
}



let chatDisplayData=null;
function renderChatDisplay(){
  const d=chatDisplayData||{};
  if(!$('chatDisplayState'))return;
  $('chatDisplayState').textContent=d.available===false?'Service unavailable':'Live settings loaded';
  $('chatDisplayRole').checked=!!d.showRoleBeforeName;
  $('chatDisplayBoldName').checked=!!d.boldPlayerName;
  $('chatDisplayTimestamp').checked=!!d.showTimestampBeforeMessage;
  $('chatDisplayTimestampFormat').value=d.timestampFormat||'HH:mm';
  $('chatDisplayUtc').checked=!!d.useUtcTimestamp;
  $('chatDisplayGeneral').checked=d.formatGeneralChat!==false;
  $('chatDisplayOtherGroups').checked=!!d.formatOtherChatGroups;
  $('chatDisplayAdditionalGroups').value=Array.isArray(d.additionalFormattedChatGroupIds)?d.additionalFormattedChatGroupIds.join(', '):'';
  $('chatDisplayUseRoleColors').checked=!!d.useRoleNameColors;
  $('chatDisplayRoleColors').value=roleColorMapToText(d.roleNameColors);
  renderChatDisplayRoleColorPreview();
  $('chatDisplayPreview').innerHTML=`<b>Preview:</b> <code>${esc(d.preview||'ExamplePlayer: Hello world')}</code>`;
  const extraGroups=Array.isArray(d.additionalFormattedChatGroupIds)?d.additionalFormattedChatGroupIds:[];
  $('chatDisplayMetrics').innerHTML=
    metric('General chat',d.formatGeneralChat!==false?'FORMATTED':'PASS-THROUGH',d.formatGeneralChat!==false?'good':'')+
    metric('All other groups',d.formatOtherChatGroups?'FORMATTED':'PASS-THROUGH',d.formatOtherChatGroups?'warn':'good')+
    metric('Specific extra groups',extraGroups.length?extraGroups.join(', '):'None')+
    metric('Role prefix',d.showRoleBeforeName?'ON':'OFF',d.showRoleBeforeName?'good':'')+
    metric('Role name colors',d.useRoleNameColors?`${Object.keys(d.roleNameColors||{}).length} OVERRIDES`:'OFF',d.useRoleNameColors?'good':'')+
    metric('Bold player name',d.boldPlayerName?'ON':'OFF',d.boldPlayerName?'good':'')+
    metric('Timestamp',d.showTimestampBeforeMessage?'ON':'OFF',d.showTimestampBeforeMessage?'good':'')+
    metric('Timezone',d.useUtcTimestamp?'UTC':'Server local')+
    metric('Format',d.timestampFormat||'HH:mm');
  const ro=currentSessionRole==='ReadOnly';
  ['chatDisplayRole','chatDisplayBoldName','chatDisplayTimestamp','chatDisplayTimestampFormat','chatDisplayUtc','chatDisplayGeneral','chatDisplayOtherGroups','chatDisplayAdditionalGroups','chatDisplayUseRoleColors','chatDisplayRoleColors','chatDisplaySave'].forEach(id=>{const e=$(id);if(e)e.disabled=ro||d.available===false;});
}
async function loadChatDisplay(showLoading=true){
  if(showLoading&&$('chatDisplayState'))$('chatDisplayState').textContent='Loading…';
  try{chatDisplayData=await api('/api/chat-display');renderChatDisplay();}
  catch(e){if($('chatDisplayState'))$('chatDisplayState').textContent=e.message;if(showLoading)toast(e.message,'error');}
}
async function saveChatDisplay(){
  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change chat display settings.','error');return;}
  const payload={
    showRoleBeforeName:!!$('chatDisplayRole').checked,
    boldPlayerName:!!$('chatDisplayBoldName').checked,
    showTimestampBeforeMessage:!!$('chatDisplayTimestamp').checked,
    timestampFormat:$('chatDisplayTimestampFormat').value||'HH:mm',
    useUtcTimestamp:!!$('chatDisplayUtc').checked,
    formatGeneralChat:!!$('chatDisplayGeneral').checked,
    formatOtherChatGroups:!!$('chatDisplayOtherGroups').checked,
    additionalFormattedChatGroupIds:($('chatDisplayAdditionalGroups').value||'').split(/[;,\s]+/).map(v=>Number(v)).filter(v=>Number.isInteger(v)&&v>=0),
    useRoleNameColors:!!$('chatDisplayUseRoleColors').checked,
    roleNameColors:parseRoleColorMap($('chatDisplayRoleColors').value||'')
  };
  try{
    const d=await api('/api/chat-display/settings',{method:'POST',body:JSON.stringify(payload)});
    chatDisplayData=d.chatDisplay||chatDisplayData;
    renderChatDisplay();toast(d.message||'Chat display settings saved.','success');
  }catch(e){toast(e.message,'error');}
}



let suiteCustomizationData=null;
const SUITE_CUSTOMIZATION_DEFAULTS={
  panelName:"Newfie's Server Suite",headerSubtitle:'WebPanel',loginKicker:'Secure Administration Console',
  loginSubtitle:'Remote server administration. Fresh installs on 127.0.0.1 enter automatically without a login.',
  dashboardTitle:'Server Dashboard',
  dashboardSubtitle:'Actionable server and Suite overview: what needs attention, current operations state, health evidence, and recent lag.',
  searchPlaceholder:'Search Server Essentials Suite…',sidebarFooterText:"Newfie's Server Suite · Server Administration",
  accentHex:'#69AEFA',showBuildId:true,showHeaderLogo:true,compactLayout:false,sidebarWidth:232,cardRadius:14,
  showStatusBar:true,showModuleStatus:true,showDashboardAttention:true,showDashboardOperations:true
};
function normalizeAccentHex(value){
  const v=String(value||'').trim().toUpperCase();
  return /^#[0-9A-F]{6}$/.test(v)?v:SUITE_CUSTOMIZATION_DEFAULTS.accentHex;
}
function applySuiteCustomization(d,updateForm=false){
  const c=Object.assign({},SUITE_CUSTOMIZATION_DEFAULTS,d||{});
  c.accentHex=normalizeAccentHex(c.accentHex);
  c.sidebarWidth=clamp(Number(c.sidebarWidth)||232,190,320);
  c.cardRadius=clamp(Number(c.cardRadius)||14,0,24);
  document.documentElement.style.setProperty('--accent',c.accentHex);
  document.documentElement.style.setProperty('--suite-sidebar-width',`${c.sidebarWidth}px`);
  document.documentElement.style.setProperty('--radius-md',`${c.cardRadius}px`);
  document.documentElement.style.setProperty('--radius-lg',`${Math.min(30,c.cardRadius+4)}px`);
  document.body.classList.toggle('suiteCompact',!!c.compactLayout);
  document.body.classList.toggle('suiteHideStatus',c.showStatusBar===false);
  document.body.classList.toggle('suiteHideModuleStatus',c.showModuleStatus===false);
  document.body.classList.toggle('suiteHideHeaderLogo',c.showHeaderLogo===false);
  document.title=c.panelName;
  if($('suiteBrandName'))$('suiteBrandName').textContent=c.panelName;
  if($('suiteHeaderSubtitle'))$('suiteHeaderSubtitle').textContent=c.headerSubtitle;
  if($('suiteHeaderTitle'))$('suiteHeaderTitle').textContent=c.panelName;
  if($('suiteLoginKicker'))$('suiteLoginKicker').textContent=c.loginKicker;
  const loginSubtitle=document.querySelector('#loginView [data-login-subtitle]');if(loginSubtitle)loginSubtitle.textContent=c.loginSubtitle;
  if($('suiteDashboardTitle'))$('suiteDashboardTitle').textContent=c.dashboardTitle;
  if($('suiteDashboardSubtitle'))$('suiteDashboardSubtitle').textContent=c.dashboardSubtitle;
  if($('suiteSidebarFooter'))$('suiteSidebarFooter').textContent=c.sidebarFooterText;
  if($('commandOpen')&&$('commandOpen').childNodes.length)$('commandOpen').childNodes[0].nodeValue=`⌕ ${c.searchPlaceholder} `;
  if($('commandInput'))$('commandInput').placeholder=c.searchPlaceholder;
  if($('dashboardAttentionCard'))$('dashboardAttentionCard').style.display=c.showDashboardAttention===false?'none':'';
  if($('dashboardOperationsCard'))$('dashboardOperationsCard').style.display=c.showDashboardOperations===false?'none':'';
  const mobile=document.querySelector('.mobileNavHead span'); if(mobile)mobile.textContent=c.panelName;
  const crumb=document.querySelector('#breadcrumbBar > span:first-child'); if(crumb)crumb.textContent=c.panelName;
  if(updateForm){
    if($('suiteCustomizationPanelName'))$('suiteCustomizationPanelName').value=c.panelName;
    if($('suiteCustomizationHeaderSubtitle'))$('suiteCustomizationHeaderSubtitle').value=c.headerSubtitle;
    if($('suiteCustomizationLoginKicker'))$('suiteCustomizationLoginKicker').value=c.loginKicker;
    if($('suiteCustomizationLoginSubtitle'))$('suiteCustomizationLoginSubtitle').value=c.loginSubtitle;
    if($('suiteCustomizationDashboardTitle'))$('suiteCustomizationDashboardTitle').value=c.dashboardTitle;
    if($('suiteCustomizationDashboardSubtitle'))$('suiteCustomizationDashboardSubtitle').value=c.dashboardSubtitle;
    if($('suiteCustomizationSearchPlaceholder'))$('suiteCustomizationSearchPlaceholder').value=c.searchPlaceholder;
    if($('suiteCustomizationSidebarFooter'))$('suiteCustomizationSidebarFooter').value=c.sidebarFooterText;
    if($('suiteCustomizationAccent'))$('suiteCustomizationAccent').value=c.accentHex.toLowerCase();
    if($('suiteCustomizationAccentText'))$('suiteCustomizationAccentText').value=c.accentHex;
    if($('suiteCustomizationShowBuild'))$('suiteCustomizationShowBuild').checked=c.showBuildId!==false;
    if($('suiteCustomizationHeaderLogo'))$('suiteCustomizationHeaderLogo').checked=c.showHeaderLogo!==false;
    if($('suiteCustomizationCompact'))$('suiteCustomizationCompact').checked=!!c.compactLayout;
    if($('suiteCustomizationSidebarWidth'))$('suiteCustomizationSidebarWidth').value=c.sidebarWidth;
    if($('suiteCustomizationCardRadius'))$('suiteCustomizationCardRadius').value=c.cardRadius;
    if($('suiteCustomizationStatusBar'))$('suiteCustomizationStatusBar').checked=c.showStatusBar!==false;
    if($('suiteCustomizationModuleStatus'))$('suiteCustomizationModuleStatus').checked=c.showModuleStatus!==false;
    if($('suiteCustomizationAttention'))$('suiteCustomizationAttention').checked=c.showDashboardAttention!==false;
    if($('suiteCustomizationOperations'))$('suiteCustomizationOperations').checked=c.showDashboardOperations!==false;
  }
  if($('suiteCustomizationPreview')){
    const build=(c.showBuildId!==false&&c.buildId)?`<br><span class="small">Build: <code>${esc(c.buildId)}</code></span>`:'';
    const mode=c.compactLayout?'Compact':'Standard';
    $('suiteCustomizationPreview').innerHTML=`<b>${esc(c.panelName)}</b> <span class="badge low">${esc(c.headerSubtitle)}</span><br>${esc(c.dashboardTitle)} — ${esc(c.dashboardSubtitle)}<br><span class="small">${esc(mode)} layout · ${c.sidebarWidth}px sidebar · ${c.cardRadius}px cards</span>${build}`;
  }
}
function readSuiteCustomizationForm(){
  return {
    panelName:String($('suiteCustomizationPanelName')?.value||SUITE_CUSTOMIZATION_DEFAULTS.panelName).trim(),
    headerSubtitle:String($('suiteCustomizationHeaderSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.headerSubtitle).trim(),
    loginKicker:String($('suiteCustomizationLoginKicker')?.value||SUITE_CUSTOMIZATION_DEFAULTS.loginKicker).trim(),
    loginSubtitle:String($('suiteCustomizationLoginSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.loginSubtitle).trim(),
    dashboardTitle:String($('suiteCustomizationDashboardTitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.dashboardTitle).trim(),
    dashboardSubtitle:String($('suiteCustomizationDashboardSubtitle')?.value||SUITE_CUSTOMIZATION_DEFAULTS.dashboardSubtitle).trim(),
    searchPlaceholder:String($('suiteCustomizationSearchPlaceholder')?.value||SUITE_CUSTOMIZATION_DEFAULTS.searchPlaceholder).trim(),
    sidebarFooterText:String($('suiteCustomizationSidebarFooter')?.value||SUITE_CUSTOMIZATION_DEFAULTS.sidebarFooterText).trim(),
    accentHex:normalizeAccentHex($('suiteCustomizationAccentText')?.value||$('suiteCustomizationAccent')?.value),
    showBuildId:$('suiteCustomizationShowBuild')?.checked!==false,
    showHeaderLogo:$('suiteCustomizationHeaderLogo')?.checked!==false,
    compactLayout:!!$('suiteCustomizationCompact')?.checked,
    sidebarWidth:clamp(Number($('suiteCustomizationSidebarWidth')?.value||232),190,320),
    cardRadius:clamp(Number($('suiteCustomizationCardRadius')?.value||14),0,24),
    showStatusBar:$('suiteCustomizationStatusBar')?.checked!==false,
    showModuleStatus:$('suiteCustomizationModuleStatus')?.checked!==false,
    showDashboardAttention:$('suiteCustomizationAttention')?.checked!==false,
    showDashboardOperations:$('suiteCustomizationOperations')?.checked!==false
  };
}
function previewSuiteCustomization(){
  const c=readSuiteCustomizationForm();
  c.buildId=suiteCustomizationData?.buildId||'';
  applySuiteCustomization(c,false);
}
async function loadSuiteCustomization(showLoading=true){
  if(showLoading&&$('suiteCustomizationState'))$('suiteCustomizationState').textContent='Loading…';
  try{
    suiteCustomizationData=await api('/api/customization');
    applySuiteCustomization(suiteCustomizationData,true);
    if($('suiteCustomizationState'))$('suiteCustomizationState').textContent='Live customization loaded';
    const ro=currentSessionRole==='ReadOnly';
    document.querySelectorAll('#customization input,#customization textarea,#customization button').forEach(e=>{if(e.id!=='suiteCustomizationRefresh')e.disabled=ro;});
    if($('suiteCustomizationRefresh'))$('suiteCustomizationRefresh').disabled=false;
  }catch(e){if($('suiteCustomizationState'))$('suiteCustomizationState').textContent=e.message;if(showLoading)toast(e.message,'error');}
}
async function saveSuiteCustomization(){
  if(currentSessionRole==='ReadOnly'){toast('Read-only sessions cannot change Suite customization.','error');return;}
  const payload=readSuiteCustomizationForm();
  try{
    const d=await api('/api/customization',{method:'POST',body:JSON.stringify(payload)});
    suiteCustomizationData=Object.assign({},d.customization||payload);
    applySuiteCustomization(suiteCustomizationData,true);
    if($('suiteCustomizationState'))$('suiteCustomizationState').textContent='Saved';
    toast(d.message||'Suite customization saved.','success');
  }catch(e){toast(e.message,'error');}
}
function resetSuiteCustomization(){
  if(currentSessionRole==='ReadOnly')return;
  const c=Object.assign({},SUITE_CUSTOMIZATION_DEFAULTS,{buildId:suiteCustomizationData?.buildId||''});
  applySuiteCustomization(c,true);previewSuiteCustomization();
  toast('Default customization loaded in the editor. Save to persist it.','success');
}

let communityMotdData=null;
let communityMotdConfig=null;
let communityMotdContentTab='main';
const COMMUNITY_MOTD_CONTENT_KEYS={main:'Content',announcements:'AnnouncementsVtml',updates:'UpdatesVtml',events:'EventsVtml',rules:'RulesVtml',serverinfo:'ServerInfoVtml',commands:'CommandsVtml'};
function motdBool(id){return !!$(id)?.checked;}
function motdInt(id,fallback){const n=Number($(id)?.value);return Number.isFinite(n)?Math.trunc(n):fallback;}
function stashCommunityMotdEditor(){
  if(!communityMotdConfig)return;
  const key=COMMUNITY_MOTD_CONTENT_KEYS[communityMotdContentTab]||'Content';
  communityMotdConfig[key]=String($('communityMotdEditor')?.value||'');
  if(key==='Content')communityMotdConfig.ContentLines=[];
}
function selectCommunityMotdContentTab(tab){
  if(!COMMUNITY_MOTD_CONTENT_KEYS[tab])return;
  stashCommunityMotdEditor();
  communityMotdContentTab=tab;
  document.querySelectorAll('#communityMotdContentTabs button[data-motd-content]').forEach(b=>b.classList.toggle('active',b.dataset.motdContent===tab));
  const key=COMMUNITY_MOTD_CONTENT_KEYS[tab];
  if($('communityMotdEditor'))$('communityMotdEditor').value=String(communityMotdConfig?.[key]||'');
}
