const adminDbStorageCanvas=$('adminDatabaseStorageGraph');
if(adminDbStorageCanvas){
  adminDbStorageCanvas.addEventListener('mousemove',e=>{
    const rect=adminDbStorageCanvas.getBoundingClientRect();
    const y=e.clientY-rect.top;
    const hit=adminDatabaseStorageGraphHitAreas.find(a=>y>=a.y&&y<=a.y+a.h);
    const tip=$('adminDatabaseStorageGraphTip');
    const next=hit?hit.index:-1;
    if(next!==adminDatabaseStorageGraphHover){adminDatabaseStorageGraphHover=next;renderAdminDatabaseStorageGraph();}
    if(!tip||!hit){if(tip)tip.style.display='none';return;}
    const r=hit.row;
    const share=(v)=>r.total>0?`${(Number(v||0)*100/r.total).toFixed(1)}%`:'0.0%';
    tip.innerHTML=`<b>${esc(r.db.name||r.db.key||'Database')}</b><br>Database: <b>${esc(formatBytesTotal(r.database))}</b> · ${share(r.database)}<br>WAL: <b>${esc(formatBytesTotal(r.wal))}</b> · ${share(r.wal)}<br>SHM: <b>${esc(formatBytesTotal(r.shm))}</b> · ${share(r.shm)}<br>Backups: <b>${esc(formatBytesTotal(r.backups))}</b> · ${share(r.backups)}<br>Total: <b>${esc(formatBytesTotal(r.total))}</b>`;
    tip.style.display='block';
    const left=Math.min(rect.width-235,Math.max(8,e.clientX-rect.left+12));
    const top=Math.min(rect.height-125,Math.max(8,e.clientY-rect.top+12));
    tip.style.left=`${left}px`;tip.style.top=`${top}px`;
  });
  adminDbStorageCanvas.addEventListener('mouseleave',()=>{
    adminDatabaseStorageGraphHover=-1;
    const tip=$('adminDatabaseStorageGraphTip');if(tip)tip.style.display='none';
    renderAdminDatabaseStorageGraph();
  });
}
