document.addEventListener('keydown',e=>{
  const tag=String(document.activeElement&&document.activeElement.tagName||'').toLowerCase();
  const typing=tag==='input'||tag==='textarea'||tag==='select'||document.activeElement?.isContentEditable;

  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){
    e.preventDefault();openCommandPalette();return;
  }

  if($('commandOverlay').classList.contains('open')){
    if(e.key==='Escape'){e.preventDefault();closeCommandPalette();return}
    if(e.key==='ArrowDown'){e.preventDefault();commandSelectedIndex=Math.min(commandResultCache.length-1,commandSelectedIndex+1);renderCommandResults();return}
    if(e.key==='ArrowUp'){e.preventDefault();commandSelectedIndex=Math.max(0,commandSelectedIndex-1);renderCommandResults();return}
    if(e.key==='Enter'){e.preventDefault();runCommandIndex(commandSelectedIndex);return}
  }

  if(e.key==='Escape'){
    $('notificationPanel').classList.remove('open');
    $('dashboardCustomizeOverlay').classList.remove('open');
    if($('perfIncidentDetailCard')&&$('perfIncidentDetailCard').style.display!=='none'){
      $('perfIncidentDetailCard').style.display='none';selectedPerformanceIncidentStart=0;setBreadcrumb();
    }
    return;
  }

  if(typing)return;

  if(shortcutPrefix==='g'){
    const map={d:'dashboard',p:'performance',a:'actionCenter',m:'memory',h:'health'};
    const section=map[e.key.toLowerCase()];
    shortcutPrefix='';
    clearTimeout(shortcutPrefixTimer);
    if(section){e.preventDefault();setSection(section,true)}
    return;
  }

  if(e.key.toLowerCase()==='g'){
    shortcutPrefix='g';
    clearTimeout(shortcutPrefixTimer);
    shortcutPrefixTimer=setTimeout(()=>shortcutPrefix='',1200);
    return;
  }

  if(e.key.toLowerCase()==='r'){
    e.preventDefault();refreshShortcutSection();return;
  }
});

