let panelLeaderboardData=null;
let panelLeaderboardTab='overview';
let panelLeaderboardProfileName='';
const panelLeaderboardOverlay=$('panelLeaderboardOverlay');
const panelLeaderboardBody=$('panelLeaderboardBody');
const panelLeaderboardStatus=$('panelLeaderboardStatus');
const panelLeaderboardNotice=$('panelLeaderboardNotice');

function panelLbDuration(seconds){
  seconds=Math.max(0,Number(seconds)||0);const d=Math.floor(seconds/86400),h=Math.floor((seconds%86400)/3600),m=Math.floor((seconds%3600)/60);
  if(d)return `${d.toLocaleString()}d ${h}h`;if(h)return `${h.toLocaleString()}h ${m}m`;return `${m.toLocaleString()}m`;
}
function panelLbNumber(value){value=Math.max(0,Number(value)||0);if(value>=1e9)return `${(value/1e9).toFixed(value>=1e10?1:2).replace(/\.?0+$/,'')}B`;if(value>=1e6)return `${(value/1e6).toFixed(value>=1e7?1:2).replace(/\.?0+$/,'')}M`;if(value>=1e3)return `${(value/1e3).toFixed(value>=1e4?1:2).replace(/\.?0+$/,'')}K`;return Math.round(value).toLocaleString()}
function panelLbDate(ms){const n=Number(ms)||0;if(!n)return '—';try{return new Date(n).toLocaleDateString()}catch{return '—'}}
function panelLbPlayerMarkup(row){return `${row?.online?'<span class="panelLbOnline"></span>':''}${esc(row?.player||'Unknown')}`}
function panelLbRankClass(rank){rank=Number(rank)||0;return rank>=1&&rank<=3?` r${rank}`:''}
function panelLbRows(rows,formatter){rows=Array.isArray(rows)?rows:[];if(!rows.length)return '<div class="panelLbEmpty">No ranked progress yet.</div>';return `<div class="panelLbRows">${rows.map(r=>`<div class="panelLbRow"><span class="panelLbRank${panelLbRankClass(r.rank)}">#${Number(r.rank||0)}</span><span class="panelLbPlayer" data-panel-lb-player="${esc(r.player||'')}">${panelLbPlayerMarkup(r)}</span><span class="panelLbValue">${esc(formatter(r))}</span></div>`).join('')}</div>`}
function panelLbCard(title,icon,rows,formatter){return `<div class="panelLbCard"><div class="panelLbCardHead"><span>${icon}</span><span>${esc(title)}</span></div>${panelLbRows(rows,formatter)}</div>`}
function bindPanelLbPlayers(){panelLeaderboardBody?.querySelectorAll('[data-panel-lb-player]').forEach(el=>el.onclick=()=>{panelLeaderboardProfileName=el.dataset.panelLbPlayer||'';renderPanelLeaderboard()})}
function renderPanelLeaderboardStatus(){
  const d=panelLeaderboardData||{};const tracked=Number(d.playerCount||0),offline=Number(d.offlinePlayerCount||0),online=Math.max(0,tracked-offline),xoff=Number(d.xSkillsOfflinePlayerCount||0);
  if(panelLeaderboardStatus)panelLeaderboardStatus.innerHTML=`<span class="panelLbChip gold">♛ ${tracked.toLocaleString()} tracked</span><span class="panelLbChip good">● ${online.toLocaleString()} online</span><span class="panelLbChip">◌ ${offline.toLocaleString()} offline</span><span class="panelLbChip ${d.xSkillsDetected?'good':''}">✦ ${d.xSkillsDetected?`${Number(d.xSkillsPlayerCount||0).toLocaleString()} XSkills players`:'XSkills unavailable'}</span>${d.xSkillsDetected?`<span class="panelLbChip">↳ ${xoff.toLocaleString()} offline XSkills</span>`:''}`;
  if(panelLeaderboardNotice)panelLeaderboardNotice.innerHTML=d.xSkillsStatus?`<div class="panelLbNotice">${esc(d.xSkillsStatus)}</div>`:'';
}
function renderPanelLeaderboardProfile(){
  const d=panelLeaderboardData||{};const p=(d.players||[]).find(x=>String(x.player||'').toLowerCase()===String(panelLeaderboardProfileName||'').toLowerCase());if(!p){panelLeaderboardProfileName='';renderPanelLeaderboard();return}
  const skills=Array.isArray(p.topSkills)?p.topSkills:[];
  panelLeaderboardBody.innerHTML=`<button class="panelLbBack" id="panelLbBack">← Back</button><div class="panelLbProfileHero"><div class="panelLbProfileName">${p.online?'<span class="panelLbOnline"></span>':''}${esc(p.player||'')}</div><div class="small">${p.online?'Online now':'Offline'} · Public progression profile</div><div class="panelLbProfileStats"><div class="panelLbStat"><div class="panelLbStatLabel">Tracked Playtime</div><div class="panelLbStatValue">${panelLbDuration(p.totalPlaySeconds)}</div></div><div class="panelLbStat"><div class="panelLbStatLabel">Total Skill Levels</div><div class="panelLbStatValue">${Number(p.totalSkillLevels||0).toLocaleString()}</div></div><div class="panelLbStat"><div class="panelLbStatLabel">Cumulative Skill XP</div><div class="panelLbStatValue">${panelLbNumber(p.totalSkillExperience)}</div></div><div class="panelLbStat"><div class="panelLbStatLabel">Skills Progressed</div><div class="panelLbStatValue">${Number(p.skillsLeveled||0).toLocaleString()}</div></div><div class="panelLbStat"><div class="panelLbStatLabel">First Seen</div><div class="panelLbStatValue">${panelLbDate(p.firstSeenUnixMilliseconds)}</div></div><div class="panelLbStat"><div class="panelLbStatLabel">Last Seen</div><div class="panelLbStatValue">${p.online?'Now':panelLbDate(p.lastSeenUnixMilliseconds)}</div></div></div>${skills.length?`<div style="margin-top:12px;font-weight:900">Top Skills</div><div class="panelLbSkills" style="margin-top:8px">${skills.map(sk=>`<div class="panelLbSkill"><div class="panelLbSkillHead"><span class="panelLbSkillIcon">${esc(sk.icon||'★')}</span><div><div class="panelLbSkillName">${esc(sk.displayName||sk.name||'Skill')}</div><div class="panelLbSkillSub">Level ${Number(sk.level||0).toLocaleString()} · ${panelLbNumber(sk.experience)} current XP</div></div></div></div>`).join('')}</div>`:''}</div>`;
  $('panelLbBack').onclick=()=>{panelLeaderboardProfileName='';renderPanelLeaderboard()};
}
function renderPanelLeaderboard(){
  if(!panelLeaderboardBody)return;renderPanelLeaderboardStatus();document.querySelectorAll('[data-panel-lb-tab]').forEach(b=>b.classList.toggle('active',(b.dataset.panelLbTab||'overview')===panelLeaderboardTab));
  const d=panelLeaderboardData;if(!d){panelLeaderboardBody.innerHTML='<div class="panelLbEmpty">Loading leaderboard…</div>';return}if(d.enabled===false){panelLeaderboardBody.innerHTML=`<div class="panelLbEmpty">${esc(d.xSkillsStatus||'Leaderboards are disabled.')}</div>`;return}if(panelLeaderboardProfileName){renderPanelLeaderboardProfile();return}
  if(panelLeaderboardTab==='skills'){
    const skills=Array.isArray(d.skills)?d.skills:[];panelLeaderboardBody.innerHTML=skills.length?`<div class="panelLbSkills">${skills.map(sk=>{const accent=/^#[0-9a-fA-F]{6}$/.test(sk.accent||'')?sk.accent:'#60a5fa';return `<div class="panelLbSkill" style="--skillAccent:${accent}"><div class="panelLbSkillHead"><span class="panelLbSkillIcon">${esc(sk.icon||'★')}</span><div><div class="panelLbSkillName">${esc(sk.displayName||sk.name||'Skill')}</div><div class="panelLbSkillSub">Top ${Number(d.topCount||5)} by level and XP</div></div></div>${panelLbRows(sk.entries,r=>`Lv. ${Number(r.level||0).toLocaleString()} · ${panelLbNumber(r.experience)} XP`)}</div>`}).join('')}</div>`:'<div class="panelLbEmpty">No XSkills rankings are available.</div>';
  }else if(panelLeaderboardTab==='playtime'){
    panelLeaderboardBody.innerHTML=`<div class="panelLbGrid">${panelLbCard('Most Tracked Playtime','⏱',d.playtime,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Longest Current Session','⌛',d.currentSession,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Server Veterans','★',d.veterans,r=>r.displayValue||'—')}</div>`;
  }else{
    panelLeaderboardBody.innerHTML=`<div class="panelLbGrid">${panelLbCard('Top Total Skill Levels','♛',d.totalLevels,r=>r.displayValue||Math.round(Number(r.value||0)).toLocaleString())}${panelLbCard('Top Cumulative Skill XP','✦',d.totalExperience,r=>r.displayValue||panelLbNumber(r.value))}${panelLbCard('Most Tracked Playtime','⏱',d.playtime,r=>r.displayValue||panelLbDuration(r.value))}${panelLbCard('Longest Current Session','⌛',d.currentSession,r=>r.displayValue||panelLbDuration(r.value))}</div>`;
  }
  bindPanelLbPlayers();
}
async function loadPanelLeaderboard(){
  panelLeaderboardData=null;panelLeaderboardProfileName='';renderPanelLeaderboard();
  try{panelLeaderboardData=await api('/api/leaderboard');renderPanelLeaderboard()}catch(e){panelLeaderboardBody.innerHTML=`<div class="panelLbEmpty">Leaderboard unavailable: ${esc(e.message||e)}</div>`}
}
function openPanelLeaderboard(){panelLeaderboardOverlay?.classList.add('open');panelLeaderboardOverlay?.setAttribute('aria-hidden','false');loadPanelLeaderboard()}
function closePanelLeaderboard(){panelLeaderboardOverlay?.classList.remove('open');panelLeaderboardOverlay?.setAttribute('aria-hidden','true');panelLeaderboardProfileName=''}
if($('leaderboardTopBtn'))$('leaderboardTopBtn').onclick=openPanelLeaderboard;
if($('panelLeaderboardClose'))$('panelLeaderboardClose').onclick=closePanelLeaderboard;
if($('panelLeaderboardRefresh'))$('panelLeaderboardRefresh').onclick=loadPanelLeaderboard;
document.querySelectorAll('[data-panel-lb-tab]').forEach(b=>b.onclick=()=>{panelLeaderboardTab=b.dataset.panelLbTab||'overview';panelLeaderboardProfileName='';renderPanelLeaderboard()});
panelLeaderboardOverlay?.addEventListener('click',e=>{if(e.target===panelLeaderboardOverlay)closePanelLeaderboard()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panelLeaderboardOverlay?.classList.contains('open'))closePanelLeaderboard()});

renderBlockLoggerSavedViews();
renderDashboardWatchlist();
enhanceToggleSwitches();
initToggleSwitchObserver();
setModsTab(modsActiveTab,false);
setGlobalLiveState();
enhanceImportantTables();
initHeaderLayout();
initUiScale();
initMotionPreference();
initLocalization();
checkSession();
